{
  "name": "LogicLab Ultra",
  "description": "A professional-grade, web-based logic circuit simulator with real-time state evaluation and a modern dark UI."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type NodeType = 'AND' | 'OR' | 'NOT' | 'XOR' | 'NAND' | 'SWITCH' | 'BULB';

export interface Point {
  x: number;
  y: number;
}

export interface Port {
  id: string;
  type: 'input' | 'output';
  offset: Point;
  label?: string;
}

export interface NodeData {
  id: string;
  type: NodeType;
  position: Point;
  inputs: boolean[];
  output: boolean;
  label?: string;
}

export interface Wire {
  id: string;
  sourceNodeId: string;
  targetNodeId: string;
  targetInputIndex: number; // 0 for A, 1 for B, etc.
  state: boolean;
}

export interface CircuitState {
  nodes: NodeData[];
  wires: Wire[];
}

// For drag operations
export interface DragItem {
  type: NodeType;
  offsetX: number;
  offsetY: number;
}

export interface WiringState {
  sourceNodeId: string;
  startPoint: Point;
  active: boolean;
}

import { NodeType, Port } from './types';

export const GRID_SIZE = 20;

export const NODE_DEFINITIONS: Record<NodeType, {
  width: number;
  height: number;
  inputs: number;
  inputOffsets: { x: number, y: number }[];
  outputOffset: { x: number, y: number };
  name: string;
}> = {
  AND: {
    width: 60,
    height: 60,
    inputs: 2,
    inputOffsets: [{ x: 0, y: 15 }, { x: 0, y: 45 }],
    outputOffset: { x: 60, y: 30 },
    name: 'AND Gate'
  },
  OR: {
    width: 60,
    height: 60,
    inputs: 2,
    inputOffsets: [{ x: 0, y: 15 }, { x: 0, y: 45 }],
    outputOffset: { x: 60, y: 30 },
    name: 'OR Gate'
  },
  XOR: {
    width: 60,
    height: 60,
    inputs: 2,
    inputOffsets: [{ x: 0, y: 15 }, { x: 0, y: 45 }],
    outputOffset: { x: 60, y: 30 },
    name: 'XOR Gate'
  },
  NAND: {
    width: 70, // Slightly wider for the bubble
    height: 60,
    inputs: 2,
    inputOffsets: [{ x: 0, y: 15 }, { x: 0, y: 45 }],
    outputOffset: { x: 70, y: 30 },
    name: 'NAND Gate'
  },
  NOT: {
    width: 50,
    height: 40,
    inputs: 1,
    inputOffsets: [{ x: 0, y: 20 }],
    outputOffset: { x: 50, y: 20 },
    name: 'NOT Gate'
  },
  SWITCH: {
    width: 40,
    height: 40,
    inputs: 0,
    inputOffsets: [],
    outputOffset: { x: 40, y: 20 },
    name: 'Input Switch'
  },
  BULB: {
    width: 40,
    height: 40,
    inputs: 1,
    inputOffsets: [{ x: 0, y: 20 }],
    outputOffset: { x: 20, y: 20 }, // Center-ish for logic, but usually bulbs don't output
    name: 'Output Lamp'
  }
};

import { CircuitState, NodeData, Wire, NodeType } from '../types';

const evaluateGate = (type: NodeType, inputs: boolean[], currentState: boolean): boolean => {
  switch (type) {
    case 'AND':
      return inputs[0] && inputs[1];
    case 'OR':
      return inputs[0] || inputs[1];
    case 'NOT':
      return !inputs[0];
    case 'XOR':
      return inputs[0] !== inputs[1];
    case 'NAND':
      return !(inputs[0] && inputs[1]);
    case 'SWITCH':
      // Switch state is manually toggled, so we just return the current state preserved in the node
      // However, in our loop, we treat the 'inputs' array as the driven values. 
      // For a switch, the 'output' is the source of truth, so we return it as is.
      return currentState;
    case 'BULB':
      // Bulb state is just its input
      return inputs[0] || false;
    default:
      return false;
  }
};

export const evaluateCircuit = (nodes: NodeData[], wires: Wire[]): { nodes: NodeData[], wires: Wire[] } => {
  // Deep copy to avoid direct mutation during calculation
  let nextNodes = nodes.map(n => ({ ...n, inputs: [...n.inputs] }));
  let nextWires = wires.map(w => ({ ...w }));

  // We need to settle the circuit. Since there are no delays, we can iterate a few times
  // or use a topological approach. To handle cycles (simple ones), we'll iterate until stable
  // or max iterations reached.

  let stable = false;
  let iterations = 0;
  const MAX_ITERATIONS = 20; // Prevent infinite loops in cyclic circuits

  while (!stable && iterations < MAX_ITERATIONS) {
    stable = true;
    iterations++;

    // 1. Update wires based on source node outputs
    nextWires.forEach(wire => {
      const sourceNode = nextNodes.find(n => n.id === wire.sourceNodeId);
      if (sourceNode) {
        const newWireState = sourceNode.output;
        if (wire.state !== newWireState) {
          wire.state = newWireState;
          stable = false;
        }
      }
    });

    // 2. Propagate wires to target node inputs
    nextWires.forEach(wire => {
      const targetNode = nextNodes.find(n => n.id === wire.targetNodeId);
      if (targetNode) {
        if (targetNode.inputs[wire.targetInputIndex] !== wire.state) {
          targetNode.inputs[wire.targetInputIndex] = wire.state;
          stable = false;
        }
      }
    });

    // 3. Evaluate gates
    nextNodes.forEach(node => {
      // Switches are input sources, their output is toggled by user, not by circuit inputs
      if (node.type !== 'SWITCH') {
        const newOutput = evaluateGate(node.type, node.inputs, node.output);
        if (node.output !== newOutput) {
          node.output = newOutput;
          stable = false;
        }
      }
    });
  }

  return { nodes: nextNodes, wires: nextWires };
};

import React from 'react';
import { NodeType } from '../types';

interface GateShapeProps {
  type: NodeType;
  active: boolean; // For bulbs mainly, or active glowing borders
}

export const GateShape: React.FC<GateShapeProps> = ({ type, active }) => {
  const strokeColor = active ? "#22d3ee" : "#71717a"; // Cyan-400 vs Zinc-500
  const fillColor = "#18181b"; // Zinc-950
  const activeFill = active ? "#0ea5e9" : "#18181b"; // Sky-500 for bulbs

  switch (type) {
    case 'AND':
      return (
        <path
          d="M 0 0 L 25 0 A 30 30 0 0 1 25 60 L 0 60 Z"
          fill={fillColor}
          stroke={strokeColor}
          strokeWidth="2"
        />
      );
    case 'NAND':
      return (
        <g>
          <path
            d="M 0 0 L 25 0 A 30 30 0 0 1 25 60 L 0 60 Z"
            fill={fillColor}
            stroke={strokeColor}
            strokeWidth="2"
          />
           <circle cx="58" cy="30" r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case 'OR':
      return (
        <path
          d="M 0 0 Q 15 30 0 60 Q 40 60 60 30 Q 40 0 0 0 Z"
          fill={fillColor}
          stroke={strokeColor}
          strokeWidth="2"
        />
      );
    case 'XOR':
      return (
        <g>
          <path
            d="M 10 0 Q 25 30 10 60 Q 50 60 60 30 Q 50 0 10 0 Z"
            fill={fillColor}
            stroke={strokeColor}
            strokeWidth="2"
          />
          <path
             d="M -5 0 Q 10 30 -5 60"
             fill="none"
             stroke={strokeColor}
             strokeWidth="2"
          />
        </g>
      );
    case 'NOT':
      return (
        <g>
          <path
            d="M 0 0 L 35 20 L 0 40 Z"
            fill={fillColor}
            stroke={strokeColor}
            strokeWidth="2"
          />
          <circle cx="40" cy="20" r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case 'SWITCH':
      return (
        <g>
          <rect x="0" y="0" width="40" height="40" rx="4" fill={activeFill} stroke={strokeColor} strokeWidth="2" />
          <text x="20" y="25" textAnchor="middle" fill={active ? "#fff" : "#a1a1aa"} fontSize="12" fontWeight="bold">
            {active ? "1" : "0"}
          </text>
        </g>
      );
    case 'BULB':
      return (
        <g>
          <circle cx="20" cy="20" r="15" fill={active ? "#fbbf24" : "#27272a"} stroke={active ? "#f59e0b" : "#52525b"} strokeWidth="2" style={{ filter: active ? 'drop-shadow(0 0 8px #fbbf24)' : 'none'}} />
        </g>
      );
    default:
      return <rect width="40" height="40" fill="red" />;
  }
};

import React from 'react';
import { NODE_DEFINITIONS } from '../constants';
import { NodeType } from '../types';
import { SquareActivity, ToggleLeft, Lightbulb, Combine, GitBranch, ArrowRightFromLine, AlertCircle } from 'lucide-react';

const SidebarItem = ({ type, icon: Icon, label }: { type: NodeType; icon: any; label: string }) => {
  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('application/react-circuit-node', type);
    e.dataTransfer.effectAllowed = 'copy';
  };

  return (
    <div
      draggable
      onDragStart={handleDragStart}
      className="flex flex-col items-center justify-center p-3 mb-3 bg-zinc-800 border border-zinc-700 rounded-lg cursor-grab hover:bg-zinc-700 hover:border-zinc-500 transition-all shadow-sm group"
    >
      <div className="text-zinc-400 group-hover:text-cyan-400 transition-colors mb-2">
        <Icon size={24} />
      </div>
      <span className="text-xs font-medium text-zinc-300">{label}</span>
    </div>
  );
};

export const Sidebar: React.FC = () => {
  return (
    <div className="w-24 bg-zinc-900 border-r border-zinc-800 flex flex-col p-4 h-full select-none z-10 shadow-xl overflow-y-auto">
      <div className="mb-6 flex flex-col items-center">
         <div className="w-8 h-8 bg-cyan-500 rounded-md flex items-center justify-center mb-2 shadow-lg shadow-cyan-500/20">
            <SquareActivity size={20} className="text-white" />
         </div>
         <span className="text-[10px] font-bold tracking-wider text-zinc-500 uppercase">LogicLab</span>
      </div>

      <div className="space-y-1">
        <div className="text-[10px] font-semibold text-zinc-600 mb-2 uppercase tracking-wide">IO</div>
        <SidebarItem type="SWITCH" icon={ToggleLeft} label="Switch" />
        <SidebarItem type="BULB" icon={Lightbulb} label="Bulb" />

        <div className="h-px bg-zinc-800 my-3" />

        <div className="text-[10px] font-semibold text-zinc-600 mb-2 uppercase tracking-wide">Gates</div>
        <SidebarItem type="AND" icon={Combine} label="AND" />
        <SidebarItem type="OR" icon={GitBranch} label="OR" />
        <SidebarItem type="NOT" icon={ArrowRightFromLine} label="NOT" />
        <SidebarItem type="XOR" icon={AlertCircle} label="XOR" />
        <SidebarItem type="NAND" icon={Combine} label="NAND" />
      </div>
    </div>
  );
};

import React, { useRef, useState, useEffect, useCallback } from 'react';
import { GRID_SIZE, NODE_DEFINITIONS } from '../constants';
import { CircuitState, NodeData, NodeType, Wire, Point, WiringState } from '../types';
import { GateShape } from './GateShapes';
import { evaluateCircuit } from '../utils/circuitLogic';
import { X, Trash2, Undo2, MousePointer2 } from 'lucide-react';

export const CircuitCanvas: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [circuit, setCircuit] = useState<CircuitState>({ nodes: [], wires: [] });

  // Interaction State
  const [draggingNodeId, setDraggingNodeId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<Point>({ x: 0, y: 0 });
  const [wiring, setWiring] = useState<WiringState | null>(null);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });
  const [selectedId, setSelectedId] = useState<string | null>(null); // Node or Wire ID

  // --- Logic Helpers ---
  const updateCircuit = (newNodes: NodeData[], newWires: Wire[]) => {
    // Run evaluation immediately on state change
    const evaluated = evaluateCircuit(newNodes, newWires);
    setCircuit(evaluated);
  };

  const addNode = (type: NodeType, x: number, y: number) => {
    const def = NODE_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newNode: NodeData = {
      id: `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      position: { x: snapX, y: snapY },
      inputs: Array(def.inputs).fill(false),
      output: false,
    };

    updateCircuit([...circuit.nodes, newNode], circuit.wires);
  };

  const deleteSelection = () => {
    if (!selectedId) return;

    // Check if it's a wire
    const isWire = circuit.wires.find(w => w.id === selectedId);
    if (isWire) {
      updateCircuit(circuit.nodes, circuit.wires.filter(w => w.id !== selectedId));
      setSelectedId(null);
      return;
    }

    // It's a node
    const newWires = circuit.wires.filter(w => w.sourceNodeId !== selectedId && w.targetNodeId !== selectedId);
    const newNodes = circuit.nodes.filter(n => n.id !== selectedId);
    updateCircuit(newNodes, newWires);
    setSelectedId(null);
  };

  // --- Interaction Handlers ---

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const type = e.dataTransfer.getData('application/react-circuit-node') as NodeType;
    if (!type || !containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    addNode(type, x, y);
  };

  const handleNodeMouseDown = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    // Check if we clicked a port (handled separately usually, but for simple Hit testing we can check coordinates)
    // If not wiring, then drag node.
    if (wiring) return;

    setSelectedId(id);
    const node = circuit.nodes.find(n => n.id === id);
    if (!node) return;

    // Toggle switch logic
    if (node.type === 'SWITCH') {
        const toggledNodes = circuit.nodes.map(n => {
            if (n.id === id) return { ...n, output: !n.output };
            return n;
        });
        updateCircuit(toggledNodes, circuit.wires);
        return; // Don't drag switches on click, maybe need a handle for that? 
        // Better UX: Drag if clicked on body, toggle if clicked on switch specific area?
        // For simplicity: If holding shift, drag. Or if clicked on text.
        // Actually, let's just make switches draggable by default, but toggle on Click (MouseUp without move).
        // We'll handle drag start here.
    }

    setDraggingNodeId(id);

    // Calculate offset from node top-left
    const rect = containerRef.current!.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    setDragOffset({
        x: mouseX - node.position.x,
        y: mouseY - node.position.y
    });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    if (draggingNodeId) {
        const snapX = Math.round((x - dragOffset.x) / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round((y - dragOffset.y) / GRID_SIZE) * GRID_SIZE;

        const updatedNodes = circuit.nodes.map(n => {
            if (n.id === draggingNodeId) {
                return { ...n, position: { x: snapX, y: snapY }};
            }
            return n;
        });
        // We update state directly for smooth drag, re-evaluate only on drop could be optimized
        // but evaluating on drag ensures wires move correctly visually
        setCircuit(prev => ({ ...prev, nodes: updatedNodes })); // Just update positions, don't re-eval logic yet
    }
  };

  const handleMouseUp = () => {
    if (draggingNodeId) {
        setDraggingNodeId(null);
        // Trigger evaluation once to ensure everything is settled
        updateCircuit(circuit.nodes, circuit.wires); 
    }
    // Cancel wiring if dropped on empty space
    if (wiring) {
        setWiring(null);
    }
  };

  const startWiring = (e: React.MouseEvent, nodeId: string) => {
    e.stopPropagation();
    e.preventDefault();
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setWiring({
        sourceNodeId: nodeId,
        startPoint: { x, y },
        active: true
    });
  };

  const completeWiring = (e: React.MouseEvent, targetNodeId: string, inputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();

    if (!wiring) return;

    if (wiring.sourceNodeId === targetNodeId) {
        setWiring(null);
        return;
    }

    // Check if wire already exists
    const exists = circuit.wires.some(w => 
        w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex
    );

    // Ideally we should replace existing wire to that input
    let newWires = exists 
        ? circuit.wires.filter(w => !(w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex))
        : [...circuit.wires];

    newWires.push({
        id: `wire-${Date.now()}`,
        sourceNodeId: wiring.sourceNodeId,
        targetNodeId: targetNodeId,
        targetInputIndex: inputIndex,
        state: false
    });

    updateCircuit(circuit.nodes, newWires);
    setWiring(null);
  };

  // --- Render Helpers ---

  const getBezierPath = (x1: number, y1: number, x2: number, y2: number) => {
    const dist = Math.abs(x2 - x1);
    const controlPointOffset = Math.max(dist * 0.5, 50);
    return `M ${x1} ${y1} C ${x1 + controlPointOffset} ${y1}, ${x2 - controlPointOffset} ${y2}, ${x2} ${y2}`;
  };

  return (
    <div className="flex-1 h-full relative bg-zinc-950 flex flex-col overflow-hidden">
        {/* Toolbar */}
        <div className="h-14 border-b border-zinc-800 bg-zinc-900/50 flex items-center px-6 justify-between z-20 backdrop-blur-sm">
            <div className="flex items-center space-x-4">
                <button 
                    onClick={() => setCircuit({ nodes: [], wires: [] })}
                    className="flex items-center space-x-2 px-3 py-1.5 bg-zinc-800 hover:bg-red-900/30 hover:text-red-400 text-zinc-300 rounded-md text-xs font-medium transition-colors border border-zinc-700 hover:border-red-800"
                >
                    <Trash2 size={14} />
                    <span>Clear Board</span>
                </button>
                <div className="h-4 w-px bg-zinc-700 mx-2"></div>
                <div className="text-zinc-500 text-xs flex items-center space-x-2">
                    <MousePointer2 size={14} />
                    <span>Left click to toggle switches / drag nodes</span>
                </div>
            </div>
            {selectedId && (
                 <button 
                 onClick={deleteSelection}
                 className="flex items-center space-x-2 px-3 py-1.5 bg-red-500/10 text-red-400 hover:bg-red-500/20 border border-red-500/30 rounded-md text-xs font-medium transition-colors"
             >
                 <X size={14} />
                 <span>Delete Selected</span>
             </button>
            )}
        </div>

        {/* Canvas Area */}
        <div 
            ref={containerRef}
            className="flex-1 relative overflow-hidden cursor-crosshair"
            onDragOver={handleDragOver}
            onDrop={handleDrop}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onClick={() => setSelectedId(null)}
        >
            {/* Grid Pattern */}
            <svg className="absolute inset-0 pointer-events-none w-full h-full opacity-20">
                <defs>
                    <pattern id="grid" width={GRID_SIZE} height={GRID_SIZE} patternUnits="userSpaceOnUse">
                        <circle cx="1" cy="1" r="1" fill="#71717a" />
                    </pattern>
                </defs>
                <rect width="100%" height="100%" fill="url(#grid)" />
            </svg>

            {/* Connections */}
            <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
                {circuit.wires.map(wire => {
                    const sourceNode = circuit.nodes.find(n => n.id === wire.sourceNodeId);
                    const targetNode = circuit.nodes.find(n => n.id === wire.targetNodeId);
                    if (!sourceNode || !targetNode) return null;

                    const sourceDef = NODE_DEFINITIONS[sourceNode.type];
                    const targetDef = NODE_DEFINITIONS[targetNode.type];

                    const startX = sourceNode.position.x + sourceDef.outputOffset.x;
                    const startY = sourceNode.position.y + sourceDef.outputOffset.y;
                    const endX = targetNode.position.x + targetDef.inputOffsets[wire.targetInputIndex].x;
                    const endY = targetNode.position.y + targetDef.inputOffsets[wire.targetInputIndex].y;

                    const isSelected = selectedId === wire.id;

                    return (
                        <g key={wire.id} onClick={(e) => { e.stopPropagation(); setSelectedId(wire.id); }} className="pointer-events-auto cursor-pointer group">
                             {/* Thicker invisible stroke for easier clicking */}
                            <path
                                d={getBezierPath(startX, startY, endX, endY)}
                                stroke="transparent"
                                strokeWidth="12"
                                fill="none"
                            />
                            {/* Glow effect for active wires */}
                            {wire.state && (
                                <path
                                    d={getBezierPath(startX, startY, endX, endY)}
                                    stroke={wire.state ? "#22d3ee" : "transparent"} // Cyan-400
                                    strokeWidth="4"
                                    fill="none"
                                    opacity="0.3"
                                    filter="blur(2px)"
                                />
                            )}
                            {/* Actual Wire */}
                            <path
                                d={getBezierPath(startX, startY, endX, endY)}
                                stroke={wire.state ? "#22d3ee" : "#52525b"} // Cyan-400 : Zinc-600
                                strokeWidth={isSelected ? "3" : "2"}
                                fill="none"
                                className="transition-colors duration-150"
                                strokeDasharray={isSelected ? "4" : "0"}
                            />
                        </g>
                    );
                })}

                {/* Temp Wire being dragged */}
                {wiring && (
                     <path
                     d={getBezierPath(wiring.startPoint.x, wiring.startPoint.y, mousePos.x, mousePos.y)}
                     stroke="#fbbf24" // Amber-400
                     strokeWidth="2"
                     fill="none"
                     strokeDasharray="4"
                     className="animate-pulse"
                 />
                )}
            </svg>

            {/* Nodes */}
            {circuit.nodes.map(node => {
                const def = NODE_DEFINITIONS[node.type];
                const isSelected = selectedId === node.id;

                return (
                    <div
                        key={node.id}
                        className={`absolute group select-none`}
                        style={{
                            left: node.position.x,
                            top: node.position.y,
                            width: def.width,
                            height: def.height,
                            // If switch, allow pointer events on the whole thing for toggling
                            pointerEvents: 'none' // We handle interaction via specific areas below, or wrap container
                        }}
                    >
                        {/* SVG Container for the Gate Shape */}
                        <div 
                            className={`absolute inset-0 pointer-events-auto transition-all duration-200 ${isSelected ? 'drop-shadow-[0_0_8px_rgba(34,211,238,0.5)]' : ''}`}
                            onMouseDown={(e) => handleNodeMouseDown(e, node.id)}
                        >
                            <svg width={def.width} height={def.height} className="overflow-visible">
                                <GateShape type={node.type} active={node.output} />
                            </svg>
                        </div>

                        {/* Input Ports (Drop Targets for Wires) */}
                        {def.inputOffsets.map((offset, idx) => (
                             <div
                                key={`input-${idx}`}
                                className="absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform cursor-crosshair z-10"
                                style={{ left: offset.x, top: offset.y }}
                                onMouseUp={(e) => completeWiring(e, node.id, idx)}
                             >
                                <div className={`w-2 h-2 rounded-full bg-zinc-900 border ${node.inputs[idx] ? 'border-cyan-400 bg-cyan-900' : 'border-zinc-500'}`} />
                             </div>
                        ))}

                        {/* Output Port (Source for Wires) */}
                        {node.type !== 'BULB' && (
                             <div
                                className="absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform cursor-crosshair z-10"
                                style={{ left: def.outputOffset.x, top: def.outputOffset.y }}
                                onMouseDown={(e) => startWiring(e, node.id)}
                            >
                                <div className={`w-2 h-2 rounded-full bg-zinc-900 border ${node.output ? 'border-cyan-400 bg-cyan-500' : 'border-zinc-500 group-hover:border-zinc-300'}`} />
                            </div>
                        )}

                        {/* Label (Optional) */}
                        {isSelected && (
                            <div className="absolute -top-6 left-1/2 -translate-x-1/2 bg-zinc-800 text-zinc-300 text-[10px] px-2 py-0.5 rounded border border-zinc-700 whitespace-nowrap z-50 pointer-events-none">
                                {def.name}
                            </div>
                        )}
                    </div>
                );
            })}
        </div>
    </div>
  );
};

