import { NodeData, Wire, NodeType } from '../types';

// Returns array of booleans for outputs
const evaluateGate = (type: NodeType, inputs: boolean[], currentOutputs: boolean[]): boolean[] => {
  switch (type) {
    case 'AND':
      return [inputs[0] && inputs[1]];
    case 'OR':
      return [inputs[0] || inputs[1]];
    case 'NOT':
      return [!inputs[0]];
    case 'XOR':
      return [inputs[0] !== inputs[1]];
    case 'NAND':
      return [!(inputs[0] && inputs[1])];
    case 'SWITCH':
      // Switch is source, preserves its state
      return [currentOutputs[0]];
    case 'BULB':
      // Bulb has no output
      return [];
    case 'HALF_ADDER':
      const a = inputs[0];
      const b = inputs[1];
      return [a !== b, a && b]; // [Sum, Carry]
    case 'D_LATCH':
      const D = inputs[0];
      const E = inputs[1]; // Enable/Clock
      const prevQ = currentOutputs[0];
      // Transparent latch: when E is high, Q follows D. When E is low, Q holds.
      const nextQ = E ? D : prevQ;
      return [nextQ, !nextQ]; // [Q, Q']
    case 'MUX_2_1':
      const in0 = inputs[0];
      const in1 = inputs[1];
      const sel = inputs[2];
      return [sel ? in1 : in0];
    default:
      return [false];
  }
};

export const evaluateCircuit = (nodes: NodeData[], wires: Wire[]): { nodes: NodeData[], wires: Wire[] } => {
  let nextNodes = nodes.map(n => ({ ...n, inputs: [...n.inputs], outputs: [...n.outputs] }));
  let nextWires = wires.map(w => ({ ...w }));

  let stable = false;
  let iterations = 0;
  // Reduced max iterations to avoid hanging on unstable latch loops, though 20 is usually fine.
  const MAX_ITERATIONS = 25; 

  while (!stable && iterations < MAX_ITERATIONS) {
    stable = true;
    iterations++;

    // 1. Update wires based on source node outputs
    nextWires.forEach(wire => {
      const sourceNode = nextNodes.find(n => n.id === wire.sourceNodeId);
      if (sourceNode) {
        // Use the specific output index
        const newWireState = sourceNode.outputs[wire.sourceOutputIndex] || false;
        if (wire.state !== newWireState) {
          wire.state = newWireState;
          stable = false;
        }
      }
    });

    // 2. Propagate wires to target node inputs
    nextWires.forEach(wire => {
      const targetNode = nextNodes.find(n => n.id === wire.targetNodeId);
      if (targetNode) {
        if (targetNode.inputs[wire.targetInputIndex] !== wire.state) {
          targetNode.inputs[wire.targetInputIndex] = wire.state;
          stable = false;
        }
      }
    });

    // 3. Evaluate gates
    nextNodes.forEach(node => {
      if (node.type !== 'SWITCH') {
        const newOutputs = evaluateGate(node.type, node.inputs, node.outputs);

        // Check if any output changed
        let changed = false;
        if (newOutputs.length !== node.outputs.length) {
            changed = true;
        } else {
            for(let i=0; i<newOutputs.length; i++) {
                if (node.outputs[i] !== newOutputs[i]) {
                    changed = true;
                    break;
                }
            }
        }

        if (changed) {
          node.outputs = newOutputs;
          stable = false;
        }
      }
    });
  }

  return { nodes: nextNodes, wires: nextWires };
};

import React from 'react';
