}

export const GateShape: React.FC<GateShapeProps> = ({ type, active }) => {
  const strokeColor = active ? "#22d3ee" : "#71717a"; 
  const fillColor = "#18181b"; 
  const activeFill = active ? "#0ea5e9" : "#18181b"; 

  const Text = ({ x, y, children }: { x: number, y: number, children: string }) => (
    <text x={x} y={y} textAnchor="middle" dominantBaseline="middle" fill="#71717a" fontSize="10" fontWeight="bold" className="pointer-events-none select-none">
      {children}
    </text>
  );

  switch (type) {
    case 'AND':
      return <path d="M 0 0 L 25 0 A 30 30 0 0 1 25 60 L 0 60 Z" fill={fillColor} stroke={strokeColor} strokeWidth="2" />;
    case 'NAND':
      return (
        <g>
          <path d="M 0 0 L 25 0 A 30 30 0 0 1 25 60 L 0 60 Z" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <circle cx="58" cy="30" r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case 'OR':
      return <path d="M 0 0 Q 15 30 0 60 Q 40 60 60 30 Q 40 0 0 0 Z" fill={fillColor} stroke={strokeColor} strokeWidth="2" />;
    case 'XOR':
      return (
        <g>
          <path d="M 10 0 Q 25 30 10 60 Q 50 60 60 30 Q 50 0 10 0 Z" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <path d="M -5 0 Q 10 30 -5 60" fill="none" stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case 'NOT':
      return (
        <g>
          <path d="M 0 0 L 35 20 L 0 40 Z" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <circle cx="40" cy="20" r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case 'SWITCH':
      return (
        <g>
          <rect x="0" y="0" width="40" height="40" rx="4" fill={activeFill} stroke={strokeColor} strokeWidth="2" />
          <text x="20" y="25" textAnchor="middle" fill={active ? "#fff" : "#a1a1aa"} fontSize="12" fontWeight="bold">{active ? "1" : "0"}</text>
        </g>
      );
    case 'BULB':
      return (
        <g>
          <circle cx="20" cy="20" r="15" fill={active ? "#fbbf24" : "#27272a"} stroke={active ? "#f59e0b" : "#52525b"} strokeWidth="2" style={{ filter: active ? 'drop-shadow(0 0 8px #fbbf24)' : 'none'}} />
        </g>
      );
    case 'HALF_ADDER':
      return (
        <g>
            <rect x="0" y="0" width="80" height="80" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
            <Text x="40" y="40">HALF ADDER</Text>
            <Text x="10" y="20">A</Text>
            <Text x="10" y="60">B</Text>
            <Text x="70" y="20">S</Text>
            <Text x="70" y="60">C</Text>
        </g>
      );
    case 'D_LATCH':
        return (
          <g>
              <rect x="0" y="0" width="80" height="80" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
              <Text x="40" y="25">D-LATCH</Text>
              <Text x="10" y="20">D</Text>
              <Text x="10" y="60">E</Text>
              <Text x="70" y="20">Q</Text>
              <Text x="70" y="60">Q'</Text>
          </g>
        );
