       <div className="p-4 space-y-6 overflow-y-auto flex-1">
          {/* General Section */}
          <div className="space-y-3">
             <div className="text-xs font-bold text-zinc-500 uppercase tracking-wider">General</div>

             <div className="space-y-1">
                <label className="text-xs text-zinc-400">Type</label>
                <div className="w-full bg-zinc-800 border border-zinc-700 rounded px-3 py-2 text-sm text-zinc-300 font-mono">
                    {node.type}
                </div>
             </div>

             <div className="space-y-1">
                <label className="text-xs text-zinc-400">Label</label>
                <input 
                    type="text" 
                    value={node.properties?.label || ''} 
                    onChange={handleLabelChange}
                    placeholder="Component Name..."
                    className="w-full bg-zinc-950 border border-zinc-700 rounded px-3 py-2 text-sm text-zinc-200 focus:border-cyan-500 focus:outline-none transition-colors"
                />
             </div>
          </div>

          <div className="h-px bg-zinc-800" />

          {/* Attributes Section */}
          <div className="space-y-3">
             <div className="text-xs font-bold text-zinc-500 uppercase tracking-wider">Attributes</div>

             {isGate ? (
                 <div className="space-y-1">
                    <label className="text-xs text-zinc-400">Number of Inputs</label>
                    <select 
                        value={node.properties?.inputCount || 2}
                        onChange={handleInputCountChange}
                        className="w-full bg-zinc-950 border border-zinc-700 rounded px-3 py-2 text-sm text-zinc-200 focus:border-cyan-500 focus:outline-none"
                    >
                        {[2,3,4,5,6,8].map(n => (
                            <option key={n} value={n}>{n} Inputs</option>
                        ))}
                    </select>
                 </div>
             ) : (
                <div className="text-xs text-zinc-600 italic">
                    No configurable attributes for this component.
                </div>
             )}
          </div>
       </div>

       <div className="p-4 border-t border-zinc-800 text-xs text-zinc-600 text-center">
           ID: <span className="font-mono text-zinc-700">{node.id.split('-')[1]}...</span>
       </div>
    </div>
  );
};

import React, { useRef, useState, useEffect } from 'react';
import { GRID_SIZE, NODE_DEFINITIONS } from '../constants';
import { CircuitState, NodeData, NodeType, Wire, Point, WiringState } from '../types';
import { GateShape } from './GateShapes';
import { evaluateCircuit } from '../utils/circuitLogic';
import { getNodeDimensions, getInputPorts, getOutputPorts } from '../utils/componentUtils';
import { PropertiesPanel } from './PropertiesPanel';
import { X, Trash2, MousePointer2 } from 'lucide-react';

export const CircuitCanvas: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [circuit, setCircuit] = useState<CircuitState>({ nodes: [], wires: [] });

  // Interaction State
  const [draggingNodeId, setDraggingNodeId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<Point>({ x: 0, y: 0 });
  const [wiring, setWiring] = useState<WiringState | null>(null);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });
  const [selectedId, setSelectedId] = useState<string | null>(null); 

  // --- Clock Simulation ---
  useEffect(() => {
    const interval = setInterval(() => {
        setCircuit(prev => {
            const hasClock = prev.nodes.some(n => n.type === 'CLOCK');
            if (!hasClock) return prev;

            const nextNodes = prev.nodes.map(n => {
                if (n.type === 'CLOCK') {
                    return { ...n, outputs: [!n.outputs[0]] };
                }
                return n;
            });
            return evaluateCircuit(nextNodes, prev.wires);
        });
    }, 1000); 
    return () => clearInterval(interval);
  }, []);

  // --- Logic Helpers ---
  const updateCircuit = (newNodes: NodeData[], newWires: Wire[]) => {
    const evaluated = evaluateCircuit(newNodes, newWires);
    setCircuit(evaluated);
  };

  const handleNodeUpdate = (id: string, updates: Partial<NodeData>) => {
    setCircuit(prev => {
        const newNodes = prev.nodes.map(n => {
            if (n.id === id) {
                const updatedNode = { ...n, ...updates };
                // Handle resizing of inputs array if inputCount changes
                if (updates.properties?.inputCount) {
                    const count = updates.properties.inputCount;
                    if (count > updatedNode.inputs.length) {
                        // Grow: add false
                        updatedNode.inputs = [...updatedNode.inputs, ...Array(count - updatedNode.inputs.length).fill(false)];
                    } else if (count < updatedNode.inputs.length) {
                        // Shrink: slice
                        updatedNode.inputs = updatedNode.inputs.slice(0, count);
                        // Also remove attached wires that are now out of bounds
                        // This is handled in the next step implicitly or explicitly below
                    }
                }
                return updatedNode;
            }
            return n;
        });

        // Remove wires that might be connected to non-existent ports if input count shrunk
        // This is a bit complex, strictly we should check targetInputIndex < inputCount
        // For now, let's just evaluate.

        return evaluateCircuit(newNodes, prev.wires);
    });
  };

  const addNode = (type: NodeType, x: number, y: number) => {
    const def = NODE_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newNode: NodeData = {
      id: `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      position: { x: snapX, y: snapY },
      inputs: Array(def.inputs).fill(false),
      outputs: Array(def.outputs).fill(false),
      internalState: {},
      properties: {
          label: '',
          inputCount: def.inputs
      }
    };

    updateCircuit([...circuit.nodes, newNode], circuit.wires);
    setSelectedId(newNode.id);
  };

  const deleteSelection = () => {
    if (!selectedId) return;

    const isWire = circuit.wires.find(w => w.id === selectedId);
    if (isWire) {
      updateCircuit(circuit.nodes, circuit.wires.filter(w => w.id !== selectedId));
      setSelectedId(null);
      return;
    }

    const newWires = circuit.wires.filter(w => w.sourceNodeId !== selectedId && w.targetNodeId !== selectedId);
    const newNodes = circuit.nodes.filter(n => n.id !== selectedId);
    updateCircuit(newNodes, newWires);
    setSelectedId(null);
  };

  // --- Interaction Handlers ---

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); 
    e.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const type = e.dataTransfer.getData('application/react-circuit-node') as NodeType;

    if (!type || !containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    addNode(type, x, y);
  };

  const handleNodeMouseDown = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (wiring) return;

    setSelectedId(id);
    const node = circuit.nodes.find(n => n.id === id);
    if (!node) return;

    if (node.type === 'SWITCH' || node.type === 'BUTTON') {
        const toggledNodes = circuit.nodes.map(n => {
            if (n.id === id) {
                const newState = !n.outputs[0];
                return { ...n, outputs: [newState] };
            }
            return n;
        });
        updateCircuit(toggledNodes, circuit.wires);
        return; 
    }

    setDraggingNodeId(id);

    const rect = containerRef.current!.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    setDragOffset({
        x: mouseX - node.position.x,
        y: mouseY - node.position.y
    });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    if (draggingNodeId) {
        const snapX = Math.round((x - dragOffset.x) / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round((y - dragOffset.y) / GRID_SIZE) * GRID_SIZE;

        const updatedNodes = circuit.nodes.map(n => {
            if (n.id === draggingNodeId) {
                return { ...n, position: { x: snapX, y: snapY }};
            }
            return n;
        });
        setCircuit(prev => ({ ...prev, nodes: updatedNodes }));
    }
  };

  const handleMouseUp = () => {
    if (draggingNodeId) {
        setDraggingNodeId(null);
        updateCircuit(circuit.nodes, circuit.wires); 
    }
    if (wiring) {
        setWiring(null);
    }
  };

  const startWiring = (e: React.MouseEvent, nodeId: string, outputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setWiring({
        sourceNodeId: nodeId,
        sourceOutputIndex: outputIndex,
        startPoint: { x, y },
        active: true
    });
  };

  const completeWiring = (e: React.MouseEvent, targetNodeId: string, inputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();

    if (!wiring) return;

    if (wiring.sourceNodeId === targetNodeId) {
        setWiring(null);
        return;
    }

    const exists = circuit.wires.some(w => 
        w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex
    );

    let newWires = exists 
        ? circuit.wires.filter(w => !(w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex))
        : [...circuit.wires];

    newWires.push({
        id: `wire-${Date.now()}`,
        sourceNodeId: wiring.sourceNodeId,
        sourceOutputIndex: wiring.sourceOutputIndex,
        targetNodeId: targetNodeId,
        targetInputIndex: inputIndex,
        state: false
    });

    updateCircuit(circuit.nodes, newWires);
    setWiring(null);
  };

  // --- Render Helpers ---

  const getBezierPath = (x1: number, y1: number, x2: number, y2: number) => {
    const dist = Math.abs(x2 - x1);
    const controlPointOffset = Math.max(dist * 0.5, 50);
    return `M ${x1} ${y1} C ${x1 + controlPointOffset} ${y1}, ${x2 - controlPointOffset} ${y2}, ${x2} ${y2}`;
  };

  const selectedNode = circuit.nodes.find(n => n.id === selectedId) || null;

  return (
    <div className="flex-1 h-full relative bg-zinc-950 flex flex-row overflow-hidden">
        {/* Main Canvas Area */}
        <div className="flex-1 flex flex-col relative h-full overflow-hidden">
             {/* Toolbar */}
            <div className="h-14 border-b border-zinc-800 bg-zinc-900/50 flex items-center px-6 justify-between z-20 backdrop-blur-sm shrink-0">
                <div className="flex items-center space-x-4">
                    <button 
                        onClick={() => setCircuit({ nodes: [], wires: [] })}
                        className="flex items-center space-x-2 px-3 py-1.5 bg-zinc-800 hover:bg-red-900/30 hover:text-red-400 text-zinc-300 rounded-md text-xs font-medium transition-colors border border-zinc-700 hover:border-red-800"
                    >
                        <Trash2 size={14} />
                        <span>Clear Board</span>
                    </button>
                    <div className="h-4 w-px bg-zinc-700 mx-2"></div>
                    <div className="text-zinc-500 text-xs flex items-center space-x-2">
                        <MousePointer2 size={14} />
                        <span>Left click to toggle switches / drag nodes</span>
                    </div>
                </div>
                {selectedId && (
                    <button 
                    onClick={deleteSelection}
                    className="flex items-center space-x-2 px-3 py-1.5 bg-red-500/10 text-red-400 hover:bg-red-500/20 border border-red-500/30 rounded-md text-xs font-medium transition-colors"
                >
                    <X size={14} />
                    <span>Delete Selected</span>
                </button>
                )}
            </div>

            <div 
                ref={containerRef}
                className="flex-1 relative w-full h-full overflow-hidden cursor-crosshair"
                onDragOver={handleDragOver}
                onDrop={handleDrop}
                onMouseMove={handleMouseMove}
                onMouseUp={handleMouseUp}
                onClick={() => setSelectedId(null)}
            >
                {/* Grid Pattern */}
                <svg className="absolute inset-0 pointer-events-none w-full h-full opacity-20">
                    <defs>
                        <pattern id="grid" width={GRID_SIZE} height={GRID_SIZE} patternUnits="userSpaceOnUse">
                            <circle cx="1" cy="1" r="1" fill="#71717a" />
                        </pattern>
                    </defs>
                    <rect width="100%" height="100%" fill="url(#grid)" />
                </svg>

                {/* Connections */}
                <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
                    {circuit.wires.map(wire => {
                        const sourceNode = circuit.nodes.find(n => n.id === wire.sourceNodeId);
                        const targetNode = circuit.nodes.find(n => n.id === wire.targetNodeId);
                        if (!sourceNode || !targetNode) return null;

                        const sourcePorts = getOutputPorts(sourceNode);
                        const targetPorts = getInputPorts(targetNode);

                        const outputOffset = sourcePorts[wire.sourceOutputIndex] || { x: 0, y: 0 };
                        const inputOffset = targetPorts[wire.targetInputIndex] || { x: 0, y: 0 };

                        const startX = sourceNode.position.x + outputOffset.x;
                        const startY = sourceNode.position.y + outputOffset.y;
                        const endX = targetNode.position.x + inputOffset.x;
                        const endY = targetNode.position.y + inputOffset.y;

                        const isSelected = selectedId === wire.id;

                        return (
                            <g key={wire.id} onClick={(e) => { e.stopPropagation(); setSelectedId(wire.id); }} className="pointer-events-auto cursor-pointer group">
                                <path d={getBezierPath(startX, startY, endX, endY)} stroke="transparent" strokeWidth="12" fill="none" />
                                {wire.state && <path d={getBezierPath(startX, startY, endX, endY)} stroke="#22d3ee" strokeWidth="4" fill="none" opacity="0.3" filter="blur(2px)" />}
                                <path d={getBezierPath(startX, startY, endX, endY)} stroke={wire.state ? "#22d3ee" : "#52525b"} strokeWidth={isSelected ? "3" : "2"} fill="none" className="transition-colors duration-150" strokeDasharray={isSelected ? "4" : "0"} />
                            </g>
                        );
                    })}

                    {wiring && (
                        <path d={getBezierPath(wiring.startPoint.x, wiring.startPoint.y, mousePos.x, mousePos.y)} stroke="#fbbf24" strokeWidth="2" fill="none" strokeDasharray="4" className="animate-pulse" />
                    )}
                </svg>

                {/* Nodes */}
                {circuit.nodes.map(node => {
                    const { width, height } = getNodeDimensions(node);
                    const isSelected = selectedId === node.id;
                    const inputPorts = getInputPorts(node);
                    const outputPorts = getOutputPorts(node);
                    const def = NODE_DEFINITIONS[node.type];

                    return (
                        <div
                            key={node.id}
                            className={`absolute group select-none`}
                            style={{
                                left: node.position.x,
                                top: node.position.y,
                                width: width,
                                height: height,
                                pointerEvents: 'none' 
                            }}
                        >
                            <div 
                                className={`absolute inset-0 pointer-events-auto transition-all duration-200 ${isSelected ? 'drop-shadow-[0_0_8px_rgba(34,211,238,0.5)]' : ''}`}
                                onMouseDown={(e) => handleNodeMouseDown(e, node.id)}
                            >
                                <svg width={width} height={height} className="overflow-visible">
                                    <GateShape node={node} />
                                </svg>
                            </div>

                            {inputPorts.map((offset, idx) => (
                                <div
                                    key={`input-${idx}`}
                                    className="absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform cursor-crosshair z-10"
                                    style={{ left: offset.x, top: offset.y }}
                                    onMouseUp={(e) => completeWiring(e, node.id, idx)}
                                    title={offset.label || "Input"}
                                >
                                    <div className={`w-2 h-2 rounded-full bg-zinc-900 border ${node.inputs[idx] ? 'border-cyan-400 bg-cyan-900' : 'border-zinc-500'}`} />
                                </div>
                            ))}

                            {outputPorts.map((offset, idx) => (
                                <div
                                    key={`output-${idx}`}
                                    className="absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform cursor-crosshair z-10"
                                    style={{ left: offset.x, top: offset.y }}
                                    onMouseDown={(e) => startWiring(e, node.id, idx)}
                                    title={offset.label || "Output"}
                                >
                                    <div className={`w-2 h-2 rounded-full bg-zinc-900 border ${node.outputs[idx] ? 'border-cyan-400 bg-cyan-500' : 'border-zinc-500 group-hover:border-zinc-300'}`} />
                                </div>
                            ))}

                            {/* Label */}
                            {(isSelected || node.properties?.label) && (
                                <div className="absolute -top-6 left-1/2 -translate-x-1/2 bg-zinc-800 text-zinc-300 text-[10px] px-2 py-0.5 rounded border border-zinc-700 whitespace-nowrap z-50 pointer-events-none">
                                    {node.properties?.label || def.name}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </div>

        {/* Properties Panel (Right Side) */}
        <PropertiesPanel node={selectedNode} onUpdate={handleNodeUpdate} />
    </div>
  );
};

import React, { useRef, useState, useEffect } from 'react';
import { GRID_SIZE, NODE_DEFINITIONS } from '../constants';
import { CircuitState, NodeData, NodeType, Wire, Point, WiringState } from '../types';
import { GateShape } from './GateShapes';
import { evaluateCircuit } from '../utils/circuitLogic';
import { getNodeDimensions, getInputPorts, getOutputPorts } from '../utils/componentUtils';
import { PropertiesPanel } from './PropertiesPanel';
import { X, Trash2, MousePointer2, Hand, Move } from 'lucide-react';

export const CircuitCanvas: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [circuit, setCircuit] = useState<CircuitState>({ nodes: [], wires: [] });

  // Interaction State
  const [toolMode, setToolMode] = useState<'select' | 'interact'>('select');
  const [draggingNodeId, setDraggingNodeId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<Point>({ x: 0, y: 0 });
  const [wiring, setWiring] = useState<WiringState | null>(null);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });
  const [selectedId, setSelectedId] = useState<string | null>(null); 

  // --- Clock Simulation ---
  useEffect(() => {
    const interval = setInterval(() => {
        setCircuit(prev => {
            const hasClock = prev.nodes.some(n => n.type === 'CLOCK');
            if (!hasClock) return prev;

            const nextNodes = prev.nodes.map(n => {
                if (n.type === 'CLOCK') {
                    return { ...n, outputs: [!n.outputs[0]] };
                }
                return n;
            });
            return evaluateCircuit(nextNodes, prev.wires);
        });
    }, 1000); 
    return () => clearInterval(interval);
  }, []);

  // --- Logic Helpers ---
  const updateCircuit = (newNodes: NodeData[], newWires: Wire[]) => {
    const evaluated = evaluateCircuit(newNodes, newWires);
    setCircuit(evaluated);
  };

  const handleNodeUpdate = (id: string, updates: Partial<NodeData>) => {
    setCircuit(prev => {
        const newNodes = prev.nodes.map(n => {
            if (n.id === id) {
                const updatedNode = { ...n, ...updates };

                // Handle resizing inputs
                if (updates.properties?.inputCount) {
                    const count = updates.properties.inputCount;
                    if (count > updatedNode.inputs.length) {
                        updatedNode.inputs = [...updatedNode.inputs, ...Array(count - updatedNode.inputs.length).fill(false)];
                    } else if (count < updatedNode.inputs.length) {
                        updatedNode.inputs = updatedNode.inputs.slice(0, count);
                    }
                }

                // Handle Initial State changes for Switch/Constant directly impacting output
                if (updates.properties?.initialState !== undefined) {
                    if (['SWITCH', 'CONSTANT_1', 'CONSTANT_0'].includes(updatedNode.type)) {
                         updatedNode.outputs = [!!updates.properties.initialState];
                    }
                    // For Flip-Flops, we might want to update internal state if simulation hasn't really started or just force it
                    if (['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'D_LATCH'].includes(updatedNode.type)) {
                        updatedNode.internalState = {
                            ...updatedNode.internalState,
                            storedValue: !!updates.properties.initialState
                        };
                        updatedNode.outputs = [!!updates.properties.initialState, !updates.properties.initialState];
                    }
                }

                return updatedNode;
            }
            return n;
        });

        return evaluateCircuit(newNodes, prev.wires);
    });
  };

  const addNode = (type: NodeType, x: number, y: number) => {
    const def = NODE_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newNode: NodeData = {
      id: `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      position: { x: snapX, y: snapY },
      inputs: Array(def.inputs).fill(false),
      outputs: Array(def.outputs).fill(false),
      internalState: {},
      properties: {
          label: '',
          inputCount: def.inputs,
          propagationDelay: 0,
          initialState: false
      }
    };

    updateCircuit([...circuit.nodes, newNode], circuit.wires);
    setSelectedId(newNode.id);
    setToolMode('select'); // Auto-switch to select when placing to allow adjustment
  };

  const deleteSelection = () => {
    if (!selectedId) return;

    const isWire = circuit.wires.find(w => w.id === selectedId);
    if (isWire) {
      updateCircuit(circuit.nodes, circuit.wires.filter(w => w.id !== selectedId));
      setSelectedId(null);
      return;
    }

    const newWires = circuit.wires.filter(w => w.sourceNodeId !== selectedId && w.targetNodeId !== selectedId);
    const newNodes = circuit.nodes.filter(n => n.id !== selectedId);
    updateCircuit(newNodes, newWires);
    setSelectedId(null);
  };

  // --- Interaction Handlers ---

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); 
    e.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const type = e.dataTransfer.getData('application/react-circuit-node') as NodeType;

    if (!type || !containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    addNode(type, x, y);
  };

  const handleNodeMouseDown = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (wiring) return;

    setSelectedId(id);
    const node = circuit.nodes.find(n => n.id === id);
    if (!node) return;

    // Interaction Mode Logic
    const isInteractive = ['SWITCH', 'BUTTON'].includes(node.type);

    if (toolMode === 'interact' && isInteractive) {
        const toggledNodes = circuit.nodes.map(n => {
            if (n.id === id) {
                const newState = !n.outputs[0];
                return { ...n, outputs: [newState] };
            }
            return n;
        });
        updateCircuit(toggledNodes, circuit.wires);
        return; 
    }

    // Select/Move Mode Logic
    setDraggingNodeId(id);
    const rect = containerRef.current!.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    setDragOffset({
        x: mouseX - node.position.x,
        y: mouseY - node.position.y
    });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    if (draggingNodeId) {
        const snapX = Math.round((x - dragOffset.x) / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round((y - dragOffset.y) / GRID_SIZE) * GRID_SIZE;

        const updatedNodes = circuit.nodes.map(n => {
            if (n.id === draggingNodeId) {
                return { ...n, position: { x: snapX, y: snapY }};
            }
            return n;
        });
        setCircuit(prev => ({ ...prev, nodes: updatedNodes }));
    }
  };

  const handleMouseUp = () => {
    if (draggingNodeId) {
        setDraggingNodeId(null);
        updateCircuit(circuit.nodes, circuit.wires); 
    }
    if (wiring) {
        setWiring(null);
    }
  };

  const startWiring = (e: React.MouseEvent, nodeId: string, outputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();
    if (toolMode === 'interact') return; // Prevent wiring in interact mode

    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setWiring({
        sourceNodeId: nodeId,
        sourceOutputIndex: outputIndex,
        startPoint: { x, y },
        active: true
    });
  };

  const completeWiring = (e: React.MouseEvent, targetNodeId: string, inputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();

    if (!wiring) return;

    if (wiring.sourceNodeId === targetNodeId) {
        setWiring(null);
        return;
    }

    const exists = circuit.wires.some(w => 
        w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex
    );

    let newWires = exists 
        ? circuit.wires.filter(w => !(w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex))
        : [...circuit.wires];

    newWires.push({
        id: `wire-${Date.now()}`,
        sourceNodeId: wiring.sourceNodeId,
        sourceOutputIndex: wiring.sourceOutputIndex,
        targetNodeId: targetNodeId,
        targetInputIndex: inputIndex,
        state: false
    });

    updateCircuit(circuit.nodes, newWires);
    setWiring(null);
  };

  // --- Render Helpers ---
  const getBezierPath = (x1: number, y1: number, x2: number, y2: number) => {
    const dist = Math.abs(x2 - x1);
    const controlPointOffset = Math.max(dist * 0.5, 50);
    return `M ${x1} ${y1} C ${x1 + controlPointOffset} ${y1}, ${x2 - controlPointOffset} ${y2}, ${x2} ${y2}`;
  };

  const selectedNode = circuit.nodes.find(n => n.id === selectedId) || null;

  return (
    <div className="flex-1 h-full relative bg-zinc-950 flex flex-row overflow-hidden">
        {/* Main Canvas Area */}
        <div className="flex-1 flex flex-col relative h-full overflow-hidden">
             {/* Toolbar */}
            <div className="h-14 border-b border-zinc-800 bg-zinc-900/50 flex items-center px-6 justify-between z-20 backdrop-blur-sm shrink-0">
                <div className="flex items-center space-x-4">
                     {/* Tool Mode Switcher */}
                     <div className="flex items-center bg-zinc-800 rounded-md p-0.5 border border-zinc-700">
                        <button 
                            onClick={() => setToolMode('select')}
                            className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-medium transition-colors ${toolMode === 'select' ? 'bg-zinc-700 text-white shadow-sm' : 'text-zinc-400 hover:text-zinc-200'}`}
                            title="Select / Move Mode"
                        >
                            <Move size={14} />
                            <span>Select</span>
                        </button>
                        <button 
                            onClick={() => setToolMode('interact')}
                            className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-medium transition-colors ${toolMode === 'interact' ? 'bg-cyan-900/50 text-cyan-400 border border-cyan-800/50 shadow-sm' : 'text-zinc-400 hover:text-zinc-200'}`}
                            title="Interact / Experiment Mode"
                        >
                            <Hand size={14} />
                            <span>Interact</span>
                        </button>
                     </div>

                    <div className="h-4 w-px bg-zinc-700 mx-2"></div>

                    <button 
                        onClick={() => setCircuit({ nodes: [], wires: [] })}
                        className="flex items-center space-x-2 px-3 py-1.5 bg-zinc-800 hover:bg-red-900/30 hover:text-red-400 text-zinc-300 rounded-md text-xs font-medium transition-colors border border-zinc-700 hover:border-red-800"
                    >
                        <Trash2 size={14} />
                        <span>Clear</span>
                    </button>
                </div>

                <div className="flex items-center space-x-4">
                     <div className="text-zinc-500 text-xs flex items-center space-x-2">
                        <MousePointer2 size={14} />
                        <span>{toolMode === 'select' ? 'Drag to move • Properties on right' : 'Click switches to toggle'}</span>
                     </div>

                     {selectedId && (
                        <button 
                        onClick={deleteSelection}
                        className="flex items-center space-x-2 px-3 py-1.5 bg-red-500/10 text-red-400 hover:bg-red-500/20 border border-red-500/30 rounded-md text-xs font-medium transition-colors"
                        >
                        <X size={14} />
                        <span>Delete</span>
                    </button>
                    )}
                </div>
            </div>

            <div 
                ref={containerRef}
                className={`flex-1 relative w-full h-full overflow-hidden ${toolMode === 'interact' ? 'cursor-default' : 'cursor-crosshair'}`}
                onDragOver={handleDragOver}
                onDrop={handleDrop}
                onMouseMove={handleMouseMove}
                onMouseUp={handleMouseUp}
                onClick={() => setSelectedId(null)}
            >
                {/* Grid Pattern */}
                <svg className="absolute inset-0 pointer-events-none w-full h-full opacity-20">
                    <defs>
                        <pattern id="grid" width={GRID_SIZE} height={GRID_SIZE} patternUnits="userSpaceOnUse">
                            <circle cx="1" cy="1" r="1" fill="#71717a" />
                        </pattern>
                    </defs>
                    <rect width="100%" height="100%" fill="url(#grid)" />
                </svg>

                {/* Connections */}
                <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
                    {circuit.wires.map(wire => {
                        const sourceNode = circuit.nodes.find(n => n.id === wire.sourceNodeId);
                        const targetNode = circuit.nodes.find(n => n.id === wire.targetNodeId);
                        if (!sourceNode || !targetNode) return null;

                        const sourcePorts = getOutputPorts(sourceNode);
                        const targetPorts = getInputPorts(targetNode);

                        const outputOffset = sourcePorts[wire.sourceOutputIndex] || { x: 0, y: 0 };
                        const inputOffset = targetPorts[wire.targetInputIndex] || { x: 0, y: 0 };

                        const startX = sourceNode.position.x + outputOffset.x;
                        const startY = sourceNode.position.y + outputOffset.y;
                        const endX = targetNode.position.x + inputOffset.x;
                        const endY = targetNode.position.y + inputOffset.y;

                        const isSelected = selectedId === wire.id;

                        return (
                            <g key={wire.id} onClick={(e) => { e.stopPropagation(); setSelectedId(wire.id); }} className={`pointer-events-auto cursor-pointer group`}>
                                <path d={getBezierPath(startX, startY, endX, endY)} stroke="transparent" strokeWidth="12" fill="none" />
                                {wire.state && <path d={getBezierPath(startX, startY, endX, endY)} stroke="#22d3ee" strokeWidth="4" fill="none" opacity="0.3" filter="blur(2px)" />}
                                <path d={getBezierPath(startX, startY, endX, endY)} stroke={wire.state ? "#22d3ee" : "#52525b"} strokeWidth={isSelected ? "3" : "2"} fill="none" className="transition-colors duration-150" strokeDasharray={isSelected ? "4" : "0"} />
                            </g>
                        );
                    })}

                    {wiring && (
                        <path d={getBezierPath(wiring.startPoint.x, wiring.startPoint.y, mousePos.x, mousePos.y)} stroke="#fbbf24" strokeWidth="2" fill="none" strokeDasharray="4" className="animate-pulse" />
                    )}
                </svg>

                {/* Nodes */}
                {circuit.nodes.map(node => {
                    const { width, height } = getNodeDimensions(node);
                    const isSelected = selectedId === node.id;
                    const inputPorts = getInputPorts(node);
                    const outputPorts = getOutputPorts(node);
                    const def = NODE_DEFINITIONS[node.type];
                    const canInteract = ['SWITCH', 'BUTTON'].includes(node.type);

                    return (
                        <div
                            key={node.id}
                            className={`absolute group select-none`}
                            style={{
                                left: node.position.x,
                                top: node.position.y,
                                width: width,
                                height: height,
                                pointerEvents: 'none' 
                            }}
                        >
                            <div 
                                className={`absolute inset-0 pointer-events-auto transition-all duration-200 
                                    ${isSelected ? 'drop-shadow-[0_0_8px_rgba(34,211,238,0.5)]' : ''} 
                                    ${toolMode === 'interact' && canInteract ? 'cursor-pointer' : 'cursor-grab active:cursor-grabbing'}
                                `}
                                onMouseDown={(e) => handleNodeMouseDown(e, node.id)}
                            >
                                <svg width={width} height={height} className="overflow-visible">
                                    <GateShape node={node} />
                                </svg>
                            </div>

                            {/* Ports only interactive in Select Mode to avoid clutter during Interaction */}
                            {inputPorts.map((offset, idx) => (
                                <div
                                    key={`input-${idx}`}
                                    className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 ${toolMode === 'select' ? 'cursor-crosshair' : 'cursor-default'}`}
                                    style={{ left: offset.x, top: offset.y }}
                                    onMouseUp={(e) => toolMode === 'select' && completeWiring(e, node.id, idx)}
                                    title={offset.label || "Input"}
                                >
                                    <div className={`w-2 h-2 rounded-full bg-zinc-900 border ${node.inputs[idx] ? 'border-cyan-400 bg-cyan-900' : 'border-zinc-500'}`} />
                                </div>
                            ))}

                            {outputPorts.map((offset, idx) => (
                                <div
                                    key={`output-${idx}`}
                                    className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 ${toolMode === 'select' ? 'cursor-crosshair' : 'cursor-default'}`}
                                    style={{ left: offset.x, top: offset.y }}
                                    onMouseDown={(e) => toolMode === 'select' && startWiring(e, node.id, idx)}
                                    title={offset.label || "Output"}
                                >
                                    <div className={`w-2 h-2 rounded-full bg-zinc-900 border ${node.outputs[idx] ? 'border-cyan-400 bg-cyan-500' : 'border-zinc-500 group-hover:border-zinc-300'}`} />
                                </div>
                            ))}

                            {/* Label */}
                            {(isSelected || node.properties?.label) && (
                                <div className="absolute -top-6 left-1/2 -translate-x-1/2 bg-zinc-800 text-zinc-300 text-[10px] px-2 py-0.5 rounded border border-zinc-700 whitespace-nowrap z-50 pointer-events-none">
                                    {node.properties?.label || def.name}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </div>

        {/* Properties Panel (Right Side) */}
        <PropertiesPanel node={selectedNode} onUpdate={handleNodeUpdate} />
    </div>
  );
};

import React from 'react';
import { NodeData } from '../types';
import { Settings2 } from 'lucide-react';
import { VARIABLE_INPUT_GATES } from '../utils/componentUtils';

interface PropertiesPanelProps {
  node: NodeData | null;
  onUpdate: (id: string, updates: Partial<NodeData>) => void;
}

export const PropertiesPanel: React.FC<PropertiesPanelProps> = ({ node, onUpdate }) => {
  if (!node) {
    return (
      <div className="w-64 bg-zinc-900 border-l border-zinc-800 p-6 flex flex-col items-center justify-center text-zinc-500 h-full select-none">
         <Settings2 size={32} className="mb-3 opacity-50" />
         <p className="text-sm font-medium">Select a component</p>
         <p className="text-xs text-zinc-600 text-center mt-1">Click on any component on the canvas to view and edit its properties.</p>
      </div>
    );
  }

  const isGate = VARIABLE_INPUT_GATES.includes(node.type) || ['BUFFER', 'NOT'].includes(node.type);
  const isStateful = ['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'D_LATCH'].includes(node.type);
  const isSwitch = ['SWITCH'].includes(node.type);

  const handleLabelChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      onUpdate(node.id, { properties: { ...node.properties, label: e.target.value } });
  };

  const handleInputCountChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      const count = parseInt(e.target.value, 10);
      onUpdate(node.id, { 
          properties: { ...node.properties, inputCount: count }
      });
  };

  const handleDelayChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const delay = Math.max(0, parseInt(e.target.value, 10) || 0);
      onUpdate(node.id, {
          properties: { ...node.properties, propagationDelay: delay }
      });
  };

  const handleInitialStateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      onUpdate(node.id, {
          properties: { ...node.properties, initialState: e.target.checked }
      });
  };

  return (
    <div className="w-64 bg-zinc-900 border-l border-zinc-800 flex flex-col h-full shadow-xl">
       <div className="p-4 border-b border-zinc-800 flex items-center space-x-2">
          <div className="w-6 h-6 rounded bg-cyan-900/50 flex items-center justify-center">
             <Settings2 size={14} className="text-cyan-400" />
          </div>
          <span className="font-semibold text-sm text-zinc-200">Component Properties</span>
       </div>

       <div className="p-4 space-y-6 overflow-y-auto flex-1">
          {/* General Section */}
          <div className="space-y-3">
             <div className="text-xs font-bold text-zinc-500 uppercase tracking-wider">General</div>

             <div className="space-y-1">
                <label className="text-xs text-zinc-400">Type</label>
                <div className="w-full bg-zinc-800 border border-zinc-700 rounded px-3 py-2 text-sm text-zinc-300 font-mono">
                    {node.type}
                </div>
             </div>

             <div className="space-y-1">
                <label className="text-xs text-zinc-400">Label</label>
                <input 
                    type="text" 
                    value={node.properties?.label || ''} 
                    onChange={handleLabelChange}
                    placeholder="Component Name..."
                    className="w-full bg-zinc-950 border border-zinc-700 rounded px-3 py-2 text-sm text-zinc-200 focus:border-cyan-500 focus:outline-none transition-colors"
                />
             </div>
          </div>

          <div className="h-px bg-zinc-800" />

          {/* Attributes Section */}
          <div className="space-y-3">
             <div className="text-xs font-bold text-zinc-500 uppercase tracking-wider">Attributes</div>

             {/* Dynamic Inputs for Gates */}
             {VARIABLE_INPUT_GATES.includes(node.type) && (
                 <div className="space-y-1">
                    <label className="text-xs text-zinc-400">Number of Inputs</label>
                    <select 
                        value={node.properties?.inputCount || 2}
                        onChange={handleInputCountChange}
                        className="w-full bg-zinc-950 border border-zinc-700 rounded px-3 py-2 text-sm text-zinc-200 focus:border-cyan-500 focus:outline-none"
                    >
                        {[2,3,4,5,6,8].map(n => (
                            <option key={n} value={n}>{n} Inputs</option>
                        ))}
                    </select>
                 </div>
             )}

             {/* Propagation Delay for Logic Gates */}
             {isGate && (
                 <div className="space-y-1">
                     <label className="text-xs text-zinc-400">Propagation Delay (ms)</label>
                     <input 
                        type="number"
                        value={node.properties?.propagationDelay || 0}
                        onChange={handleDelayChange}
                        className="w-full bg-zinc-950 border border-zinc-700 rounded px-3 py-2 text-sm text-zinc-200 focus:border-cyan-500 focus:outline-none"
                     />
                     <p className="text-[10px] text-zinc-600">Simulated logic delay.</p>
                 </div>
             )}

             {/* Initial State for Switches or Flip Flops */}
             {(isStateful || isSwitch) && (
                 <div className="flex items-center justify-between bg-zinc-950 border border-zinc-700 rounded px-3 py-2">
                     <label className="text-xs text-zinc-400">Initial State (High)</label>
                     <input 
                        type="checkbox"
                        checked={!!node.properties?.initialState}
                        onChange={handleInitialStateChange}
                        className="w-4 h-4 rounded border-zinc-600 bg-zinc-800 text-cyan-500 focus:ring-0 focus:ring-offset-0"
                     />
                 </div>
             )}

             {!isGate && !isStateful && !isSwitch && (
                <div className="text-xs text-zinc-600 italic">
                    No configurable attributes.
                </div>
             )}
          </div>
       </div>

       <div className="p-4 border-t border-zinc-800 text-xs text-zinc-600 text-center">
           ID: <span className="font-mono text-zinc-700">{node.id.split('-')[1]}...</span>
       </div>
    </div>
  );
};

export type NodeType = 
  | 'AND' | 'OR' | 'NOT' | 'XOR' | 'NAND' | 'NOR' | 'XNOR' | 'BUFFER'
  | 'SWITCH' | 'BULB' | 'CLOCK' | 'BUTTON' | 'CONSTANT_1' | 'CONSTANT_0'
  | 'HALF_ADDER' | 'FULL_ADDER' | 'SUBTRACTOR' | 'COMPARATOR_1BIT'
  | 'D_LATCH' | 'D_FF' | 'JK_FF' | 'T_FF' | 'SR_FF'
  | 'GATED_SR_LATCH' | 'JK_MASTER_SLAVE' | 'RAM_1BIT' | 'ROM_1BIT' | 'SHIFT_REGISTER_4BIT'
  | 'MUX_2_1' | 'MUX_4_1' | 'DEMUX_1_2' | 'DEMUX_1_4'
  | 'DECODER_2_4' | 'PRIORITY_ENCODER_4_2'
  | 'HEX_DISPLAY' | 'SEVEN_SEGMENT';

export interface Point {
  x: number;
  y: number;
}

export interface Port {
  id: string;
  type: 'input' | 'output';
  offset: Point;
  label?: string;
}

export interface NodeData {
  id: string;
  type: NodeType;
  position: Point;
  inputs: boolean[];
  outputs: boolean[];
  // Used for stateful components like Flip-Flops to detect edges
  internalState?: {
    lastClock?: boolean;
    storedValue?: boolean;
    masterValue?: boolean; // For Master-Slave
    register?: boolean[]; // For Shift Register
    [key: string]: any;
  };
  // Customizable properties
  properties?: {
    label?: string;
    inputCount?: number;
    propagationDelay?: number;
    initialState?: boolean;
    romValue?: boolean; // For ROM
    [key: string]: any;
  };
}

export interface Wire {
  id: string;
  sourceNodeId: string;
  sourceOutputIndex: number;
  targetNodeId: string;
  targetInputIndex: number;
  state: boolean;
}

export interface CircuitState {
  nodes: NodeData[];
  wires: Wire[];
}

export interface WiringState {
  sourceNodeId: string;
  sourceOutputIndex: number;
  startPoint: Point;
  active: boolean;
}

