import React from 'react';
import { NodeData } from '../types';
import { getNodeDimensions } from '../utils/componentUtils';

interface GateShapeProps {
  node: NodeData;
}

export const GateShape: React.FC<GateShapeProps> = ({ node }) => {
  const type = node.type;
  // Usually output[0] is the primary active state for coloring, but for complex nodes we stick to neutral unless specified.
  const active = node.outputs[0]; 
  const strokeColor = active ? "#22d3ee" : "#71717a"; 
  const fillColor = "#18181b"; 
  const activeFill = active ? "#0ea5e9" : "#18181b"; 
  const { width, height } = getNodeDimensions(node);

  const Text = ({ x, y, children }: { x: number, y: number, children: string }) => (
    <text x={x} y={y} textAnchor="middle" dominantBaseline="middle" fill="#71717a" fontSize="10" fontWeight="bold" className="pointer-events-none select-none">
      {children}
    </text>
  );

  // Dynamic path generation for variable inputs
  const getGatePath = (gateType: 'AND' | 'OR' | 'NAND' | 'NOR' | 'XOR' | 'XNOR') => {
     // Control point offset for OR/XOR curves
     const curve = width * 0.6; 

     switch (gateType) {
         case 'AND': 
         case 'NAND':
             // Straight back, curved front
             return `M 0 0 L ${width/2} 0 A ${height/2} ${height/2} 0 0 1 ${width/2} ${height} L 0 ${height} Z`;

         case 'OR':
         case 'NOR':
             // Curved back, curved front (pointed)
             return `M 0 0 Q ${width*0.25} ${height/2} 0 ${height} Q ${width*0.8} ${height} ${width} ${height/2} Q ${width*0.8} 0 0 0 Z`;

         case 'XOR':
         case 'XNOR':
              // Similar to OR but with the extra back line (which we usually draw separately, but here we approximate the main body)
             return `M 10 0 Q ${width*0.35} ${height/2} 10 ${height} Q ${width*0.9} ${height} ${width} ${height/2} Q ${width*0.9} 0 10 0 Z`;
     }
  };

  switch (type) {
    // --- Dynamic Gates ---
    case 'AND':
      return <path d={getGatePath('AND')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />;
    case 'NAND':
      return (
        <g>
          <path d={getGatePath('NAND')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <circle cx={width} cy={height/2} r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case 'OR':
      return <path d={getGatePath('OR')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />
    case 'NOR':
      return (
        <g>
          <path d={getGatePath('OR')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <circle cx={width} cy={height/2} r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case 'XOR':
      return (
        <g>
          <path d={getGatePath('XOR')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <path d={`M -5 0 Q ${width*0.20} ${height/2} -5 ${height}`} fill="none" stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case 'XNOR':
      return (
        <g>
          <path d={getGatePath('XOR')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <path d={`M -5 0 Q ${width*0.20} ${height/2} -5 ${height}`} fill="none" stroke={strokeColor} strokeWidth="2" />
          <circle cx={width} cy={height/2} r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
        </g>
      );

    case 'NOT':
      return (
        <g>
          <path d="M 0 0 L 35 20 L 0 40 Z" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <circle cx="40" cy="20" r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case 'BUFFER':
        return <path d="M 0 0 L 30 20 L 0 40 Z" fill={fillColor} stroke={strokeColor} strokeWidth="2" />;

    // --- Constants ---
    case 'CONSTANT_1':
        return (
            <g>
                <rect x="0" y="0" width="30" height="30" rx="2" fill={fillColor} stroke="#22d3ee" strokeWidth="2" />
                <text x="15" y="15" textAnchor="middle" dominantBaseline="middle" fill="#22d3ee" fontSize="14" fontWeight="bold">1</text>
            </g>
        );
    case 'CONSTANT_0':
        return (
            <g>
                <rect x="0" y="0" width="30" height="30" rx="2" fill={fillColor} stroke="#52525b" strokeWidth="2" />
                <text x="15" y="15" textAnchor="middle" dominantBaseline="middle" fill="#71717a" fontSize="14" fontWeight="bold">0</text>
            </g>
        );

    // --- Logic ---
    case 'JUNCTION':
        return <circle cx="5" cy="5" r="5" fill={active ? "#22d3ee" : "#71717a"} />;

    // --- IO ---
    case 'SWITCH':
      return (
        <g>
          <rect x="0" y="0" width="40" height="40" rx="4" fill={activeFill} stroke={strokeColor} strokeWidth="2" />
          <text x="20" y="25" textAnchor="middle" fill={active ? "#fff" : "#a1a1aa"} fontSize="12" fontWeight="bold">{active ? "1" : "0"}</text>
        </g>
      );
    case 'BUTTON':
        return (
          <g>
            <circle cx="20" cy="20" r="15" fill={active ? "#22c55e" : "#3f3f46"} stroke={strokeColor} strokeWidth="2" />
            <circle cx="20" cy="20" r="10" fill={active ? "#16a34a" : "#18181b"} />
          </g>
        );
    case 'CLOCK':
        return (
            <g>
                <rect x="0" y="0" width="40" height="40" rx="4" fill="#18181b" stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <path d="M 10 20 L 15 20 L 15 10 L 25 10 L 25 30 L 35 30" fill="none" stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
            </g>
        );
    case 'BULB':
      return (
        <g>
          <circle cx="20" cy="20" r="15" fill={node.inputs[0] ? "#fbbf24" : "#27272a"} stroke={node.inputs[0] ? "#f59e0b" : "#52525b"} strokeWidth="2" style={{ filter: node.inputs[0] ? 'drop-shadow(0 0 8px #fbbf24)' : 'none'}} />
        </g>
      );
    case 'HEX_DISPLAY':
        // Decode 4 inputs to Hex char
        const val = (node.inputs[0]?1:0) + (node.inputs[1]?2:0) + (node.inputs[2]?4:0) + (node.inputs[3]?8:0);
        const hexChar = val.toString(16).toUpperCase();
        return (
            <g>
                <rect x="0" y="0" width="60" height="80" fill="#000" stroke="#3f3f46" strokeWidth="4" />
                <text x="30" y="45" textAnchor="middle" dominantBaseline="middle" fill="#ef4444" fontSize="40" fontFamily="monospace" style={{ filter: 'drop-shadow(0 0 4px #ef4444)'}}>
                    {hexChar}
                </text>
            </g>
        );
    case 'SEVEN_SEGMENT':
        // a,b,c,d,e,f,g,dp
        const [a, b, c, d, e, f, g, dp] = node.inputs;
        const segOn = "#ef4444";
        const segOff = "#27272a";
        const segStyle = (on: boolean) => ({ fill: on ? segOn : segOff, filter: on ? 'drop-shadow(0 0 2px #ef4444)' : 'none' });

        return (
            <g>
                <rect x="0" y="0" width="70" height="100" fill="#000" stroke="#3f3f46" strokeWidth="4" />

                {/* A */}
                <path d="M 15 10 L 55 10 L 50 15 L 20 15 Z" {...segStyle(a)} />
                {/* B */}
                <path d="M 55 10 L 60 15 L 60 45 L 55 50 L 50 45 L 50 15 Z" {...segStyle(b)} />
                {/* C */}
                <path d="M 55 50 L 60 55 L 60 85 L 55 90 L 50 85 L 50 55 Z" {...segStyle(c)} />
                {/* D */}
                <path d="M 15 90 L 55 90 L 50 85 L 20 85 Z" {...segStyle(d)} />
                {/* E */}
                <path d="M 15 50 L 20 55 L 20 85 L 15 90 L 10 85 L 10 55 Z" {...segStyle(e)} />
                {/* F */}
                <path d="M 15 10 L 20 15 L 20 45 L 15 50 L 10 45 L 10 15 Z" {...segStyle(f)} />
                {/* G */}
                <path d="M 15 50 L 20 45 L 50 45 L 55 50 L 50 55 L 20 55 Z" {...segStyle(g)} />
                {/* DP */}
                <circle cx="60" cy="90" r="3" {...segStyle(dp)} />
            </g>
        );

    // --- Arithmetic ---
    case 'HALF_ADDER':
      return (
        <g>
            <rect x="0" y="0" width="80" height="80" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
            <Text x={40} y={40}>HALF ADDER</Text>
            <Text x={10} y={20}>A</Text> <Text x={10} y={60}>B</Text>
            <Text x={70} y={20}>S</Text> <Text x={70} y={60}>C</Text>
        </g>
      );
    case 'FULL_ADDER':
        return (
          <g>
              <rect x="0" y="0" width="80" height="100" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
              <Text x={40} y={50}>FULL ADDER</Text>
              <Text x={10} y={20}>A</Text> <Text x={10} y={40}>B</Text> <Text x={10} y={80}>Cin</Text>
              <Text x={70} y={20}>S</Text> <Text x={70} y={80}>Cout</Text>
          </g>
        );
    case 'SUBTRACTOR':
        return (
            <g>
                <rect x="0" y="0" width="80" height="100" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <Text x={40} y={50}>SUBTRACTOR</Text>
                <Text x={10} y={20}>A</Text> <Text x={10} y={60}>B</Text>
                <Text x={70} y={20}>D</Text> <Text x={70} y={80}>Bo</Text>
            </g>
        );
    case 'COMPARATOR_1BIT':
        return (
            <g>
                <rect x="0" y="0" width="80" height="80" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <Text x={40} y={40}>COMPARATOR</Text>
                <Text x={10} y={20}>A</Text> <Text x={10} y={60}>B</Text>
                <Text x={70} y={20}>&gt;</Text> <Text x={70} y={40}>=</Text> <Text x={70} y={60}>&lt;</Text>
            </g>
        );

    // --- Memory ---
    case 'D_LATCH':
        return (
          <g>
              <rect x="0" y="0" width="80" height="80" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
              <Text x={40} y={25}>D-LATCH</Text>
              <Text x={10} y={20}>D</Text> <Text x={10} y={60}>En</Text>
              <Text x={70} y={20}>Q</Text> <Text x={70} y={60}>!Q</Text>
          </g>
        );
    case 'D_FF':
        return (
            <g>
                <rect x="0" y="0" width="80" height="80" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <Text x={40} y={25}>D-FF</Text>
                <Text x={10} y={20}>D</Text> 
                <path d="M 0 55 L 10 60 L 0 65" fill="none" stroke="#71717a" />
                <Text x={70} y={20}>Q</Text> <Text x={70} y={60}>!Q</Text>
            </g>
        );
    case 'T_FF':
        return (
            <g>
                <rect x="0" y="0" width="80" height="80" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <Text x={40} y={25}>T-FF</Text>
                <Text x={10} y={20}>T</Text> 
                <path d="M 0 55 L 10 60 L 0 65" fill="none" stroke="#71717a" />
                <Text x={70} y={20}>Q</Text> <Text x={70} y={60}>!Q</Text>
            </g>
        );
    case 'JK_FF':
        return (
            <g>
                <rect x="0" y="0" width="80" height="100" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <Text x={40} y={25}>JK-FF</Text>
                <Text x={10} y={20}>J</Text> <Text x={10} y={80}>K</Text>
                <path d="M 0 45 L 10 50 L 0 55" fill="none" stroke="#71717a" />
                <Text x={70} y={20}>Q</Text> <Text x={70} y={80}>!Q</Text>
            </g>
        );
    case 'SR_FF':
        return (
            <g>
                <rect x="0" y="0" width="80" height="100" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <Text x={40} y={25}>SR-FF</Text>
                <Text x={10} y={20}>S</Text> <Text x={10} y={80}>R</Text>
                <path d="M 0 45 L 10 50 L 0 55" fill="none" stroke="#71717a" />
                <Text x={70} y={20}>Q</Text> <Text x={70} y={80}>!Q</Text>
            </g>
        );

    // --- Advanced ---
    case 'GATED_SR_LATCH':
        return (
            <g>
                <rect x="0" y="0" width="80" height="100" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <Text x={40} y={25}>Gated SR</Text>
                <Text x={10} y={20}>S</Text> <Text x={10} y={50}>En</Text> <Text x={10} y={80}>R</Text>
                <Text x={70} y={20}>Q</Text> <Text x={70} y={80}>!Q</Text>
            </g>
        );
    case 'JK_MASTER_SLAVE':
        return (
            <g>
                <rect x="0" y="0" width="90" height="100" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <Text x={45} y={25}>JK M-S</Text>
                <Text x={10} y={20}>J</Text> <Text x={10} y={80}>K</Text>
                <path d="M 0 45 L 10 50 L 0 55" fill="none" stroke="#71717a" />
                <Text x={80} y={20}>Q</Text> <Text x={80} y={80}>!Q</Text>
            </g>
        );
    case 'RAM_1BIT':
        return (
            <g>
                <rect x="0" y="0" width="70" height="80" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <Text x={35} y={20}>RAM 1b</Text>
                <Text x={10} y={20}>D</Text> <Text x={10} y={40}>W</Text> <Text x={10} y={60}>S</Text>
                <Text x={60} y={40}>Q</Text>
            </g>
        );
    case 'ROM_1BIT':
        return (
            <g>
                <rect x="0" y="0" width="60" height="60" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <Text x={30} y={15}>ROM 1b</Text>
                <Text x={30} y={45}>{node.properties?.romValue ? '1' : '0'}</Text>
                <Text x={10} y={30}>S</Text>
                <Text x={50} y={30}>Q</Text>
            </g>
        );
    case 'SHIFT_REGISTER_4BIT':
        const reg = node.internalState?.register || [false, false, false, false];
        return (
            <g>
                <rect x="0" y="0" width="100" height="120" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <Text x={50} y={15}>SHIFT REG 4b</Text>
                <Text x={10} y={30}>D</Text> 
                <path d="M 0 85 L 10 90 L 0 95" fill="none" stroke="#71717a" />

                {/* Visualizing bits */}
                <rect x="30" y="40" width="15" height="40" fill={reg[0] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />
                <rect x="45" y="40" width="15" height="40" fill={reg[1] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />
                <rect x="60" y="40" width="15" height="40" fill={reg[2] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />
                <rect x="75" y="40" width="15" height="40" fill={reg[3] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />

                <Text x={90} y={20}>Q0</Text> <Text x={90} y={50}>Q1</Text>
                <Text x={90} y={80}>Q2</Text> <Text x={90} y={110}>Q3</Text>
            </g>
        );

    // --- Plexers ---
    case 'MUX_2_1':
        return (
          <g>
              <path d="M 0 0 L 60 20 L 60 60 L 0 80 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
              <Text x={30} y={40}>MUX</Text>
              <Text x={10} y={20}>0</Text> <Text x={10} y={60}>1</Text> <Text x={30} y={70}>S</Text>
              <Text x={50} y={40}>Y</Text>
          </g>
        );
    case 'MUX_4_1':
        return (
            <g>
                <path d="M 0 0 L 60 20 L 60 100 L 0 120 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <Text x={30} y={60}>MUX 4</Text>
                <Text x={10} y={20}>0</Text> <Text x={10} y={40}>1</Text>
                <Text x={10} y={60}>2</Text> <Text x={10} y={80}>3</Text>
                <Text x={50} y={60}>Y</Text>
            </g>
        );
    case 'DEMUX_1_2':
        return (
          <g>
              <path d="M 0 20 L 60 0 L 60 80 L 0 60 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
              <Text x={30} y={40}>DEMUX</Text>
              <Text x={10} y={40}>D</Text> 
              <Text x={50} y={20}>0</Text> <Text x={50} y={60}>1</Text>
          </g>
        );
    case 'DEMUX_1_4':
        return (
            <g>
                <path d="M 0 20 L 60 0 L 60 120 L 0 100 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <Text x={30} y={60}>DEMUX 4</Text>
                <Text x={10} y={60}>D</Text> 
                <Text x={50} y={20}>0</Text> <Text x={50} y={40}>1</Text>
                <Text x={50} y={60}>2</Text> <Text x={50} y={80}>3</Text>
            </g>
        );
    case 'DECODER_2_4':
        return (
            <g>
                <rect x="0" y="0" width="60" height="100" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <Text x={30} y={50}>DEC 2:4</Text>
                <Text x={10} y={80}>0</Text> <Text x={10} y={90}>1</Text>
                <Text x={50} y={20}>0</Text> <Text x={50} y={40}>1</Text>
                <Text x={50} y={60}>2</Text> <Text x={50} y={80}>3</Text>
            </g>
        );
    case 'PRIORITY_ENCODER_4_2':
        return (
            <g>
                <rect x="0" y="0" width="70" height="100" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <Text x={35} y={10}>PRIO ENC</Text>
                <Text x={10} y={20}>0</Text> <Text x={10} y={40}>1</Text>
                <Text x={10} y={60}>2</Text> <Text x={10} y={80}>3</Text>
                <Text x={60} y={30}>A0</Text> <Text x={60} y={50}>A1</Text> <Text x={60} y={80}>V</Text>
            </g>
        );

    default:
      return <rect width="40" height="40" fill="red" />;
  }
};

import { NodeData, Wire, NodeType } from '../types';

export const evaluateCircuit = (nodes: NodeData[], wires: Wire[]): { nodes: NodeData[], wires: Wire[] } => {
  // 1. Snapshot previous state (inputs/outputs) to detect edges or retain memory
  // We don't deep copy internalState here because we want to update it
  let nextNodes = nodes.map(n => ({ 
    ...n, 
    inputs: [...n.inputs], 
    outputs: [...n.outputs],
    internalState: { ...n.internalState },
    properties: { ...n.properties }
  }));
  let nextWires = wires.map(w => ({ ...w }));

  // Preserve the *initial* inputs of this frame for edge detection
  // This allows us to compare "What was the clock before this eval cycle?" vs "What is it now?"
  const initialNodesState = new Map(nodes.map(n => [n.id, n]));

  let stable = false;
  let iterations = 0;
  const MAX_ITERATIONS = 50; 

  while (!stable && iterations < MAX_ITERATIONS) {
    stable = true;
    iterations++;

    // --- Wire Propagation ---
    nextWires.forEach(wire => {
      const sourceNode = nextNodes.find(n => n.id === wire.sourceNodeId);
      if (sourceNode) {
        const val = sourceNode.outputs[wire.sourceOutputIndex] || false;
        if (wire.state !== val) {
          wire.state = val;
          stable = false;
        }
      }
    });

    nextWires.forEach(wire => {
      const targetNode = nextNodes.find(n => n.id === wire.targetNodeId);
      if (targetNode) {
        if (targetNode.inputs[wire.targetInputIndex] !== wire.state) {
          targetNode.inputs[wire.targetInputIndex] = wire.state;
          stable = false;
        }
      }
    });

    // --- Node Evaluation ---
    nextNodes.forEach(node => {
      // Skip input-only nodes (sources) but process CONSTANTs
      if (['SWITCH', 'CLOCK', 'BUTTON'].includes(node.type)) return;

      const oldOutputs = [...node.outputs];
      let newOutputs = [...oldOutputs];

      const prevNodeState = initialNodesState.get(node.id);

      switch (node.type) {
        // Gates (Dynamic Input Support)
        case 'AND': 
          newOutputs = [node.inputs.every(v => v === true)]; 
          break;
        case 'OR': 
          newOutputs = [node.inputs.some(v => v === true)]; 
          break;
        case 'NOT': 
          newOutputs = [!node.inputs[0]]; 
          break;
        case 'NAND': 
          newOutputs = [!node.inputs.every(v => v === true)]; 
          break;
        case 'NOR': 
          newOutputs = [!node.inputs.some(v => v === true)]; 
          break;
        case 'XOR': 
          // Odd number of 1s
          newOutputs = [node.inputs.filter(v => v).length % 2 === 1]; 
          break;
        case 'XNOR': 
           // Even number of 1s (for >2 inputs this is the definition usually used in parity)
           // For 2 inputs: !(A^B). For N inputs: !(OddParity).
          newOutputs = [node.inputs.filter(v => v).length % 2 === 0]; 
          break;
        case 'BUFFER': newOutputs = [node.inputs[0]]; break;
        case 'CONSTANT_1': newOutputs = [true]; break;
        case 'CONSTANT_0': newOutputs = [false]; break;

        // Junction acts as a pass-through buffer
        case 'JUNCTION':
            newOutputs = [node.inputs[0]];
            break;

        // Output Objects
        case 'BULB': case 'HEX_DISPLAY': case 'SEVEN_SEGMENT': break; // No outputs

        // Arithmetic
        case 'HALF_ADDER': {
           const a = node.inputs[0]; const b = node.inputs[1];
           newOutputs = [a !== b, a && b]; 
           break;
        }
        case 'FULL_ADDER': {
            const a = node.inputs[0]; const b = node.inputs[1]; const cin = node.inputs[2];
            const sum = (a ? 1:0) + (b ? 1:0) + (cin ? 1:0);
            newOutputs = [sum % 2 === 1, sum >= 2];
            break;
        }
        case 'SUBTRACTOR': {
            const a = node.inputs[0]; const b = node.inputs[1];
            newOutputs = [a !== b, (!a && b)]; // Diff, Borrow
            break;
        }
        case 'COMPARATOR_1BIT': {
            const a = node.inputs[0]; const b = node.inputs[1];
            newOutputs = [
                a && !b, // >
                a === b, // =
                !a && b  // <
            ];
            break;
        }

        // Plexers
        case 'MUX_2_1':
           newOutputs = [node.inputs[2] ? node.inputs[1] : node.inputs[0]];
           break;
        case 'MUX_4_1': {
            const s0 = node.inputs[4]; const s1 = node.inputs[5];
            const idx = (s0?1:0) + (s1?2:0);
            newOutputs = [node.inputs[idx]];
            break;
        }
        case 'DEMUX_1_2': {
            const d = node.inputs[0]; const s = node.inputs[1];
            newOutputs = [!s ? d : false, s ? d : false];
            break;
        }
        case 'DEMUX_1_4': {
            const d = node.inputs[0]; const s0 = node.inputs[1]; const s1 = node.inputs[2];
            const idx = (s0?1:0) + (s1?2:0);
            newOutputs = [false, false, false, false];
            newOutputs[idx] = d;
            break;
        }
        case 'DECODER_2_4': {
            const s0 = node.inputs[0]; const s1 = node.inputs[1];
            const idx = (s0?1:0) + (s1?2:0);
            newOutputs = [false, false, false, false];
            newOutputs[idx] = true;
            break;
        }
        case 'PRIORITY_ENCODER_4_2': {
            // Priority 3 > 2 > 1 > 0
            const i0 = node.inputs[0]; const i1 = node.inputs[1];
            const i2 = node.inputs[2]; const i3 = node.inputs[3];
            let a0 = false, a1 = false, v = false;

            if (i3) { a1=true; a0=true; v=true; }
            else if (i2) { a1=true; a0=false; v=true; }
            else if (i1) { a1=false; a0=true; v=true; }
            else if (i0) { a1=false; a0=false; v=true; }

            newOutputs = [a0, a1, v];
            break;
        }

        // State / Memory
        case 'D_LATCH': {
           const D = node.inputs[0]; const E = node.inputs[1];
           const Q = E ? D : oldOutputs[0];
           newOutputs = [Q, !Q];
           break;
        }
        case 'D_FF': {
           const D = node.inputs[0]; const Clk = node.inputs[1];
           const lastClk = node.internalState?.lastClock || false;
           let Q = oldOutputs[0];

           if (!lastClk && Clk) { // Rising Edge
               Q = D;
           }
           newOutputs = [Q, !Q];
           node.internalState = { ...node.internalState, lastClock: Clk };
           break;
        }
        case 'T_FF': {
           const T = node.inputs[0]; const Clk = node.inputs[1];
           const lastClk = node.internalState?.lastClock || false;
           let Q = oldOutputs[0];

           if (!lastClk && Clk) { // Rising Edge
               if (T) Q = !Q;
           }
           newOutputs = [Q, !Q];
           node.internalState = { ...node.internalState, lastClock: Clk };
           break;
        }
        case 'JK_FF': {
           const J = node.inputs[0]; const Clk = node.inputs[1]; const K = node.inputs[2];
           const lastClk = node.internalState?.lastClock || false;
           let Q = oldOutputs[0];

           if (!lastClk && Clk) { // Rising Edge
               if (J && !K) Q = true;
               else if (!J && K) Q = false;
               else if (J && K) Q = !Q;
           }
           newOutputs = [Q, !Q];
           node.internalState = { ...node.internalState, lastClock: Clk };
           break;
        }
        case 'SR_FF': {
            const S = node.inputs[0]; const Clk = node.inputs[1]; const R = node.inputs[2];
            const lastClk = node.internalState?.lastClock || false;
            let Q = oldOutputs[0];

            if (!lastClk && Clk) { // Rising Edge
                if (S && !R) Q = true;
                else if (!S && R) Q = false;
            }
            newOutputs = [Q, !Q];
            node.internalState = { ...node.internalState, lastClock: Clk };
            break;
        }
        case 'GATED_SR_LATCH': {
            const S = node.inputs[0]; const En = node.inputs[1]; const R = node.inputs[2];
            let Q = oldOutputs[0];
            if (En) {
                if (S && !R) Q = true;
                else if (!S && R) Q = false;
            }
            newOutputs = [Q, !Q];
            break;
        }
        case 'JK_MASTER_SLAVE': {
            // Functionally models a falling-edge triggered JK Flip-Flop
            const J = node.inputs[0]; const Clk = node.inputs[1]; const K = node.inputs[2];
            const lastClk = node.internalState?.lastClock || false;
            let Q = oldOutputs[0];

            if (lastClk && !Clk) { // Falling Edge
                if (J && !K) Q = true;
                else if (!J && K) Q = false;
                else if (J && K) Q = !Q;
            }
            newOutputs = [Q, !Q];
            node.internalState = { ...node.internalState, lastClock: Clk };
            break;
        }
        case 'RAM_1BIT': {
            const Data = node.inputs[0]; const Write = node.inputs[1]; const Sel = node.inputs[2];
            let stored = node.internalState?.storedValue || false;

            if (Sel && Write) {
                stored = Data;
            }

            newOutputs = [Sel ? stored : false];
            node.internalState = { ...node.internalState, storedValue: stored };
            break;
        }
        case 'ROM_1BIT': {
             const Sel = node.inputs[0];
             // Value is static property
             const val = node.properties?.romValue || false;
             newOutputs = [Sel ? val : false];
             break;
        }
        case 'SHIFT_REGISTER_4BIT': {
             const Data = node.inputs[0]; const Clk = node.inputs[1];
             const lastClk = node.internalState?.lastClock || false;
             let reg = node.internalState?.register || [false, false, false, false];

             if (!lastClk && Clk) { // Rising Edge
                 // Shift right: Q0 gets Data, Q1 gets Q0...
                 reg = [Data, reg[0], reg[1], reg[2]];
             }

             newOutputs = [...reg];
             node.internalState = { ...node.internalState, lastClock: Clk, register: reg };
             break;
        }
      }

      // Diff check
      let changed = false;
      if (newOutputs.length !== node.outputs.length) changed = true;
      else {
          for(let i=0; i<newOutputs.length; i++) {
              if (node.outputs[i] !== newOutputs[i]) {
                  changed = true;
                  break;
              }
          }
      }

      if (changed) {
          node.outputs = newOutputs;
          stable = false;
      }
    });
  }

  return { nodes: nextNodes, wires: nextWires };
};

import React, { useRef, useState, useEffect } from 'react';
import { GRID_SIZE, NODE_DEFINITIONS } from '../constants';
import { CircuitState, NodeData, NodeType, Wire, Point, WiringState } from '../types';
import { GateShape } from './GateShapes';
import { evaluateCircuit } from '../utils/circuitLogic';
import { getNodeDimensions, getInputPorts, getOutputPorts } from '../utils/componentUtils';
import { PropertiesPanel } from './PropertiesPanel';
import { X, Trash2, MousePointer2, Hand, Move, Cable, Circle } from 'lucide-react';

export const CircuitCanvas: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [circuit, setCircuit] = useState<CircuitState>({ nodes: [], wires: [] });

  // Interaction State
  const [toolMode, setToolMode] = useState<'select' | 'interact' | 'junction'>('select');
  const [wireMode, setWireMode] = useState<'manhattan' | 'bezier'>('manhattan');
  const [draggingNodeId, setDraggingNodeId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<Point>({ x: 0, y: 0 });
  const [wiring, setWiring] = useState<WiringState | null>(null);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });
  const [selectedId, setSelectedId] = useState<string | null>(null); 

  // --- Clock Simulation ---
  useEffect(() => {
    const interval = setInterval(() => {
        setCircuit(prev => {
            const hasClock = prev.nodes.some(n => n.type === 'CLOCK');
            if (!hasClock) return prev;

            const nextNodes = prev.nodes.map(n => {
                if (n.type === 'CLOCK') {
                    return { ...n, outputs: [!n.outputs[0]] };
                }
                return n;
            });
            return evaluateCircuit(nextNodes, prev.wires);
        });
    }, 1000); 
    return () => clearInterval(interval);
  }, []);

  // --- Logic Helpers ---
  const updateCircuit = (newNodes: NodeData[], newWires: Wire[]) => {
    const evaluated = evaluateCircuit(newNodes, newWires);
    setCircuit(evaluated);
  };

  const handleNodeUpdate = (id: string, updates: Partial<NodeData>) => {
    setCircuit(prev => {
        const newNodes = prev.nodes.map(n => {
            if (n.id === id) {
                const updatedNode = { ...n, ...updates };

                // Handle resizing inputs
                if (updates.properties?.inputCount) {
                    const count = updates.properties.inputCount;
                    if (count > updatedNode.inputs.length) {
                        updatedNode.inputs = [...updatedNode.inputs, ...Array(count - updatedNode.inputs.length).fill(false)];
                    } else if (count < updatedNode.inputs.length) {
                        updatedNode.inputs = updatedNode.inputs.slice(0, count);
                    }
                }

                // Handle Initial State changes for Switch/Constant directly impacting output
                if (updates.properties?.initialState !== undefined) {
                    if (['SWITCH', 'CONSTANT_1', 'CONSTANT_0'].includes(updatedNode.type)) {
                         updatedNode.outputs = [!!updates.properties.initialState];
                    }
                    // For Flip-Flops, we might want to update internal state if simulation hasn't really started or just force it
                    if (['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'D_LATCH'].includes(updatedNode.type)) {
                        updatedNode.internalState = {
                            ...updatedNode.internalState,
                            storedValue: !!updates.properties.initialState
                        };
                        updatedNode.outputs = [!!updates.properties.initialState, !updates.properties.initialState];
                    }
                }

                return updatedNode;
            }
            return n;
        });

        return evaluateCircuit(newNodes, prev.wires);
    });
  };

  const addNode = (type: NodeType, x: number, y: number) => {
    const def = NODE_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newNode: NodeData = {
      id: `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      position: { x: snapX, y: snapY },
      inputs: Array(def.inputs).fill(false),
      outputs: Array(def.outputs).fill(false),
      internalState: {},
      properties: {
          label: '',
          inputCount: def.inputs,
          propagationDelay: 0,
          initialState: false,
          romValue: false
      }
    };

    updateCircuit([...circuit.nodes, newNode], circuit.wires);
    setSelectedId(newNode.id);
    if (type !== 'JUNCTION') {
        setToolMode('select'); 
    }
  };

  const deleteSelection = () => {
    if (!selectedId) return;

    const isWire = circuit.wires.find(w => w.id === selectedId);
    if (isWire) {
      updateCircuit(circuit.nodes, circuit.wires.filter(w => w.id !== selectedId));
      setSelectedId(null);
      return;
    }

    const newWires = circuit.wires.filter(w => w.sourceNodeId !== selectedId && w.targetNodeId !== selectedId);
    const newNodes = circuit.nodes.filter(n => n.id !== selectedId);
    updateCircuit(newNodes, newWires);
    setSelectedId(null);
  };

  // --- Interaction Handlers ---

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); 
    e.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const type = e.dataTransfer.getData('application/react-circuit-node') as NodeType;

    if (!type || !containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    addNode(type, x, y);
  };

  const handleNodeMouseDown = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (wiring) return;

    // In Junction mode, clicking a node shouldn't necessarily drag it, 
    // but maybe we want to allow selecting. 
    // For now, allow selecting/dragging unless wiring.

    setSelectedId(id);
    const node = circuit.nodes.find(n => n.id === id);
    if (!node) return;

    // Interaction Mode Logic
    const isInteractive = ['SWITCH', 'BUTTON'].includes(node.type);

    if (toolMode === 'interact' && isInteractive) {
        const toggledNodes = circuit.nodes.map(n => {
            if (n.id === id) {
                const newState = !n.outputs[0];
                return { ...n, outputs: [newState] };
            }
            return n;
        });
        updateCircuit(toggledNodes, circuit.wires);
        return; 
    }

    // Select/Move Mode Logic
    if (toolMode === 'select' || toolMode === 'junction') {
        setDraggingNodeId(id);
        const rect = containerRef.current!.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;
        setDragOffset({
            x: mouseX - node.position.x,
            y: mouseY - node.position.y
        });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    if (draggingNodeId) {
        const snapX = Math.round((x - dragOffset.x) / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round((y - dragOffset.y) / GRID_SIZE) * GRID_SIZE;

        const updatedNodes = circuit.nodes.map(n => {
            if (n.id === draggingNodeId) {
                return { ...n, position: { x: snapX, y: snapY }};
            }
            return n;
        });
        setCircuit(prev => ({ ...prev, nodes: updatedNodes }));
    }
  };

  const handleMouseUp = () => {
    if (draggingNodeId) {
        setDraggingNodeId(null);
        updateCircuit(circuit.nodes, circuit.wires); 
    }
    if (wiring) {
        setWiring(null);
    }
  };

  const startWiring = (e: React.MouseEvent, nodeId: string, outputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();
    if (toolMode === 'interact') return; 

    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setWiring({
        sourceNodeId: nodeId,
        sourceOutputIndex: outputIndex,
        startPoint: { x, y },
        active: true
    });
  };

  const completeWiring = (e: React.MouseEvent, targetNodeId: string, inputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();

    if (!wiring) return;

    if (wiring.sourceNodeId === targetNodeId) {
        setWiring(null);
        return;
    }

    const exists = circuit.wires.some(w => 
        w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex
    );

    let newWires = exists 
        ? circuit.wires.filter(w => !(w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex))
        : [...circuit.wires];

    newWires.push({
        id: `wire-${Date.now()}`,
        sourceNodeId: wiring.sourceNodeId,
        sourceOutputIndex: wiring.sourceOutputIndex,
        targetNodeId: targetNodeId,
        targetInputIndex: inputIndex,
        state: false
    });

    updateCircuit(circuit.nodes, newWires);
    setWiring(null);
  };

  const handleWireClick = (e: React.MouseEvent, wire: Wire, x: number, y: number) => {
    if (toolMode !== 'junction') {
        e.stopPropagation();
        setSelectedId(wire.id);
        return;
    }

    e.stopPropagation();

    // Create Junction at clicked location
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const junctionId = `node-${Date.now()}-junction`;

    const newJunction: NodeData = {
        id: junctionId,
        type: 'JUNCTION',
        position: { x: snapX - 5, y: snapY - 5 }, // Center it (10px wide)
        inputs: [false],
        outputs: [false],
        properties: { label: '' }
    };

    // Remove old wire, create two new ones
    // Wire 1: Source -> Junction
    const wire1: Wire = {
        id: `wire-${Date.now()}-1`,
        sourceNodeId: wire.sourceNodeId,
        sourceOutputIndex: wire.sourceOutputIndex,
        targetNodeId: junctionId,
        targetInputIndex: 0,
        state: wire.state
    };

    // Wire 2: Junction -> Target
    const wire2: Wire = {
        id: `wire-${Date.now()}-2`,
        sourceNodeId: junctionId,
        sourceOutputIndex: 0,
        targetNodeId: wire.targetNodeId,
        targetInputIndex: wire.targetInputIndex,
        state: wire.state
    };

    const newWires = circuit.wires.filter(w => w.id !== wire.id).concat([wire1, wire2]);
    const newNodes = [...circuit.nodes, newJunction];

    updateCircuit(newNodes, newWires);
    setSelectedId(junctionId);
  };

  const handleCanvasClick = (e: React.MouseEvent) => {
      // If clicking empty space in Junction mode, create floating junction
      if (toolMode === 'junction' && !draggingNodeId) {
          if (!containerRef.current) return;
          const rect = containerRef.current.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;
          addNode('JUNCTION', x, y);
      }
      setSelectedId(null);
  };

  // --- Render Helpers ---
  const getWirePath = (x1: number, y1: number, x2: number, y2: number) => {
    if (wireMode === 'bezier') {
        const dist = Math.abs(x2 - x1);
        const controlPointOffset = Math.max(dist * 0.5, 50);
        return `M ${x1} ${y1} C ${x1 + controlPointOffset} ${y1}, ${x2 - controlPointOffset} ${y2}, ${x2} ${y2}`;
    }

    // Manhattan Routing (Straight Lines)
    const dx = x2 - x1;
    const dy = y2 - y1;

    // Normal case: Target is to the right
    if (dx > 20) {
        const midX = (x1 + x2) / 2;
        return `M ${x1} ${y1} L ${midX} ${y1} L ${midX} ${y2} L ${x2} ${y2}`;
    }

    // Feedback/Loop-back case: Target is to the left or too close
    // Route: Right -> Vert -> Left -> Vert -> Right
    const stub = 20;
    const midY = (y1 + y2) / 2;
    // Push vertical segment out to avoid overlap
    const verticalClearance = 0; 

    return `M ${x1} ${y1} L ${x1 + stub} ${y1} L ${x1 + stub} ${midY} L ${x2 - stub} ${midY} L ${x2 - stub} ${y2} L ${x2} ${y2}`;
  };

  const selectedNode = circuit.nodes.find(n => n.id === selectedId) || null;

  return (
    <div className="flex-1 h-full relative bg-zinc-950 flex flex-row overflow-hidden">
        {/* Main Canvas Area */}
        <div className="flex-1 flex flex-col relative h-full overflow-hidden">
             {/* Toolbar */}
            <div className="h-14 border-b border-zinc-800 bg-zinc-900/50 flex items-center px-6 justify-between z-20 backdrop-blur-sm shrink-0">
                <div className="flex items-center space-x-4">
                     {/* Tool Mode Switcher */}
                     <div className="flex items-center bg-zinc-800 rounded-md p-0.5 border border-zinc-700">
                        <button 
                            onClick={() => setToolMode('select')}
                            className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-medium transition-colors ${toolMode === 'select' ? 'bg-zinc-700 text-white shadow-sm' : 'text-zinc-400 hover:text-zinc-200'}`}
                            title="Select / Move Mode"
                        >
                            <Move size={14} />
                            <span>Select</span>
                        </button>
                        <button 
                            onClick={() => setToolMode('interact')}
                            className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-medium transition-colors ${toolMode === 'interact' ? 'bg-cyan-900/50 text-cyan-400 border border-cyan-800/50 shadow-sm' : 'text-zinc-400 hover:text-zinc-200'}`}
                            title="Interact / Experiment Mode"
                        >
                            <Hand size={14} />
                            <span>Interact</span>
                        </button>
                     </div>

                     <div className="h-4 w-px bg-zinc-700 mx-2"></div>

                     {/* Junction Tool */}
                     <div className="flex items-center bg-zinc-800 rounded-md p-0.5 border border-zinc-700">
                        <button 
                            onClick={() => setToolMode(toolMode === 'junction' ? 'select' : 'junction')}
                            className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-medium transition-colors ${toolMode === 'junction' ? 'bg-zinc-700 text-white shadow-sm' : 'text-zinc-400 hover:text-zinc-200'}`}
                            title="Junction Tool: Click wires to split/connect"
                        >
                            <Circle size={14} />
                            <span>Junction</span>
                        </button>
                     </div>

                     <div className="h-4 w-px bg-zinc-700 mx-2"></div>

                     {/* Wire Mode Toggle */}
                     <div className="flex items-center bg-zinc-800 rounded-md p-0.5 border border-zinc-700" title="Toggle Wire Style">
                        <button 
                            onClick={() => setWireMode(wireMode === 'manhattan' ? 'bezier' : 'manhattan')}
                            className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-medium transition-colors ${wireMode === 'manhattan' ? 'bg-zinc-700 text-white shadow-sm' : 'text-zinc-400 hover:text-zinc-200'}`}
                        >
                            <Cable size={14} />
                            <span>{wireMode === 'manhattan' ? 'Straight' : 'Curved'}</span>
                        </button>
                     </div>

                    <div className="h-4 w-px bg-zinc-700 mx-2"></div>

                    <button 
                        onClick={() => setCircuit({ nodes: [], wires: [] })}
                        className="flex items-center space-x-2 px-3 py-1.5 bg-zinc-800 hover:bg-red-900/30 hover:text-red-400 text-zinc-300 rounded-md text-xs font-medium transition-colors border border-zinc-700 hover:border-red-800"
                    >
                        <Trash2 size={14} />
                        <span>Clear</span>
                    </button>
                </div>

                <div className="flex items-center space-x-4">
                     <div className="text-zinc-500 text-xs flex items-center space-x-2">
                        <MousePointer2 size={14} />
                        <span>{toolMode === 'junction' ? 'Click on a wire to create a connection point' : toolMode === 'select' ? 'Drag to move' : 'Click switches to toggle'}</span>
                     </div>

                     {selectedId && (
                        <button 
                        onClick={deleteSelection}
                        className="flex items-center space-x-2 px-3 py-1.5 bg-red-500/10 text-red-400 hover:bg-red-500/20 border border-red-500/30 rounded-md text-xs font-medium transition-colors"
                        >
                        <X size={14} />
                        <span>Delete</span>
                    </button>
                    )}
                </div>
            </div>

            <div 
                ref={containerRef}
                className={`flex-1 relative w-full h-full overflow-hidden 
                    ${toolMode === 'interact' ? 'cursor-default' : toolMode === 'junction' ? 'cursor-crosshair' : 'cursor-crosshair'}`}
                onDragOver={handleDragOver}
                onDrop={handleDrop}
                onMouseMove={handleMouseMove}
                onMouseUp={handleMouseUp}
                onClick={handleCanvasClick}
                onContextMenu={(e) => e.preventDefault()}
            >
                {/* Grid Pattern */}
                <svg className="absolute inset-0 pointer-events-none w-full h-full opacity-20">
                    <defs>
                        <pattern id="grid" width={GRID_SIZE} height={GRID_SIZE} patternUnits="userSpaceOnUse">
                            <circle cx="1" cy="1" r="1" fill="#71717a" />
                        </pattern>
                    </defs>
                    <rect width="100%" height="100%" fill="url(#grid)" />
                </svg>

                {/* Connections */}
                <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
                    {circuit.wires.map(wire => {
                        const sourceNode = circuit.nodes.find(n => n.id === wire.sourceNodeId);
                        const targetNode = circuit.nodes.find(n => n.id === wire.targetNodeId);
                        if (!sourceNode || !targetNode) return null;

                        const sourcePorts = getOutputPorts(sourceNode);
                        const targetPorts = getInputPorts(targetNode);

                        const outputOffset = sourcePorts[wire.sourceOutputIndex] || { x: 0, y: 0 };
                        const inputOffset = targetPorts[wire.targetInputIndex] || { x: 0, y: 0 };

                        const startX = sourceNode.position.x + outputOffset.x;
                        const startY = sourceNode.position.y + outputOffset.y;
                        const endX = targetNode.position.x + inputOffset.x;
                        const endY = targetNode.position.y + inputOffset.y;

                        const isSelected = selectedId === wire.id;
                        const pathData = getWirePath(startX, startY, endX, endY);

                        return (
                            <g 
                                key={wire.id} 
                                onClick={(e) => { 
                                    // Pass coordinates to handleWireClick
                                    if (!containerRef.current) return;
                                    const rect = containerRef.current.getBoundingClientRect();
                                    handleWireClick(e, wire, e.clientX - rect.left, e.clientY - rect.top);
                                }} 
                                className={`pointer-events-auto cursor-pointer group`}
                            >
                                {/* Thicker transparent path for easier clicking */}
                                <path d={pathData} stroke="transparent" strokeWidth="16" fill="none" />
                                {wire.state && <path d={pathData} stroke="#22d3ee" strokeWidth="4" fill="none" opacity="0.3" filter="blur(2px)" />}
                                <path d={pathData} stroke={wire.state ? "#22d3ee" : "#52525b"} strokeWidth={isSelected ? "3" : "2"} fill="none" className="transition-colors duration-150" strokeDasharray={isSelected ? "4" : "0"} strokeLinejoin="round" strokeLinecap="round" />
                            </g>
                        );
                    })}

                    {wiring && (
                        <path d={getWirePath(wiring.startPoint.x, wiring.startPoint.y, mousePos.x, mousePos.y)} stroke="#fbbf24" strokeWidth="2" fill="none" strokeDasharray="4" className="animate-pulse" strokeLinejoin="round" />
                    )}
                </svg>

                {/* Nodes */}
                {circuit.nodes.map(node => {
                    const { width, height } = getNodeDimensions(node);
                    const isSelected = selectedId === node.id;
                    const inputPorts = getInputPorts(node);
                    const outputPorts = getOutputPorts(node);
                    const def = NODE_DEFINITIONS[node.type];
                    const canInteract = ['SWITCH', 'BUTTON'].includes(node.type);

                    return (
                        <div
                            key={node.id}
                            className={`absolute group select-none`}
                            style={{
                                left: node.position.x,
                                top: node.position.y,
                                width: width,
                                height: height,
                                pointerEvents: 'none',
                                zIndex: isSelected ? 50 : 10 // Lift selected node above others
                            }}
                        >
                            <div 
                                className={`absolute inset-0 pointer-events-auto transition-all duration-200 
                                    ${isSelected ? 'drop-shadow-[0_0_8px_rgba(34,211,238,0.5)]' : ''} 
                                    ${toolMode === 'interact' && canInteract ? 'cursor-pointer' : 'cursor-grab active:cursor-grabbing'}
                                `}
                                onMouseDown={(e) => handleNodeMouseDown(e, node.id)}
                            >
                                <svg width={width} height={height} className="overflow-visible">
                                    <GateShape node={node} />
                                </svg>
                            </div>

                            {/* Ports only interactive in Select/Junction Mode to avoid clutter during Interaction */}
                            {inputPorts.map((offset, idx) => (
                                <div
                                    key={`input-${idx}`}
                                    className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 
                                    ${(toolMode === 'select' || toolMode === 'junction') ? 'cursor-crosshair' : 'cursor-default'}`}
                                    style={{ left: offset.x, top: offset.y }}
                                    onMouseUp={(e) => (toolMode === 'select' || toolMode === 'junction') && completeWiring(e, node.id, idx)}
                                    title={offset.label || "Input"}
                                >
                                    <div className={`w-2 h-2 rounded-full bg-zinc-900 border ${node.inputs[idx] ? 'border-cyan-400 bg-cyan-900' : 'border-zinc-500'}`} />
                                </div>
                            ))}

                            {outputPorts.map((offset, idx) => (
                                <div
                                    key={`output-${idx}`}
                                    className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 
                                    ${(toolMode === 'select' || toolMode === 'junction') ? 'cursor-crosshair' : 'cursor-default'}`}
                                    style={{ left: offset.x, top: offset.y }}
                                    onMouseDown={(e) => (toolMode === 'select' || toolMode === 'junction') && startWiring(e, node.id, idx)}
                                    title={offset.label || "Output"}
                                >
                                    <div className={`w-2 h-2 rounded-full bg-zinc-900 border ${node.outputs[idx] ? 'border-cyan-400 bg-cyan-500' : 'border-zinc-500 group-hover:border-zinc-300'}`} />
                                </div>
                            ))}

                            {/* Label: Adjusted z-index and position for maximum visibility */}
                            {(isSelected || node.properties?.label) && node.type !== 'JUNCTION' && (
                                <div className="absolute -top-7 left-1/2 -translate-x-1/2 bg-zinc-900/90 text-zinc-100 text-[10px] px-2 py-0.5 rounded border border-zinc-700 whitespace-nowrap shadow-md pointer-events-none backdrop-blur-sm z-[60]">
                                    {node.properties?.label || def.name}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </div>

        {/* Properties Panel (Right Side) */}
        <PropertiesPanel node={selectedNode} onUpdate={handleNodeUpdate} />
    </div>
  );
};

import React, { useRef, useState, useEffect, useCallback } from 'react';
import { GRID_SIZE, NODE_DEFINITIONS } from '../constants';
import { CircuitState, NodeData, NodeType, Wire, Point, WiringState } from '../types';
import { GateShape } from './GateShapes';
import { evaluateCircuit } from '../utils/circuitLogic';
import { getNodeDimensions, getInputPorts, getOutputPorts } from '../utils/componentUtils';
import { PropertiesPanel } from './PropertiesPanel';
import { 
    X, Trash2, MousePointer2, Hand, Move, Cable, Circle, 
    Play, Pause, SkipForward, SkipBack, CheckCircle2, RotateCcw, AlertTriangle 
} from 'lucide-react';

export const CircuitCanvas: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [circuit, setCircuit] = useState<CircuitState>({ nodes: [], wires: [] });

  // Interaction State
  const [toolMode, setToolMode] = useState<'select' | 'interact' | 'junction'>('select');
  const [wireMode, setWireMode] = useState<'manhattan' | 'bezier'>('manhattan');
  const [draggingNodeId, setDraggingNodeId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<Point>({ x: 0, y: 0 });
  const [wiring, setWiring] = useState<WiringState | null>(null);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });
  const [selectedId, setSelectedId] = useState<string | null>(null); 

  // Simulation State
  const [isSimulating, setIsSimulating] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [history, setHistory] = useState<CircuitState[]>([]);
  const MAX_HISTORY = 50;

  // Validation State
  const [validationResult, setValidationResult] = useState<{valid: boolean, messages: string[]} | null>(null);

  // --- Simulation Logic ---

  const tick = useCallback(() => {
    setCircuit(prev => {
        // Save history before tick for Step Back
        setHistory(h => {
            const newHistory = [...h, prev];
            if (newHistory.length > MAX_HISTORY) return newHistory.slice(1);
            return newHistory;
        });

        const hasClock = prev.nodes.some(n => n.type === 'CLOCK');
        let nextNodes = [...prev.nodes];

        // Toggle Clocks on tick
        if (hasClock) {
            nextNodes = nextNodes.map(n => {
                if (n.type === 'CLOCK') {
                    return { ...n, outputs: [!n.outputs[0]] };
                }
                return n;
            });
        }

        // Evaluate Logic
        return evaluateCircuit(nextNodes, prev.wires);
    });
  }, []);

  // Auto-Run Clock
  useEffect(() => {
    let interval: number;
    if (isSimulating && !isPaused) {
        interval = window.setInterval(tick, 1000);
    }
    return () => clearInterval(interval);
  }, [isSimulating, isPaused, tick]);

  // Compatibility Check
  const checkCompatibility = () => {
      const messages: string[] = [];
      let valid = true;

      if (circuit.nodes.length === 0) {
          setValidationResult({ valid: false, messages: ["Circuit is empty."] });
          return;
      }

      circuit.nodes.forEach(node => {
          // Check for floating inputs on Logic Gates and Arithmetic components
          const inputCount = node.inputs.length;
          // Skip sources that don't have inputs usually
          if (['SWITCH', 'CLOCK', 'BUTTON', 'CONSTANT_1', 'CONSTANT_0'].includes(node.type)) return;

          for(let i=0; i<inputCount; i++) {
              const isConnected = circuit.wires.some(w => w.targetNodeId === node.id && w.targetInputIndex === i);
              if (!isConnected) {
                  const label = node.properties?.label || node.type;
                  messages.push(`${label} (ID: ${node.id.slice(-4)}): Input ${i+1} is floating/disconnected.`);
                  valid = false;
              }
          }
      });

      if (valid) {
          setValidationResult({ valid: true, messages: ["Circuit is compatible and valid."] });
      } else {
          setValidationResult({ valid: false, messages });
      }

      // Auto-hide success message
      if (valid) {
          setTimeout(() => setValidationResult(null), 3000);
      }
  };

  const toggleSimulation = () => {
      if (isSimulating) {
          // Stop
          setIsSimulating(false);
          setIsPaused(false);
          setHistory([]); 
          setToolMode('select');
      } else {
          // Start
          // Run check first? Optional. Let's allow running even if broken, but maybe warn.
          setIsSimulating(true);
          setToolMode('interact'); 
          setHistory([circuit]);
      }
  };

  const stepForward = () => {
      if (!isSimulating) return;
      setIsPaused(true); 
      tick();
  };

  const stepBackward = () => {
      if (!isSimulating || history.length === 0) return;
      setIsPaused(true);
      const prev = history[history.length - 1];
      setCircuit(prev);
      setHistory(h => h.slice(0, -1));
  };

  // --- Logic Helpers ---
  const updateCircuit = (newNodes: NodeData[], newWires: Wire[]) => {
    // If simulating, we just update state directly, effectively "injecting" changes live
    // But usually you stop sim to edit. We'll allow live editing.
    const evaluated = evaluateCircuit(newNodes, newWires);
    setCircuit(evaluated);
  };

  const handleNodeUpdate = (id: string, updates: Partial<NodeData>) => {
    setCircuit(prev => {
        const newNodes = prev.nodes.map(n => {
            if (n.id === id) {
                const updatedNode = { ...n, ...updates };

                // Handle resizing inputs
                if (updates.properties?.inputCount) {
                    const count = updates.properties.inputCount;
                    if (count > updatedNode.inputs.length) {
                        updatedNode.inputs = [...updatedNode.inputs, ...Array(count - updatedNode.inputs.length).fill(false)];
                    } else if (count < updatedNode.inputs.length) {
                        updatedNode.inputs = updatedNode.inputs.slice(0, count);
                    }
                }

                if (updates.properties?.initialState !== undefined) {
                    if (['SWITCH', 'CONSTANT_1', 'CONSTANT_0'].includes(updatedNode.type)) {
                         updatedNode.outputs = [!!updates.properties.initialState];
                    }
                    if (['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'D_LATCH'].includes(updatedNode.type)) {
                        updatedNode.internalState = {
                            ...updatedNode.internalState,
                            storedValue: !!updates.properties.initialState
                        };
                        updatedNode.outputs = [!!updates.properties.initialState, !updates.properties.initialState];
                    }
                }

                return updatedNode;
            }
            return n;
        });

        return evaluateCircuit(newNodes, prev.wires);
    });
  };

  const addNode = (type: NodeType, x: number, y: number) => {
    const def = NODE_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newNode: NodeData = {
      id: `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      position: { x: snapX, y: snapY },
      inputs: Array(def.inputs).fill(false),
      outputs: Array(def.outputs).fill(false),
      internalState: {},
      properties: {
          label: '',
          inputCount: def.inputs,
          propagationDelay: 0,
          initialState: false,
          romValue: false
      }
    };

    updateCircuit([...circuit.nodes, newNode], circuit.wires);
    setSelectedId(newNode.id);
    if (type !== 'JUNCTION') {
        setToolMode('select'); 
    }
  };

  const deleteSelection = () => {
    if (!selectedId) return;

    const isWire = circuit.wires.find(w => w.id === selectedId);
    if (isWire) {
      updateCircuit(circuit.nodes, circuit.wires.filter(w => w.id !== selectedId));
      setSelectedId(null);
      return;
    }

    const newWires = circuit.wires.filter(w => w.sourceNodeId !== selectedId && w.targetNodeId !== selectedId);
    const newNodes = circuit.nodes.filter(n => n.id !== selectedId);
    updateCircuit(newNodes, newWires);
    setSelectedId(null);
  };

  // --- Interaction Handlers ---

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); 
    e.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const type = e.dataTransfer.getData('application/react-circuit-node') as NodeType;

    if (!type || !containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    addNode(type, x, y);
  };

  const handleNodeMouseDown = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (wiring) return;

    setSelectedId(id);
    const node = circuit.nodes.find(n => n.id === id);
    if (!node) return;

    const isInteractive = ['SWITCH', 'BUTTON'].includes(node.type);

    if ((toolMode === 'interact' || isSimulating) && isInteractive) {
        const toggledNodes = circuit.nodes.map(n => {
            if (n.id === id) {
                const newState = !n.outputs[0];
                return { ...n, outputs: [newState] };
            }
            return n;
        });
        updateCircuit(toggledNodes, circuit.wires);
        return; 
    }

    if (toolMode === 'select' || toolMode === 'junction') {
        setDraggingNodeId(id);
        const rect = containerRef.current!.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;
        setDragOffset({
            x: mouseX - node.position.x,
            y: mouseY - node.position.y
        });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    if (draggingNodeId) {
        const snapX = Math.round((x - dragOffset.x) / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round((y - dragOffset.y) / GRID_SIZE) * GRID_SIZE;

        const updatedNodes = circuit.nodes.map(n => {
            if (n.id === draggingNodeId) {
                return { ...n, position: { x: snapX, y: snapY }};
            }
            return n;
        });
        setCircuit(prev => ({ ...prev, nodes: updatedNodes }));
    }
  };

  const handleMouseUp = () => {
    if (draggingNodeId) {
        setDraggingNodeId(null);
        updateCircuit(circuit.nodes, circuit.wires); 
    }
    if (wiring) {
        setWiring(null);
    }
  };

  const startWiring = (e: React.MouseEvent, nodeId: string, outputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();
    if (toolMode === 'interact' && !isSimulating) return; 

    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setWiring({
        sourceNodeId: nodeId,
        sourceOutputIndex: outputIndex,
        startPoint: { x, y },
        active: true
    });
  };

  const completeWiring = (e: React.MouseEvent, targetNodeId: string, inputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();

    if (!wiring) return;

    if (wiring.sourceNodeId === targetNodeId) {
        setWiring(null);
        return;
    }

    const exists = circuit.wires.some(w => 
        w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex
    );

    let newWires = exists 
        ? circuit.wires.filter(w => !(w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex))
        : [...circuit.wires];

    newWires.push({
        id: `wire-${Date.now()}`,
        sourceNodeId: wiring.sourceNodeId,
        sourceOutputIndex: wiring.sourceOutputIndex,
        targetNodeId: targetNodeId,
        targetInputIndex: inputIndex,
        state: false
    });

    updateCircuit(circuit.nodes, newWires);
    setWiring(null);
  };

  const handleWireClick = (e: React.MouseEvent, wire: Wire, x: number, y: number) => {
    if (toolMode !== 'junction') {
        e.stopPropagation();
        setSelectedId(wire.id);
        return;
    }

    e.stopPropagation();

    // Create Junction at clicked location
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const junctionId = `node-${Date.now()}-junction`;

    const newJunction: NodeData = {
        id: junctionId,
        type: 'JUNCTION',
        position: { x: snapX - 5, y: snapY - 5 }, // Center it (10px wide)
        inputs: [false],
        outputs: [false],
        properties: { label: '' }
    };

    const wire1: Wire = {
        id: `wire-${Date.now()}-1`,
        sourceNodeId: wire.sourceNodeId,
        sourceOutputIndex: wire.sourceOutputIndex,
        targetNodeId: junctionId,
        targetInputIndex: 0,
        state: wire.state
    };

    const wire2: Wire = {
        id: `wire-${Date.now()}-2`,
        sourceNodeId: junctionId,
        sourceOutputIndex: 0,
        targetNodeId: wire.targetNodeId,
        targetInputIndex: wire.targetInputIndex,
        state: wire.state
    };

    const newWires = circuit.wires.filter(w => w.id !== wire.id).concat([wire1, wire2]);
    const newNodes = [...circuit.nodes, newJunction];

    updateCircuit(newNodes, newWires);
    setSelectedId(junctionId);
  };

  const handleCanvasClick = (e: React.MouseEvent) => {
      if (toolMode === 'junction' && !draggingNodeId) {
          if (!containerRef.current) return;
          const rect = containerRef.current.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;
          addNode('JUNCTION', x, y);
      }
      setSelectedId(null);
      if (validationResult?.valid) setValidationResult(null); // Clear success message on click
  };

  // --- Render Helpers ---
  const getWirePath = (x1: number, y1: number, x2: number, y2: number) => {
    if (wireMode === 'bezier') {
        const dist = Math.abs(x2 - x1);
        const controlPointOffset = Math.max(dist * 0.5, 50);
        return `M ${x1} ${y1} C ${x1 + controlPointOffset} ${y1}, ${x2 - controlPointOffset} ${y2}, ${x2} ${y2}`;
    }

    const dx = x2 - x1;
    // Simple Manhattan
    if (dx > 20) {
        const midX = (x1 + x2) / 2;
        return `M ${x1} ${y1} L ${midX} ${y1} L ${midX} ${y2} L ${x2} ${y2}`;
    }
    const stub = 20;
    const midY = (y1 + y2) / 2;
    return `M ${x1} ${y1} L ${x1 + stub} ${y1} L ${x1 + stub} ${midY} L ${x2 - stub} ${midY} L ${x2 - stub} ${y2} L ${x2} ${y2}`;
  };

  const selectedNode = circuit.nodes.find(n => n.id === selectedId) || null;

  return (
    <div className="flex-1 h-full relative bg-zinc-950 flex flex-row overflow-hidden">
        {/* Main Canvas Area */}
        <div className="flex-1 flex flex-col relative h-full overflow-hidden">
             {/* Toolbar */}
            <div className="h-14 border-b border-zinc-800 bg-zinc-900/50 flex items-center px-4 justify-between z-20 backdrop-blur-sm shrink-0 gap-4">

                {/* Left: Tools */}
                <div className="flex items-center space-x-2">
                     <div className="flex items-center bg-zinc-800 rounded-md p-0.5 border border-zinc-700">
                        <button 
                            onClick={() => { setToolMode('select'); setIsSimulating(false); }}
                            className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-medium transition-colors ${toolMode === 'select' ? 'bg-zinc-700 text-white shadow-sm' : 'text-zinc-400 hover:text-zinc-200'}`}
                            title="Select / Move Mode"
                        >
                            <Move size={14} />
                            <span>Select</span>
                        </button>
                        <button 
                            onClick={() => setToolMode(toolMode === 'junction' ? 'select' : 'junction')}
                            className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-medium transition-colors ${toolMode === 'junction' ? 'bg-zinc-700 text-white shadow-sm' : 'text-zinc-400 hover:text-zinc-200'}`}
                            title="Junction Tool"
                        >
                            <Circle size={14} />
                        </button>
                     </div>

                     <div className="h-4 w-px bg-zinc-700 mx-1"></div>

                     <div className="flex items-center bg-zinc-800 rounded-md p-0.5 border border-zinc-700">
                        <button 
                            onClick={() => setWireMode(wireMode === 'manhattan' ? 'bezier' : 'manhattan')}
                            className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-medium transition-colors text-zinc-400 hover:text-zinc-200`}
                            title="Toggle Wire Style"
                        >
                            <Cable size={14} />
                        </button>
                     </div>
                </div>

                {/* Center: Simulation Controls */}
                <div className="flex items-center space-x-2 bg-zinc-900 border border-zinc-800 p-1 rounded-lg shadow-inner">
                    <button 
                        onClick={checkCompatibility}
                        className="p-1.5 rounded text-zinc-400 hover:text-green-400 hover:bg-green-900/20 transition-colors"
                        title="Check Circuit Compatibility"
                    >
                        <CheckCircle2 size={16} />
                    </button>
                    <div className="h-4 w-px bg-zinc-800"></div>

                    <button 
                        onClick={stepBackward}
                        disabled={!isSimulating || history.length === 0}
                        className="p-1.5 rounded text-zinc-400 hover:text-white hover:bg-zinc-700 transition-colors disabled:opacity-30 disabled:hover:bg-transparent"
                        title="Step Back"
                    >
                        <SkipBack size={16} />
                    </button>

                    <button 
                        onClick={toggleSimulation}
                        className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-bold transition-all ${
                            isSimulating 
                                ? 'bg-red-500/10 text-red-500 hover:bg-red-500/20 border border-red-500/50' 
                                : 'bg-green-600 hover:bg-green-500 text-white shadow-lg shadow-green-900/20'
                        }`}
                    >
                        {isSimulating ? <RotateCcw size={14} /> : <Play size={14} />}
                        <span>{isSimulating ? 'Stop' : 'Run'}</span>
                    </button>

                    {isSimulating && (
                         <button 
                            onClick={() => setIsPaused(!isPaused)}
                            className={`p-1.5 rounded transition-colors ${isPaused ? 'text-amber-400 bg-amber-900/20' : 'text-zinc-400 hover:text-white hover:bg-zinc-700'}`}
                            title={isPaused ? "Resume" : "Pause"}
                        >
                            {isPaused ? <Play size={14} /> : <Pause size={14} />}
                        </button>
                    )}

                    <button 
                        onClick={stepForward}
                        disabled={!isSimulating}
                        className="p-1.5 rounded text-zinc-400 hover:text-white hover:bg-zinc-700 transition-colors disabled:opacity-30 disabled:hover:bg-transparent"
                        title="Step Forward"
                    >
                        <SkipForward size={16} />
                    </button>
                </div>

                {/* Right: Actions */}
                <div className="flex items-center space-x-4">
                     {selectedId && (
                        <button 
                        onClick={deleteSelection}
                        className="flex items-center space-x-2 px-3 py-1.5 bg-red-500/10 text-red-400 hover:bg-red-500/20 border border-red-500/30 rounded-md text-xs font-medium transition-colors"
                        >
                        <X size={14} />
                        <span>Delete</span>
                    </button>
                    )}
                    <button 
                        onClick={() => { setCircuit({ nodes: [], wires: [] }); setIsSimulating(false); }}
                        className="p-2 hover:bg-zinc-800 text-zinc-500 hover:text-red-400 rounded-md transition-colors"
                        title="Clear Canvas"
                    >
                        <Trash2 size={16} />
                    </button>
                </div>
            </div>

            {/* Canvas */}
            <div 
                ref={containerRef}
                className={`flex-1 relative w-full h-full overflow-hidden 
                    ${isSimulating ? 'cursor-default' : toolMode === 'junction' ? 'cursor-crosshair' : 'cursor-crosshair'}`}
                onDragOver={handleDragOver}
                onDrop={handleDrop}
                onMouseMove={handleMouseMove}
                onMouseUp={handleMouseUp}
                onClick={handleCanvasClick}
                onContextMenu={(e) => e.preventDefault()}
            >
                {/* Validation Messages Overlay */}
                {validationResult && (
                    <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 pointer-events-none w-auto max-w-lg">
                        <div className={`p-4 rounded-lg shadow-xl backdrop-blur-md border animate-in slide-in-from-top-4 duration-200
                            ${validationResult.valid ? 'bg-green-950/80 border-green-800 text-green-200' : 'bg-red-950/80 border-red-800 text-red-200'}`}
                        >
                            <div className="flex items-start gap-3">
                                {validationResult.valid ? <CheckCircle2 size={20} className="mt-0.5 text-green-400" /> : <AlertTriangle size={20} className="mt-0.5 text-red-400" />}
                                <div>
                                    <h4 className="font-bold text-sm mb-1">{validationResult.valid ? 'Circuit Valid' : 'Compatibility Issues Found'}</h4>
                                    <ul className="text-xs space-y-1 list-disc list-inside opacity-90">
                                        {validationResult.messages.map((m, i) => <li key={i}>{m}</li>)}
                                    </ul>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* Grid Pattern */}
                <svg className="absolute inset-0 pointer-events-none w-full h-full opacity-20">
                    <defs>
                        <pattern id="grid" width={GRID_SIZE} height={GRID_SIZE} patternUnits="userSpaceOnUse">
                            <circle cx="1" cy="1" r="1" fill="#71717a" />
                        </pattern>
                    </defs>
                    <rect width="100%" height="100%" fill="url(#grid)" />
                </svg>

                {/* Connections */}
                <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
                    {circuit.wires.map(wire => {
                        const sourceNode = circuit.nodes.find(n => n.id === wire.sourceNodeId);
                        const targetNode = circuit.nodes.find(n => n.id === wire.targetNodeId);
                        if (!sourceNode || !targetNode) return null;

                        const sourcePorts = getOutputPorts(sourceNode);
                        const targetPorts = getInputPorts(targetNode);

                        const outputOffset = sourcePorts[wire.sourceOutputIndex] || { x: 0, y: 0 };
                        const inputOffset = targetPorts[wire.targetInputIndex] || { x: 0, y: 0 };

                        const startX = sourceNode.position.x + outputOffset.x;
                        const startY = sourceNode.position.y + outputOffset.y;
                        const endX = targetNode.position.x + inputOffset.x;
                        const endY = targetNode.position.y + inputOffset.y;

                        const isSelected = selectedId === wire.id;
                        const pathData = getWirePath(startX, startY, endX, endY);

                        return (
                            <g 
                                key={wire.id} 
                                onClick={(e) => { 
                                    if (!containerRef.current) return;
                                    const rect = containerRef.current.getBoundingClientRect();
                                    handleWireClick(e, wire, e.clientX - rect.left, e.clientY - rect.top);
                                }} 
                                className={`pointer-events-auto cursor-pointer group`}
                            >
                                <path d={pathData} stroke="transparent" strokeWidth="16" fill="none" />
                                {wire.state && <path d={pathData} stroke="#22d3ee" strokeWidth="4" fill="none" opacity="0.3" filter="blur(2px)" />}
                                <path d={pathData} stroke={wire.state ? "#22d3ee" : "#52525b"} strokeWidth={isSelected ? "3" : "2"} fill="none" className="transition-colors duration-150" strokeDasharray={isSelected ? "4" : "0"} strokeLinejoin="round" strokeLinecap="round" />
                            </g>
                        );
                    })}

                    {wiring && (
                        <path d={getWirePath(wiring.startPoint.x, wiring.startPoint.y, mousePos.x, mousePos.y)} stroke="#fbbf24" strokeWidth="2" fill="none" strokeDasharray="4" className="animate-pulse" strokeLinejoin="round" />
                    )}
                </svg>

                {/* Nodes */}
                {circuit.nodes.map(node => {
                    const { width, height } = getNodeDimensions(node);
                    const isSelected = selectedId === node.id;
                    const inputPorts = getInputPorts(node);
                    const outputPorts = getOutputPorts(node);
                    const def = NODE_DEFINITIONS[node.type];
                    // Always allow interaction in sim mode
                    const canInteract = ['SWITCH', 'BUTTON'].includes(node.type);

                    return (
                        <div
                            key={node.id}
                            className={`absolute group select-none`}
                            style={{
                                left: node.position.x,
                                top: node.position.y,
                                width: width,
                                height: height,
                                pointerEvents: 'none',
                                zIndex: isSelected ? 50 : 10 
                            }}
                        >
                            <div 
                                className={`absolute inset-0 pointer-events-auto transition-all duration-200 
                                    ${isSelected ? 'drop-shadow-[0_0_8px_rgba(34,211,238,0.5)]' : ''} 
                                    ${(toolMode === 'interact' || isSimulating) && canInteract ? 'cursor-pointer' : 'cursor-grab active:cursor-grabbing'}
                                `}
                                onMouseDown={(e) => handleNodeMouseDown(e, node.id)}
                            >
                                <svg width={width} height={height} className="overflow-visible">
                                    <GateShape node={node} />
                                </svg>
                            </div>

                            {inputPorts.map((offset, idx) => (
                                <div
                                    key={`input-${idx}`}
                                    className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 
                                    ${(toolMode === 'select' || toolMode === 'junction') && !isSimulating ? 'cursor-crosshair' : 'cursor-default'}`}
                                    style={{ left: offset.x, top: offset.y }}
                                    onMouseUp={(e) => !isSimulating && (toolMode === 'select' || toolMode === 'junction') && completeWiring(e, node.id, idx)}
                                    title={offset.label || "Input"}
                                >
                                    <div className={`w-2 h-2 rounded-full bg-zinc-900 border ${node.inputs[idx] ? 'border-cyan-400 bg-cyan-900' : 'border-zinc-500'}`} />
                                </div>
                            ))}

                            {outputPorts.map((offset, idx) => (
                                <div
                                    key={`output-${idx}`}
                                    className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 
                                    ${(toolMode === 'select' || toolMode === 'junction') && !isSimulating ? 'cursor-crosshair' : 'cursor-default'}`}
                                    style={{ left: offset.x, top: offset.y }}
                                    onMouseDown={(e) => !isSimulating && (toolMode === 'select' || toolMode === 'junction') && startWiring(e, node.id, idx)}
                                    title={offset.label || "Output"}
                                >
                                    <div className={`w-2 h-2 rounded-full bg-zinc-900 border ${node.outputs[idx] ? 'border-cyan-400 bg-cyan-500' : 'border-zinc-500 group-hover:border-zinc-300'}`} />
                                </div>
                            ))}

                            {(isSelected || node.properties?.label) && node.type !== 'JUNCTION' && (
                                <div className="absolute -top-7 left-1/2 -translate-x-1/2 bg-zinc-900/90 text-zinc-100 text-[10px] px-2 py-0.5 rounded border border-zinc-700 whitespace-nowrap shadow-md pointer-events-none backdrop-blur-sm z-[60]">
                                    {node.properties?.label || def.name}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </div>

        {/* Properties Panel (Right Side) */}
        <PropertiesPanel node={selectedNode} onUpdate={handleNodeUpdate} />
    </div>
  );
};

export type NodeType = 
  | 'AND' | 'OR' | 'NOT' | 'XOR' | 'NAND' | 'NOR' | 'XNOR' | 'BUFFER'
  | 'SWITCH' | 'BULB' | 'CLOCK' | 'BUTTON' | 'CONSTANT_1' | 'CONSTANT_0'
  | 'INPUT_2BIT' | 'INPUT_4BIT' | 'INPUT_8BIT' | 'INPUT_16BIT'
  | 'OUTPUT_2BIT' | 'OUTPUT_4BIT' | 'OUTPUT_8BIT' | 'OUTPUT_16BIT'
  | 'HALF_ADDER' | 'FULL_ADDER' | 'SUBTRACTOR' | 'COMPARATOR_1BIT'
  | 'D_LATCH' | 'D_FF' | 'JK_FF' | 'T_FF' | 'SR_FF'
  | 'GATED_SR_LATCH' | 'JK_MASTER_SLAVE' | 'RAM_1BIT' | 'ROM_1BIT' | 'SHIFT_REGISTER_4BIT'
  | 'MUX_2_1' | 'MUX_4_1' | 'DEMUX_1_2' | 'DEMUX_1_4'
  | 'DECODER_2_4' | 'PRIORITY_ENCODER_4_2'
  | 'HEX_DISPLAY' | 'SEVEN_SEGMENT'
  | 'JUNCTION';

export interface Point {
  x: number;
  y: number;
}

export interface Port {
  id: string;
  type: 'input' | 'output';
  offset: Point;
  label?: string;
}

export interface NodeData {
  id: string;
  type: NodeType;
  position: Point;
  inputs: boolean[];
  outputs: boolean[];
  // Used for stateful components like Flip-Flops to detect edges
  internalState?: {
    lastClock?: boolean;
    storedValue?: boolean;
    masterValue?: boolean; // For Master-Slave
    register?: boolean[]; // For Shift Register
    [key: string]: any;
  };
  // Customizable properties
  properties?: {
    label?: string;
    inputCount?: number;
    propagationDelay?: number;
    initialState?: boolean;
    romValue?: boolean; // For ROM
    [key: string]: any;
  };
}

export interface Wire {
  id: string;
  sourceNodeId: string;
  sourceOutputIndex: number;
  targetNodeId: string;
  targetInputIndex: number;
  state: boolean;
}

export interface CircuitState {
  nodes: NodeData[];
  wires: Wire[];
}

export interface WiringState {
  sourceNodeId: string;
  sourceOutputIndex: number;
  startPoint: Point;
  active: boolean;
}

import { NodeType } from './types';

export const GRID_SIZE = 20;

// Helper to generate port offsets for multi-bit components
const generatePorts = (count: number, x: number, startY: number = 20) => {
    return Array.from({ length: count }, (_, i) => ({
        x,
        y: startY + (i * 20),
        label: `${i}`
    }));
};

