                        <CheckCircle2 size={16} />
                    </button>
                    <div className="h-4 w-px bg-zinc-200 dark:bg-zinc-800"></div>
                    <button onClick={stepBackward} disabled={!isSimulating || !hasHistory} className="p-1.5 rounded text-zinc-400 hover:text-zinc-900 dark:hover:text-white hover:bg-zinc-100 dark:hover:bg-zinc-700 transition-colors disabled:opacity-30 disabled:hover:bg-transparent" title="Step Back">
                        <SkipBack size={16} />
