                    {isSimulating && (
                        <button onClick={() => setIsPaused(!isPaused)} className={`p-1.5 rounded transition-colors ${isPaused ? 'text-amber-500 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20' : 'text-zinc-400 hover:text-zinc-900 dark:hover:text-white hover:bg-zinc-100 dark:hover:bg-zinc-700'}`} title={isPaused ? "Resume" : "Pause"}>
                            {isPaused ? <Play size={14} /> : <Pause size={14} />}
                        </button>
                    )}
                    <button onClick={stepForward} disabled={!isSimulating} className="p-1.5 rounded text-zinc-400 hover:text-zinc-900 dark:hover:text-white hover:bg-zinc-100 dark:hover:bg-zinc-700 transition-colors disabled:opacity-30 disabled:hover:bg-transparent" title="Step Forward">
                        <SkipForward size={16} />
                    </button>
                </div>

            </div>

            {/* Right Actions */}
            <div className="flex items-center space-x-3 ml-4">
                 {selectedId && (
                    <button onClick={deleteSelection} className="flex items-center space-x-1 px-3 py-1.5 bg-red-50 text-red-500 dark:bg-red-500/10 dark:text-red-400 hover:bg-red-100 dark:hover:bg-red-500/20 border border-red-200 dark:border-red-500/30 rounded-md text-xs font-medium transition-colors" title="Delete Selected">
                        <X size={14} />
                        <span className="hidden sm:inline">Delete</span>
                    </button>
                )}
                <button onClick={toggleTheme} className="p-2 text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-white transition-colors" title="Toggle Theme">
                    {theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}
                </button>
                <button onClick={onClear} className="p-2 hover:bg-zinc-100 dark:hover:bg-zinc-800 text-zinc-500 hover:text-red-500 dark:hover:text-red-400 rounded-md transition-colors" title="Clear Canvas">
                    <Trash2 size={16} />
                </button>
            </div>
