                <rect x="40" y="75" width="60" height="40" rx="2" fill="#000" stroke="#3f3f46" />
                <GateText x={70} y={87} fill="#71717a" fontSize="9">DATA</GateText>
                <GateText x={70} y={103} fill="#ef4444" fontSize="12">{`0x${storedVal.toString(16).toUpperCase().padStart(dataBits > 8 ? 4 : 2, '0')}`}</GateText>

                {/* Status Indicator */}
                <rect x="40" y="125" width="60" height="16" rx="2" fill={CS ? (WE ? "#7f1d1d" : "#064e3b") : "#27272a"} />
                <GateText x={70} y={133} fill={CS ? "#fff" : "#52525b"} fontSize="9">{status}</GateText>

            </g>
        );

    // --- Plexers ---
    case 'MUX_2_1':
        return (
          <g>
              <path d="M 0 0 L 60 20 L 60 60 L 0 80 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
              <GateText x={30} y={40}>MUX</GateText>
              <GateText x={10} y={20}>0</GateText> <GateText x={10} y={60}>1</GateText> <GateText x={30} y={70}>S</GateText>
              <GateText x={50} y={40}>Y</GateText>
          </g>
        );
    case 'MUX_4_1':
        return (
            <g>
                <path d="M 0 0 L 60 20 L 60 100 L 0 120 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <GateText x={30} y={60}>MUX 4</GateText>
                <GateText x={10} y={20}>0</GateText> <GateText x={10} y={40}>1</GateText>
                <GateText x={10} y={60}>2</GateText> <GateText x={10} y={80}>3</GateText>
                <GateText x={50} y={60}>Y</GateText>
            </g>
        );
    case 'DEMUX_1_2':
        return (
          <g>
              <path d="M 0 20 L 60 0 L 60 80 L 0 60 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
              <GateText x={30} y={40}>DEMUX</GateText>
              <GateText x={10} y={40}>D</GateText> 
              <GateText x={50} y={20}>0</GateText> <GateText x={50} y={60}>1</GateText>
          </g>
        );
    case 'DEMUX_1_4':
        return (
            <g>
                <path d="M 0 20 L 60 0 L 60 120 L 0 100 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <GateText x={30} y={60}>DEMUX 4</GateText>
                <GateText x={10} y={60}>D</GateText> 
                <GateText x={50} y={20}>0</GateText> <GateText x={50} y={40}>1</GateText>
                <GateText x={50} y={60}>2</GateText> <GateText x={50} y={80}>3</GateText>
            </g>
        );
    case 'DECODER_2_4':
        return (
            <g>
                <rect x="0" y="0" width="60" height="100" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={30} y={50}>DEC 2:4</GateText>
                <GateText x={10} y={80}>0</GateText> <GateText x={10} y={90}>1</GateText>
                <GateText x={50} y={20}>0</GateText> <GateText x={50} y={40}>1</GateText>
                <GateText x={50} y={60}>2</GateText> <GateText x={50} y={80}>3</GateText>
            </g>
        );
    case 'PRIORITY_ENCODER_4_2':
        return (
            <g>
                <rect x="0" y="0" width="70" height="100" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={35} y={10}>PRIO ENC</GateText>
                <GateText x={10} y={20}>0</GateText> <GateText x={10} y={40}>1</GateText>
                <GateText x={10} y={60}>2</GateText> <GateText x={10} y={80}>3</GateText>
                <GateText x={60} y={30}>A0</GateText> <GateText x={60} y={50}>A1</GateText> <GateText x={60} y={80}>V</GateText>
            </g>
        );

    default:
      return <rect width="40" height="40" fill="red" />;
  }
};

import { NodeData, Wire, NodeType } from '../types';

export const evaluateCircuit = (nodes: NodeData[], wires: Wire[]): { nodes: NodeData[], wires: Wire[] } => {
  // 1. Snapshot previous state (inputs/outputs) to detect edges or retain memory
  // We don't deep copy internalState here because we want to update it
  let nextNodes = nodes.map(n => ({ 
    ...n, 
    inputs: [...n.inputs], 
    outputs: [...n.outputs],
    internalState: { ...n.internalState },
    properties: { ...n.properties }
  }));
  let nextWires = wires.map(w => ({ ...w }));

  // Preserve the *initial* inputs of this frame for edge detection
  // This allows us to compare "What was the clock before this eval cycle?" vs "What is it now?"
  const initialNodesState = new Map(nodes.map(n => [n.id, n]));

  let stable = false;
  let iterations = 0;
  const MAX_ITERATIONS = 50; 

  while (!stable && iterations < MAX_ITERATIONS) {
    stable = true;
    iterations++;

    // --- Wire Propagation ---
    nextWires.forEach(wire => {
      const sourceNode = nextNodes.find(n => n.id === wire.sourceNodeId);
      if (sourceNode) {
        const val = sourceNode.outputs[wire.sourceOutputIndex] || false;
        if (wire.state !== val) {
          wire.state = val;
          stable = false;
        }
      }
    });

    nextWires.forEach(wire => {
      const targetNode = nextNodes.find(n => n.id === wire.targetNodeId);
      if (targetNode) {
        if (targetNode.inputs[wire.targetInputIndex] !== wire.state) {
          targetNode.inputs[wire.targetInputIndex] = wire.state;
          stable = false;
        }
      }
    });

    // --- Node Evaluation ---
    nextNodes.forEach(node => {
      // Skip input-only nodes (sources) but process CONSTANTs
      if (['SWITCH', 'CLOCK', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type)) return;

      const oldOutputs = [...node.outputs];
      let newOutputs = [...oldOutputs];

      const prevNodeState = initialNodesState.get(node.id);

      switch (node.type) {
        // Gates (Dynamic Input Support)
        case 'AND': 
          newOutputs = [node.inputs.every(v => v === true)]; 
          break;
        case 'OR': 
          newOutputs = [node.inputs.some(v => v === true)]; 
          break;
        case 'NOT': 
          newOutputs = [!node.inputs[0]]; 
          break;
        case 'NAND': 
          newOutputs = [!node.inputs.every(v => v === true)]; 
          break;
        case 'NOR': 
          newOutputs = [!node.inputs.some(v => v === true)]; 
          break;
        case 'XOR': 
          // Odd number of 1s
          newOutputs = [node.inputs.filter(v => v).length % 2 === 1]; 
          break;
        case 'XNOR': 
           // Even number of 1s (for >2 inputs this is the definition usually used in parity)
           // For 2 inputs: !(A^B). For N inputs: !(OddParity).
          newOutputs = [node.inputs.filter(v => v).length % 2 === 0]; 
          break;
        case 'BUFFER': newOutputs = [node.inputs[0]]; break;
        case 'CONSTANT_1': newOutputs = [true]; break;
        case 'CONSTANT_0': newOutputs = [false]; break;

        // Junction acts as a pass-through buffer
        case 'JUNCTION':
            newOutputs = [node.inputs[0]];
            break;

        // Output Objects
        case 'BULB': case 'HEX_DISPLAY': case 'SEVEN_SEGMENT': 
        case 'OUTPUT_2BIT': case 'OUTPUT_4BIT': case 'OUTPUT_8BIT': case 'OUTPUT_16BIT':
            break; // No outputs

        // Arithmetic
        case 'HALF_ADDER': {
           const a = node.inputs[0]; const b = node.inputs[1];
           newOutputs = [a !== b, a && b]; 
           break;
        }
        case 'FULL_ADDER': {
            const a = node.inputs[0]; const b = node.inputs[1]; const cin = node.inputs[2];
            const sum = (a ? 1:0) + (b ? 1:0) + (cin ? 1:0);
            newOutputs = [sum % 2 === 1, sum >= 2];
            break;
        }
        case 'SUBTRACTOR': {
            const a = node.inputs[0]; const b = node.inputs[1];
            newOutputs = [a !== b, (!a && b)]; // Diff, Borrow
            break;
        }
        case 'COMPARATOR_1BIT': {
            const a = node.inputs[0]; const b = node.inputs[1];
            newOutputs = [
                a && !b, // >
                a === b, // =
                !a && b  // <
            ];
            break;
        }

        // Plexers
        case 'MUX_2_1':
           newOutputs = [node.inputs[2] ? node.inputs[1] : node.inputs[0]];
           break;
        case 'MUX_4_1': {
            const s0 = node.inputs[4]; const s1 = node.inputs[5];
            const idx = (s0?1:0) + (s1?2:0);
            newOutputs = [node.inputs[idx]];
            break;
        }
        case 'DEMUX_1_2': {
            const d = node.inputs[0]; const s = node.inputs[1];
            newOutputs = [!s ? d : false, s ? d : false];
            break;
        }
        case 'DEMUX_1_4': {
            const d = node.inputs[0]; const s0 = node.inputs[1]; const s1 = node.inputs[2];
            const idx = (s0?1:0) + (s1?2:0);
            newOutputs = [false, false, false, false];
            newOutputs[idx] = d;
            break;
        }
        case 'DECODER_2_4': {
            const s0 = node.inputs[0]; const s1 = node.inputs[1];
            const idx = (s0?1:0) + (s1?2:0);
            newOutputs = [false, false, false, false];
            newOutputs[idx] = true;
            break;
        }
        case 'PRIORITY_ENCODER_4_2': {
            // Priority 3 > 2 > 1 > 0
            const i0 = node.inputs[0]; const i1 = node.inputs[1];
            const i2 = node.inputs[2]; const i3 = node.inputs[3];
            let a0 = false, a1 = false, v = false;

            if (i3) { a1=true; a0=true; v=true; }
            else if (i2) { a1=true; a0=false; v=true; }
            else if (i1) { a1=false; a0=true; v=true; }
            else if (i0) { a1=false; a0=false; v=true; }

            newOutputs = [a0, a1, v];
            break;
        }

        // State / Memory
        case 'D_LATCH': {
           const D = node.inputs[0]; const E = node.inputs[1];
           const Q = E ? D : oldOutputs[0];
           newOutputs = [Q, !Q];
           break;
        }
        case 'D_FF': {
           const D = node.inputs[0]; const Clk = node.inputs[1];
           const lastClk = node.internalState?.lastClock || false;
           const trigger = node.properties?.trigger || 'Rising';
           let triggered = false;

           if (trigger === 'Rising') triggered = !lastClk && Clk;
           else if (trigger === 'Falling') triggered = lastClk && !Clk;

           let Q = oldOutputs[0];

           if (triggered) {
               Q = D;
           }
           newOutputs = [Q, !Q];
           node.internalState = { ...node.internalState, lastClock: Clk };
           break;
        }
        case 'T_FF': {
           const T = node.inputs[0]; const Clk = node.inputs[1];
           const lastClk = node.internalState?.lastClock || false;
           const trigger = node.properties?.trigger || 'Rising';
           let triggered = false;

           if (trigger === 'Rising') triggered = !lastClk && Clk;
           else if (trigger === 'Falling') triggered = lastClk && !Clk;

           let Q = oldOutputs[0];

           if (triggered) {
               if (T) Q = !Q;
           }
           newOutputs = [Q, !Q];
           node.internalState = { ...node.internalState, lastClock: Clk };
           break;
        }
        case 'JK_FF': {
           const J = node.inputs[0]; const Clk = node.inputs[1]; const K = node.inputs[2];
           const lastClk = node.internalState?.lastClock || false;
           const trigger = node.properties?.trigger || 'Rising';
           let triggered = false;

           if (trigger === 'Rising') triggered = !lastClk && Clk;
           else if (trigger === 'Falling') triggered = lastClk && !Clk;

           let Q = oldOutputs[0];

           if (triggered) {
               if (J && !K) Q = true;
               else if (!J && K) Q = false;
               else if (J && K) Q = !Q;
           }
           newOutputs = [Q, !Q];
           node.internalState = { ...node.internalState, lastClock: Clk };
           break;
        }
        case 'SR_FF': {
            const S = node.inputs[0]; const Clk = node.inputs[1]; const R = node.inputs[2];
            const lastClk = node.internalState?.lastClock || false;
            const trigger = node.properties?.trigger || 'Rising';
            let triggered = false;

            if (trigger === 'Rising') triggered = !lastClk && Clk;
            else if (trigger === 'Falling') triggered = lastClk && !Clk;

            let Q = oldOutputs[0];

            if (triggered) {
                if (S && !R) Q = true;
                else if (!S && R) Q = false;
            }
            newOutputs = [Q, !Q];
            node.internalState = { ...node.internalState, lastClock: Clk };
            break;
        }
        case 'GATED_SR_LATCH': {
            const S = node.inputs[0]; const En = node.inputs[1]; const R = node.inputs[2];
            let Q = oldOutputs[0];
            if (En) {
                if (S && !R) Q = true;
                else if (!S && R) Q = false;
            }
            newOutputs = [Q, !Q];
            break;
        }
        case 'JK_MASTER_SLAVE': {
            const J = node.inputs[0]; const Clk = node.inputs[1]; const K = node.inputs[2];
            const lastClk = node.internalState?.lastClock || false;
            // Usually Master-Slave is pulse triggered (High level Master active, Falling edge transfer to Slave)
            // But if we want to support "Trigger" prop here, we can.
            // Standard JK-MS behavior is latching on High, updating output on Falling.
            // Let's stick to standard behavior unless heavily modified.
            // For now, let's just make it behave like a Falling Edge FF if no prop, but respectful of standard M-S mechanics if feasible.
            // Simplified M-S often just looks like Falling Edge in discrete sim.

            let Q = oldOutputs[0];

            if (lastClk && !Clk) { // Falling Edge
                if (J && !K) Q = true;
                else if (!J && K) Q = false;
                else if (J && K) Q = !Q;
            }
            newOutputs = [Q, !Q];
            node.internalState = { ...node.internalState, lastClock: Clk };
            break;
        }
        case 'RAM_1BIT': {
            const Data = node.inputs[0]; const Write = node.inputs[1]; const Sel = node.inputs[2];
            let stored = node.internalState?.storedValue || false;

            if (Sel && Write) {
                stored = Data;
            }

            newOutputs = [Sel ? stored : false];
            node.internalState = { ...node.internalState, storedValue: stored };
            break;
        }
        case 'ROM_1BIT': {
             const Sel = node.inputs[0];
             // Value is static property
             const val = node.properties?.romValue || false;
             newOutputs = [Sel ? val : false];
             break;
        }
        case 'SHIFT_REGISTER_4BIT': {
             const Data = node.inputs[0]; const Clk = node.inputs[1];
             const lastClk = node.internalState?.lastClock || false;
             const trigger = node.properties?.trigger || 'Rising';
             let triggered = false;

             if (trigger === 'Rising') triggered = !lastClk && Clk;
             else if (trigger === 'Falling') triggered = lastClk && !Clk;

             let reg = node.internalState?.register || [false, false, false, false];

             if (triggered) { 
                 // Shift right: Q0 gets Data, Q1 gets Q0...
                 reg = [Data, reg[0], reg[1], reg[2]];
             }

             newOutputs = [...reg];
             node.internalState = { ...node.internalState, lastClock: Clk, register: reg };
             break;
        }
        case 'RAM_4BIT':
        case 'RAM_8BIT':
        case 'RAM_16BIT': {
            const dataWidth = node.type === 'RAM_4BIT' ? 4 : (node.type === 'RAM_8BIT' ? 8 : 16);
            const addrWidth = 4; // hardcoded for 16 words

            // Reconstruct Address
            let address = 0;
            for(let i=0; i<addrWidth; i++) {
                if(node.inputs[i]) address += Math.pow(2, i);
            }

            // Reconstruct Data In
            let dataIn = 0;
            for(let i=0; i<dataWidth; i++) {
                if(node.inputs[addrWidth + i]) dataIn += Math.pow(2, i);
            }

            const WE = node.inputs[addrWidth + dataWidth];
            const CS = node.inputs[addrWidth + dataWidth + 1];

            // Initialize memory if empty. 2^4 = 16 words.
            let memory = node.internalState?.memory;
            if (!memory || !Array.isArray(memory)) {
                memory = new Array(16).fill(0);
            }

            let val = 0;
            if (CS) {
                if (WE) {
                    // Write
                    memory[address] = dataIn;
                }
                // Read (always read current address if CS enabled, effectively)
                val = memory[address];
            }

            // Deconstruct output bits from val
            newOutputs = [];
            for(let i=0; i<dataWidth; i++) {
                newOutputs.push(!!((val >> i) & 1));
            }

            // Update state
            // Copy array to avoid direct mutation issues
            const nextMemory = [...memory];
            if (CS && WE) {
                nextMemory[address] = dataIn;
            }

            node.internalState = { ...node.internalState, memory: nextMemory };
            break;
        }
      }

      // Diff check
      let changed = false;
      if (newOutputs.length !== node.outputs.length) changed = true;
      else {
          for(let i=0; i<newOutputs.length; i++) {
              if (node.outputs[i] !== newOutputs[i]) {
                  changed = true;
                  break;
              }
          }
      }

      if (changed) {
          node.outputs = newOutputs;
          stable = false;
      }
    });
  }

  return { nodes: nextNodes, wires: nextWires };
};

import React, { useState, useCallback, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { CircuitCanvas } from './components/CircuitCanvas';
import { Header } from './components/Header';
import { PropertiesPanel } from './components/PropertiesPanel';
import { ThemeProvider, useTheme } from './components/ThemeContext';
import { CircuitState, NodeData, NodeType, Wire } from './types';
import { evaluateCircuit } from './utils/circuitLogic';
import { NODE_DEFINITIONS } from './constants';

const MAX_HISTORY = 50;

const AppContent: React.FC = () => {
  const { theme, toggleTheme } = useTheme();

  // -- Global Application State --
  const [circuit, setCircuit] = useState<CircuitState>({ nodes: [], wires: [] });
  // Edit History
  const [past, setPast] = useState<CircuitState[]>([]);
  const [future, setFuture] = useState<CircuitState[]>([]);
  // Simulation History (Running Buffer)
  const [simHistory, setSimHistory] = useState<CircuitState[]>([]);

  const [pendingComponent, setPendingComponent] = useState<NodeType | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  // -- Interaction Modes --
  const [toolMode, setToolMode] = useState<'select' | 'interact' | 'junction'>('select');
  const [wireMode, setWireMode] = useState<'manhattan' | 'bezier'>('manhattan');

  // -- Simulation State --
  const [isSimulating, setIsSimulating] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  // -- UI Layout State --
  const [sidebarWidth, setSidebarWidth] = useState(260);
  const [panelWidth, setPanelWidth] = useState(260);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);
  const [isResizingPanel, setIsResizingPanel] = useState(false);

  // -- Validation State --
  const [validationResult, setValidationResult] = useState<{
      valid: boolean; 
      messages: string[]; 
      invalidNodeIds: string[];
      floatingInputs: { nodeId: string; index: number }[];
  } | null>(null);

  // --------------------------------------------------------------------------
  // History Management (Undo/Redo)
  // --------------------------------------------------------------------------

  // Save current state to history. Should be called BEFORE a destructive action.
  const snapshot = useCallback(() => {
    setPast(prev => {
        // Dedup: Don't push if identical to last state (simple reference/string check)
        const last = prev[prev.length - 1];
        if (last && JSON.stringify(last) === JSON.stringify(circuit)) return prev;

        const newPast = [...prev, circuit];
        if (newPast.length > MAX_HISTORY) return newPast.slice(newPast.length - MAX_HISTORY);
        return newPast;
    });
    setFuture([]);
  }, [circuit]);

  const undo = useCallback(() => {
      if (past.length === 0) return;
      const previous = past[past.length - 1];
      const newPast = past.slice(0, -1);

      setFuture(prev => [circuit, ...prev]);
      setPast(newPast);
      setCircuit(previous);
      // Stop sim if undoing edits
      if (isSimulating) {
        setIsSimulating(false);
        setSimHistory([]);
      }
      setValidationResult(null);
  }, [past, circuit, isSimulating]);

  const redo = useCallback(() => {
      if (future.length === 0) return;
      const next = future[0];
      const newFuture = future.slice(1);

      setPast(prev => [...prev, circuit]);
      setFuture(newFuture);
      setCircuit(next);
      if (isSimulating) {
        setIsSimulating(false);
        setSimHistory([]);
      }
      setValidationResult(null);
  }, [future, circuit, isSimulating]);

  // Keyboard Shortcuts for Undo/Redo
  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if ((e.metaKey || e.ctrlKey) && e.key === 'z') {
              e.preventDefault();
              undo();
          }
          if ((e.metaKey || e.ctrlKey) && e.key === 'y') {
              e.preventDefault();
              redo();
          }
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [undo, redo]);

  // --------------------------------------------------------------------------
  // Simulation Logic
  // --------------------------------------------------------------------------
  const tick = useCallback(() => {
    setCircuit(prev => {
        // Save history before tick for stepping back in simulation
        setSimHistory(h => {
            const newHistory = [...h, prev];
            if (newHistory.length > MAX_HISTORY) return newHistory.slice(1);
            return newHistory;
        });

        const hasClock = prev.nodes.some(n => n.type === 'CLOCK');
        let nextNodes = [...prev.nodes];

        // Update Clocks
        if (hasClock) {
            nextNodes = nextNodes.map(n => {
                if (n.type === 'CLOCK') {
                    const speed = n.properties?.interval || 20; 
                    const currentCount = (n.internalState?.tickCount || 0) + 1;

                    if (currentCount >= speed) {
                         return { 
                             ...n, 
                             outputs: [!n.outputs[0]],
                             internalState: { ...n.internalState, tickCount: 0 }
                         };
                    } else {
                        return { 
                             ...n, 
                             internalState: { ...n.internalState, tickCount: currentCount }
                        };
                    }
                }
                return n;
            });
        }
        return evaluateCircuit(nextNodes, prev.wires);
    });
  }, []);

  useEffect(() => {
    let interval: number;
    if (isSimulating && !isPaused) {
        interval = window.setInterval(tick, 50);
    }
    return () => clearInterval(interval);
  }, [isSimulating, isPaused, tick]);

  // --------------------------------------------------------------------------
  // Validation Logic
  // --------------------------------------------------------------------------
  const validateCircuit = useCallback(() => {
      const messages: string[] = [];
      const invalidNodeIds: string[] = [];
      const floatingInputs: { nodeId: string; index: number }[] = [];
      let valid = true;

      if (circuit.nodes.length === 0) {
          return { valid: false, messages: ["Circuit is empty."], invalidNodeIds: [], floatingInputs: [] };
      }

      circuit.nodes.forEach(node => {
          // Components that don't need input validation
          if (['SWITCH', 'CLOCK', 'BUTTON', 'CONSTANT_1', 'CONSTANT_0', 'JUNCTION'].includes(node.type)) return;

          const inputCount = node.inputs.length;
          let nodeHasFloatingInput = false;

          for(let i=0; i<inputCount; i++) {
              const isConnected = circuit.wires.some(w => w.targetNodeId === node.id && w.targetInputIndex === i);
              if (!isConnected) {
                  valid = false;
                  nodeHasFloatingInput = true;
                  floatingInputs.push({ nodeId: node.id, index: i });
              }
          }

          if (nodeHasFloatingInput) {
              const label = node.properties?.label || node.type;
              messages.push(`${label} (ID: ${node.id.slice(-4)}): Missing input connections.`);
              invalidNodeIds.push(node.id);
          }
      });

      return { 
          valid, 
          messages: valid ? ["Circuit is compatible and valid."] : messages, 
          invalidNodeIds,
          floatingInputs
      };
  }, [circuit]);

  const toggleSimulation = () => {
    if (isSimulating) {
        setIsSimulating(false);
        setIsPaused(false);
        setSimHistory([]); 
        setToolMode('select');
        setValidationResult(null);
    } else {
        // Enforce validation before running
        const result = validateCircuit();
        setValidationResult(result);
        if (!result.valid) {
            return;
        }

        setIsSimulating(true);
        setToolMode('interact'); 
        setSimHistory([circuit]);
    }
  };

  const checkCompatibility = () => {
      const result = validateCircuit();
      setValidationResult(result);
      if (result.valid) setTimeout(() => setValidationResult(null), 2000);
  };

  const stepForward = () => {
    if (!isSimulating) return;
    setIsPaused(true); 
    tick();
  };

  const stepBackward = () => {
    if (!isSimulating || simHistory.length === 0) return;
    setIsPaused(true);
    const prev = simHistory[simHistory.length - 1];
    setCircuit(prev);
    setSimHistory(h => h.slice(0, -1));
  };

  // --------------------------------------------------------------------------
  // Circuit Logic Helpers
  // --------------------------------------------------------------------------
  const handleUpdateCircuit = (nodes: NodeData[], wires: Wire[]) => {
      const evaluated = evaluateCircuit(nodes, wires);
      setCircuit(evaluated);
  };

  // --------------------------------------------------------------------------
  // File Ops
  // --------------------------------------------------------------------------
  const handleSave = () => {
    const data = JSON.stringify(circuit, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `logiclab-circuit-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleLoad = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
        try {
            const content = event.target?.result as string;
            const parsed = JSON.parse(content);
            if (parsed && Array.isArray(parsed.nodes) && Array.isArray(parsed.wires)) {
                // Loading a new file resets history
                setCircuit(parsed);
                setPast([]);
                setFuture([]);
                setSimHistory([]);
                setIsSimulating(false);
                setIsPaused(false);
                setValidationResult(null);
            } else {
                alert("Invalid circuit file format.");
            }
        } catch (err) {
            console.error(err);
            alert("Failed to parse file.");
        }
    };
    reader.readAsText(file);
  };

  const handleDeleteSelection = () => {
    if (!selectedId) return;
    // Snapshot before deleting
    snapshot();

    const isWire = circuit.wires.find(w => w.id === selectedId);
    if (isWire) {
        handleUpdateCircuit(circuit.nodes, circuit.wires.filter(w => w.id !== selectedId));
        setSelectedId(null);
        return;
    }
    const newWires = circuit.wires.filter(w => w.sourceNodeId !== selectedId && w.targetNodeId !== selectedId);
    const newNodes = circuit.nodes.filter(n => n.id !== selectedId);
    handleUpdateCircuit(newNodes, newWires);
    setSelectedId(null);
  };

  const handleNodeUpdate = (id: string, updates: Partial<NodeData>) => {
    // Snapshot before updating property
    snapshot();

    const prev = circuit;
    const newNodes = prev.nodes.map(n => {
        if (n.id === id) {
            let updatedNode = { ...n, ...updates };
            // Resize logic if type changes
            if (updates.type && updates.type !== n.type) {
                 const def = NODE_DEFINITIONS[updates.type];
                 if (def) {
                     const currentInputs = updatedNode.inputs;
                     updatedNode.inputs = def.inputs > currentInputs.length 
                        ? [...currentInputs, ...Array(def.inputs - currentInputs.length).fill(false)] 
                        : currentInputs.slice(0, def.inputs);

                     const currentOutputs = updatedNode.outputs;
                     updatedNode.outputs = def.outputs > currentOutputs.length 
                        ? [...currentOutputs, ...Array(def.outputs - currentOutputs.length).fill(false)] 
                        : currentOutputs.slice(0, def.outputs);
                 }
            }
            // Resize logic for variable gates
            if (updates.properties?.inputCount) {
                const count = updates.properties.inputCount;
                if (count > updatedNode.inputs.length) {
                    updatedNode.inputs = [...updatedNode.inputs, ...Array(count - updatedNode.inputs.length).fill(false)];
                } else if (count < updatedNode.inputs.length) {
                    updatedNode.inputs = updatedNode.inputs.slice(0, count);
                }
            }
            // Logic for initializing inputs based on properties
            if (updates.properties?.initialState !== undefined) {
                if (['SWITCH', 'CONSTANT_1', 'CONSTANT_0'].includes(updatedNode.type)) {
                     updatedNode.outputs = [!!updates.properties.initialState];
                }
                if (['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'D_LATCH'].includes(updatedNode.type)) {
                    updatedNode.internalState = { ...updatedNode.internalState, storedValue: !!updates.properties.initialState };
                    updatedNode.outputs = [!!updates.properties.initialState, !updates.properties.initialState];
                }
            }
            return updatedNode;
        }
        return n;
    });

    // Cleanup disconnected wires
    const validWires = prev.wires.filter(w => {
        const source = newNodes.find(n => n.id === w.sourceNodeId);
        const target = newNodes.find(n => n.id === w.targetNodeId);
        if (!source || !target) return false;
        if (w.sourceOutputIndex >= source.outputs.length) return false;
        if (w.targetInputIndex >= target.inputs.length) return false;
        return true;
    });

    handleUpdateCircuit(newNodes, validWires);
  };

  // --------------------------------------------------------------------------
  // Resize Handlers
  // --------------------------------------------------------------------------
  const startResizingSidebar = useCallback(() => setIsResizingSidebar(true), []);
  const startResizingPanel = useCallback(() => setIsResizingPanel(true), []);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (isResizingSidebar) {
          setSidebarWidth(Math.max(180, Math.min(450, e.clientX)));
      }
      if (isResizingPanel) {
          setPanelWidth(Math.max(200, Math.min(500, window.innerWidth - e.clientX)));
      }
    };
    const handleMouseUp = () => {
        setIsResizingSidebar(false);
        setIsResizingPanel(false);
    };

    if (isResizingSidebar || isResizingPanel) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
    } else {
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    }

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    };
  }, [isResizingSidebar, isResizingPanel]);

  const selectedNode = circuit.nodes.find(n => n.id === selectedId) || null;

  return (
    <div className={`${theme} h-screen w-screen overflow-hidden flex flex-col`}>
      {/* Header (Top) */}
      <Header 
        onSave={handleSave}
        onLoad={handleLoad}
        toolMode={toolMode}
        setToolMode={setToolMode}
        wireMode={wireMode}
        setWireMode={setWireMode}
        isSimulating={isSimulating}
        toggleSimulation={toggleSimulation}
        isPaused={isPaused}
        setIsPaused={setIsPaused}
        stepBackward={stepBackward}
        stepForward={stepForward}
        checkCompatibility={checkCompatibility}
        theme={theme}
        toggleTheme={toggleTheme}
        onClear={() => { snapshot(); setCircuit({nodes:[], wires:[]}); setIsSimulating(false); }}
        selectedId={selectedId}
        deleteSelection={handleDeleteSelection}
        hasHistory={simHistory.length > 0}
        onUndo={undo}
        onRedo={redo}
        canUndo={past.length > 0}
        canRedo={future.length > 0}
      />

      {/* Main Content (Row) */}
      <div className="flex flex-1 w-full bg-zinc-50 dark:bg-black text-zinc-900 dark:text-white font-sans transition-colors duration-300 overflow-hidden relative">
        <Sidebar 
          onSelectComponent={setPendingComponent} 
          selectedComponent={pendingComponent} 
          width={sidebarWidth}
        />

        {/* Sidebar Splitter */}
        <div 
            className="w-1 cursor-col-resize hover:bg-cyan-500 transition-colors z-20 bg-zinc-200 dark:bg-zinc-800 flex-shrink-0" 
            onMouseDown={startResizingSidebar}
        />

        <CircuitCanvas 
          circuit={circuit}
          onUpdateCircuit={handleUpdateCircuit}
          onCommit={snapshot}
          selectedId={selectedId}
          setSelectedId={setSelectedId}
          pendingComponent={pendingComponent}
          setPendingComponent={setPendingComponent}
          toolMode={toolMode}
          wireMode={wireMode}
          isSimulating={isSimulating}
          validationResult={validationResult}
          setValidationResult={setValidationResult}
        />

        {/* Panel Splitter */}
        <div 
            className="w-1 cursor-col-resize hover:bg-cyan-500 transition-colors z-20 bg-zinc-200 dark:bg-zinc-800 flex-shrink-0" 
            onMouseDown={startResizingPanel}
        />

        <PropertiesPanel 
            node={selectedNode} 
            onUpdate={handleNodeUpdate} 
            width={panelWidth} 
        />
      </div>
    </div>
  );
};

const App: React.FC = () => {
  return (
    <ThemeProvider>
      <AppContent />
    </ThemeProvider>
  );
};

export default App;

import React, { useRef, useState, useEffect } from 'react';
import { GRID_SIZE, NODE_DEFINITIONS } from '../constants';
import { CircuitState, NodeData, NodeType, Wire, Point, WiringState } from '../types';
import { GateShape } from './GateShapes';
import { getNodeDimensions, getInputPorts, getOutputPorts } from '../utils/componentUtils';
import { CheckCircle2, AlertTriangle } from 'lucide-react';
import { useTheme } from './ThemeContext';

interface CircuitCanvasProps {
    circuit: CircuitState;
    onUpdateCircuit: (nodes: NodeData[], wires: Wire[]) => void;
    onCommit: () => void;
    selectedId: string | null;
    setSelectedId: (id: string | null) => void;
    pendingComponent: NodeType | null;
    setPendingComponent: (type: NodeType | null) => void;
    toolMode: 'select' | 'interact' | 'junction';
    wireMode: 'manhattan' | 'bezier';
    isSimulating: boolean;
    validationResult: {
        valid: boolean;
        messages: string[];
        invalidNodeIds: string[];
        floatingInputs: { nodeId: string; index: number }[];
    } | null;
    setValidationResult: (res: any) => void;
}

export const CircuitCanvas: React.FC<CircuitCanvasProps> = ({ 
    circuit, onUpdateCircuit, onCommit,
    selectedId, setSelectedId,
    pendingComponent, setPendingComponent,
    toolMode, wireMode, isSimulating,
    validationResult, setValidationResult
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const { theme } = useTheme();

  // Local Interaction State
  const [draggingNodeId, setDraggingNodeId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<Point>({ x: 0, y: 0 });
  const [wiring, setWiring] = useState<WiringState | null>(null);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });

  // --- Keyboard Shortcuts (Local Interactions) ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
            if (pendingComponent) setPendingComponent(null);
            if (wiring) setWiring(null);
            if (selectedId) setSelectedId(null);
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [pendingComponent, wiring, selectedId, setPendingComponent, setSelectedId]);


  const addNode = (type: NodeType, x: number, y: number) => {
    onCommit(); // Snapshot before adding
    const def = NODE_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newNode: NodeData = {
      id: `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      position: { x: snapX, y: snapY },
      inputs: Array(def.inputs).fill(false),
      outputs: Array(def.outputs).fill(false),
      internalState: {},
      properties: {
          label: '',
          labelPosition: 'Top',
          inputCount: def.inputs,
          propagationDelay: 0,
          initialState: false,
          romValue: false,
          interval: type === 'CLOCK' ? 20 : 0
      }
    };

    onUpdateCircuit([...circuit.nodes, newNode], circuit.wires);
    setSelectedId(newNode.id);
  };

  // --- Interaction Handlers ---

  const handleNodeMouseDown = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (wiring) return;
    if (pendingComponent) return; 

    setSelectedId(id);
    const node = circuit.nodes.find(n => n.id === id);
    if (!node) return;

    const isInteractive = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

    if ((toolMode === 'interact' || isSimulating) && isInteractive) {
        if (!isSimulating) onCommit();

        let toggledNodes = circuit.nodes;

        // Special handling for Multi-bit inputs
        if (node.type.startsWith('INPUT_')) {
            const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
            const relY = e.clientY - rect.top; 
            const relX = e.clientX - rect.left;
            const { width, height } = getNodeDimensions(node);
            const bitCount = node.outputs.length;

            let bitIndexToCheck = -1;

            // Check Footer (Binary) Click
            if (relY > height - 30) {
                const bitWidth = 10;
                const bitSpacing = 2;
                const nibbleGap = 6;
                const totalWidth = bitCount * bitWidth + (bitCount - 1) * bitSpacing + Math.floor((bitCount - 1) / 4) * nibbleGap;
                const startX = (width - totalWidth) / 2 + bitWidth / 2;

                for (let i = 0; i < bitCount; i++) {
                    const nibblesBefore = Math.floor(i / 4);
                    const xPos = startX + i * (bitWidth + bitSpacing) + nibblesBefore * nibbleGap;
                    if (Math.abs(relX - xPos) < 8) {
                        bitIndexToCheck = bitCount - 1 - i;
                        break;
                    }
                }
            } else {
                // Check Row Switch Click
                const rowIdx = Math.floor((relY - 25) / 20);
                if (rowIdx >= 0 && rowIdx < bitCount) {
                    bitIndexToCheck = rowIdx;
                }
            }

            if (bitIndexToCheck >= 0 && bitIndexToCheck < bitCount) {
                toggledNodes = circuit.nodes.map(n => {
                    if (n.id === id) {
                        const newOutputs = [...n.outputs];
                        newOutputs[bitIndexToCheck] = !newOutputs[bitIndexToCheck];
                        return { ...n, outputs: newOutputs };
                    }
                    return n;
                });
            }
        } else {
            // Standard single toggle
            toggledNodes = circuit.nodes.map(n => {
                if (n.id === id) {
                    const newState = !n.outputs[0];
                    return { ...n, outputs: [newState] };
                }
                return n;
            });
        }

        onUpdateCircuit(toggledNodes, circuit.wires);
        return; 
    }

    if (toolMode === 'select' || toolMode === 'junction') {
        // Start dragging
        onCommit(); // Snapshot position before move
        setDraggingNodeId(id);
        const rect = containerRef.current!.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;
        setDragOffset({
            x: mouseX - node.position.x,
            y: mouseY - node.position.y
        });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    if (draggingNodeId) {
        const snapX = Math.round((x - dragOffset.x) / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round((y - dragOffset.y) / GRID_SIZE) * GRID_SIZE;

        const updatedNodes = circuit.nodes.map(n => {
            if (n.id === draggingNodeId) {
                return { ...n, position: { x: snapX, y: snapY }};
            }
            return n;
        });
        onUpdateCircuit(updatedNodes, circuit.wires);
    }
  };

  const handleMouseUp = () => {
    if (draggingNodeId) {
        setDraggingNodeId(null);
    }
    if (wiring) {
        setWiring(null);
    }
  };

  const startWiring = (e: React.MouseEvent, nodeId: string, outputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();
    if (toolMode === 'interact' && !isSimulating) return; 

    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setWiring({
        sourceNodeId: nodeId,
        sourceOutputIndex: outputIndex,
        startPoint: { x, y },
        active: true
    });
  };

  const completeWiring = (e: React.MouseEvent, targetNodeId: string, inputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();

    if (!wiring) return;

    if (wiring.sourceNodeId === targetNodeId) {
        setWiring(null);
        return;
    }

    onCommit(); // Snapshot before wiring change

    const exists = circuit.wires.some(w => 
        w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex
    );

    let newWires = exists 
        ? circuit.wires.filter(w => !(w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex))
        : [...circuit.wires];

    newWires.push({
        id: `wire-${Date.now()}`,
        sourceNodeId: wiring.sourceNodeId,
        sourceOutputIndex: wiring.sourceOutputIndex,
        targetNodeId: targetNodeId,
        targetInputIndex: inputIndex,
        state: false
    });

    onUpdateCircuit(circuit.nodes, newWires);
    setWiring(null);
  };

  const handleWireClick = (e: React.MouseEvent, wire: Wire, x: number, y: number) => {
    if (toolMode !== 'junction') {
        e.stopPropagation();
        setSelectedId(wire.id);
        return;
    }
    e.stopPropagation();

    onCommit(); // Snapshot before creating junction

    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;
    const junctionId = `node-${Date.now()}-junction`;

    const newJunction: NodeData = {
        id: junctionId,
        type: 'JUNCTION',
        position: { x: snapX - 5, y: snapY - 5 },
        inputs: [false],
        outputs: [false],
        properties: { label: '' }
    };

    const wire1: Wire = {
        id: `wire-${Date.now()}-1`,
        sourceNodeId: wire.sourceNodeId,
        sourceOutputIndex: wire.sourceOutputIndex,
        targetNodeId: junctionId,
        targetInputIndex: 0,
        state: wire.state
    };
    const wire2: Wire = {
        id: `wire-${Date.now()}-2`,
        sourceNodeId: junctionId,
        sourceOutputIndex: 0,
        targetNodeId: wire.targetNodeId,
        targetInputIndex: wire.targetInputIndex,
        state: wire.state
    };

    const newWires = circuit.wires.filter(w => w.id !== wire.id).concat([wire1, wire2]);
    const newNodes = [...circuit.nodes, newJunction];

    onUpdateCircuit(newNodes, newWires);
    setSelectedId(junctionId);
  };

  const handleCanvasClick = (e: React.MouseEvent) => {
      if (pendingComponent && containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        addNode(pendingComponent, x, y);
        setPendingComponent(null);
        return;
      }
      setSelectedId(null);
      if (validationResult?.valid) setValidationResult(null);
  };

  const getWirePath = (x1: number, y1: number, x2: number, y2: number) => {
    if (wireMode === 'bezier') {
        const dist = Math.abs(x2 - x1);
        const controlPointOffset = Math.max(dist * 0.5, 50);
        return `M ${x1} ${y1} C ${x1 + controlPointOffset} ${y1}, ${x2 - controlPointOffset} ${y2}, ${x2} ${y2}`;
    }
    const dx = x2 - x1;
    if (dx > 20) {
        const midX = (x1 + x2) / 2;
        return `M ${x1} ${y1} L ${midX} ${y1} L ${midX} ${y2} L ${x2} ${y2}`;
    }
    const stub = 20;
    const midY = (y1 + y2) / 2;
    return `M ${x1} ${y1} L ${x1 + stub} ${y1} L ${x1 + stub} ${midY} L ${x2 - stub} ${midY} L ${x2 - stub} ${y2} L ${x2} ${y2}`;
  };

  // Helper to determine label CSS class based on position
  const getLabelStyle = (pos: string | undefined): React.CSSProperties => {
      switch (pos) {
          case 'Bottom': return { top: '100%', left: '50%', transform: 'translate(-50%, 8px)' };
          case 'Left': return { top: '50%', right: '100%', transform: 'translate(-8px, -50%)' };
          case 'Right': return { top: '50%', left: '100%', transform: 'translate(8px, -50%)' };
          case 'Top': default: return { bottom: '100%', left: '50%', transform: 'translate(-50%, -8px)' };
      }
  };

  // Preview Logic
  const ghostSnapX = Math.round(mousePos.x / GRID_SIZE) * GRID_SIZE;
  const ghostSnapY = Math.round(mousePos.y / GRID_SIZE) * GRID_SIZE;
  const pendingDef = pendingComponent ? NODE_DEFINITIONS[pendingComponent] : null;

  return (
    <div 
        ref={containerRef}
        className={`flex-1 relative w-full h-full overflow-hidden bg-zinc-50 dark:bg-zinc-950
            ${isSimulating ? 'cursor-default' : pendingComponent ? 'cursor-cell' : toolMode === 'junction' ? 'cursor-crosshair' : 'cursor-crosshair'}`}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onClick={handleCanvasClick}
        onContextMenu={(e) => e.preventDefault()}
    >
        {/* Validation Messages Overlay */}
        {validationResult && (
            <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 pointer-events-none w-auto max-w-lg">
                <div className={`p-4 rounded-lg shadow-xl backdrop-blur-md border animate-in slide-in-from-top-4 duration-200
                    ${validationResult.valid ? 'bg-green-50/90 dark:bg-green-950/80 border-green-200 dark:border-green-800 text-green-800 dark:text-green-200' : 'bg-red-50/90 dark:bg-red-950/80 border-red-200 dark:border-red-800 text-red-800 dark:text-red-200'}`}
                >
                    <div className="flex items-start gap-3">
                        {validationResult.valid ? <CheckCircle2 size={20} className="mt-0.5 text-green-600 dark:text-green-400" /> : <AlertTriangle size={20} className="mt-0.5 text-red-600 dark:text-red-400" />}
                        <div>
                            <h4 className="font-bold text-sm mb-1">{validationResult.valid ? 'Circuit Valid' : 'Compatibility Issues Found'}</h4>
                            <ul className="text-xs space-y-1 list-disc list-inside opacity-90">
                                {validationResult.messages.map((m, i) => <li key={i}>{m}</li>)}
                            </ul>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* Grid Pattern */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full opacity-20 dark:opacity-20">
            <defs>
                <pattern id="grid" width={GRID_SIZE} height={GRID_SIZE} patternUnits="userSpaceOnUse">
                    <circle cx="1" cy="1" r="1" className="fill-zinc-400 dark:fill-zinc-500" />
                </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#grid)" />
        </svg>

        {/* Connections */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
            {circuit.wires.map(wire => {
                const sourceNode = circuit.nodes.find(n => n.id === wire.sourceNodeId);
                const targetNode = circuit.nodes.find(n => n.id === wire.targetNodeId);
                if (!sourceNode || !targetNode) return null;

                const sourcePorts = getOutputPorts(sourceNode);
                const targetPorts = getInputPorts(targetNode);

                const outputOffset = sourcePorts[wire.sourceOutputIndex] || { x: 0, y: 0 };
                const inputOffset = targetPorts[wire.targetInputIndex] || { x: 0, y: 0 };

                const startX = sourceNode.position.x + outputOffset.x;
                const startY = sourceNode.position.y + outputOffset.y;
                const endX = targetNode.position.x + inputOffset.x;
                const endY = targetNode.position.y + inputOffset.y;

                const isSelected = selectedId === wire.id;
                const pathData = getWirePath(startX, startY, endX, endY);

                return (
                    <g 
                        key={wire.id} 
                        onClick={(e) => { 
                            if (!containerRef.current) return;
                            const rect = containerRef.current.getBoundingClientRect();
                            handleWireClick(e, wire, e.clientX - rect.left, e.clientY - rect.top);
                        }} 
                        className={`pointer-events-auto cursor-pointer group`}
                    >
                        <path d={pathData} stroke="transparent" strokeWidth="16" fill="none" />
                        {wire.state && <path d={pathData} stroke="#22d3ee" strokeWidth="4" fill="none" opacity="0.3" filter="blur(2px)" />}
                        <path d={pathData} stroke={wire.state ? "#22d3ee" : (theme === 'dark' ? "#52525b" : "#a1a1aa")} strokeWidth={isSelected ? "3" : "2"} fill="none" className="transition-colors duration-150" strokeDasharray={isSelected ? "4" : "0"} strokeLinejoin="round" strokeLinecap="round" />
                    </g>
                );
            })}

            {wiring && (
                <path d={getWirePath(wiring.startPoint.x, wiring.startPoint.y, mousePos.x, mousePos.y)} stroke="#fbbf24" strokeWidth="2" fill="none" strokeDasharray="4" className="animate-pulse" strokeLinejoin="round" />
            )}
        </svg>

        {/* Nodes */}
        {circuit.nodes.map(node => {
            const { width, height } = getNodeDimensions(node);
            const isSelected = selectedId === node.id;
            const isInvalid = validationResult?.invalidNodeIds?.includes(node.id);
            const inputPorts = getInputPorts(node);
            const outputPorts = getOutputPorts(node);
            const def = NODE_DEFINITIONS[node.type];
            const canInteract = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

            return (
                <div
                    key={node.id}
                    className={`absolute group select-none`}
                    style={{
                        left: node.position.x,
                        top: node.position.y,
                        width: width,
                        height: height,
                        pointerEvents: 'none',
                        zIndex: isSelected ? 50 : 10 
                    }}
                >
                    <div 
                        className={`absolute inset-0 pointer-events-auto transition-all duration-200 
                            ${isSelected ? 'drop-shadow-[0_0_8px_rgba(34,211,238,0.5)]' : ''} 
                            ${isInvalid ? 'drop-shadow-[0_0_8px_rgba(239,68,68,0.8)]' : ''}
                            ${(toolMode === 'interact' || isSimulating) && canInteract ? 'cursor-pointer' : 'cursor-grab active:cursor-grabbing'}
                        `}
                        onMouseDown={(e) => handleNodeMouseDown(e, node.id)}
                    >
                        <svg width={width} height={height} className="overflow-visible">
                            <GateShape node={node} />
                        </svg>
                    </div>

                    {isInvalid && (
                        <div className="absolute -top-3 -right-3 text-red-500 bg-white dark:bg-zinc-950 rounded-full p-0.5 shadow-md border border-red-200 dark:border-red-900 animate-bounce z-50">
                            <AlertTriangle size={14} fill="currentColor" className="text-red-100 dark:text-red-900" stroke="currentColor" />
                        </div>
                    )}

                    {inputPorts.map((offset, idx) => {
                        const isFloating = validationResult?.floatingInputs?.some(fi => fi.nodeId === node.id && fi.index === idx);

                        return (
                        <div
                            key={`input-${idx}`}
                            className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 
                            ${(toolMode === 'select' || toolMode === 'junction') && !isSimulating ? 'cursor-crosshair' : 'cursor-default'}`}
                            style={{ left: offset.x, top: offset.y }}
                            onMouseUp={(e) => !isSimulating && (toolMode === 'select' || toolMode === 'junction') && completeWiring(e, node.id, idx)}
                            title={offset.label || "Input"}
                        >
                            <div className={`w-2 h-2 rounded-full bg-white dark:bg-zinc-900 border transition-all duration-300 ${
                                isFloating 
                                ? 'border-red-500 bg-red-500/50 ring-2 ring-red-500 ring-opacity-50 animate-pulse' 
                                : node.inputs[idx] ? 'border-cyan-400 bg-cyan-100 dark:bg-cyan-900' : 'border-zinc-400 dark:border-zinc-500'
                            }`} />
                        </div>
                        );
                    })}

                    {outputPorts.map((offset, idx) => (
                        <div
                            key={`output-${idx}`}
                            className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 
                            ${(toolMode === 'select' || toolMode === 'junction') && !isSimulating ? 'cursor-crosshair' : 'cursor-default'}`}
                            style={{ left: offset.x, top: offset.y }}
                            onMouseDown={(e) => !isSimulating && (toolMode === 'select' || toolMode === 'junction') && startWiring(e, node.id, idx)}
                            title={offset.label || "Output"}
                        >
                            <div className={`w-2 h-2 rounded-full bg-white dark:bg-zinc-900 border ${node.outputs[idx] ? 'border-cyan-400 bg-cyan-500' : 'border-zinc-400 dark:border-zinc-500 group-hover:border-zinc-600 dark:group-hover:border-zinc-300'}`} />
                        </div>
                    ))}

                    {(isSelected || node.properties?.label) && node.type !== 'JUNCTION' && (
                        <div 
                            className="absolute bg-white/90 dark:bg-zinc-900/90 text-zinc-800 dark:text-zinc-100 text-[10px] px-2 py-0.5 rounded border border-zinc-200 dark:border-zinc-700 whitespace-nowrap shadow-md pointer-events-none backdrop-blur-sm z-[60]"
                            style={getLabelStyle(node.properties?.labelPosition)}
                        >
                            {node.properties?.label || def.name}
                        </div>
                    )}
                </div>
            );
        })}

        {/* Ghost Component */}
        {pendingComponent && pendingDef && (
            <div 
                className="absolute pointer-events-none opacity-50 z-50"
                style={{
                    left: ghostSnapX,
                    top: ghostSnapY,
                    width: pendingDef.width,
                    height: pendingDef.height
                }}
            >
                <svg width={pendingDef.width} height={pendingDef.height} className="overflow-visible">
                        <GateShape node={{ 
                        id: 'ghost', 
                        type: pendingComponent, 
                        position: {x: 0, y: 0}, 
                        inputs: Array(pendingDef.inputs).fill(false), 
                        outputs: Array(pendingDef.outputs).fill(false),
                        properties: { inputCount: pendingDef.inputs }
                    }} />
                </svg>
                <div className="absolute -top-6 left-0 bg-cyan-500 text-white text-[10px] px-2 py-0.5 rounded shadow-sm whitespace-nowrap">
                    Click to place
                </div>
            </div>
        )}
    </div>
  );
};

import React from 'react';
import { NodeData } from '../types';
import { getNodeDimensions } from '../utils/componentUtils';

interface GateShapeProps {
  node: NodeData;
}

interface TextProps {
  x: number;
  y: number;
  children?: React.ReactNode;
  fill?: string;
  fontSize?: string;
}

const GateText = ({ x, y, children, fill="#71717a", fontSize="10" }: TextProps) => (
  <text x={x} y={y} textAnchor="middle" dominantBaseline="middle" fill={fill} fontSize={fontSize} fontWeight="bold" className="pointer-events-none select-none">
    {children}
  </text>
);

// Helper: Convert boolean array to integer value
const boolsToVal = (bools: boolean[]) => {
    return bools.reduce((acc, b, i) => acc + (b ? Math.pow(2, i) : 0), 0);
};

const boolsToHex = (bools: boolean[]) => {
    const val = boolsToVal(bools);
    const hex = val.toString(16).toUpperCase();
    const pad = Math.ceil(bools.length / 4);
    return `0x${hex.padStart(pad, '0')}`;
};

export const GateShape: React.FC<GateShapeProps> = ({ node }) => {
  const type = node.type;
  // Usually output[0] is the primary active state for coloring, but for complex nodes we stick to neutral unless specified.
  const active = node.outputs[0]; 
  const strokeColor = active ? "#22d3ee" : "#71717a"; 
  const fillColor = node.properties?.color || "#18181b"; // Allow custom color override
  const activeFill = active ? "#0ea5e9" : fillColor; 
  const { width, height } = getNodeDimensions(node);

  // Dynamic path generation for variable inputs
  const getGatePath = (gateType: 'AND' | 'OR' | 'NAND' | 'NOR' | 'XOR' | 'XNOR') => {
     // Control point offset for OR/XOR curves
     const curve = width * 0.6; 

     switch (gateType) {
         case 'AND': 
         case 'NAND':
             // Straight back, curved front
             return `M 0 0 L ${width/2} 0 A ${height/2} ${height/2} 0 0 1 ${width/2} ${height} L 0 ${height} Z`;

         case 'OR':
         case 'NOR':
             // Curved back, curved front (pointed)
             return `M 0 0 Q ${width*0.25} ${height/2} 0 ${height} Q ${width*0.8} ${height} ${width} ${height/2} Q ${width*0.8} 0 0 0 Z`;

         case 'XOR':
         case 'XNOR':
              // Similar to OR but with the extra back line (which we usually draw separately, but here we approximate the main body)
             return `M 10 0 Q ${width*0.35} ${height/2} 10 ${height} Q ${width*0.9} ${height} ${width} ${height/2} Q ${width*0.9} 0 10 0 Z`;
     }
  };

  // Helper to render binary string
  // Renders bits from MSB (left) to LSB (right)
  const renderBinaryFooter = (bitCount: number, values: boolean[]) => {
      // Configuration
      const bitWidth = 10;
      const bitSpacing = 2;
      const nibbleGap = 6;

      const totalWidth = bitCount * bitWidth + (bitCount - 1) * bitSpacing + Math.floor((bitCount - 1) / 4) * nibbleGap;
      const startX = (width - totalWidth) / 2 + bitWidth / 2;

      return (
        <g transform={`translate(0, ${height - 30})`}>
            {/* Background for footer */}
            <rect x="5" y="0" width={width - 10} height="25" rx="4" fill="#000" stroke="#3f3f46" />

            {Array.from({length: bitCount}).map((_, i) => {
                // i goes from 0 to N-1.
                // We want to render bit N-1 at the left (first position), bit 0 at right.
                // Display Index 0 -> Bit N-1. Display Index k -> Bit N-1-k.
                const bitIndex = bitCount - 1 - i;
                const bitVal = values[bitIndex];

                // Calculate position considering nibble gaps
                // Groups of 4: 0,1,2,3 (gap) 4,5,6,7
                const nibblesBefore = Math.floor(i / 4);
                const xPos = startX + i * (bitWidth + bitSpacing) + nibblesBefore * nibbleGap;

                return (
                    <text 
                        key={bitIndex} 
                        x={xPos} 
                        y="13" 
                        textAnchor="middle" 
                        dominantBaseline="middle" 
                        fill={bitVal ? "#22d3ee" : "#52525b"} 
                        fontSize="12" 
                        fontFamily="monospace"
                        fontWeight="bold"
                    >
                        {bitVal ? "1" : "0"}
                    </text>
                );
            })}
        </g>
      );
  };

  switch (type) {
    // --- Dynamic Gates ---
    case 'AND':
      return <path d={getGatePath('AND')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />;
    case 'NAND':
      return (
        <g>
          <path d={getGatePath('NAND')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <circle cx={width} cy={height/2} r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case 'OR':
      return <path d={getGatePath('OR')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />
    case 'NOR':
      return (
        <g>
          <path d={getGatePath('OR')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <circle cx={width} cy={height/2} r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case 'XOR':
      return (
        <g>
          <path d={getGatePath('XOR')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <path d={`M -5 0 Q ${width*0.20} ${height/2} -5 ${height}`} fill="none" stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case 'XNOR':
      return (
        <g>
          <path d={getGatePath('XOR')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <path d={`M -5 0 Q ${width*0.20} ${height/2} -5 ${height}`} fill="none" stroke={strokeColor} strokeWidth="2" />
          <circle cx={width} cy={height/2} r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
        </g>
      );

    case 'NOT':
      return (
        <g>
          <path d="M 0 0 L 35 20 L 0 40 Z" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <circle cx="40" cy="20" r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case 'BUFFER':
        return <path d="M 0 0 L 30 20 L 0 40 Z" fill={fillColor} stroke={strokeColor} strokeWidth="2" />;

    // --- Constants ---
    case 'CONSTANT_1':
        return (
            <g>
                <rect x="0" y="0" width="30" height="30" rx="2" fill={fillColor} stroke="#22d3ee" strokeWidth="2" />
                <text x="15" y="15" textAnchor="middle" dominantBaseline="middle" fill="#22d3ee" fontSize="14" fontWeight="bold">1</text>
            </g>
        );
    case 'CONSTANT_0':
        return (
            <g>
                <rect x="0" y="0" width="30" height="30" rx="2" fill={fillColor} stroke="#52525b" strokeWidth="2" />
                <text x="15" y="15" textAnchor="middle" dominantBaseline="middle" fill="#71717a" fontSize="14" fontWeight="bold">0</text>
            </g>
        );

    // --- Logic ---
    case 'JUNCTION':
        return <circle cx="5" cy="5" r="5" fill={active ? "#22d3ee" : "#71717a"} />;

    // --- IO ---
    case 'SWITCH':
      return (
        <g>
          <rect x="0" y="0" width="40" height="40" rx="4" fill={activeFill} stroke={strokeColor} strokeWidth="2" />
          <text x="20" y="25" textAnchor="middle" fill={active ? "#fff" : "#a1a1aa"} fontSize="12" fontWeight="bold">{active ? "1" : "0"}</text>
        </g>
      );
    case 'BUTTON':
        return (
          <g>
            <circle cx="20" cy="20" r="15" fill={active ? "#22c55e" : "#3f3f46"} stroke={strokeColor} strokeWidth="2" />
            <circle cx="20" cy="20" r="10" fill={active ? "#16a34a" : "#18181b"} />
          </g>
        );
    case 'CLOCK':
        return (
            <g>
                <rect x="0" y="0" width="40" height="40" rx="4" fill="#18181b" stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <path d="M 10 20 L 15 20 L 15 10 L 25 10 L 25 30 L 35 30" fill="none" stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
            </g>
        );
    case 'BULB':
      return (
        <g>
          <circle cx="20" cy="20" r="15" fill={node.inputs[0] ? "#fbbf24" : "#27272a"} stroke={node.inputs[0] ? "#f59e0b" : "#52525b"} strokeWidth="2" style={{ filter: node.inputs[0] ? 'drop-shadow(0 0 8px #fbbf24)' : 'none'}} />
        </g>
      );
    case 'HEX_DISPLAY':
        // Decode 4 inputs to Hex char
        const val = (node.inputs[0]?1:0) + (node.inputs[1]?2:0) + (node.inputs[2]?4:0) + (node.inputs[3]?8:0);
        const hexChar = val.toString(16).toUpperCase();
        return (
            <g>
                <rect x="0" y="0" width="60" height="80" fill="#000" stroke="#3f3f46" strokeWidth="4" />
                <text x="30" y="45" textAnchor="middle" dominantBaseline="middle" fill="#ef4444" fontSize="40" fontFamily="monospace" style={{ filter: 'drop-shadow(0 0 4px #ef4444)'}}>
                    {hexChar}
                </text>
            </g>
        );
    case 'SEVEN_SEGMENT':
        // a,b,c,d,e,f,g,dp
        const [a, b, c, d, e, f, g, dp] = node.inputs;
        const segOn = "#ef4444";
        const segOff = "#27272a";
        const segStyle = (on: boolean) => ({ fill: on ? segOn : segOff, filter: on ? 'drop-shadow(0 0 2px #ef4444)' : 'none' });

        return (
            <g>
                <rect x="0" y="0" width="70" height="100" fill="#000" stroke="#3f3f46" strokeWidth="4" />

                {/* A */}
                <path d="M 15 10 L 55 10 L 50 15 L 20 15 Z" {...segStyle(a)} />
                {/* B */}
                <path d="M 55 10 L 60 15 L 60 45 L 55 50 L 50 45 L 50 15 Z" {...segStyle(b)} />
                {/* C */}
                <path d="M 55 50 L 60 55 L 60 85 L 55 90 L 50 85 L 50 55 Z" {...segStyle(c)} />
                {/* D */}
                <path d="M 15 90 L 55 90 L 50 85 L 20 85 Z" {...segStyle(d)} />
                {/* E */}
                <path d="M 15 50 L 20 55 L 20 85 L 15 90 L 10 85 L 10 55 Z" {...segStyle(e)} />
                {/* F */}
                <path d="M 15 10 L 20 15 L 20 45 L 15 50 L 10 45 L 10 15 Z" {...segStyle(f)} />
                {/* G */}
                <path d="M 15 50 L 20 45 L 50 45 L 55 50 L 50 55 L 20 55 Z" {...segStyle(g)} />
                {/* DP */}
                <circle cx="60" cy="90" r="3" {...segStyle(dp)} />
            </g>
        );

    // --- Multi-bit IO ---
    case 'INPUT_2BIT':
    case 'INPUT_4BIT':
    case 'INPUT_8BIT':
    case 'INPUT_16BIT':
        const bitCount = node.outputs.length;
        return (
            <g>
                <rect x="0" y="0" width={width} height={height} rx="4" fill="#18181b" stroke="#52525b" strokeWidth="2" />
                <GateText x={width/2} y={12}>{`IN ${bitCount}b (${boolsToHex(node.outputs)})`}</GateText>

                {/* Switches */}
                {/* Header is 25px. Rows are 20px. Start Y = 25. Centered at 25 + 10 = 35. */}
                {/* i*20 offset */}
                {node.outputs.map((state, i) => (
                   <g key={i} transform={`translate(10, ${25 + (i * 20)})`}>
                       {/* Row visual container (for hit area visualization mostly) */}
                       <rect x="0" y="2" width={width - 20} height="16" rx="2" fill="#27272a" stroke="none" />

                       {/* Switch toggle */}
                       <g transform="translate(5, 4)">
                           <rect x="0" y="0" width="20" height="12" rx="2" fill={state ? "#0ea5e9" : "#3f3f46"} stroke={state ? "#22d3ee" : "#52525b"} />
                           <circle cx={state ? 16 : 4} cy={6} r="3" fill="white" />
                       </g>

                       <text x="35" y="10" dominantBaseline="middle" fill="#71717a" fontSize="10" fontFamily="monospace">{i.toString()}</text>
                   </g>
                ))}

                {/* Footer Binary Input */}
                {renderBinaryFooter(bitCount, node.outputs)}
            </g>
        );

    case 'OUTPUT_2BIT':
    case 'OUTPUT_4BIT':
    case 'OUTPUT_8BIT':
    case 'OUTPUT_16BIT':
        const outBits = node.inputs.length;
        return (
            <g>
                <rect x="0" y="0" width={width} height={height} rx="4" fill="#09090b" stroke="#52525b" strokeWidth="2" />
                <GateText x={width/2} y={12}>{`OUT ${outBits}b (${boolsToHex(node.inputs)})`}</GateText>

                {/* Bits */}
                {node.inputs.map((state, i) => (
                    <g key={i} transform={`translate(10, ${25 + (i * 20)})`}>
                         {/* Row visual container */}
                         <rect x="0" y="2" width={width - 20} height="16" rx="2" fill="#18181b" stroke="none" />

                         <circle cx="10" cy="10" r="4" fill={state ? "#ef4444" : "#27272a"} stroke={state ? "#f87171" : "#3f3f46"} style={{ filter: state ? 'drop-shadow(0 0 2px #ef4444)' : 'none' }} />
                         <text x="25" y="10" dominantBaseline="middle" fill="#71717a" fontSize="10" fontFamily="monospace">{i.toString()}</text>
                    </g>
                ))}

                 {/* Footer Binary Display */}
                 {renderBinaryFooter(outBits, node.inputs)}
            </g>
        );


    // --- Arithmetic ---
    case 'HALF_ADDER':
      return (
        <g>
            <rect x="0" y="0" width="80" height="80" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
            <GateText x={40} y={40}>HALF ADDER</GateText>
            <GateText x={10} y={20}>A</GateText> <GateText x={10} y={60}>B</GateText>
            <GateText x={70} y={20}>S</GateText> <GateText x={70} y={60}>C</GateText>
        </g>
      );
    case 'FULL_ADDER':
        return (
          <g>
              <rect x="0" y="0" width="80" height="100" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
              <GateText x={40} y={50}>FULL ADDER</GateText>
              <GateText x={10} y={20}>A</GateText> <GateText x={10} y={40}>B</GateText> <GateText x={10} y={80}>Cin</GateText>
              <GateText x={70} y={20}>S</GateText> <GateText x={70} y={80}>Cout</GateText>
          </g>
        );
    case 'SUBTRACTOR':
        return (
            <g>
                <rect x="0" y="0" width="80" height="100" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={40} y={50}>SUBTRACTOR</GateText>
                <GateText x={10} y={20}>A</GateText> <GateText x={10} y={60}>B</GateText>
                <GateText x={70} y={20}>D</GateText> <GateText x={70} y={80}>Bo</GateText>
            </g>
        );
    case 'COMPARATOR_1BIT':
        return (
            <g>
                <rect x="0" y="0" width="80" height="80" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={40} y={40}>COMPARATOR</GateText>
                <GateText x={10} y={20}>A</GateText> <GateText x={10} y={60}>B</GateText>
                <GateText x={70} y={20}>&gt;</GateText> <GateText x={70} y={40}>=</GateText> <GateText x={70} y={60}>&lt;</GateText>
            </g>
        );

    // --- Memory ---
    case 'D_LATCH':
        return (
          <g>
              <rect x="0" y="0" width="80" height="80" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
              <GateText x={40} y={25}>D-LATCH</GateText>
              <GateText x={10} y={20}>D</GateText> <GateText x={10} y={60}>En</GateText>
              <GateText x={70} y={20}>Q</GateText> <GateText x={70} y={60}>!Q</GateText>
          </g>
        );
    case 'D_FF':
        return (
            <g>
                <rect x="0" y="0" width="80" height="80" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <GateText x={40} y={25}>D-FF</GateText>
                <GateText x={10} y={20}>D</GateText> 
                <path d="M 0 55 L 10 60 L 0 65" fill="none" stroke="#71717a" />
                <GateText x={70} y={20}>Q</GateText> <GateText x={70} y={60}>!Q</GateText>
            </g>
        );
    case 'T_FF':
        return (
            <g>
                <rect x="0" y="0" width="80" height="80" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <GateText x={40} y={25}>T-FF</GateText>
                <GateText x={10} y={20}>T</GateText> 
                <path d="M 0 55 L 10 60 L 0 65" fill="none" stroke="#71717a" />
                <GateText x={70} y={20}>Q</GateText> <GateText x={70} y={60}>!Q</GateText>
            </g>
        );
    case 'JK_FF':
        return (
            <g>
                <rect x="0" y="0" width="80" height="100" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <GateText x={40} y={25}>JK-FF</GateText>
                <GateText x={10} y={20}>J</GateText> <GateText x={10} y={80}>K</GateText>
                <path d="M 0 45 L 10 50 L 0 55" fill="none" stroke="#71717a" />
                <GateText x={70} y={20}>Q</GateText> <GateText x={70} y={80}>!Q</GateText>
            </g>
        );
    case 'SR_FF':
        return (
            <g>
                <rect x="0" y="0" width="80" height="100" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <GateText x={40} y={25}>SR-FF</GateText>
                <GateText x={10} y={20}>S</GateText> <GateText x={10} y={80}>R</GateText>
                <path d="M 0 45 L 10 50 L 0 55" fill="none" stroke="#71717a" />
                <GateText x={70} y={20}>Q</GateText> <GateText x={70} y={80}>!Q</GateText>
            </g>
        );

    // --- Advanced ---
    case 'GATED_SR_LATCH':
        return (
            <g>
                <rect x="0" y="0" width="80" height="100" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <GateText x={40} y={25}>Gated SR</GateText>
                <GateText x={10} y={20}>S</GateText> <GateText x={10} y={50}>En</GateText> <GateText x={10} y={80}>R</GateText>
                <GateText x={70} y={20}>Q</GateText> <GateText x={70} y={80}>!Q</GateText>
            </g>
        );
    case 'JK_MASTER_SLAVE':
        return (
            <g>
                <rect x="0" y="0" width="90" height="100" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <GateText x={45} y={25}>JK M-S</GateText>
                <GateText x={10} y={20}>J</GateText> <GateText x={10} y={80}>K</GateText>
                <path d="M 0 45 L 10 50 L 0 55" fill="none" stroke="#71717a" />
                <GateText x={80} y={20}>Q</GateText> <GateText x={80} y={80}>!Q</GateText>
            </g>
        );
    case 'RAM_1BIT':
        return (
            <g>
                <rect x="0" y="0" width="70" height="80" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={35} y={20}>RAM 1b</GateText>
                <GateText x={10} y={20}>D</GateText> <GateText x={10} y={40}>W</GateText> <GateText x={10} y={60}>S</GateText>
                <GateText x={60} y={40}>Q</GateText>
            </g>
        );
    case 'ROM_1BIT':
        return (
            <g>
                <rect x="0" y="0" width="60" height="60" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={30} y={15}>ROM 1b</GateText>
                <GateText x={30} y={45}>{node.properties?.romValue ? '1' : '0'}</GateText>
                <GateText x={10} y={30}>S</GateText>
                <GateText x={50} y={30}>Q</GateText>
            </g>
        );
    case 'SHIFT_REGISTER_4BIT':
        const reg = node.internalState?.register || [false, false, false, false];
        return (
            <g>
                <rect x="0" y="0" width="100" height="120" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={50} y={15}>SHIFT REG 4b</GateText>
                <GateText x={10} y={30}>D</GateText> 
                <path d="M 0 85 L 10 90 L 0 95" fill="none" stroke="#71717a" />

                {/* Visualizing bits */}
                <rect x="30" y="40" width="15" height="40" fill={reg[0] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />
                <rect x="45" y="40" width="15" height="40" fill={reg[1] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />
                <rect x="60" y="40" width="15" height="40" fill={reg[2] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />
                <rect x="75" y="40" width="15" height="40" fill={reg[3] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />

                <GateText x={90} y={20}>Q0</GateText> <GateText x={90} y={50}>Q1</GateText>
                <GateText x={90} y={80}>Q2</GateText> <GateText x={90} y={110}>Q3</GateText>
            </g>
        );

    // --- RAM BLOCKS ---
    case 'RAM_4BIT':
    case 'RAM_8BIT':
    case 'RAM_16BIT':
        const dataBits = type === 'RAM_4BIT' ? 4 : (type === 'RAM_8BIT' ? 8 : 16);
        const addrBits = 4;

        // Compute current state for display
        // Address
        let addr = 0;
        for(let i=0; i<addrBits; i++) {
            if (node.inputs[i]) addr += Math.pow(2, i);
        }

        // Data In (for visual reference only, if needed)

        // Controls
        const WE = node.inputs[addrBits + dataBits];
        const CS = node.inputs[addrBits + dataBits + 1];

        // Stored Value at current address
        const mem = node.internalState?.memory || [];
        const storedVal = mem[addr] || 0;

        // Status Text
        let status = "IDLE";
        if (CS) {
            status = WE ? "WRITE" : "READ";
        } else {
            status = "OFF";
        }

        return (
            <g>
                <rect x="0" y="0" width={width} height={height} rx="4" fill="#09090b" stroke="#52525b" strokeWidth="2" />
                <GateText x={width/2} y={15} fill="#e4e4e7" fontSize="12">{type.replace('_', ' ')}</GateText>

                {/* Internal Monitor Screen */}
                <rect x="40" y="30" width="60" height="40" rx="2" fill="#000" stroke="#3f3f46" />
                <GateText x={70} y={42} fill="#71717a" fontSize="9">ADDR</GateText>
                <GateText x={70} y={58} fill="#22d3ee" fontSize="12" >{`0x${addr.toString(16).toUpperCase()}`}</GateText>

                <rect x="40" y="75" width="60" height="40" rx="2" fill="#000" stroke="#3f3f46" />
                <GateText x={70} y={87} fill="#71717a" fontSize="9">DATA</GateText>
                <GateText x={70} y={103} fill="#ef4444" fontSize="12">{`0x${storedVal.toString(16).toUpperCase().padStart(dataBits > 8 ? 4 : 2, '0')}`}</GateText>

                {/* Status Indicator */}
                <rect x="40" y="125" width="60" height="16" rx="2" fill={CS ? (WE ? "#7f1d1d" : "#064e3b") : "#27272a"} />
                <GateText x={70} y={133} fill={CS ? "#fff" : "#52525b"} fontSize="9">{status}</GateText>

            </g>
        );

    // --- Plexers ---
    case 'MUX_2_1':
        return (
          <g>
              <path d="M 0 0 L 60 20 L 60 60 L 0 80 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
              <GateText x={30} y={40}>MUX</GateText>
              <GateText x={10} y={20}>0</GateText> <GateText x={10} y={60}>1</GateText> <GateText x={30} y={70}>S</GateText>
              <GateText x={50} y={40}>Y</GateText>
          </g>
        );
    case 'MUX_4_1':
        return (
            <g>
                <path d="M 0 0 L 60 20 L 60 100 L 0 120 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <GateText x={30} y={60}>MUX 4</GateText>
                <GateText x={10} y={20}>0</GateText> <GateText x={10} y={40}>1</GateText>
                <GateText x={10} y={60}>2</GateText> <GateText x={10} y={80}>3</GateText>
                <GateText x={50} y={60}>Y</GateText>
            </g>
        );
    case 'DEMUX_1_2':
        return (
          <g>
              <path d="M 0 20 L 60 0 L 60 80 L 0 60 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
              <GateText x={30} y={40}>DEMUX</GateText>
              <GateText x={10} y={40}>D</GateText> 
              <GateText x={50} y={20}>0</GateText> <GateText x={50} y={60}>1</GateText>
          </g>
        );
    case 'DEMUX_1_4':
        return (
            <g>
                <path d="M 0 20 L 60 0 L 60 120 L 0 100 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <GateText x={30} y={60}>DEMUX 4</GateText>
                <GateText x={10} y={60}>D</GateText> 
                <GateText x={50} y={20}>0</GateText> <GateText x={50} y={40}>1</GateText>
                <GateText x={50} y={60}>2</GateText> <GateText x={50} y={80}>3</GateText>
            </g>
        );
    case 'DECODER_2_4':
        return (
            <g>
                <rect x="0" y="0" width="60" height="100" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={30} y={50}>DEC 2:4</GateText>
                <GateText x={10} y={80}>0</GateText> <GateText x={10} y={90}>1</GateText>
                <GateText x={50} y={20}>0</GateText> <GateText x={50} y={40}>1</GateText>
                <GateText x={50} y={60}>2</GateText> <GateText x={50} y={80}>3</GateText>
            </g>
        );
    case 'PRIORITY_ENCODER_4_2':
        return (
            <g>
                <rect x="0" y="0" width="70" height="100" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={35} y={10}>PRIO ENC</GateText>
                <GateText x={10} y={20}>0</GateText> <GateText x={10} y={40}>1</GateText>
                <GateText x={10} y={60}>2</GateText> <GateText x={10} y={80}>3</GateText>
                <GateText x={60} y={30}>A0</GateText> <GateText x={60} y={50}>A1</GateText> <GateText x={60} y={80}>V</GateText>
            </g>
        );

    default:
      return <rect width="40" height="40" fill="red" />;
  }
};

import React, { useRef, useState, useEffect } from 'react';
import { GRID_SIZE, NODE_DEFINITIONS } from '../constants';
import { CircuitState, NodeData, NodeType, Wire, Point, WiringState } from '../types';
import { GateShape } from './GateShapes';
import { getNodeDimensions, getInputPorts, getOutputPorts } from '../utils/componentUtils';
import { CheckCircle2, AlertTriangle } from 'lucide-react';
import { useTheme } from './ThemeContext';

interface CircuitCanvasProps {
    circuit: CircuitState;
    onUpdateCircuit: (nodes: NodeData[], wires: Wire[]) => void;
    onCommit: () => void;
    selectedId: string | null;
    setSelectedId: (id: string | null) => void;
    pendingComponent: NodeType | null;
    setPendingComponent: (type: NodeType | null) => void;
    toolMode: 'select' | 'interact' | 'junction';
    wireMode: 'manhattan' | 'bezier';
    isSimulating: boolean;
    validationResult: {
        valid: boolean;
        messages: string[];
        invalidNodeIds: string[];
        floatingInputs: { nodeId: string; index: number }[];
    } | null;
    setValidationResult: (res: any) => void;
}

export const CircuitCanvas: React.FC<CircuitCanvasProps> = ({ 
    circuit, onUpdateCircuit, onCommit,
    selectedId, setSelectedId,
    pendingComponent, setPendingComponent,
    toolMode, wireMode, isSimulating,
    validationResult, setValidationResult
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const { theme } = useTheme();

  // Local Interaction State
  const [draggingNodeId, setDraggingNodeId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<Point>({ x: 0, y: 0 });
  const [wiring, setWiring] = useState<WiringState | null>(null);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });

  // --- Keyboard Shortcuts (Local Interactions) ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
            if (pendingComponent) setPendingComponent(null);
            if (wiring) setWiring(null);
            if (selectedId) setSelectedId(null);
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [pendingComponent, wiring, selectedId, setPendingComponent, setSelectedId]);


  const addNode = (type: NodeType, x: number, y: number) => {
    onCommit(); // Snapshot before adding
    const def = NODE_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newNode: NodeData = {
      id: `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      position: { x: snapX, y: snapY },
      inputs: Array(def.inputs).fill(false),
      outputs: Array(def.outputs).fill(false),
      internalState: {},
      properties: {
          label: '',
          labelPosition: 'Top',
          inputCount: def.inputs,
          propagationDelay: 0,
          initialState: false,
          romValue: false,
          interval: type === 'CLOCK' ? 20 : 0
      }
    };

    onUpdateCircuit([...circuit.nodes, newNode], circuit.wires);
    setSelectedId(newNode.id);
  };

  // --- Interaction Handlers ---

  const handleNodeMouseDown = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (wiring) return;
    if (pendingComponent) return; 

    setSelectedId(id);
    const node = circuit.nodes.find(n => n.id === id);
    if (!node) return;

    const isInteractive = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

    if ((toolMode === 'interact' || isSimulating) && isInteractive) {
        if (!isSimulating) onCommit();

        let toggledNodes = circuit.nodes;

        // Special handling for Multi-bit inputs
        if (node.type.startsWith('INPUT_')) {
            const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
            const relY = e.clientY - rect.top; 
            const relX = e.clientX - rect.left;
            const { width, height } = getNodeDimensions(node);
            const bitCount = node.outputs.length;

            // Check Header Click (Direct Value Input)
            if (relY < 25) {
                const inputVal = window.prompt(`Set Value for ${bitCount}-bit Input:\nUse decimal, hex (0x...), or binary (0b...)`);
                if (inputVal !== null) {
                    let val = parseInt(inputVal);
                    if (inputVal.startsWith('0b')) val = parseInt(inputVal.slice(2), 2);
                    else if (inputVal.startsWith('0x')) val = parseInt(inputVal, 16);

                    if (!isNaN(val)) {
                        const newOutputs = [];
                        for(let i=0; i<bitCount; i++) {
                            newOutputs.push(!!((val >> i) & 1));
                        }
                        toggledNodes = circuit.nodes.map(n => n.id === id ? { ...n, outputs: newOutputs } : n);
                        onUpdateCircuit(toggledNodes, circuit.wires);
                    }
                }
                return;
            }

            let bitIndexToCheck = -1;

            // Check Footer (Binary) Click
            if (relY > height - 30) {
                const bitWidth = 10;
                const bitSpacing = 2;
                const nibbleGap = 6;
                const totalWidth = bitCount * bitWidth + (bitCount - 1) * bitSpacing + Math.floor((bitCount - 1) / 4) * nibbleGap;
                const startX = (width - totalWidth) / 2 + bitWidth / 2;

                for (let i = 0; i < bitCount; i++) {
                    const nibblesBefore = Math.floor(i / 4);
                    const xPos = startX + i * (bitWidth + bitSpacing) + nibblesBefore * nibbleGap;
                    if (Math.abs(relX - xPos) < 8) {
                        bitIndexToCheck = bitCount - 1 - i;
                        break;
                    }
                }
            } else {
                // Check Row Switch Click
                // Header is 25. Rows start at 25. Each row 20.
                const rowIdx = Math.floor((relY - 25) / 20);
                if (rowIdx >= 0 && rowIdx < bitCount) {
                    bitIndexToCheck = rowIdx;
                }
            }

            if (bitIndexToCheck >= 0 && bitIndexToCheck < bitCount) {
                toggledNodes = circuit.nodes.map(n => {
                    if (n.id === id) {
                        const newOutputs = [...n.outputs];
                        newOutputs[bitIndexToCheck] = !newOutputs[bitIndexToCheck];
                        return { ...n, outputs: newOutputs };
                    }
                    return n;
                });
            }
        } else {
            // Standard single toggle
            toggledNodes = circuit.nodes.map(n => {
                if (n.id === id) {
                    const newState = !n.outputs[0];
                    return { ...n, outputs: [newState] };
                }
                return n;
            });
        }

        onUpdateCircuit(toggledNodes, circuit.wires);
        return; 
    }

    if (toolMode === 'select' || toolMode === 'junction') {
        // Start dragging
        onCommit(); // Snapshot position before move
        setDraggingNodeId(id);
        const rect = containerRef.current!.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;
        setDragOffset({
            x: mouseX - node.position.x,
            y: mouseY - node.position.y
        });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    if (draggingNodeId) {
        const snapX = Math.round((x - dragOffset.x) / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round((y - dragOffset.y) / GRID_SIZE) * GRID_SIZE;

        const updatedNodes = circuit.nodes.map(n => {
            if (n.id === draggingNodeId) {
                return { ...n, position: { x: snapX, y: snapY }};
            }
            return n;
        });
        onUpdateCircuit(updatedNodes, circuit.wires);
    }
  };

  const handleMouseUp = () => {
    if (draggingNodeId) {
        setDraggingNodeId(null);
    }
    if (wiring) {
        setWiring(null);
    }
  };

  const startWiring = (e: React.MouseEvent, nodeId: string, outputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();
    if (toolMode === 'interact' && !isSimulating) return; 

    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setWiring({
        sourceNodeId: nodeId,
        sourceOutputIndex: outputIndex,
        startPoint: { x, y },
        active: true
    });
  };

  const completeWiring = (e: React.MouseEvent, targetNodeId: string, inputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();

    if (!wiring) return;

    if (wiring.sourceNodeId === targetNodeId) {
        setWiring(null);
        return;
    }

    onCommit(); // Snapshot before wiring change

    const exists = circuit.wires.some(w => 
        w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex
    );

    let newWires = exists 
        ? circuit.wires.filter(w => !(w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex))
        : [...circuit.wires];

    newWires.push({
        id: `wire-${Date.now()}`,
        sourceNodeId: wiring.sourceNodeId,
        sourceOutputIndex: wiring.sourceOutputIndex,
        targetNodeId: targetNodeId,
        targetInputIndex: inputIndex,
        state: false
    });

    onUpdateCircuit(circuit.nodes, newWires);
    setWiring(null);
  };

  const handleWireClick = (e: React.MouseEvent, wire: Wire, x: number, y: number) => {
    if (toolMode !== 'junction') {
        e.stopPropagation();
        setSelectedId(wire.id);
        return;
    }
    e.stopPropagation();

    onCommit(); // Snapshot before creating junction

    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;
    const junctionId = `node-${Date.now()}-junction`;

    const newJunction: NodeData = {
        id: junctionId,
        type: 'JUNCTION',
        position: { x: snapX - 5, y: snapY - 5 },
        inputs: [false],
        outputs: [false],
        properties: { label: '' }
    };

    const wire1: Wire = {
        id: `wire-${Date.now()}-1`,
        sourceNodeId: wire.sourceNodeId,
        sourceOutputIndex: wire.sourceOutputIndex,
        targetNodeId: junctionId,
        targetInputIndex: 0,
        state: wire.state
    };
    const wire2: Wire = {
        id: `wire-${Date.now()}-2`,
        sourceNodeId: junctionId,
        sourceOutputIndex: 0,
        targetNodeId: wire.targetNodeId,
        targetInputIndex: wire.targetInputIndex,
        state: wire.state
    };

    const newWires = circuit.wires.filter(w => w.id !== wire.id).concat([wire1, wire2]);
    const newNodes = [...circuit.nodes, newJunction];

    onUpdateCircuit(newNodes, newWires);
    setSelectedId(junctionId);
  };

  const handleCanvasClick = (e: React.MouseEvent) => {
      if (pendingComponent && containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        addNode(pendingComponent, x, y);
        setPendingComponent(null);
        return;
      }
      setSelectedId(null);
      if (validationResult?.valid) setValidationResult(null);
  };

  const getWirePath = (x1: number, y1: number, x2: number, y2: number) => {
    if (wireMode === 'bezier') {
        const dist = Math.abs(x2 - x1);
        const controlPointOffset = Math.max(dist * 0.5, 50);
        return `M ${x1} ${y1} C ${x1 + controlPointOffset} ${y1}, ${x2 - controlPointOffset} ${y2}, ${x2} ${y2}`;
    }
    const dx = x2 - x1;
    if (dx > 20) {
        const midX = (x1 + x2) / 2;
        return `M ${x1} ${y1} L ${midX} ${y1} L ${midX} ${y2} L ${x2} ${y2}`;
    }
    const stub = 20;
    const midY = (y1 + y2) / 2;
    return `M ${x1} ${y1} L ${x1 + stub} ${y1} L ${x1 + stub} ${midY} L ${x2 - stub} ${midY} L ${x2 - stub} ${y2} L ${x2} ${y2}`;
  };

  // Helper to determine label CSS class based on position
  const getLabelStyle = (pos: string | undefined): React.CSSProperties => {
      switch (pos) {
          case 'Bottom': return { top: '100%', left: '50%', transform: 'translate(-50%, 8px)' };
          case 'Left': return { top: '50%', right: '100%', transform: 'translate(-8px, -50%)' };
          case 'Right': return { top: '50%', left: '100%', transform: 'translate(8px, -50%)' };
          case 'Top': default: return { bottom: '100%', left: '50%', transform: 'translate(-50%, -8px)' };
      }
  };

  // Preview Logic
  const ghostSnapX = Math.round(mousePos.x / GRID_SIZE) * GRID_SIZE;
  const ghostSnapY = Math.round(mousePos.y / GRID_SIZE) * GRID_SIZE;
  const pendingDef = pendingComponent ? NODE_DEFINITIONS[pendingComponent] : null;

  return (
    <div 
        ref={containerRef}
        className={`flex-1 relative w-full h-full overflow-hidden bg-zinc-50 dark:bg-zinc-950
            ${isSimulating ? 'cursor-default' : pendingComponent ? 'cursor-cell' : toolMode === 'junction' ? 'cursor-crosshair' : 'cursor-crosshair'}`}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onClick={handleCanvasClick}
        onContextMenu={(e) => e.preventDefault()}
    >
        {/* Validation Messages Overlay */}
        {validationResult && (
            <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 pointer-events-none w-auto max-w-lg">
                <div className={`p-4 rounded-lg shadow-xl backdrop-blur-md border animate-in slide-in-from-top-4 duration-200
                    ${validationResult.valid ? 'bg-green-50/90 dark:bg-green-950/80 border-green-200 dark:border-green-800 text-green-800 dark:text-green-200' : 'bg-red-50/90 dark:bg-red-950/80 border-red-200 dark:border-red-800 text-red-800 dark:text-red-200'}`}
                >
                    <div className="flex items-start gap-3">
                        {validationResult.valid ? <CheckCircle2 size={20} className="mt-0.5 text-green-600 dark:text-green-400" /> : <AlertTriangle size={20} className="mt-0.5 text-red-600 dark:text-red-400" />}
                        <div>
                            <h4 className="font-bold text-sm mb-1">{validationResult.valid ? 'Circuit Valid' : 'Compatibility Issues Found'}</h4>
                            <ul className="text-xs space-y-1 list-disc list-inside opacity-90">
                                {validationResult.messages.map((m, i) => <li key={i}>{m}</li>)}
                            </ul>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* Grid Pattern */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full opacity-20 dark:opacity-20">
            <defs>
                <pattern id="grid" width={GRID_SIZE} height={GRID_SIZE} patternUnits="userSpaceOnUse">
                    <circle cx="1" cy="1" r="1" className="fill-zinc-400 dark:fill-zinc-500" />
                </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#grid)" />
        </svg>

        {/* Connections */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
            {circuit.wires.map(wire => {
                const sourceNode = circuit.nodes.find(n => n.id === wire.sourceNodeId);
                const targetNode = circuit.nodes.find(n => n.id === wire.targetNodeId);
                if (!sourceNode || !targetNode) return null;

                const sourcePorts = getOutputPorts(sourceNode);
                const targetPorts = getInputPorts(targetNode);

                const outputOffset = sourcePorts[wire.sourceOutputIndex] || { x: 0, y: 0 };
                const inputOffset = targetPorts[wire.targetInputIndex] || { x: 0, y: 0 };

                const startX = sourceNode.position.x + outputOffset.x;
                const startY = sourceNode.position.y + outputOffset.y;
                const endX = targetNode.position.x + inputOffset.x;
                const endY = targetNode.position.y + inputOffset.y;

                const isSelected = selectedId === wire.id;
                const pathData = getWirePath(startX, startY, endX, endY);

                return (
                    <g 
                        key={wire.id} 
                        onClick={(e) => { 
                            if (!containerRef.current) return;
                            const rect = containerRef.current.getBoundingClientRect();
                            handleWireClick(e, wire, e.clientX - rect.left, e.clientY - rect.top);
                        }} 
                        className={`pointer-events-auto cursor-pointer group`}
                    >
                        <path d={pathData} stroke="transparent" strokeWidth="16" fill="none" />
                        {wire.state && <path d={pathData} stroke="#22d3ee" strokeWidth="4" fill="none" opacity="0.3" filter="blur(2px)" />}
                        <path d={pathData} stroke={wire.state ? "#22d3ee" : (theme === 'dark' ? "#52525b" : "#a1a1aa")} strokeWidth={isSelected ? "3" : "2"} fill="none" className="transition-colors duration-150" strokeDasharray={isSelected ? "4" : "0"} strokeLinejoin="round" strokeLinecap="round" />
                    </g>
                );
            })}

            {wiring && (
                <path d={getWirePath(wiring.startPoint.x, wiring.startPoint.y, mousePos.x, mousePos.y)} stroke="#fbbf24" strokeWidth="2" fill="none" strokeDasharray="4" className="animate-pulse" strokeLinejoin="round" />
            )}
        </svg>

        {/* Nodes */}
        {circuit.nodes.map(node => {
            const { width, height } = getNodeDimensions(node);
            const isSelected = selectedId === node.id;
            const isInvalid = validationResult?.invalidNodeIds?.includes(node.id);
            const inputPorts = getInputPorts(node);
            const outputPorts = getOutputPorts(node);
            const def = NODE_DEFINITIONS[node.type];
            const canInteract = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

            return (
                <div
                    key={node.id}
                    className={`absolute group select-none`}
                    style={{
                        left: node.position.x,
                        top: node.position.y,
                        width: width,
                        height: height,
                        pointerEvents: 'none',
                        zIndex: isSelected ? 50 : 10 
                    }}
                >
                    <div 
                        className={`absolute inset-0 pointer-events-auto transition-all duration-200 
                            ${isSelected ? 'drop-shadow-[0_0_8px_rgba(34,211,238,0.5)]' : ''} 
                            ${isInvalid ? 'drop-shadow-[0_0_8px_rgba(239,68,68,0.8)]' : ''}
                            ${(toolMode === 'interact' || isSimulating) && canInteract ? 'cursor-pointer' : 'cursor-grab active:cursor-grabbing'}
                        `}
                        onMouseDown={(e) => handleNodeMouseDown(e, node.id)}
                    >
                        <svg width={width} height={height} className="overflow-visible">
                            <GateShape node={node} />
                        </svg>
                    </div>

                    {isInvalid && (
                        <div className="absolute -top-3 -right-3 text-red-500 bg-white dark:bg-zinc-950 rounded-full p-0.5 shadow-md border border-red-200 dark:border-red-900 animate-bounce z-50">
                            <AlertTriangle size={14} fill="currentColor" className="text-red-100 dark:text-red-900" stroke="currentColor" />
                        </div>
                    )}

                    {inputPorts.map((offset, idx) => {
                        const isFloating = validationResult?.floatingInputs?.some(fi => fi.nodeId === node.id && fi.index === idx);

                        return (
                        <div
                            key={`input-${idx}`}
                            className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 
                            ${(toolMode === 'select' || toolMode === 'junction') && !isSimulating ? 'cursor-crosshair' : 'cursor-default'}`}
                            style={{ left: offset.x, top: offset.y }}
                            onMouseUp={(e) => !isSimulating && (toolMode === 'select' || toolMode === 'junction') && completeWiring(e, node.id, idx)}
                            title={offset.label || "Input"}
                        >
                            <div className={`w-2 h-2 rounded-full bg-white dark:bg-zinc-900 border transition-all duration-300 ${
                                isFloating 
                                ? 'border-red-500 bg-red-500/50 ring-2 ring-red-500 ring-opacity-50 animate-pulse' 
                                : node.inputs[idx] ? 'border-cyan-400 bg-cyan-100 dark:bg-cyan-900' : 'border-zinc-400 dark:border-zinc-500'
                            }`} />
                        </div>
                        );
                    })}

                    {outputPorts.map((offset, idx) => (
                        <div
                            key={`output-${idx}`}
                            className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 
                            ${(toolMode === 'select' || toolMode === 'junction') && !isSimulating ? 'cursor-crosshair' : 'cursor-default'}`}
                            style={{ left: offset.x, top: offset.y }}
                            onMouseDown={(e) => !isSimulating && (toolMode === 'select' || toolMode === 'junction') && startWiring(e, node.id, idx)}
                            title={offset.label || "Output"}
                        >
                            <div className={`w-2 h-2 rounded-full bg-white dark:bg-zinc-900 border ${node.outputs[idx] ? 'border-cyan-400 bg-cyan-500' : 'border-zinc-400 dark:border-zinc-500 group-hover:border-zinc-600 dark:group-hover:border-zinc-300'}`} />
                        </div>
                    ))}

                    {(isSelected || node.properties?.label) && node.type !== 'JUNCTION' && (
                        <div 
                            className="absolute bg-white/90 dark:bg-zinc-900/90 text-zinc-800 dark:text-zinc-100 text-[10px] px-2 py-0.5 rounded border border-zinc-200 dark:border-zinc-700 whitespace-nowrap shadow-md pointer-events-none backdrop-blur-sm z-[60]"
                            style={getLabelStyle(node.properties?.labelPosition)}
                        >
                            {node.properties?.label || def.name}
                        </div>
                    )}
                </div>
            );
        })}

        {/* Ghost Component */}
        {pendingComponent && pendingDef && (
            <div 
                className="absolute pointer-events-none opacity-50 z-50"
                style={{
                    left: ghostSnapX,
                    top: ghostSnapY,
                    width: pendingDef.width,
                    height: pendingDef.height
                }}
            >
                <svg width={pendingDef.width} height={pendingDef.height} className="overflow-visible">
                        <GateShape node={{ 
                        id: 'ghost', 
                        type: pendingComponent, 
                        position: {x: 0, y: 0}, 
                        inputs: Array(pendingDef.inputs).fill(false), 
                        outputs: Array(pendingDef.outputs).fill(false),
                        properties: { inputCount: pendingDef.inputs }
                    }} />
                </svg>
                <div className="absolute -top-6 left-0 bg-cyan-500 text-white text-[10px] px-2 py-0.5 rounded shadow-sm whitespace-nowrap">
                    Click to place
                </div>
            </div>
        )}
    </div>
  );
};

import React from 'react';
import { NodeData, NodeType } from '../types';
import { Settings2, Hash, Type, Palette, Activity, Clock, AlignCenterVertical, MousePointerClick, Binary } from 'lucide-react';
import { VARIABLE_INPUT_GATES } from '../utils/componentUtils';

interface PropertiesPanelProps {
  node: NodeData | null;
  onUpdate: (id: string, updates: Partial<NodeData>) => void;
  width: number;
}

export const PropertiesPanel: React.FC<PropertiesPanelProps> = ({ node, onUpdate, width }) => {
  if (!node) {
    return (
      <div 
        style={{ width }}
        className="bg-white dark:bg-zinc-900 border-l border-zinc-200 dark:border-zinc-800 p-6 flex flex-col items-center justify-center text-zinc-400 dark:text-zinc-500 h-full select-none transition-colors duration-300 flex-shrink-0"
      >
         <Settings2 size={32} className="mb-3 opacity-50" />
         <p className="text-sm font-medium">No Selection</p>
         <p className="text-xs text-zinc-500 dark:text-zinc-600 text-center mt-1">Select a component to edit its attributes.</p>
      </div>
    );
  }

  // --- Helper Checks ---
  const isGate = VARIABLE_INPUT_GATES.includes(node.type) || ['BUFFER', 'NOT'].includes(node.type);
  const isStateful = ['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'D_LATCH', 'JK_MASTER_SLAVE', 'SHIFT_REGISTER_4BIT'].includes(node.type);
  const isSwitch = ['SWITCH'].includes(node.type);
  const isClock = node.type === 'CLOCK';
  const isROM = node.type === 'ROM_1BIT';
  const isEdgeTriggered = ['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'SHIFT_REGISTER_4BIT'].includes(node.type);

  const isMultiBitInput = node.type.startsWith('INPUT_') && node.type.includes('BIT');
  const isMultiBitOutput = node.type.startsWith('OUTPUT_') && node.type.includes('BIT');
  const isMultiBit = isMultiBitInput || isMultiBitOutput;

  // --- Helpers ---
  const getMultiBitValue = (bools: boolean[]) => {
      return bools.reduce((acc, b, i) => acc + (b ? Math.pow(2, i) : 0), 0);
  };

  const boolsToBinStr = (bools: boolean[]) => {
      // MSB at left (highest index), LSB at right (index 0)
      return bools.map(b => b ? '1' : '0').reverse().join('');
  }

  const updateMultiBitValue = (val: number, bitCount: number) => {
      const newOutputs = [];
      for(let i=0; i<bitCount; i++) {
          newOutputs.push(!!((val >> i) & 1));
      }
      onUpdate(node.id, { outputs: newOutputs });
  };

  // --- Handlers ---
  const updateProp = (key: string, value: any) => {
      onUpdate(node.id, { properties: { ...node.properties, [key]: value } });
  };

  const handleBitWidthChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      const width = parseInt(e.target.value);
      let newType = node.type;
      if (isMultiBitInput) newType = `INPUT_${width}BIT` as NodeType;
      else if (isMultiBitOutput) newType = `OUTPUT_${width}BIT` as NodeType;

      if (newType !== node.type) {
          onUpdate(node.id, { type: newType });
      }
  };

  // --- Renderers ---
  const renderRow = (label: string, icon: React.ReactNode, control: React.ReactNode) => (
      <div className="flex items-center justify-between py-2 border-b border-zinc-100 dark:border-zinc-800/50 last:border-0">
          <div className="flex items-center gap-2 text-zinc-600 dark:text-zinc-400">
              {icon}
              <span className="text-xs font-medium">{label}</span>
          </div>
          <div className="w-1/2 flex justify-end">
              {control}
          </div>
      </div>
  );

  const getBitWidth = (type: NodeType) => {
      if (type.includes('2BIT')) return 2;
      if (type.includes('4BIT')) return 4;
      if (type.includes('8BIT')) return 8;
      if (type.includes('16BIT')) return 16;
      return 0;
  };

  return (
    <div 
        style={{ width }}
        className="bg-white dark:bg-zinc-900 border-l border-zinc-200 dark:border-zinc-800 flex flex-col h-full shadow-xl transition-colors duration-300 flex-shrink-0"
    >
       <div className="h-14 flex items-center px-4 border-b border-zinc-200 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50">
          <div className="flex items-center gap-2">
             <Settings2 size={16} className="text-cyan-600 dark:text-cyan-400" />
