import React, { useRef, useState, useEffect } from 'react';
import { GRID_SIZE, NODE_DEFINITIONS } from '../constants';
import { CircuitState, NodeData, NodeType, Wire, Point, WiringState } from '../types';
import { GateShape } from './GateShapes';
import { getNodeDimensions, getInputPorts, getOutputPorts } from '../utils/componentUtils';
import { CheckCircle2, AlertTriangle } from 'lucide-react';
import { useTheme } from './ThemeContext';

interface CircuitCanvasProps {
    circuit: CircuitState;
    onUpdateCircuit: (nodes: NodeData[], wires: Wire[]) => void;
    onCommit: () => void;
    selectedId: string | null;
    setSelectedId: (id: string | null) => void;
    pendingComponent: NodeType | null;
    setPendingComponent: (type: NodeType | null) => void;
    toolMode: 'select' | 'interact' | 'junction';
    wireMode: 'manhattan' | 'bezier';
    isSimulating: boolean;
    validationResult: {
        valid: boolean;
        messages: string[];
        invalidNodeIds: string[];
        floatingInputs: { nodeId: string; index: number }[];
    } | null;
    setValidationResult: (res: any) => void;
}

export const CircuitCanvas: React.FC<CircuitCanvasProps> = ({ 
    circuit, onUpdateCircuit, onCommit,
    selectedId, setSelectedId,
    pendingComponent, setPendingComponent,
    toolMode, wireMode, isSimulating,
    validationResult, setValidationResult
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const { theme } = useTheme();

  // Local Interaction State
  const [draggingNodeId, setDraggingNodeId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<Point>({ x: 0, y: 0 });
  const [wiring, setWiring] = useState<WiringState | null>(null);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });

  // --- Keyboard Shortcuts (Local Interactions) ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
            if (pendingComponent) setPendingComponent(null);
            if (wiring) setWiring(null);
            if (selectedId) setSelectedId(null);
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [pendingComponent, wiring, selectedId, setPendingComponent, setSelectedId]);


  const addNode = (type: NodeType, x: number, y: number) => {
    onCommit(); // Snapshot before adding
    const def = NODE_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newNode: NodeData = {
      id: `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      position: { x: snapX, y: snapY },
      inputs: Array(def.inputs).fill(false),
      outputs: Array(def.outputs).fill(false),
      internalState: {},
      properties: {
          label: '',
          labelPosition: 'Top',
          inputCount: def.inputs,
          propagationDelay: 0,
          initialState: false,
          romValue: false,
          interval: type === 'CLOCK' ? 20 : 0
      }
    };

    onUpdateCircuit([...circuit.nodes, newNode], circuit.wires);
    setSelectedId(newNode.id);
  };

  // --- Interaction Handlers ---

  const handleNodeMouseDown = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (wiring) return;
    if (pendingComponent) return; 

    setSelectedId(id);
    const node = circuit.nodes.find(n => n.id === id);
    if (!node) return;

    const isInteractive = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

    // Strict Mode Separation

    // 1. INTERACT MODE: Only allow interactions, disable dragging
    if (toolMode === 'interact' || isSimulating) {
        if (isInteractive) {
            if (!isSimulating) onCommit();

            let toggledNodes = circuit.nodes;

            // Special handling for Multi-bit inputs
            if (node.type.startsWith('INPUT_')) {
                const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
                const relY = e.clientY - rect.top; 
                const relX = e.clientX - rect.left;
                const { width, height } = getNodeDimensions(node);
                const bitCount = node.outputs.length;

                // Check Header Click (Direct Value Input)
                if (relY < 25) {
                    const inputVal = window.prompt(`Set Value for ${bitCount}-bit Input:\nUse decimal, hex (0x...), or binary (0b...)`);
                    if (inputVal !== null) {
                        let val = parseInt(inputVal);
                        if (inputVal.startsWith('0b')) val = parseInt(inputVal.slice(2), 2);
                        else if (inputVal.startsWith('0x')) val = parseInt(inputVal, 16);

                        if (!isNaN(val)) {
                            const newOutputs = [];
                            for(let i=0; i<bitCount; i++) {
                                newOutputs.push(!!((val >> i) & 1));
                            }
                            toggledNodes = circuit.nodes.map(n => n.id === id ? { ...n, outputs: newOutputs } : n);
                            onUpdateCircuit(toggledNodes, circuit.wires);
                        }
                    }
                    return;
                }

                let bitIndexToCheck = -1;

                // Check Footer (Binary) Click
                if (relY > height - 30) {
                    const bitWidth = 10;
                    const bitSpacing = 2;
                    const nibbleGap = 6;
                    const totalWidth = bitCount * bitWidth + (bitCount - 1) * bitSpacing + Math.floor((bitCount - 1) / 4) * nibbleGap;
                    const startX = (width - totalWidth) / 2 + bitWidth / 2;

                    for (let i = 0; i < bitCount; i++) {
                        const nibblesBefore = Math.floor(i / 4);
                        const xPos = startX + i * (bitWidth + bitSpacing) + nibblesBefore * nibbleGap;
                        if (Math.abs(relX - xPos) < 8) {
                            bitIndexToCheck = bitCount - 1 - i;
                            break;
                        }
                    }
                } else {
                    // Check Row Switch Click
                    // Header is 25. Rows start at 25. Each row 20.
                    const rowIdx = Math.floor((relY - 25) / 20);
                    if (rowIdx >= 0 && rowIdx < bitCount) {
                        bitIndexToCheck = rowIdx;
                    }
                }

                if (bitIndexToCheck >= 0 && bitIndexToCheck < bitCount) {
                    toggledNodes = circuit.nodes.map(n => {
                        if (n.id === id) {
                            const newOutputs = [...n.outputs];
                            newOutputs[bitIndexToCheck] = !newOutputs[bitIndexToCheck];
                            return { ...n, outputs: newOutputs };
                        }
                        return n;
                    });
                }
            } else {
                // Standard single toggle
                toggledNodes = circuit.nodes.map(n => {
                    if (n.id === id) {
                        const newState = !n.outputs[0];
                        return { ...n, outputs: [newState] };
                    }
                    return n;
                });
            }
            onUpdateCircuit(toggledNodes, circuit.wires);
        }
        return; // Important: Return here prevents dragging in Interact mode
    }

    // 2. MOVE MODE: Allow dragging, ignore interactions
    if (toolMode === 'select' || toolMode === 'junction') {
        // Start dragging
        onCommit(); // Snapshot position before move
        setDraggingNodeId(id);
        const rect = containerRef.current!.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;
        setDragOffset({
            x: mouseX - node.position.x,
            y: mouseY - node.position.y
        });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    if (draggingNodeId) {
        const snapX = Math.round((x - dragOffset.x) / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round((y - dragOffset.y) / GRID_SIZE) * GRID_SIZE;

        const updatedNodes = circuit.nodes.map(n => {
            if (n.id === draggingNodeId) {
                return { ...n, position: { x: snapX, y: snapY }};
            }
            return n;
        });
        onUpdateCircuit(updatedNodes, circuit.wires);
    }
  };

  const handleMouseUp = () => {
    if (draggingNodeId) {
        setDraggingNodeId(null);
    }
    if (wiring) {
        setWiring(null);
    }
  };

  const startWiring = (e: React.MouseEvent, nodeId: string, outputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();
    if (toolMode === 'interact' && !isSimulating) return; 

    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setWiring({
        sourceNodeId: nodeId,
        sourceOutputIndex: outputIndex,
        startPoint: { x, y },
        active: true
    });
  };

  const completeWiring = (e: React.MouseEvent, targetNodeId: string, inputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();

    if (!wiring) return;

    if (wiring.sourceNodeId === targetNodeId) {
        setWiring(null);
        return;
    }

    onCommit(); // Snapshot before wiring change

    const exists = circuit.wires.some(w => 
        w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex
    );

    let newWires = exists 
        ? circuit.wires.filter(w => !(w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex))
        : [...circuit.wires];

    newWires.push({
        id: `wire-${Date.now()}`,
        sourceNodeId: wiring.sourceNodeId,
        sourceOutputIndex: wiring.sourceOutputIndex,
        targetNodeId: targetNodeId,
        targetInputIndex: inputIndex,
        state: false
    });

    onUpdateCircuit(circuit.nodes, newWires);
    setWiring(null);
  };

  const handleWireClick = (e: React.MouseEvent, wire: Wire, x: number, y: number) => {
    if (toolMode !== 'junction') {
        e.stopPropagation();
        setSelectedId(wire.id);
        return;
    }
    e.stopPropagation();

    onCommit(); // Snapshot before creating junction

    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;
    const junctionId = `node-${Date.now()}-junction`;

    const newJunction: NodeData = {
        id: junctionId,
        type: 'JUNCTION',
        position: { x: snapX - 5, y: snapY - 5 },
        inputs: [false],
        outputs: [false],
        properties: { label: '' }
    };

    const wire1: Wire = {
        id: `wire-${Date.now()}-1`,
        sourceNodeId: wire.sourceNodeId,
        sourceOutputIndex: wire.sourceOutputIndex,
        targetNodeId: junctionId,
        targetInputIndex: 0,
        state: wire.state
    };
    const wire2: Wire = {
        id: `wire-${Date.now()}-2`,
        sourceNodeId: junctionId,
        sourceOutputIndex: 0,
        targetNodeId: wire.targetNodeId,
        targetInputIndex: wire.targetInputIndex,
        state: wire.state
    };

    const newWires = circuit.wires.filter(w => w.id !== wire.id).concat([wire1, wire2]);
    const newNodes = [...circuit.nodes, newJunction];

    onUpdateCircuit(newNodes, newWires);
    setSelectedId(junctionId);
  };

  const handleCanvasClick = (e: React.MouseEvent) => {
      if (pendingComponent && containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        addNode(pendingComponent, x, y);
        setPendingComponent(null);
        return;
      }
      setSelectedId(null);
      if (validationResult?.valid) setValidationResult(null);
  };

  const getWirePath = (x1: number, y1: number, x2: number, y2: number) => {
    if (wireMode === 'bezier') {
        const dist = Math.abs(x2 - x1);
        const controlPointOffset = Math.max(dist * 0.5, 50);
        return `M ${x1} ${y1} C ${x1 + controlPointOffset} ${y1}, ${x2 - controlPointOffset} ${y2}, ${x2} ${y2}`;
    }
    const dx = x2 - x1;
    if (dx > 20) {
        const midX = (x1 + x2) / 2;
        return `M ${x1} ${y1} L ${midX} ${y1} L ${midX} ${y2} L ${x2} ${y2}`;
    }
    const stub = 20;
    const midY = (y1 + y2) / 2;
    return `M ${x1} ${y1} L ${x1 + stub} ${y1} L ${x1 + stub} ${midY} L ${x2 - stub} ${midY} L ${x2 - stub} ${y2} L ${x2} ${y2}`;
  };

  // Helper to determine label CSS class based on position
  const getLabelStyle = (pos: string | undefined): React.CSSProperties => {
      switch (pos) {
          case 'Bottom': return { top: '100%', left: '50%', transform: 'translate(-50%, 8px)' };
          case 'Left': return { top: '50%', right: '100%', transform: 'translate(-8px, -50%)' };
          case 'Right': return { top: '50%', left: '100%', transform: 'translate(8px, -50%)' };
          case 'Top': default: return { bottom: '100%', left: '50%', transform: 'translate(-50%, -8px)' };
      }
  };

  // Preview Logic
  const ghostSnapX = Math.round(mousePos.x / GRID_SIZE) * GRID_SIZE;
  const ghostSnapY = Math.round(mousePos.y / GRID_SIZE) * GRID_SIZE;
  const pendingDef = pendingComponent ? NODE_DEFINITIONS[pendingComponent] : null;

  return (
    <div 
        ref={containerRef}
        className={`flex-1 relative w-full h-full overflow-hidden bg-zinc-50 dark:bg-zinc-950
            ${isSimulating ? 'cursor-default' : pendingComponent ? 'cursor-cell' : toolMode === 'junction' ? 'cursor-crosshair' : 'cursor-crosshair'}`}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onClick={handleCanvasClick}
        onContextMenu={(e) => e.preventDefault()}
    >
        {/* Validation Messages Overlay */}
        {validationResult && (
            <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 pointer-events-none w-auto max-w-lg">
                <div className={`p-4 rounded-lg shadow-xl backdrop-blur-md border animate-in slide-in-from-top-4 duration-200
                    ${validationResult.valid ? 'bg-green-50/90 dark:bg-green-950/80 border-green-200 dark:border-green-800 text-green-800 dark:text-green-200' : 'bg-red-50/90 dark:bg-red-950/80 border-red-200 dark:border-red-800 text-red-800 dark:text-red-200'}`}
                >
                    <div className="flex items-start gap-3">
                        {validationResult.valid ? <CheckCircle2 size={20} className="mt-0.5 text-green-600 dark:text-green-400" /> : <AlertTriangle size={20} className="mt-0.5 text-red-600 dark:text-red-400" />}
                        <div>
                            <h4 className="font-bold text-sm mb-1">{validationResult.valid ? 'Circuit Valid' : 'Compatibility Issues Found'}</h4>
                            <ul className="text-xs space-y-1 list-disc list-inside opacity-90">
                                {validationResult.messages.map((m, i) => <li key={i}>{m}</li>)}
                            </ul>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* Grid Pattern */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full opacity-20 dark:opacity-20">
            <defs>
                <pattern id="grid" width={GRID_SIZE} height={GRID_SIZE} patternUnits="userSpaceOnUse">
                    <circle cx="1" cy="1" r="1" className="fill-zinc-400 dark:fill-zinc-500" />
                </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#grid)" />
        </svg>

        {/* Connections */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
            {circuit.wires.map(wire => {
                const sourceNode = circuit.nodes.find(n => n.id === wire.sourceNodeId);
                const targetNode = circuit.nodes.find(n => n.id === wire.targetNodeId);
                if (!sourceNode || !targetNode) return null;

                const sourcePorts = getOutputPorts(sourceNode);
                const targetPorts = getInputPorts(targetNode);

                const outputOffset = sourcePorts[wire.sourceOutputIndex] || { x: 0, y: 0 };
                const inputOffset = targetPorts[wire.targetInputIndex] || { x: 0, y: 0 };

                const startX = sourceNode.position.x + outputOffset.x;
                const startY = sourceNode.position.y + outputOffset.y;
                const endX = targetNode.position.x + inputOffset.x;
                const endY = targetNode.position.y + inputOffset.y;

                const isSelected = selectedId === wire.id;
                const pathData = getWirePath(startX, startY, endX, endY);

                return (
                    <g 
                        key={wire.id} 
                        onClick={(e) => { 
                            if (!containerRef.current) return;
                            const rect = containerRef.current.getBoundingClientRect();
                            handleWireClick(e, wire, e.clientX - rect.left, e.clientY - rect.top);
                        }} 
                        className={`pointer-events-auto cursor-pointer group`}
                    >
                        <path d={pathData} stroke="transparent" strokeWidth="16" fill="none" />
                        {wire.state && <path d={pathData} stroke="#22d3ee" strokeWidth="4" fill="none" opacity="0.3" filter="blur(2px)" />}
                        <path d={pathData} stroke={wire.state ? "#22d3ee" : (theme === 'dark' ? "#52525b" : "#a1a1aa")} strokeWidth={isSelected ? "3" : "2"} fill="none" className="transition-colors duration-150" strokeDasharray={isSelected ? "4" : "0"} strokeLinejoin="round" strokeLinecap="round" />
                    </g>
                );
            })}

            {wiring && (
                <path d={getWirePath(wiring.startPoint.x, wiring.startPoint.y, mousePos.x, mousePos.y)} stroke="#fbbf24" strokeWidth="2" fill="none" strokeDasharray="4" className="animate-pulse" strokeLinejoin="round" />
            )}
        </svg>

        {/* Nodes */}
        {circuit.nodes.map(node => {
            const { width, height } = getNodeDimensions(node);
            const isSelected = selectedId === node.id;
            const isInvalid = validationResult?.invalidNodeIds?.includes(node.id);
            const inputPorts = getInputPorts(node);
            const outputPorts = getOutputPorts(node);
            const def = NODE_DEFINITIONS[node.type];
            const canInteract = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

            // Determine Cursor Style
            let cursorClass = 'cursor-default';
            if (toolMode === 'interact' || isSimulating) {
                 cursorClass = canInteract ? 'cursor-pointer' : 'cursor-default';
            } else if (toolMode === 'select' || toolMode === 'junction') {
                 cursorClass = 'cursor-grab active:cursor-grabbing';
            }

            return (
                <div
                    key={node.id}
                    className={`absolute group select-none`}
                    style={{
                        left: node.position.x,
                        top: node.position.y,
                        width: width,
                        height: height,
                        pointerEvents: 'none',
                        zIndex: isSelected ? 50 : 10 
                    }}
                >
                    <div 
                        className={`absolute inset-0 pointer-events-auto transition-all duration-200 
                            ${isSelected ? 'drop-shadow-[0_0_8px_rgba(34,211,238,0.5)]' : ''} 
                            ${isInvalid ? 'drop-shadow-[0_0_8px_rgba(239,68,68,0.8)]' : ''}
                            ${cursorClass}
                        `}
                        onMouseDown={(e) => handleNodeMouseDown(e, node.id)}
                    >
                        <svg width={width} height={height} className="overflow-visible">
                            <GateShape node={node} />
                        </svg>
                    </div>

                    {isInvalid && (
                        <div className="absolute -top-3 -right-3 text-red-500 bg-white dark:bg-zinc-950 rounded-full p-0.5 shadow-md border border-red-200 dark:border-red-900 animate-bounce z-50">
                            <AlertTriangle size={14} fill="currentColor" className="text-red-100 dark:text-red-900" stroke="currentColor" />
                        </div>
                    )}

                    {inputPorts.map((offset, idx) => {
                        const isFloating = validationResult?.floatingInputs?.some(fi => fi.nodeId === node.id && fi.index === idx);

                        return (
                        <div
                            key={`input-${idx}`}
                            className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 
                            ${(toolMode === 'select' || toolMode === 'junction') && !isSimulating ? 'cursor-crosshair' : 'cursor-default'}`}
                            style={{ left: offset.x, top: offset.y }}
                            onMouseUp={(e) => !isSimulating && (toolMode === 'select' || toolMode === 'junction') && completeWiring(e, node.id, idx)}
                            title={offset.label || "Input"}
                        >
                            <div className={`w-2 h-2 rounded-full bg-white dark:bg-zinc-900 border transition-all duration-300 ${
                                isFloating 
                                ? 'border-red-500 bg-red-500/50 ring-2 ring-red-500 ring-opacity-50 animate-pulse' 
                                : node.inputs[idx] ? 'border-cyan-400 bg-cyan-100 dark:bg-cyan-900' : 'border-zinc-400 dark:border-zinc-500'
                            }`} />
                        </div>
                        );
                    })}

                    {outputPorts.map((offset, idx) => (
                        <div
                            key={`output-${idx}`}
                            className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 
                            ${(toolMode === 'select' || toolMode === 'junction') && !isSimulating ? 'cursor-crosshair' : 'cursor-default'}`}
                            style={{ left: offset.x, top: offset.y }}
                            onMouseDown={(e) => !isSimulating && (toolMode === 'select' || toolMode === 'junction') && startWiring(e, node.id, idx)}
                            title={offset.label || "Output"}
                        >
                            <div className={`w-2 h-2 rounded-full bg-white dark:bg-zinc-900 border ${node.outputs[idx] ? 'border-cyan-400 bg-cyan-500' : 'border-zinc-400 dark:border-zinc-500 group-hover:border-zinc-600 dark:group-hover:border-zinc-300'}`} />
                        </div>
                    ))}

                    {(isSelected || node.properties?.label) && node.type !== 'JUNCTION' && (
                        <div 
                            className="absolute bg-white/90 dark:bg-zinc-900/90 text-zinc-800 dark:text-zinc-100 text-[10px] px-2 py-0.5 rounded border border-zinc-200 dark:border-zinc-700 whitespace-nowrap shadow-md pointer-events-none backdrop-blur-sm z-[60]"
                            style={getLabelStyle(node.properties?.labelPosition)}
                        >
                            {node.properties?.label || def.name}
                        </div>
                    )}
                </div>
            );
        })}

        {/* Ghost Component */}
        {pendingComponent && pendingDef && (
            <div 
                className="absolute pointer-events-none opacity-50 z-50"
                style={{
                    left: ghostSnapX,
                    top: ghostSnapY,
                    width: pendingDef.width,
                    height: pendingDef.height
                }}
            >
                <svg width={pendingDef.width} height={pendingDef.height} className="overflow-visible">
                        <GateShape node={{ 
                        id: 'ghost', 
                        type: pendingComponent, 
                        position: {x: 0, y: 0}, 
                        inputs: Array(pendingDef.inputs).fill(false), 
                        outputs: Array(pendingDef.outputs).fill(false),
                        properties: { inputCount: pendingDef.inputs }
                    }} />
                </svg>
                <div className="absolute -top-6 left-0 bg-cyan-500 text-white text-[10px] px-2 py-0.5 rounded shadow-sm whitespace-nowrap">
                    Click to place
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useRef, useState, useEffect } from 'react';
import { GRID_SIZE, NODE_DEFINITIONS } from '../constants';
import { CircuitState, NodeData, NodeType, Wire, Point, WiringState } from '../types';
import { GateShape } from './GateShapes';
import { getNodeDimensions, getInputPorts, getOutputPorts } from '../utils/componentUtils';
import { CheckCircle2, AlertTriangle } from 'lucide-react';
import { useTheme } from './ThemeContext';

interface CircuitCanvasProps {
    circuit: CircuitState;
    onUpdateCircuit: (nodes: NodeData[], wires: Wire[]) => void;
    onCommit: () => void;
    selectedId: string | null;
    setSelectedId: (id: string | null) => void;
    pendingComponent: NodeType | null;
    setPendingComponent: (type: NodeType | null) => void;
    toolMode: 'select' | 'interact' | 'junction';
    wireMode: 'manhattan' | 'bezier';
    isSimulating: boolean;
    validationResult: {
        valid: boolean;
        messages: string[];
        invalidNodeIds: string[];
        floatingInputs: { nodeId: string; index: number }[];
    } | null;
    setValidationResult: (res: any) => void;
}

export const CircuitCanvas: React.FC<CircuitCanvasProps> = ({ 
    circuit, onUpdateCircuit, onCommit,
    selectedId, setSelectedId,
    pendingComponent, setPendingComponent,
    toolMode, wireMode, isSimulating,
    validationResult, setValidationResult
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const { theme } = useTheme();

  // Local Interaction State
  const [draggingNodeId, setDraggingNodeId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<Point>({ x: 0, y: 0 });
  const [wiring, setWiring] = useState<WiringState | null>(null);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });

  // --- Keyboard Shortcuts (Local Interactions) ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
            if (pendingComponent) setPendingComponent(null);
            if (wiring) setWiring(null);
            if (selectedId) setSelectedId(null);
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [pendingComponent, wiring, selectedId, setPendingComponent, setSelectedId]);


  const addNode = (type: NodeType, x: number, y: number) => {
    onCommit(); // Snapshot before adding
    const def = NODE_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newNode: NodeData = {
      id: `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      position: { x: snapX, y: snapY },
      inputs: Array(def.inputs).fill(false),
      outputs: Array(def.outputs).fill(false),
      internalState: {},
      properties: {
          label: '',
          labelPosition: 'Top',
          inputCount: def.inputs,
          propagationDelay: 0,
          initialState: false,
          romValue: false,
          interval: type === 'CLOCK' ? 20 : 0
      }
    };

    onUpdateCircuit([...circuit.nodes, newNode], circuit.wires);
    setSelectedId(newNode.id);
  };

  // --- Interaction Handlers ---

  const handleNodeMouseDown = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (wiring) return;
    if (pendingComponent) return; 

    const node = circuit.nodes.find(n => n.id === id);
    if (!node) return;

    const isInteractive = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

    // Strict Mode Separation

    // 1. INTERACT MODE: Only allow interactions for interactive components. 
    //    For non-interactive components, allow selection (to see state).
    if (toolMode === 'interact' || isSimulating) {
        if (isInteractive) {
            // Interactive: Toggle/Action only. DO NOT SELECT.
            if (!isSimulating) onCommit();

            let toggledNodes = circuit.nodes;

            // Special handling for Multi-bit inputs
            if (node.type.startsWith('INPUT_')) {
                const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
                const relY = e.clientY - rect.top; 
                const relX = e.clientX - rect.left;
                const { width, height } = getNodeDimensions(node);
                const bitCount = node.outputs.length;

                // Check Header Click (Direct Value Input)
                if (relY < 25) {
                    const inputVal = window.prompt(`Set Value for ${bitCount}-bit Input:\nUse decimal, hex (0x...), or binary (0b...)`);
                    if (inputVal !== null) {
                        let val = parseInt(inputVal);
                        if (inputVal.startsWith('0b')) val = parseInt(inputVal.slice(2), 2);
                        else if (inputVal.startsWith('0x')) val = parseInt(inputVal, 16);

                        if (!isNaN(val)) {
                            const newOutputs = [];
                            for(let i=0; i<bitCount; i++) {
                                newOutputs.push(!!((val >> i) & 1));
                            }
                            toggledNodes = circuit.nodes.map(n => n.id === id ? { ...n, outputs: newOutputs } : n);
                            onUpdateCircuit(toggledNodes, circuit.wires);
                        }
                    }
                    return;
                }

                let bitIndexToCheck = -1;

                // Check Footer (Binary) Click
                if (relY > height - 30) {
                    const bitWidth = 10;
                    const bitSpacing = 2;
                    const nibbleGap = 6;
                    const totalWidth = bitCount * bitWidth + (bitCount - 1) * bitSpacing + Math.floor((bitCount - 1) / 4) * nibbleGap;
                    const startX = (width - totalWidth) / 2 + bitWidth / 2;

                    for (let i = 0; i < bitCount; i++) {
                        const nibblesBefore = Math.floor(i / 4);
                        const xPos = startX + i * (bitWidth + bitSpacing) + nibblesBefore * nibbleGap;
                        if (Math.abs(relX - xPos) < 8) {
                            bitIndexToCheck = bitCount - 1 - i;
                            break;
                        }
                    }
                } else {
                    // Check Row Switch Click
                    // Header is 25. Rows start at 25. Each row 20.
                    const rowIdx = Math.floor((relY - 25) / 20);
                    if (rowIdx >= 0 && rowIdx < bitCount) {
                        bitIndexToCheck = rowIdx;
                    }
                }

                if (bitIndexToCheck >= 0 && bitIndexToCheck < bitCount) {
                    toggledNodes = circuit.nodes.map(n => {
                        if (n.id === id) {
                            const newOutputs = [...n.outputs];
                            newOutputs[bitIndexToCheck] = !newOutputs[bitIndexToCheck];
                            return { ...n, outputs: newOutputs };
                        }
                        return n;
                    });
                }
            } else {
                // Standard single toggle
                toggledNodes = circuit.nodes.map(n => {
                    if (n.id === id) {
                        const newState = !n.outputs[0];
                        return { ...n, outputs: [newState] };
                    }
                    return n;
                });
            }
            onUpdateCircuit(toggledNodes, circuit.wires);
        } else {
            // Non-interactive: Allow selection to inspect properties
            setSelectedId(id);
        }
        return; // Prevents dragging in Interact mode
    }

    // 2. MOVE MODE: Allow dragging, ignore interactions.
    //    ALWAYS select on click to show settings.
    if (toolMode === 'select' || toolMode === 'junction') {
        setSelectedId(id);

        // Start dragging
        onCommit(); // Snapshot position before move
        setDraggingNodeId(id);
        const rect = containerRef.current!.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;
        setDragOffset({
            x: mouseX - node.position.x,
            y: mouseY - node.position.y
        });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    if (draggingNodeId) {
        const snapX = Math.round((x - dragOffset.x) / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round((y - dragOffset.y) / GRID_SIZE) * GRID_SIZE;

        const updatedNodes = circuit.nodes.map(n => {
            if (n.id === draggingNodeId) {
                return { ...n, position: { x: snapX, y: snapY }};
            }
            return n;
        });
        onUpdateCircuit(updatedNodes, circuit.wires);
    }
  };

  const handleMouseUp = () => {
    if (draggingNodeId) {
        setDraggingNodeId(null);
    }
    if (wiring) {
        setWiring(null);
    }
  };

  const startWiring = (e: React.MouseEvent, nodeId: string, outputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();
    if (toolMode === 'interact' && !isSimulating) return; 

    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setWiring({
        sourceNodeId: nodeId,
        sourceOutputIndex: outputIndex,
        startPoint: { x, y },
        active: true
    });
  };

  const completeWiring = (e: React.MouseEvent, targetNodeId: string, inputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();

    if (!wiring) return;

    if (wiring.sourceNodeId === targetNodeId) {
        setWiring(null);
        return;
    }

    onCommit(); // Snapshot before wiring change

    const exists = circuit.wires.some(w => 
        w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex
    );

    let newWires = exists 
        ? circuit.wires.filter(w => !(w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex))
        : [...circuit.wires];

    newWires.push({
        id: `wire-${Date.now()}`,
        sourceNodeId: wiring.sourceNodeId,
        sourceOutputIndex: wiring.sourceOutputIndex,
        targetNodeId: targetNodeId,
        targetInputIndex: inputIndex,
        state: false
    });

    onUpdateCircuit(circuit.nodes, newWires);
    setWiring(null);
  };

  const handleWireClick = (e: React.MouseEvent, wire: Wire, x: number, y: number) => {
    if (toolMode !== 'junction') {
        e.stopPropagation();
        setSelectedId(wire.id);
        return;
    }
    e.stopPropagation();

    onCommit(); // Snapshot before creating junction

    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;
    const junctionId = `node-${Date.now()}-junction`;

    const newJunction: NodeData = {
        id: junctionId,
        type: 'JUNCTION',
        position: { x: snapX - 5, y: snapY - 5 },
        inputs: [false],
        outputs: [false],
        properties: { label: '' }
    };

    const wire1: Wire = {
        id: `wire-${Date.now()}-1`,
        sourceNodeId: wire.sourceNodeId,
        sourceOutputIndex: wire.sourceOutputIndex,
        targetNodeId: junctionId,
        targetInputIndex: 0,
        state: wire.state
    };
    const wire2: Wire = {
        id: `wire-${Date.now()}-2`,
        sourceNodeId: junctionId,
        sourceOutputIndex: 0,
        targetNodeId: wire.targetNodeId,
        targetInputIndex: wire.targetInputIndex,
        state: wire.state
    };

    const newWires = circuit.wires.filter(w => w.id !== wire.id).concat([wire1, wire2]);
    const newNodes = [...circuit.nodes, newJunction];

    onUpdateCircuit(newNodes, newWires);
    setSelectedId(junctionId);
  };

  const handleCanvasClick = (e: React.MouseEvent) => {
      if (pendingComponent && containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        addNode(pendingComponent, x, y);
        setPendingComponent(null);
        return;
      }
      setSelectedId(null);
      if (validationResult?.valid) setValidationResult(null);
  };

  const getWirePath = (x1: number, y1: number, x2: number, y2: number) => {
    if (wireMode === 'bezier') {
        const dist = Math.abs(x2 - x1);
        const controlPointOffset = Math.max(dist * 0.5, 50);
        return `M ${x1} ${y1} C ${x1 + controlPointOffset} ${y1}, ${x2 - controlPointOffset} ${y2}, ${x2} ${y2}`;
    }
    const dx = x2 - x1;
    if (dx > 20) {
        const midX = (x1 + x2) / 2;
        return `M ${x1} ${y1} L ${midX} ${y1} L ${midX} ${y2} L ${x2} ${y2}`;
    }
    const stub = 20;
    const midY = (y1 + y2) / 2;
    return `M ${x1} ${y1} L ${x1 + stub} ${y1} L ${x1 + stub} ${midY} L ${x2 - stub} ${midY} L ${x2 - stub} ${y2} L ${x2} ${y2}`;
  };

  // Helper to determine label CSS class based on position
  const getLabelStyle = (pos: string | undefined): React.CSSProperties => {
      switch (pos) {
          case 'Bottom': return { top: '100%', left: '50%', transform: 'translate(-50%, 8px)' };
          case 'Left': return { top: '50%', right: '100%', transform: 'translate(-8px, -50%)' };
          case 'Right': return { top: '50%', left: '100%', transform: 'translate(8px, -50%)' };
          case 'Top': default: return { bottom: '100%', left: '50%', transform: 'translate(-50%, -8px)' };
      }
  };

  // Preview Logic
  const ghostSnapX = Math.round(mousePos.x / GRID_SIZE) * GRID_SIZE;
  const ghostSnapY = Math.round(mousePos.y / GRID_SIZE) * GRID_SIZE;
  const pendingDef = pendingComponent ? NODE_DEFINITIONS[pendingComponent] : null;

  return (
    <div 
        ref={containerRef}
        className={`flex-1 relative w-full h-full overflow-hidden bg-zinc-50 dark:bg-zinc-950
            ${isSimulating ? 'cursor-default' : pendingComponent ? 'cursor-cell' : toolMode === 'junction' ? 'cursor-crosshair' : 'cursor-crosshair'}`}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onClick={handleCanvasClick}
        onContextMenu={(e) => e.preventDefault()}
    >
        {/* Validation Messages Overlay */}
        {validationResult && (
            <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 pointer-events-none w-auto max-w-lg">
                <div className={`p-4 rounded-lg shadow-xl backdrop-blur-md border animate-in slide-in-from-top-4 duration-200
                    ${validationResult.valid ? 'bg-green-50/90 dark:bg-green-950/80 border-green-200 dark:border-green-800 text-green-800 dark:text-green-200' : 'bg-red-50/90 dark:bg-red-950/80 border-red-200 dark:border-red-800 text-red-800 dark:text-red-200'}`}
                >
                    <div className="flex items-start gap-3">
                        {validationResult.valid ? <CheckCircle2 size={20} className="mt-0.5 text-green-600 dark:text-green-400" /> : <AlertTriangle size={20} className="mt-0.5 text-red-600 dark:text-red-400" />}
                        <div>
                            <h4 className="font-bold text-sm mb-1">{validationResult.valid ? 'Circuit Valid' : 'Compatibility Issues Found'}</h4>
                            <ul className="text-xs space-y-1 list-disc list-inside opacity-90">
                                {validationResult.messages.map((m, i) => <li key={i}>{m}</li>)}
                            </ul>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* Grid Pattern */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full opacity-20 dark:opacity-20">
            <defs>
                <pattern id="grid" width={GRID_SIZE} height={GRID_SIZE} patternUnits="userSpaceOnUse">
                    <circle cx="1" cy="1" r="1" className="fill-zinc-400 dark:fill-zinc-500" />
                </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#grid)" />
        </svg>

        {/* Connections */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
            {circuit.wires.map(wire => {
                const sourceNode = circuit.nodes.find(n => n.id === wire.sourceNodeId);
                const targetNode = circuit.nodes.find(n => n.id === wire.targetNodeId);
                if (!sourceNode || !targetNode) return null;

                const sourcePorts = getOutputPorts(sourceNode);
                const targetPorts = getInputPorts(targetNode);

                const outputOffset = sourcePorts[wire.sourceOutputIndex] || { x: 0, y: 0 };
                const inputOffset = targetPorts[wire.targetInputIndex] || { x: 0, y: 0 };

                const startX = sourceNode.position.x + outputOffset.x;
                const startY = sourceNode.position.y + outputOffset.y;
                const endX = targetNode.position.x + inputOffset.x;
                const endY = targetNode.position.y + inputOffset.y;

                const isSelected = selectedId === wire.id;
                const pathData = getWirePath(startX, startY, endX, endY);

                return (
                    <g 
                        key={wire.id} 
                        onClick={(e) => { 
                            if (!containerRef.current) return;
                            const rect = containerRef.current.getBoundingClientRect();
                            handleWireClick(e, wire, e.clientX - rect.left, e.clientY - rect.top);
                        }} 
                        className={`pointer-events-auto cursor-pointer group`}
                    >
                        <path d={pathData} stroke="transparent" strokeWidth="16" fill="none" />
                        {wire.state && <path d={pathData} stroke="#22d3ee" strokeWidth="4" fill="none" opacity="0.3" filter="blur(2px)" />}
                        <path d={pathData} stroke={wire.state ? "#22d3ee" : (theme === 'dark' ? "#52525b" : "#a1a1aa")} strokeWidth={isSelected ? "3" : "2"} fill="none" className="transition-colors duration-150" strokeDasharray={isSelected ? "4" : "0"} strokeLinejoin="round" strokeLinecap="round" />
                    </g>
                );
            })}

            {wiring && (
                <path d={getWirePath(wiring.startPoint.x, wiring.startPoint.y, mousePos.x, mousePos.y)} stroke="#fbbf24" strokeWidth="2" fill="none" strokeDasharray="4" className="animate-pulse" strokeLinejoin="round" />
            )}
        </svg>

        {/* Nodes */}
        {circuit.nodes.map(node => {
            const { width, height } = getNodeDimensions(node);
            const isSelected = selectedId === node.id;
            const isInvalid = validationResult?.invalidNodeIds?.includes(node.id);
            const inputPorts = getInputPorts(node);
            const outputPorts = getOutputPorts(node);
            const def = NODE_DEFINITIONS[node.type];
            const canInteract = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

            // Determine Cursor Style
            let cursorClass = 'cursor-default';
            if (toolMode === 'interact' || isSimulating) {
                 cursorClass = canInteract ? 'cursor-pointer' : 'cursor-default';
            } else if (toolMode === 'select' || toolMode === 'junction') {
                 cursorClass = 'cursor-grab active:cursor-grabbing';
            }

            return (
                <div
                    key={node.id}
                    className={`absolute group select-none`}
                    style={{
                        left: node.position.x,
                        top: node.position.y,
                        width: width,
                        height: height,
                        pointerEvents: 'none',
                        zIndex: isSelected ? 50 : 10 
                    }}
                >
                    <div 
                        className={`absolute inset-0 pointer-events-auto transition-all duration-200 
                            ${isSelected ? 'drop-shadow-[0_0_8px_rgba(34,211,238,0.5)]' : ''} 
                            ${isInvalid ? 'drop-shadow-[0_0_8px_rgba(239,68,68,0.8)]' : ''}
                            ${cursorClass}
                        `}
                        onMouseDown={(e) => handleNodeMouseDown(e, node.id)}
                    >
                        <svg width={width} height={height} className="overflow-visible">
                            <GateShape node={node} />
                        </svg>
                    </div>

                    {isInvalid && (
                        <div className="absolute -top-3 -right-3 text-red-500 bg-white dark:bg-zinc-950 rounded-full p-0.5 shadow-md border border-red-200 dark:border-red-900 animate-bounce z-50">
                            <AlertTriangle size={14} fill="currentColor" className="text-red-100 dark:text-red-900" stroke="currentColor" />
                        </div>
                    )}

                    {inputPorts.map((offset, idx) => {
                        const isFloating = validationResult?.floatingInputs?.some(fi => fi.nodeId === node.id && fi.index === idx);

                        return (
                        <div
                            key={`input-${idx}`}
                            className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 
                            ${(toolMode === 'select' || toolMode === 'junction') && !isSimulating ? 'cursor-crosshair' : 'cursor-default'}`}
                            style={{ left: offset.x, top: offset.y }}
                            onMouseUp={(e) => !isSimulating && (toolMode === 'select' || toolMode === 'junction') && completeWiring(e, node.id, idx)}
                            title={offset.label || "Input"}
                        >
                            <div className={`w-2 h-2 rounded-full bg-white dark:bg-zinc-900 border transition-all duration-300 ${
                                isFloating 
                                ? 'border-red-500 bg-red-500/50 ring-2 ring-red-500 ring-opacity-50 animate-pulse' 
                                : node.inputs[idx] ? 'border-cyan-400 bg-cyan-100 dark:bg-cyan-900' : 'border-zinc-400 dark:border-zinc-500'
                            }`} />
                        </div>
                        );
                    })}

                    {outputPorts.map((offset, idx) => (
                        <div
                            key={`output-${idx}`}
                            className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 
                            ${(toolMode === 'select' || toolMode === 'junction') && !isSimulating ? 'cursor-crosshair' : 'cursor-default'}`}
                            style={{ left: offset.x, top: offset.y }}
                            onMouseDown={(e) => !isSimulating && (toolMode === 'select' || toolMode === 'junction') && startWiring(e, node.id, idx)}
                            title={offset.label || "Output"}
                        >
                            <div className={`w-2 h-2 rounded-full bg-white dark:bg-zinc-900 border ${node.outputs[idx] ? 'border-cyan-400 bg-cyan-500' : 'border-zinc-400 dark:border-zinc-500 group-hover:border-zinc-600 dark:group-hover:border-zinc-300'}`} />
                        </div>
                    ))}

                    {(isSelected || node.properties?.label) && node.type !== 'JUNCTION' && (
                        <div 
                            className="absolute bg-white/90 dark:bg-zinc-900/90 text-zinc-800 dark:text-zinc-100 text-[10px] px-2 py-0.5 rounded border border-zinc-200 dark:border-zinc-700 whitespace-nowrap shadow-md pointer-events-none backdrop-blur-sm z-[60]"
                            style={getLabelStyle(node.properties?.labelPosition)}
                        >
                            {node.properties?.label || def.name}
                        </div>
                    )}
                </div>
            );
        })}

        {/* Ghost Component */}
        {pendingComponent && pendingDef && (
            <div 
                className="absolute pointer-events-none opacity-50 z-50"
                style={{
                    left: ghostSnapX,
                    top: ghostSnapY,
                    width: pendingDef.width,
                    height: pendingDef.height
                }}
            >
                <svg width={pendingDef.width} height={pendingDef.height} className="overflow-visible">
                        <GateShape node={{ 
                        id: 'ghost', 
                        type: pendingComponent, 
                        position: {x: 0, y: 0}, 
                        inputs: Array(pendingDef.inputs).fill(false), 
                        outputs: Array(pendingDef.outputs).fill(false),
                        properties: { inputCount: pendingDef.inputs }
                    }} />
                </svg>
                <div className="absolute -top-6 left-0 bg-cyan-500 text-white text-[10px] px-2 py-0.5 rounded shadow-sm whitespace-nowrap">
                    Click to place
                </div>
            </div>
        )}
    </div>
  );
};

export type NodeType = 
  | 'AND' | 'OR' | 'NOT' | 'XOR' | 'NAND' | 'NOR' | 'XNOR' | 'BUFFER'
  | 'SWITCH' | 'BULB' | 'CLOCK' | 'BUTTON' | 'CONSTANT_1' | 'CONSTANT_0'
  | 'INPUT_2BIT' | 'INPUT_4BIT' | 'INPUT_8BIT' | 'INPUT_16BIT'
  | 'OUTPUT_2BIT' | 'OUTPUT_4BIT' | 'OUTPUT_8BIT' | 'OUTPUT_16BIT'
  | 'HALF_ADDER' | 'FULL_ADDER' | 'SUBTRACTOR' | 'COMPARATOR_1BIT'
  | 'D_LATCH' | 'D_FF' | 'JK_FF' | 'T_FF' | 'SR_FF'
  | 'GATED_SR_LATCH' | 'JK_MASTER_SLAVE' | 'RAM_1BIT' | 'ROM_1BIT' | 'SHIFT_REGISTER_4BIT'
  | 'RAM_4BIT' | 'RAM_8BIT' | 'RAM_16BIT'
  | 'MUX_2_1' | 'MUX_4_1' | 'DEMUX_1_2' | 'DEMUX_1_4'
  | 'DECODER_2_4' | 'PRIORITY_ENCODER_4_2'
  | 'HEX_DISPLAY' | 'SEVEN_SEGMENT'
  | 'JUNCTION';

export interface Point {
  x: number;
  y: number;
}

export interface Port {
  id: string;
  type: 'input' | 'output';
  offset: Point;
  label?: string;
}

export interface NodeData {
  id: string;
  type: NodeType;
  position: Point;
  inputs: boolean[];
  outputs: boolean[];
  // Used for stateful components like Flip-Flops to detect edges
  internalState?: {
    lastClock?: boolean;
    storedValue?: boolean;
    masterValue?: boolean; // For Master-Slave
    register?: boolean[]; // For Shift Register
    memory?: number[]; // For RAM arrays
    [key: string]: any;
  };
  // Customizable properties
  properties?: {
    label?: string;
    inputCount?: number;
    propagationDelay?: number;
    initialState?: boolean;
    romValue?: boolean; // For ROM
    [key: string]: any;
  };
}

export interface Wire {
  id: string;
  sourceNodeId: string;
  sourceOutputIndex: number;
  targetNodeId: string;
  targetInputIndex: number;
  state: boolean;
  color?: string; // Custom wire color
}

export interface CircuitState {
  nodes: NodeData[];
  wires: Wire[];
}

export interface WiringState {
  sourceNodeId: string;
  sourceOutputIndex: number;
  startPoint: Point;
  active: boolean;
}

import React, { useRef, useState, useEffect } from 'react';
import { GRID_SIZE, NODE_DEFINITIONS } from '../constants';
import { CircuitState, NodeData, NodeType, Wire, Point, WiringState } from '../types';
import { GateShape } from './GateShapes';
import { getNodeDimensions, getInputPorts, getOutputPorts } from '../utils/componentUtils';
import { CheckCircle2, AlertTriangle } from 'lucide-react';
import { useTheme } from './ThemeContext';

interface CircuitCanvasProps {
    circuit: CircuitState;
    onUpdateCircuit: (nodes: NodeData[], wires: Wire[]) => void;
    onCommit: () => void;
    selectedId: string | null;
    setSelectedId: (id: string | null) => void;
    pendingComponent: NodeType | null;
    setPendingComponent: (type: NodeType | null) => void;
    toolMode: 'select' | 'interact' | 'junction';
    wireMode: 'manhattan' | 'bezier';
    isSimulating: boolean;
    validationResult: {
        valid: boolean;
        messages: string[];
        invalidNodeIds: string[];
        floatingInputs: { nodeId: string; index: number }[];
    } | null;
    setValidationResult: (res: any) => void;
}

export const CircuitCanvas: React.FC<CircuitCanvasProps> = ({ 
    circuit, onUpdateCircuit, onCommit,
    selectedId, setSelectedId,
    pendingComponent, setPendingComponent,
    toolMode, wireMode, isSimulating,
    validationResult, setValidationResult
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const { theme } = useTheme();

  // Local Interaction State
  const [draggingNodeId, setDraggingNodeId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<Point>({ x: 0, y: 0 });
  const [wiring, setWiring] = useState<WiringState | null>(null);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });

  // --- Keyboard Shortcuts (Local Interactions) ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
            if (pendingComponent) setPendingComponent(null);
            if (wiring) setWiring(null);
            if (selectedId) setSelectedId(null);
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [pendingComponent, wiring, selectedId, setPendingComponent, setSelectedId]);


  const addNode = (type: NodeType, x: number, y: number) => {
    onCommit(); // Snapshot before adding
    const def = NODE_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newNode: NodeData = {
      id: `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      position: { x: snapX, y: snapY },
      inputs: Array(def.inputs).fill(false),
      outputs: Array(def.outputs).fill(false),
      internalState: {},
      properties: {
          label: '',
          labelPosition: 'Top',
          inputCount: def.inputs,
          propagationDelay: 0,
          initialState: false,
          romValue: false,
          interval: type === 'CLOCK' ? 20 : 0
      }
    };

    onUpdateCircuit([...circuit.nodes, newNode], circuit.wires);
    setSelectedId(newNode.id);
  };

  // --- Interaction Handlers ---

  const handleNodeMouseDown = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (wiring) return;
    if (pendingComponent) return; 

    const node = circuit.nodes.find(n => n.id === id);
    if (!node) return;

    const isInteractive = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

    // Strict Mode Separation

    // 1. INTERACT MODE: Only allow interactions for interactive components. 
    //    For non-interactive components, allow selection (to see state).
    if (toolMode === 'interact' || isSimulating) {
        if (isInteractive) {
            // Interactive: Toggle/Action only. DO NOT SELECT.
            if (!isSimulating) onCommit();

            let toggledNodes = circuit.nodes;

            // Special handling for Multi-bit inputs
            if (node.type.startsWith('INPUT_')) {
                const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
                const relY = e.clientY - rect.top; 
                const relX = e.clientX - rect.left;
                const { width, height } = getNodeDimensions(node);
                const bitCount = node.outputs.length;

                // Check Header Click (Direct Value Input)
                if (relY < 25) {
                    const inputVal = window.prompt(`Set Value for ${bitCount}-bit Input:\nUse decimal, hex (0x...), or binary (0b...)`);
                    if (inputVal !== null) {
                        let val = parseInt(inputVal);
                        if (inputVal.startsWith('0b')) val = parseInt(inputVal.slice(2), 2);
                        else if (inputVal.startsWith('0x')) val = parseInt(inputVal, 16);

                        if (!isNaN(val)) {
                            const newOutputs = [];
                            for(let i=0; i<bitCount; i++) {
                                newOutputs.push(!!((val >> i) & 1));
                            }
                            toggledNodes = circuit.nodes.map(n => n.id === id ? { ...n, outputs: newOutputs } : n);
                            onUpdateCircuit(toggledNodes, circuit.wires);
                        }
                    }
                    return;
                }

                let bitIndexToCheck = -1;

                // Check Footer (Binary) Click
                if (relY > height - 30) {
                    const bitWidth = 10;
                    const bitSpacing = 2;
                    const nibbleGap = 6;
                    const totalWidth = bitCount * bitWidth + (bitCount - 1) * bitSpacing + Math.floor((bitCount - 1) / 4) * nibbleGap;
                    const startX = (width - totalWidth) / 2 + bitWidth / 2;

                    for (let i = 0; i < bitCount; i++) {
                        const nibblesBefore = Math.floor(i / 4);
                        const xPos = startX + i * (bitWidth + bitSpacing) + nibblesBefore * nibbleGap;
                        if (Math.abs(relX - xPos) < 8) {
                            bitIndexToCheck = bitCount - 1 - i;
                            break;
                        }
                    }
                } else {
                    // Check Row Switch Click
                    // Header is 25. Rows start at 25. Each row 20.
                    const rowIdx = Math.floor((relY - 25) / 20);
                    if (rowIdx >= 0 && rowIdx < bitCount) {
                        bitIndexToCheck = rowIdx;
                    }
                }

                if (bitIndexToCheck >= 0 && bitIndexToCheck < bitCount) {
                    toggledNodes = circuit.nodes.map(n => {
                        if (n.id === id) {
                            const newOutputs = [...n.outputs];
                            newOutputs[bitIndexToCheck] = !newOutputs[bitIndexToCheck];
                            return { ...n, outputs: newOutputs };
                        }
                        return n;
                    });
                }
            } else {
                // Standard single toggle
                toggledNodes = circuit.nodes.map(n => {
                    if (n.id === id) {
                        const newState = !n.outputs[0];
                        return { ...n, outputs: [newState] };
                    }
                    return n;
                });
            }
            onUpdateCircuit(toggledNodes, circuit.wires);
        } else {
            // Non-interactive: Allow selection to inspect properties
            setSelectedId(id);
        }
        return; // Prevents dragging in Interact mode
    }

    // 2. MOVE MODE: Allow dragging, ignore interactions.
    //    ALWAYS select on click to show settings.
    if (toolMode === 'select' || toolMode === 'junction') {
        setSelectedId(id);

        // Start dragging
        onCommit(); // Snapshot position before move
        setDraggingNodeId(id);
        const rect = containerRef.current!.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;
        setDragOffset({
            x: mouseX - node.position.x,
            y: mouseY - node.position.y
        });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    if (draggingNodeId) {
        const snapX = Math.round((x - dragOffset.x) / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round((y - dragOffset.y) / GRID_SIZE) * GRID_SIZE;

        const updatedNodes = circuit.nodes.map(n => {
            if (n.id === draggingNodeId) {
                return { ...n, position: { x: snapX, y: snapY }};
            }
            return n;
        });
        onUpdateCircuit(updatedNodes, circuit.wires);
    }
  };

  const handleMouseUp = () => {
    if (draggingNodeId) {
        setDraggingNodeId(null);
    }
    if (wiring) {
        setWiring(null);
    }
  };

  const startWiring = (e: React.MouseEvent, nodeId: string, outputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();
    if (toolMode === 'interact' && !isSimulating) return; 

    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setWiring({
        sourceNodeId: nodeId,
        sourceOutputIndex: outputIndex,
        startPoint: { x, y },
        active: true
    });
  };

  const completeWiring = (e: React.MouseEvent, targetNodeId: string, inputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();

    if (!wiring) return;

    if (wiring.sourceNodeId === targetNodeId) {
        setWiring(null);
        return;
    }

    onCommit(); // Snapshot before wiring change

    const exists = circuit.wires.some(w => 
        w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex
    );

    let newWires = exists 
        ? circuit.wires.filter(w => !(w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex))
        : [...circuit.wires];

    newWires.push({
        id: `wire-${Date.now()}`,
        sourceNodeId: wiring.sourceNodeId,
        sourceOutputIndex: wiring.sourceOutputIndex,
        targetNodeId: targetNodeId,
        targetInputIndex: inputIndex,
        state: false
    });

    onUpdateCircuit(circuit.nodes, newWires);
    setWiring(null);
  };

  const handleWireClick = (e: React.MouseEvent, wire: Wire, x: number, y: number) => {
    if (toolMode !== 'junction') {
        e.stopPropagation();
        setSelectedId(wire.id);
        return;
    }
    e.stopPropagation();

    onCommit(); // Snapshot before creating junction

    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;
    const junctionId = `node-${Date.now()}-junction`;

    const newJunction: NodeData = {
        id: junctionId,
        type: 'JUNCTION',
        position: { x: snapX - 5, y: snapY - 5 },
        inputs: [false],
        outputs: [false],
        properties: { label: '' }
    };

    const wire1: Wire = {
        id: `wire-${Date.now()}-1`,
        sourceNodeId: wire.sourceNodeId,
        sourceOutputIndex: wire.sourceOutputIndex,
        targetNodeId: junctionId,
        targetInputIndex: 0,
        state: wire.state
    };
    const wire2: Wire = {
        id: `wire-${Date.now()}-2`,
        sourceNodeId: junctionId,
        sourceOutputIndex: 0,
        targetNodeId: wire.targetNodeId,
        targetInputIndex: wire.targetInputIndex,
        state: wire.state
    };

    const newWires = circuit.wires.filter(w => w.id !== wire.id).concat([wire1, wire2]);
    const newNodes = [...circuit.nodes, newJunction];

    onUpdateCircuit(newNodes, newWires);
    setSelectedId(junctionId);
  };

  const handleCanvasClick = (e: React.MouseEvent) => {
      if (pendingComponent && containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        addNode(pendingComponent, x, y);
        setPendingComponent(null);
        return;
      }
      setSelectedId(null);
      if (validationResult?.valid) setValidationResult(null);
  };

  const getWirePath = (x1: number, y1: number, x2: number, y2: number) => {
    if (wireMode === 'bezier') {
        const dist = Math.abs(x2 - x1);
        const controlPointOffset = Math.max(dist * 0.5, 50);
        return `M ${x1} ${y1} C ${x1 + controlPointOffset} ${y1}, ${x2 - controlPointOffset} ${y2}, ${x2} ${y2}`;
    }
    const dx = x2 - x1;
    if (dx > 20) {
        const midX = (x1 + x2) / 2;
        return `M ${x1} ${y1} L ${midX} ${y1} L ${midX} ${y2} L ${x2} ${y2}`;
    }
    const stub = 20;
    const midY = (y1 + y2) / 2;
    return `M ${x1} ${y1} L ${x1 + stub} ${y1} L ${x1 + stub} ${midY} L ${x2 - stub} ${midY} L ${x2 - stub} ${y2} L ${x2} ${y2}`;
  };

  // Helper to determine label CSS class based on position
  const getLabelStyle = (pos: string | undefined): React.CSSProperties => {
      switch (pos) {
          case 'Bottom': return { top: '100%', left: '50%', transform: 'translate(-50%, 8px)' };
          case 'Left': return { top: '50%', right: '100%', transform: 'translate(-8px, -50%)' };
          case 'Right': return { top: '50%', left: '100%', transform: 'translate(8px, -50%)' };
          case 'Top': default: return { bottom: '100%', left: '50%', transform: 'translate(-50%, -8px)' };
      }
  };

  // Preview Logic
  const ghostSnapX = Math.round(mousePos.x / GRID_SIZE) * GRID_SIZE;
  const ghostSnapY = Math.round(mousePos.y / GRID_SIZE) * GRID_SIZE;
  const pendingDef = pendingComponent ? NODE_DEFINITIONS[pendingComponent] : null;

  return (
    <div 
        ref={containerRef}
        className={`flex-1 relative w-full h-full overflow-hidden bg-zinc-50 dark:bg-zinc-950
            ${isSimulating ? 'cursor-default' : pendingComponent ? 'cursor-cell' : toolMode === 'junction' ? 'cursor-crosshair' : 'cursor-crosshair'}`}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onClick={handleCanvasClick}
        onContextMenu={(e) => e.preventDefault()}
    >
        {/* Validation Messages Overlay */}
        {validationResult && (
            <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 pointer-events-none w-auto max-w-lg">
                <div className={`p-4 rounded-lg shadow-xl backdrop-blur-md border animate-in slide-in-from-top-4 duration-200
                    ${validationResult.valid ? 'bg-green-50/90 dark:bg-green-950/80 border-green-200 dark:border-green-800 text-green-800 dark:text-green-200' : 'bg-red-50/90 dark:bg-red-950/80 border-red-200 dark:border-red-800 text-red-800 dark:text-red-200'}`}
                >
                    <div className="flex items-start gap-3">
                        {validationResult.valid ? <CheckCircle2 size={20} className="mt-0.5 text-green-600 dark:text-green-400" /> : <AlertTriangle size={20} className="mt-0.5 text-red-600 dark:text-red-400" />}
                        <div>
                            <h4 className="font-bold text-sm mb-1">{validationResult.valid ? 'Circuit Valid' : 'Compatibility Issues Found'}</h4>
                            <ul className="text-xs space-y-1 list-disc list-inside opacity-90">
                                {validationResult.messages.map((m, i) => <li key={i}>{m}</li>)}
                            </ul>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* Grid Pattern */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full opacity-20 dark:opacity-20">
            <defs>
                <pattern id="grid" width={GRID_SIZE} height={GRID_SIZE} patternUnits="userSpaceOnUse">
                    <circle cx="1" cy="1" r="1" className="fill-zinc-400 dark:fill-zinc-500" />
                </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#grid)" />
        </svg>

        {/* Connections */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
            {circuit.wires.map(wire => {
                const sourceNode = circuit.nodes.find(n => n.id === wire.sourceNodeId);
                const targetNode = circuit.nodes.find(n => n.id === wire.targetNodeId);
                if (!sourceNode || !targetNode) return null;

                const sourcePorts = getOutputPorts(sourceNode);
                const targetPorts = getInputPorts(targetNode);

                const outputOffset = sourcePorts[wire.sourceOutputIndex] || { x: 0, y: 0 };
                const inputOffset = targetPorts[wire.targetInputIndex] || { x: 0, y: 0 };

                const startX = sourceNode.position.x + outputOffset.x;
                const startY = sourceNode.position.y + outputOffset.y;
                const endX = targetNode.position.x + inputOffset.x;
                const endY = targetNode.position.y + inputOffset.y;

                const isSelected = selectedId === wire.id;
                const pathData = getWirePath(startX, startY, endX, endY);

                // Color Logic: If active, standard Cyan. If inactive, use Custom Color or Fallback.
                const inactiveColor = wire.color || (theme === 'dark' ? "#52525b" : "#a1a1aa");
                const activeColor = "#22d3ee";
                const strokeColor = wire.state ? activeColor : inactiveColor;

                return (
                    <g 
                        key={wire.id} 
                        onClick={(e) => { 
                            if (!containerRef.current) return;
                            const rect = containerRef.current.getBoundingClientRect();
                            handleWireClick(e, wire, e.clientX - rect.left, e.clientY - rect.top);
                        }} 
                        className={`pointer-events-auto cursor-pointer group`}
                    >
                        <path d={pathData} stroke="transparent" strokeWidth="16" fill="none" />
                        {wire.state && <path d={pathData} stroke={activeColor} strokeWidth="4" fill="none" opacity="0.3" filter="blur(2px)" />}
                        <path d={pathData} stroke={strokeColor} strokeWidth={isSelected ? "3" : "2"} fill="none" className="transition-colors duration-150" strokeDasharray={isSelected ? "4" : "0"} strokeLinejoin="round" strokeLinecap="round" />
                    </g>
                );
            })}

            {wiring && (
                <path d={getWirePath(wiring.startPoint.x, wiring.startPoint.y, mousePos.x, mousePos.y)} stroke="#fbbf24" strokeWidth="2" fill="none" strokeDasharray="4" className="animate-pulse" strokeLinejoin="round" />
            )}
        </svg>

        {/* Nodes */}
        {circuit.nodes.map(node => {
            const { width, height } = getNodeDimensions(node);
            const isSelected = selectedId === node.id;
            const isInvalid = validationResult?.invalidNodeIds?.includes(node.id);
            const inputPorts = getInputPorts(node);
            const outputPorts = getOutputPorts(node);
            const def = NODE_DEFINITIONS[node.type];
            const canInteract = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

            // Determine Cursor Style
            let cursorClass = 'cursor-default';
            if (toolMode === 'interact' || isSimulating) {
                 cursorClass = canInteract ? 'cursor-pointer' : 'cursor-default';
            } else if (toolMode === 'select' || toolMode === 'junction') {
                 cursorClass = 'cursor-grab active:cursor-grabbing';
            }

            return (
                <div
                    key={node.id}
                    className={`absolute group select-none`}
                    style={{
                        left: node.position.x,
                        top: node.position.y,
                        width: width,
                        height: height,
                        pointerEvents: 'none',
                        zIndex: isSelected ? 50 : 10 
                    }}
                >
                    <div 
                        className={`absolute inset-0 pointer-events-auto transition-all duration-200 
                            ${isSelected ? 'drop-shadow-[0_0_8px_rgba(34,211,238,0.5)]' : ''} 
                            ${isInvalid ? 'drop-shadow-[0_0_8px_rgba(239,68,68,0.8)]' : ''}
                            ${cursorClass}
                        `}
                        onMouseDown={(e) => handleNodeMouseDown(e, node.id)}
                    >
                        <svg width={width} height={height} className="overflow-visible">
                            <GateShape node={node} />
                        </svg>
                    </div>

                    {isInvalid && (
                        <div className="absolute -top-3 -right-3 text-red-500 bg-white dark:bg-zinc-950 rounded-full p-0.5 shadow-md border border-red-200 dark:border-red-900 animate-bounce z-50">
                            <AlertTriangle size={14} fill="currentColor" className="text-red-100 dark:text-red-900" stroke="currentColor" />
                        </div>
                    )}

                    {inputPorts.map((offset, idx) => {
                        const isFloating = validationResult?.floatingInputs?.some(fi => fi.nodeId === node.id && fi.index === idx);

                        return (
                        <div
                            key={`input-${idx}`}
                            className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 
                            ${(toolMode === 'select' || toolMode === 'junction') && !isSimulating ? 'cursor-crosshair' : 'cursor-default'}`}
                            style={{ left: offset.x, top: offset.y }}
                            onMouseUp={(e) => !isSimulating && (toolMode === 'select' || toolMode === 'junction') && completeWiring(e, node.id, idx)}
                            title={offset.label || "Input"}
                        >
                            <div className={`w-2 h-2 rounded-full bg-white dark:bg-zinc-900 border transition-all duration-300 ${
                                isFloating 
                                ? 'border-red-500 bg-red-500/50 ring-2 ring-red-500 ring-opacity-50 animate-pulse' 
                                : node.inputs[idx] ? 'border-cyan-400 bg-cyan-100 dark:bg-cyan-900' : 'border-zinc-400 dark:border-zinc-500'
                            }`} />
                        </div>
                        );
                    })}

                    {outputPorts.map((offset, idx) => (
                        <div
                            key={`output-${idx}`}
                            className={`absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 
                            ${(toolMode === 'select' || toolMode === 'junction') && !isSimulating ? 'cursor-crosshair' : 'cursor-default'}`}
                            style={{ left: offset.x, top: offset.y }}
                            onMouseDown={(e) => !isSimulating && (toolMode === 'select' || toolMode === 'junction') && startWiring(e, node.id, idx)}
                            title={offset.label || "Output"}
                        >
                            <div className={`w-2 h-2 rounded-full bg-white dark:bg-zinc-900 border ${node.outputs[idx] ? 'border-cyan-400 bg-cyan-500' : 'border-zinc-400 dark:border-zinc-500 group-hover:border-zinc-600 dark:group-hover:border-zinc-300'}`} />
                        </div>
                    ))}

                    {(isSelected || node.properties?.label) && node.type !== 'JUNCTION' && (
                        <div 
                            className="absolute bg-white/90 dark:bg-zinc-900/90 text-zinc-800 dark:text-zinc-100 text-[10px] px-2 py-0.5 rounded border border-zinc-200 dark:border-zinc-700 whitespace-nowrap shadow-md pointer-events-none backdrop-blur-sm z-[60]"
                            style={getLabelStyle(node.properties?.labelPosition)}
                        >
                            {node.properties?.label || def.name}
                        </div>
                    )}
                </div>
            );
        })}

        {/* Ghost Component */}
        {pendingComponent && pendingDef && (
            <div 
                className="absolute pointer-events-none opacity-50 z-50"
                style={{
                    left: ghostSnapX,
                    top: ghostSnapY,
                    width: pendingDef.width,
                    height: pendingDef.height
                }}
            >
                <svg width={pendingDef.width} height={pendingDef.height} className="overflow-visible">
                        <GateShape node={{ 
                        id: 'ghost', 
                        type: pendingComponent, 
                        position: {x: 0, y: 0}, 
                        inputs: Array(pendingDef.inputs).fill(false), 
                        outputs: Array(pendingDef.outputs).fill(false),
                        properties: { inputCount: pendingDef.inputs }
                    }} />
                </svg>
                <div className="absolute -top-6 left-0 bg-cyan-500 text-white text-[10px] px-2 py-0.5 rounded shadow-sm whitespace-nowrap">
                    Click to place
                </div>
            </div>
        )}
    </div>
  );
};

import React from 'react';
import { NodeData, NodeType, Wire } from '../types';
import { Settings2, Hash, Type, Palette, Activity, Clock, AlignCenterVertical, MousePointerClick, Binary, Cable } from 'lucide-react';
import { VARIABLE_INPUT_GATES } from '../utils/componentUtils';

interface PropertiesPanelProps {
  node: NodeData | null;
  wire: Wire | null;
  onUpdate: (id: string, updates: Partial<NodeData>) => void;
  onUpdateWire: (id: string, updates: Partial<Wire>) => void;
  width: number;
}

export const PropertiesPanel: React.FC<PropertiesPanelProps> = ({ node, wire, onUpdate, onUpdateWire, width }) => {
  if (!node && !wire) {
    return (
      <div 
        style={{ width }}
        className="bg-white dark:bg-zinc-900 border-l border-zinc-200 dark:border-zinc-800 p-6 flex flex-col items-center justify-center text-zinc-400 dark:text-zinc-500 h-full select-none transition-colors duration-300 flex-shrink-0"
      >
         <Settings2 size={32} className="mb-3 opacity-50" />
         <p className="text-sm font-medium">No Selection</p>
         <p className="text-xs text-zinc-500 dark:text-zinc-600 text-center mt-1">Select a component to edit its attributes.</p>
      </div>
    );
  }

  // --- Helpers ---
  const renderRow = (label: string, icon: React.ReactNode, control: React.ReactNode) => (
      <div className="flex items-center justify-between py-2 border-b border-zinc-100 dark:border-zinc-800/50 last:border-0">
          <div className="flex items-center gap-2 text-zinc-600 dark:text-zinc-400">
              {icon}
              <span className="text-xs font-medium">{label}</span>
          </div>
          <div className="w-1/2 flex justify-end">
              {control}
          </div>
      </div>
  );

  // --- WIRE RENDERER ---
  if (wire) {
      return (
        <div 
            style={{ width }}
            className="bg-white dark:bg-zinc-900 border-l border-zinc-200 dark:border-zinc-800 flex flex-col h-full shadow-xl transition-colors duration-300 flex-shrink-0"
        >
           <div className="h-14 flex items-center px-4 border-b border-zinc-200 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50">
              <div className="flex items-center gap-2">
                 <Cable size={16} className="text-cyan-600 dark:text-cyan-400" />
                 <span className="font-semibold text-sm text-zinc-800 dark:text-zinc-200">Wire Attributes</span>
              </div>
           </div>

           <div className="flex-1 overflow-y-auto p-4">
              <div className="mb-6">
                  <h3 className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider mb-2">Appearance</h3>
                  <div className="bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-lg px-3 shadow-sm">
                      {renderRow(
                          "Color (Inactive)", 
                          <Palette size={14} />, 
                          <div className="flex items-center gap-2">
                            <input 
                                type="color" 
                                value={wire.color || '#52525b'} 
                                onChange={(e) => onUpdateWire(wire.id, { color: e.target.value })}
                                className="w-5 h-5 rounded cursor-pointer border-0 p-0 bg-transparent"
                            />
                            <span className="text-[10px] font-mono text-zinc-400">{wire.color || 'Default'}</span>
                          </div>
                      )}
                  </div>
              </div>

              <div className="mb-6">
                  <h3 className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider mb-2">Status</h3>
                  <div className="bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-lg px-3 shadow-sm">
                        {renderRow(
                            "Signal State",
                            <Activity size={14} />,
                            <span className={`text-xs font-bold ${wire.state ? 'text-cyan-500' : 'text-zinc-500'}`}>
                                {wire.state ? 'HIGH (1)' : 'LOW (0)'}
                            </span>
                        )}
                  </div>
              </div>

              <div className="text-xs text-zinc-400 dark:text-zinc-600 italic text-center mt-8">
                 ID: {wire.id.split('-')[1]}...
              </div>
           </div>
        </div>
      );
  }

  // --- COMPONENT RENDERER ---
  const isGate = VARIABLE_INPUT_GATES.includes(node!.type) || ['BUFFER', 'NOT'].includes(node!.type);
  const isStateful = ['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'D_LATCH', 'JK_MASTER_SLAVE', 'SHIFT_REGISTER_4BIT'].includes(node!.type);
  const isSwitch = ['SWITCH'].includes(node!.type);
  const isClock = node!.type === 'CLOCK';
  const isROM = node!.type === 'ROM_1BIT';
  const isEdgeTriggered = ['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'SHIFT_REGISTER_4BIT'].includes(node!.type);

  const isMultiBitInput = node!.type.startsWith('INPUT_') && node!.type.includes('BIT');
  const isMultiBitOutput = node!.type.startsWith('OUTPUT_') && node!.type.includes('BIT');
  const isMultiBit = isMultiBitInput || isMultiBitOutput;

  // --- Helpers for Node ---
  const getMultiBitValue = (bools: boolean[]) => {
      return bools.reduce((acc, b, i) => acc + (b ? Math.pow(2, i) : 0), 0);
  };

  const boolsToBinStr = (bools: boolean[]) => {
      // MSB at left (highest index), LSB at right (index 0)
      return bools.map(b => b ? '1' : '0').reverse().join('');
  }

  const updateMultiBitValue = (val: number, bitCount: number) => {
      const newOutputs = [];
      for(let i=0; i<bitCount; i++) {
          newOutputs.push(!!((val >> i) & 1));
      }
      onUpdate(node!.id, { outputs: newOutputs });
  };

  const updateProp = (key: string, value: any) => {
      onUpdate(node!.id, { properties: { ...node!.properties, [key]: value } });
  };

  const handleBitWidthChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      const width = parseInt(e.target.value);
      let newType = node!.type;
      if (isMultiBitInput) newType = `INPUT_${width}BIT` as NodeType;
      else if (isMultiBitOutput) newType = `OUTPUT_${width}BIT` as NodeType;

      if (newType !== node!.type) {
          onUpdate(node!.id, { type: newType });
      }
  };

  const getBitWidth = (type: NodeType) => {
      if (type.includes('2BIT')) return 2;
      if (type.includes('4BIT')) return 4;
      if (type.includes('8BIT')) return 8;
      if (type.includes('16BIT')) return 16;
      return 0;
  };

  return (
    <div 
        style={{ width }}
        className="bg-white dark:bg-zinc-900 border-l border-zinc-200 dark:border-zinc-800 flex flex-col h-full shadow-xl transition-colors duration-300 flex-shrink-0"
    >
       <div className="h-14 flex items-center px-4 border-b border-zinc-200 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50">
          <div className="flex items-center gap-2">
             <Settings2 size={16} className="text-cyan-600 dark:text-cyan-400" />
             <span className="font-semibold text-sm text-zinc-800 dark:text-zinc-200">Attributes</span>
          </div>
          <div className="ml-auto text-[10px] font-mono text-zinc-400 bg-zinc-100 dark:bg-zinc-800 px-2 py-0.5 rounded">
              {node!.type}
          </div>
       </div>

       <div className="flex-1 overflow-y-auto p-4">

          {/* Group: Common */}
          <div className="mb-6">
              <h3 className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider mb-2">Common</h3>
              <div className="bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-lg px-3 shadow-sm">
                  {renderRow(
                      "Label", 
                      <Type size={14} />, 
                      <input 
                          type="text" 
                          value={node!.properties?.label || ''} 
                          onChange={(e) => updateProp('label', e.target.value)}
                          className="w-full bg-transparent text-right text-xs focus:outline-none text-zinc-800 dark:text-zinc-200 placeholder-zinc-400"
                          placeholder="Name"
                      />
                  )}
                  {renderRow(
                      "Label Position", 
                      <AlignCenterVertical size={14} />, 
                      <select 
                          value={node!.properties?.labelPosition || 'Top'}
                          onChange={(e) => updateProp('labelPosition', e.target.value)}
                          className="bg-transparent text-right text-xs focus:outline-none text-zinc-800 dark:text-zinc-200 cursor-pointer"
                      >
                          <option value="Top">Top</option>
                          <option value="Bottom">Bottom</option>
                          <option value="Left">Left</option>
                          <option value="Right">Right</option>
                      </select>
                  )}
                   {renderRow(
                      "Color", 
                      <Palette size={14} />, 
                      <div className="flex items-center gap-2">
                        <input 
                            type="color" 
                            value={node!.properties?.color || '#18181b'} 
                            onChange={(e) => updateProp('color', e.target.value)}
                            className="w-5 h-5 rounded cursor-pointer border-0 p-0 bg-transparent"
                        />
                        <span className="text-[10px] font-mono text-zinc-400">{node!.properties?.color || 'Default'}</span>
                      </div>
                  )}
              </div>
          </div>

          {/* Group: Value (For Multi-bit) */}
          {isMultiBitInput && (
              <div className="mb-6">
                  <h3 className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider mb-2">Value</h3>
                  <div className="bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-lg px-3 shadow-sm">
                        {renderRow(
                            "Decimal",
                            <Hash size={14} />,
                            <input
                                type="number"
                                min="0"
                                max={Math.pow(2, node!.outputs.length) - 1}
                                value={getMultiBitValue(node!.outputs)}
                                onChange={(e) => {
                                    const val = parseInt(e.target.value);
                                    if (!isNaN(val)) updateMultiBitValue(val, node!.outputs.length);
                                }}
                                className="w-full bg-transparent text-right text-xs focus:outline-none text-zinc-800 dark:text-zinc-200 font-mono"
                            />
                        )}
                         {renderRow(
                            "Binary",
                            <Binary size={14} />,
                            <span className="text-[10px] font-mono text-zinc-500">{boolsToBinStr(node!.outputs)}</span>
                        )}
                  </div>
              </div>
          )}

           {isMultiBitOutput && (
              <div className="mb-6">
                  <h3 className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider mb-2">State</h3>
                  <div className="bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-lg px-3 shadow-sm">
                        {renderRow(
                            "Decimal",
                            <Hash size={14} />,
                            <span className="text-xs font-mono text-zinc-800 dark:text-zinc-200">{getMultiBitValue(node!.inputs)}</span>
                        )}
                        {renderRow(
                            "Hex",
                            <Hash size={14} />,
                            <span className="text-xs font-mono text-cyan-600 dark:text-cyan-400">0x{getMultiBitValue(node!.inputs).toString(16).toUpperCase()}</span>
                        )}
                         {renderRow(
                            "Binary",
                            <Binary size={14} />,
                            <span className="text-[10px] font-mono text-zinc-500 truncate max-w-[100px] text-right block" title={boolsToBinStr(node!.inputs)}>{boolsToBinStr(node!.inputs)}</span>
                        )}
                  </div>
              </div>
          )}

          {/* Group: Simulation */}
          <div className="mb-6">
              <h3 className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider mb-2">Simulation</h3>
              <div className="bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-lg px-3 shadow-sm">

                  {VARIABLE_INPUT_GATES.includes(node!.type) && renderRow(
                      "Input Count", 
                      <Hash size={14} />, 
                      <select 
                          value={node!.properties?.inputCount || 2}
                          onChange={(e) => updateProp('inputCount', parseInt(e.target.value))}
                          className="bg-transparent text-right text-xs focus:outline-none text-zinc-800 dark:text-zinc-200"
                      >
                          {[2,3,4,5,6,8].map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                  )}

                  {isMultiBit && renderRow(
                      "Data Bits", 
                      <Hash size={14} />, 
                      <select 
                          value={getBitWidth(node!.type)}
                          onChange={handleBitWidthChange}
                          className="bg-transparent text-right text-xs focus:outline-none text-zinc-800 dark:text-zinc-200"
                      >
                          {[2,4,8,16].map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                  )}

                  {isGate && renderRow(
                      "Delay (ms)", 
                      <Activity size={14} />, 
                      <input 
                          type="number"
                          min="0"
                          value={node!.properties?.propagationDelay || 0}
                          onChange={(e) => updateProp('propagationDelay', parseInt(e.target.value) || 0)}
                          className="w-16 bg-transparent text-right text-xs focus:outline-none text-zinc-800 dark:text-zinc-200"
                      />
                  )}

                  {(isStateful || isSwitch) && renderRow(
                      "Initial State", 
                      <MousePointerClick size={14} />, 
                      <input 
                          type="checkbox"
                          checked={!!node!.properties?.initialState}
                          onChange={(e) => updateProp('initialState', e.target.checked)}
                          className="rounded border-zinc-300 text-cyan-500 focus:ring-0"
                      />
                  )}

                  {isEdgeTriggered && renderRow(
                      "Trigger", 
                      <Activity size={14} />, 
                      <select 
                          value={node!.properties?.trigger || 'Rising'}
                          onChange={(e) => updateProp('trigger', e.target.value)}
                          className="bg-transparent text-right text-xs focus:outline-none text-zinc-800 dark:text-zinc-200"
                      >
                          <option value="Rising">Rising Edge</option>
                          <option value="Falling">Falling Edge</option>
                      </select>
                  )}

                  {isROM && renderRow(
                      "ROM Value", 
                      <Hash size={14} />, 
                      <input 
                          type="checkbox"
                          checked={!!node!.properties?.romValue}
                          onChange={(e) => updateProp('romValue', e.target.checked)}
                          className="rounded border-zinc-300 text-cyan-500 focus:ring-0"
                      />
                  )}

                   {isClock && renderRow(
                      "Interval (Ticks)", 
                      <Clock size={14} />, 
                      <input 
                          type="number"
                          min="1"
                          max="100"
                          value={node!.properties?.interval || 20}
                          onChange={(e) => updateProp('interval', Math.max(1, parseInt(e.target.value)))}
                          className="w-16 bg-transparent text-right text-xs focus:outline-none text-zinc-800 dark:text-zinc-200"
                      />
                  )}
              </div>
          </div>

          <div className="text-xs text-zinc-400 dark:text-zinc-600 italic text-center mt-8">
             ID: {node!.id.split('-')[1]}...
          </div>

       </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { CircuitCanvas } from './components/CircuitCanvas';
import { Header } from './components/Header';
import { PropertiesPanel } from './components/PropertiesPanel';
import { ThemeProvider, useTheme } from './components/ThemeContext';
import { CircuitState, NodeData, NodeType, Wire } from './types';
import { evaluateCircuit } from './utils/circuitLogic';
import { NODE_DEFINITIONS } from './constants';

const MAX_HISTORY = 50;

const AppContent: React.FC = () => {
  const { theme, toggleTheme } = useTheme();

  // -- Global Application State --
  const [circuit, setCircuit] = useState<CircuitState>({ nodes: [], wires: [] });
  // Edit History
  const [past, setPast] = useState<CircuitState[]>([]);
  const [future, setFuture] = useState<CircuitState[]>([]);
  // Simulation History (Running Buffer)
  const [simHistory, setSimHistory] = useState<CircuitState[]>([]);

  const [pendingComponent, setPendingComponent] = useState<NodeType | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  // -- Interaction Modes --
  const [toolMode, setToolMode] = useState<'select' | 'interact' | 'junction'>('select');
  const [wireMode, setWireMode] = useState<'manhattan' | 'bezier'>('manhattan');

  // -- Simulation State --
  const [isSimulating, setIsSimulating] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  // -- UI Layout State --
  const [sidebarWidth, setSidebarWidth] = useState(260);
  const [panelWidth, setPanelWidth] = useState(260);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);
  const [isResizingPanel, setIsResizingPanel] = useState(false);

  // -- Validation State --
  const [validationResult, setValidationResult] = useState<{
      valid: boolean; 
      messages: string[]; 
      invalidNodeIds: string[];
      floatingInputs: { nodeId: string; index: number }[];
  } | null>(null);

  // --------------------------------------------------------------------------
  // History Management (Undo/Redo)
  // --------------------------------------------------------------------------

  // Save current state to history. Should be called BEFORE a destructive action.
  const snapshot = useCallback(() => {
    setPast(prev => {
        // Dedup: Don't push if identical to last state (simple reference/string check)
        const last = prev[prev.length - 1];
        if (last && JSON.stringify(last) === JSON.stringify(circuit)) return prev;

        const newPast = [...prev, circuit];
        if (newPast.length > MAX_HISTORY) return newPast.slice(newPast.length - MAX_HISTORY);
        return newPast;
    });
    setFuture([]);
  }, [circuit]);

  const undo = useCallback(() => {
      if (past.length === 0) return;
      const previous = past[past.length - 1];
      const newPast = past.slice(0, -1);

      setFuture(prev => [circuit, ...prev]);
      setPast(newPast);
      setCircuit(previous);
      // Stop sim if undoing edits
      if (isSimulating) {
        setIsSimulating(false);
        setSimHistory([]);
      }
      setValidationResult(null);
  }, [past, circuit, isSimulating]);

  const redo = useCallback(() => {
      if (future.length === 0) return;
      const next = future[0];
      const newFuture = future.slice(1);

      setPast(prev => [...prev, circuit]);
      setFuture(newFuture);
      setCircuit(next);
      if (isSimulating) {
        setIsSimulating(false);
        setSimHistory([]);
      }
      setValidationResult(null);
  }, [future, circuit, isSimulating]);

  // Keyboard Shortcuts for Undo/Redo
  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if ((e.metaKey || e.ctrlKey) && e.key === 'z') {
              e.preventDefault();
              undo();
          }
          if ((e.metaKey || e.ctrlKey) && e.key === 'y') {
              e.preventDefault();
              redo();
          }
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [undo, redo]);

  // --------------------------------------------------------------------------
  // Simulation Logic
  // --------------------------------------------------------------------------
  const tick = useCallback(() => {
    setCircuit(prev => {
        // Save history before tick for stepping back in simulation
        setSimHistory(h => {
            const newHistory = [...h, prev];
            if (newHistory.length > MAX_HISTORY) return newHistory.slice(1);
            return newHistory;
        });

        const hasClock = prev.nodes.some(n => n.type === 'CLOCK');
        let nextNodes = [...prev.nodes];

        // Update Clocks
        if (hasClock) {
            nextNodes = nextNodes.map(n => {
                if (n.type === 'CLOCK') {
                    const speed = n.properties?.interval || 20; 
                    const currentCount = (n.internalState?.tickCount || 0) + 1;

                    if (currentCount >= speed) {
                         return { 
                             ...n, 
                             outputs: [!n.outputs[0]],
                             internalState: { ...n.internalState, tickCount: 0 }
                         };
                    } else {
                        return { 
                             ...n, 
                             internalState: { ...n.internalState, tickCount: currentCount }
                        };
                    }
                }
                return n;
            });
        }
        return evaluateCircuit(nextNodes, prev.wires);
    });
  }, []);

  useEffect(() => {
    let interval: number;
    if (isSimulating && !isPaused) {
        interval = window.setInterval(tick, 50);
    }
    return () => clearInterval(interval);
  }, [isSimulating, isPaused, tick]);

  // --------------------------------------------------------------------------
  // Validation Logic
  // --------------------------------------------------------------------------
  const validateCircuit = useCallback(() => {
      const messages: string[] = [];
      const invalidNodeIds: string[] = [];
      const floatingInputs: { nodeId: string; index: number }[] = [];
      let valid = true;

      if (circuit.nodes.length === 0) {
          return { valid: false, messages: ["Circuit is empty."], invalidNodeIds: [], floatingInputs: [] };
      }

      circuit.nodes.forEach(node => {
          // Components that don't need input validation
          if (['SWITCH', 'CLOCK', 'BUTTON', 'CONSTANT_1', 'CONSTANT_0', 'JUNCTION'].includes(node.type)) return;

          const inputCount = node.inputs.length;
          let nodeHasFloatingInput = false;

          for(let i=0; i<inputCount; i++) {
              const isConnected = circuit.wires.some(w => w.targetNodeId === node.id && w.targetInputIndex === i);
              if (!isConnected) {
                  valid = false;
                  nodeHasFloatingInput = true;
                  floatingInputs.push({ nodeId: node.id, index: i });
              }
          }

          if (nodeHasFloatingInput) {
              const label = node.properties?.label || node.type;
              messages.push(`${label} (ID: ${node.id.slice(-4)}): Missing input connections.`);
              invalidNodeIds.push(node.id);
          }
      });

      return { 
          valid, 
          messages: valid ? ["Circuit is compatible and valid."] : messages, 
          invalidNodeIds,
          floatingInputs
      };
  }, [circuit]);

  const toggleSimulation = () => {
    if (isSimulating) {
        setIsSimulating(false);
        setIsPaused(false);
        setSimHistory([]); 
        setToolMode('select');
        setValidationResult(null);
    } else {
        // Enforce validation before running
        const result = validateCircuit();
        setValidationResult(result);
        if (!result.valid) {
            return;
        }

        setIsSimulating(true);
        setToolMode('interact'); 
        setSimHistory([circuit]);
    }
  };

  const checkCompatibility = () => {
      const result = validateCircuit();
      setValidationResult(result);
      if (result.valid) setTimeout(() => setValidationResult(null), 2000);
  };

  const stepForward = () => {
    if (!isSimulating) return;
    setIsPaused(true); 
    tick();
  };

  const stepBackward = () => {
    if (!isSimulating || simHistory.length === 0) return;
    setIsPaused(true);
    const prev = simHistory[simHistory.length - 1];
    setCircuit(prev);
    setSimHistory(h => h.slice(0, -1));
  };

  // --------------------------------------------------------------------------
  // Circuit Logic Helpers
  // --------------------------------------------------------------------------
  const handleUpdateCircuit = (nodes: NodeData[], wires: Wire[]) => {
      const evaluated = evaluateCircuit(nodes, wires);
      setCircuit(evaluated);
  };

  // --------------------------------------------------------------------------
  // File Ops
  // --------------------------------------------------------------------------
  const handleSave = () => {
    const data = JSON.stringify(circuit, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `logiclab-circuit-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleLoad = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
        try {
            const content = event.target?.result as string;
            const parsed = JSON.parse(content);
            if (parsed && Array.isArray(parsed.nodes) && Array.isArray(parsed.wires)) {
                // Loading a new file resets history
                setCircuit(parsed);
                setPast([]);
                setFuture([]);
                setSimHistory([]);
                setIsSimulating(false);
                setIsPaused(false);
                setValidationResult(null);
            } else {
                alert("Invalid circuit file format.");
            }
        } catch (err) {
            console.error(err);
            alert("Failed to parse file.");
        }
    };
    reader.readAsText(file);
  };

  const handleDeleteSelection = () => {
    if (!selectedId) return;
    // Snapshot before deleting
    snapshot();

    const isWire = circuit.wires.find(w => w.id === selectedId);
    if (isWire) {
        handleUpdateCircuit(circuit.nodes, circuit.wires.filter(w => w.id !== selectedId));
        setSelectedId(null);
        return;
    }
    const newWires = circuit.wires.filter(w => w.sourceNodeId !== selectedId && w.targetNodeId !== selectedId);
    const newNodes = circuit.nodes.filter(n => n.id !== selectedId);
    handleUpdateCircuit(newNodes, newWires);
    setSelectedId(null);
  };

  const handleNodeUpdate = (id: string, updates: Partial<NodeData>) => {
    // Snapshot before updating property
    snapshot();

    const prev = circuit;
    const newNodes = prev.nodes.map(n => {
        if (n.id === id) {
            let updatedNode = { ...n, ...updates };
            // Resize logic if type changes
            if (updates.type && updates.type !== n.type) {
                 const def = NODE_DEFINITIONS[updates.type];
                 if (def) {
                     const currentInputs = updatedNode.inputs;
                     updatedNode.inputs = def.inputs > currentInputs.length 
                        ? [...currentInputs, ...Array(def.inputs - currentInputs.length).fill(false)] 
                        : currentInputs.slice(0, def.inputs);

                     const currentOutputs = updatedNode.outputs;
                     updatedNode.outputs = def.outputs > currentOutputs.length 
                        ? [...currentOutputs, ...Array(def.outputs - currentOutputs.length).fill(false)] 
                        : currentOutputs.slice(0, def.outputs);
                 }
            }
            // Resize logic for variable gates
            if (updates.properties?.inputCount) {
                const count = updates.properties.inputCount;
                if (count > updatedNode.inputs.length) {
                    updatedNode.inputs = [...updatedNode.inputs, ...Array(count - updatedNode.inputs.length).fill(false)];
                } else if (count < updatedNode.inputs.length) {
                    updatedNode.inputs = updatedNode.inputs.slice(0, count);
                }
            }
            // Logic for initializing inputs based on properties
            if (updates.properties?.initialState !== undefined) {
                if (['SWITCH', 'CONSTANT_1', 'CONSTANT_0'].includes(updatedNode.type)) {
                     updatedNode.outputs = [!!updates.properties.initialState];
                }
                if (['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'D_LATCH'].includes(updatedNode.type)) {
                    updatedNode.internalState = { ...updatedNode.internalState, storedValue: !!updates.properties.initialState };
                    updatedNode.outputs = [!!updates.properties.initialState, !updates.properties.initialState];
                }
            }
            return updatedNode;
        }
        return n;
    });

    // Cleanup disconnected wires
    const validWires = prev.wires.filter(w => {
        const source = newNodes.find(n => n.id === w.sourceNodeId);
        const target = newNodes.find(n => n.id === w.targetNodeId);
        if (!source || !target) return false;
        if (w.sourceOutputIndex >= source.outputs.length) return false;
        if (w.targetInputIndex >= target.inputs.length) return false;
        return true;
    });

    handleUpdateCircuit(newNodes, validWires);
  };

  const handleWireUpdate = (id: string, updates: Partial<Wire>) => {
        snapshot();
        setCircuit(prev => ({
            ...prev,
            wires: prev.wires.map(w => w.id === id ? { ...w, ...updates } : w)
        }));
  };

  // --------------------------------------------------------------------------
  // Resize Handlers
  // --------------------------------------------------------------------------
  const startResizingSidebar = useCallback(() => setIsResizingSidebar(true), []);
  const startResizingPanel = useCallback(() => setIsResizingPanel(true), []);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (isResizingSidebar) {
          setSidebarWidth(Math.max(180, Math.min(450, e.clientX)));
      }
      if (isResizingPanel) {
          setPanelWidth(Math.max(200, Math.min(500, window.innerWidth - e.clientX)));
      }
    };
    const handleMouseUp = () => {
        setIsResizingSidebar(false);
        setIsResizingPanel(false);
    };

    if (isResizingSidebar || isResizingPanel) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
    } else {
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    }

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    };
  }, [isResizingSidebar, isResizingPanel]);

  const selectedNode = circuit.nodes.find(n => n.id === selectedId) || null;
  const selectedWire = circuit.wires.find(w => w.id === selectedId) || null;

  return (
    <div className={`${theme} h-screen w-screen overflow-hidden flex flex-col`}>
      {/* Header (Top) */}
      <Header 
        onSave={handleSave}
        onLoad={handleLoad}
        toolMode={toolMode}
        setToolMode={setToolMode}
        wireMode={wireMode}
        setWireMode={setWireMode}
        isSimulating={isSimulating}
        toggleSimulation={toggleSimulation}
        isPaused={isPaused}
        setIsPaused={setIsPaused}
        stepBackward={stepBackward}
        stepForward={stepForward}
        checkCompatibility={checkCompatibility}
        theme={theme}
        toggleTheme={toggleTheme}
        onClear={() => { snapshot(); setCircuit({nodes:[], wires:[]}); setIsSimulating(false); }}
        selectedId={selectedId}
        deleteSelection={handleDeleteSelection}
        hasHistory={simHistory.length > 0}
        onUndo={undo}
        onRedo={redo}
        canUndo={past.length > 0}
        canRedo={future.length > 0}
      />

      {/* Main Content (Row) */}
      <div className="flex flex-1 w-full bg-zinc-50 dark:bg-black text-zinc-900 dark:text-white font-sans transition-colors duration-300 overflow-hidden relative">
        <Sidebar 
          onSelectComponent={setPendingComponent} 
          selectedComponent={pendingComponent} 
          width={sidebarWidth}
        />

        {/* Sidebar Splitter */}
        <div 
            className="w-1 cursor-col-resize hover:bg-cyan-500 transition-colors z-20 bg-zinc-200 dark:bg-zinc-800 flex-shrink-0" 
            onMouseDown={startResizingSidebar}
        />

        <CircuitCanvas 
          circuit={circuit}
          onUpdateCircuit={handleUpdateCircuit}
          onCommit={snapshot}
          selectedId={selectedId}
          setSelectedId={setSelectedId}
          pendingComponent={pendingComponent}
          setPendingComponent={setPendingComponent}
          toolMode={toolMode}
          wireMode={wireMode}
          isSimulating={isSimulating}
          validationResult={validationResult}
          setValidationResult={setValidationResult}
        />

        {/* Panel Splitter */}
        <div 
            className="w-1 cursor-col-resize hover:bg-cyan-500 transition-colors z-20 bg-zinc-200 dark:bg-zinc-800 flex-shrink-0" 
            onMouseDown={startResizingPanel}
        />

        <PropertiesPanel 
            node={selectedNode} 
            wire={selectedWire}
            onUpdate={handleNodeUpdate} 
            onUpdateWire={handleWireUpdate}
            width={panelWidth} 
        />
      </div>
    </div>
  );
};

const App: React.FC = () => {
  return (
    <ThemeProvider>
      <AppContent />
    </ThemeProvider>
  );
};

export default App;

import React, { useState, useCallback, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { CircuitCanvas } from './components/CircuitCanvas';
import { Header } from './components/Header';
import { PropertiesPanel } from './components/PropertiesPanel';
import { ThemeProvider, useTheme } from './components/ThemeContext';
import { CircuitState, NodeData, NodeType, Wire } from './types';
import { evaluateCircuit } from './utils/circuitLogic';
import { NODE_DEFINITIONS } from './constants';

const MAX_HISTORY = 50;

const AppContent: React.FC = () => {
  const { theme, toggleTheme } = useTheme();

  // -- Global Application State --
  const [circuit, setCircuit] = useState<CircuitState>({ nodes: [], wires: [] });
  // Edit History
  const [past, setPast] = useState<CircuitState[]>([]);
  const [future, setFuture] = useState<CircuitState[]>([]);
  // Simulation History (Running Buffer)
  const [simHistory, setSimHistory] = useState<CircuitState[]>([]);

  const [pendingComponent, setPendingComponent] = useState<NodeType | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  // -- Interaction Modes --
  const [toolMode, setToolMode] = useState<'select' | 'interact' | 'junction'>('select');
  const [wireMode, setWireMode] = useState<'manhattan' | 'bezier'>('manhattan');

  // -- Simulation State --
  const [isSimulating, setIsSimulating] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  // -- UI Layout State --
  const [sidebarWidth, setSidebarWidth] = useState(260);
  const [panelWidth, setPanelWidth] = useState(260);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);
  const [isResizingPanel, setIsResizingPanel] = useState(false);

  // -- Validation State --
  const [validationResult, setValidationResult] = useState<{
      valid: boolean; 
      messages: string[]; 
      invalidNodeIds: string[];
      floatingInputs: { nodeId: string; index: number }[];
  } | null>(null);

  // --------------------------------------------------------------------------
  // History Management (Undo/Redo)
  // --------------------------------------------------------------------------

  const snapshot = useCallback(() => {
    setPast(prev => {
        const last = prev[prev.length - 1];
        if (last && JSON.stringify(last) === JSON.stringify(circuit)) return prev;

        const newPast = [...prev, circuit];
        if (newPast.length > MAX_HISTORY) return newPast.slice(newPast.length - MAX_HISTORY);
        return newPast;
    });
    setFuture([]);
  }, [circuit]);

  const undo = useCallback(() => {
      if (past.length === 0) return;
      const previous = past[past.length - 1];
      const newPast = past.slice(0, -1);

      setFuture(prev => [circuit, ...prev]);
      setPast(newPast);
      setCircuit(previous);
      if (isSimulating) {
        setIsSimulating(false);
        setSimHistory([]);
      }
      setValidationResult(null);
  }, [past, circuit, isSimulating]);

  const redo = useCallback(() => {
      if (future.length === 0) return;
      const next = future[0];
      const newFuture = future.slice(1);

      setPast(prev => [...prev, circuit]);
      setFuture(newFuture);
      setCircuit(next);
      if (isSimulating) {
        setIsSimulating(false);
        setSimHistory([]);
      }
      setValidationResult(null);
  }, [future, circuit, isSimulating]);

  // --------------------------------------------------------------------------
  // Simulation Logic
  // --------------------------------------------------------------------------
  const tick = useCallback(() => {
    setCircuit(prev => {
        // Save history before tick for stepping back
        setSimHistory(h => {
            const newHistory = [...h, prev];
            if (newHistory.length > MAX_HISTORY) return newHistory.slice(1);
            return newHistory;
        });

        const hasClock = prev.nodes.some(n => n.type === 'CLOCK');
        let nextNodes = [...prev.nodes];

        if (hasClock) {
            nextNodes = nextNodes.map(n => {
                if (n.type === 'CLOCK') {
                    const speed = n.properties?.interval || 20; 
                    const currentCount = (n.internalState?.tickCount || 0) + 1;

                    if (currentCount >= speed) {
                         return { 
                             ...n, 
                             outputs: [!n.outputs[0]],
                             internalState: { ...n.internalState, tickCount: 0 }
                         };
                    } else {
                        return { 
                             ...n, 
                             internalState: { ...n.internalState, tickCount: currentCount }
                        };
                    }
                }
                return n;
            });
        }
        return evaluateCircuit(nextNodes, prev.wires);
    });
  }, []);

  useEffect(() => {
    let interval: number;
    if (isSimulating && !isPaused) {
        interval = window.setInterval(tick, 50);
    }
    return () => clearInterval(interval);
  }, [isSimulating, isPaused, tick]);

  const validateCircuit = useCallback(() => {
      const messages: string[] = [];
      const invalidNodeIds: string[] = [];
      const floatingInputs: { nodeId: string; index: number }[] = [];
      let valid = true;

      if (circuit.nodes.length === 0) {
          return { valid: false, messages: ["Circuit is empty."], invalidNodeIds: [], floatingInputs: [] };
      }

      circuit.nodes.forEach(node => {
          if (['SWITCH', 'CLOCK', 'BUTTON', 'CONSTANT_1', 'CONSTANT_0', 'JUNCTION'].includes(node.type)) return;
          const inputCount = node.inputs.length;
          let nodeHasFloatingInput = false;
          for(let i=0; i<inputCount; i++) {
              const isConnected = circuit.wires.some(w => w.targetNodeId === node.id && w.targetInputIndex === i);
              if (!isConnected) {
                  valid = false;
                  nodeHasFloatingInput = true;
                  floatingInputs.push({ nodeId: node.id, index: i });
              }
          }
          if (nodeHasFloatingInput) {
              const label = node.properties?.label || node.type;
              messages.push(`${label} (ID: ${node.id.slice(-4)}): Missing input connections.`);
              invalidNodeIds.push(node.id);
          }
      });

      return { valid, messages: valid ? ["Circuit is compatible and valid."] : messages, invalidNodeIds, floatingInputs };
  }, [circuit]);

  const toggleSimulation = () => {
    if (isSimulating) {
        setIsSimulating(false);
        setIsPaused(false);
        setSimHistory([]); 
        setToolMode('select');
        setValidationResult(null);
    } else {
        const result = validateCircuit();
        setValidationResult(result);
        if (!result.valid) return;

        setIsSimulating(true);
        setToolMode('interact'); 
        setSimHistory([circuit]);
    }
  };

  const stepForward = useCallback(() => {
    if (!isSimulating) {
        const result = validateCircuit();
        setValidationResult(result);
        if (!result.valid) return;
        setIsSimulating(true);
        setToolMode('interact');
    }
    setIsPaused(true); 
    tick();
  }, [isSimulating, validateCircuit, tick]);

  const stepBackward = useCallback(() => {
    if (!isSimulating || simHistory.length === 0) return;
    setIsPaused(true);
    const prev = simHistory[simHistory.length - 1];
    setCircuit(prev);
    setSimHistory(h => h.slice(0, -1));
  }, [isSimulating, simHistory]);

  // Keyboard Shortcuts
  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          // Prevent shortcuts if typing in an input
          if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement || e.target instanceof HTMLSelectElement) return;

          if ((e.metaKey || e.ctrlKey) && e.key === 'z') {
              e.preventDefault();
              undo();
          } else if ((e.metaKey || e.ctrlKey) && e.key === 'y') {
              e.preventDefault();
              redo();
          } else if (e.key === '.') {
              e.preventDefault();
              stepForward();
          } else if (e.key === ',') {
              e.preventDefault();
              stepBackward();
          }
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [undo, redo, stepForward, stepBackward]);

  const checkCompatibility = () => {
      const result = validateCircuit();
      setValidationResult(result);
      if (result.valid) setTimeout(() => setValidationResult(null), 2000);
  };

  // --------------------------------------------------------------------------
  // Circuit Logic Helpers
  // --------------------------------------------------------------------------
  const handleUpdateCircuit = (nodes: NodeData[], wires: Wire[]) => {
      const evaluated = evaluateCircuit(nodes, wires);
      setCircuit(evaluated);
  };

  const handleSave = () => {
    const data = JSON.stringify(circuit, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `logiclab-circuit-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleLoad = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
        try {
            const content = event.target?.result as string;
            const parsed = JSON.parse(content);
            if (parsed && Array.isArray(parsed.nodes) && Array.isArray(parsed.wires)) {
                setCircuit(parsed);
                setPast([]);
                setFuture([]);
                setSimHistory([]);
                setIsSimulating(false);
                setIsPaused(false);
                setValidationResult(null);
            } else {
                alert("Invalid circuit file format.");
            }
        } catch (err) {
            console.error(err);
            alert("Failed to parse file.");
        }
    };
    reader.readAsText(file);
  };

  const handleDeleteSelection = () => {
    if (!selectedId) return;
    snapshot();
    const isWire = circuit.wires.find(w => w.id === selectedId);
    if (isWire) {
        handleUpdateCircuit(circuit.nodes, circuit.wires.filter(w => w.id !== selectedId));
        setSelectedId(null);
        return;
    }
    const newWires = circuit.wires.filter(w => w.sourceNodeId !== selectedId && w.targetNodeId !== selectedId);
    const newNodes = circuit.nodes.filter(n => n.id !== selectedId);
    handleUpdateCircuit(newNodes, newWires);
    setSelectedId(null);
  };

  const handleNodeUpdate = (id: string, updates: Partial<NodeData>) => {
    snapshot();
    const prev = circuit;
    const newNodes = prev.nodes.map(n => {
        if (n.id === id) {
            let updatedNode = { ...n, ...updates };
            if (updates.type && updates.type !== n.type) {
                 const def = NODE_DEFINITIONS[updates.type];
                 if (def) {
                     const currentInputs = updatedNode.inputs;
                     updatedNode.inputs = def.inputs > currentInputs.length 
                        ? [...currentInputs, ...Array(def.inputs - currentInputs.length).fill(false)] 
                        : currentInputs.slice(0, def.inputs);

                     const currentOutputs = updatedNode.outputs;
                     updatedNode.outputs = def.outputs > currentOutputs.length 
                        ? [...currentOutputs, ...Array(def.outputs - currentOutputs.length).fill(false)] 
                        : currentOutputs.slice(0, def.outputs);
                 }
            }
            if (updates.properties?.inputCount) {
                const count = updates.properties.inputCount;
                if (count > updatedNode.inputs.length) {
                    updatedNode.inputs = [...updatedNode.inputs, ...Array(count - updatedNode.inputs.length).fill(false)];
                } else if (count < updatedNode.inputs.length) {
                    updatedNode.inputs = updatedNode.inputs.slice(0, count);
                }
            }
            if (updates.properties?.initialState !== undefined) {
                if (['SWITCH', 'CONSTANT_1', 'CONSTANT_0'].includes(updatedNode.type)) {
                     updatedNode.outputs = [!!updates.properties.initialState];
                }
                if (['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'D_LATCH'].includes(updatedNode.type)) {
                    updatedNode.internalState = { ...updatedNode.internalState, storedValue: !!updates.properties.initialState };
                    updatedNode.outputs = [!!updates.properties.initialState, !updates.properties.initialState];
                }
            }
            return updatedNode;
        }
        return n;
    });

    const validWires = prev.wires.filter(w => {
        const source = newNodes.find(n => n.id === w.sourceNodeId);
        const target = newNodes.find(n => n.id === w.targetNodeId);
        if (!source || !target) return false;
        if (w.sourceOutputIndex >= source.outputs.length) return false;
        if (w.targetInputIndex >= target.inputs.length) return false;
        return true;
    });

    handleUpdateCircuit(newNodes, validWires);
  };

  const handleWireUpdate = (id: string, updates: Partial<Wire>) => {
        snapshot();
        setCircuit(prev => ({
            ...prev,
            wires: prev.wires.map(w => w.id === id ? { ...w, ...updates } : w)
        }));
  };

  const startResizingSidebar = useCallback(() => setIsResizingSidebar(true), []);
  const startResizingPanel = useCallback(() => setIsResizingPanel(true), []);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (isResizingSidebar) setSidebarWidth(Math.max(180, Math.min(450, e.clientX)));
      if (isResizingPanel) setPanelWidth(Math.max(200, Math.min(500, window.innerWidth - e.clientX)));
    };
    const handleMouseUp = () => { setIsResizingSidebar(false); setIsResizingPanel(false); };
    if (isResizingSidebar || isResizingPanel) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
    } else {
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    };
  }, [isResizingSidebar, isResizingPanel]);

  const selectedNode = circuit.nodes.find(n => n.id === selectedId) || null;
  const selectedWire = circuit.wires.find(w => w.id === selectedId) || null;

  return (
    <div className={`${theme} h-screen w-screen overflow-hidden flex flex-col`}>
      <Header 
        onSave={handleSave}
        onLoad={handleLoad}
        toolMode={toolMode}
        setToolMode={setToolMode}
        wireMode={wireMode}
        setWireMode={setWireMode}
        isSimulating={isSimulating}
        toggleSimulation={toggleSimulation}
        isPaused={isPaused}
        setIsPaused={setIsPaused}
        stepBackward={stepBackward}
        stepForward={stepForward}
        checkCompatibility={checkCompatibility}
        theme={theme}
        toggleTheme={toggleTheme}
        onClear={() => { snapshot(); setCircuit({nodes:[], wires:[]}); setIsSimulating(false); }}
        selectedId={selectedId}
        deleteSelection={handleDeleteSelection}
        hasHistory={simHistory.length > 0}
        onUndo={undo}
        onRedo={redo}
        canUndo={past.length > 0}
        canRedo={future.length > 0}
      />

      <div className="flex flex-1 w-full bg-zinc-50 dark:bg-black text-zinc-900 dark:text-white font-sans transition-colors duration-300 overflow-hidden relative">
        <Sidebar onSelectComponent={setPendingComponent} selectedComponent={pendingComponent} width={sidebarWidth} />
        <div className="w-1 cursor-col-resize hover:bg-cyan-500 transition-colors z-20 bg-zinc-200 dark:bg-zinc-800 flex-shrink-0" onMouseDown={startResizingSidebar} />
        <CircuitCanvas 
          circuit={circuit} onUpdateCircuit={handleUpdateCircuit} onCommit={snapshot}
          selectedId={selectedId} setSelectedId={setSelectedId}
          pendingComponent={pendingComponent} setPendingComponent={setPendingComponent}
          toolMode={toolMode} wireMode={wireMode} isSimulating={isSimulating}
          validationResult={validationResult} setValidationResult={setValidationResult}
        />
        <div className="w-1 cursor-col-resize hover:bg-cyan-500 transition-colors z-20 bg-zinc-200 dark:bg-zinc-800 flex-shrink-0" onMouseDown={startResizingPanel} />
        <PropertiesPanel node={selectedNode} wire={selectedWire} onUpdate={handleNodeUpdate} onUpdateWire={handleWireUpdate} width={panelWidth} />
      </div>
    </div>
  );
};

const App: React.FC = () => <ThemeProvider><AppContent /></ThemeProvider>;
export default App;

import React, { useRef } from 'react';
import { 
    SquareActivity, Save, FolderOpen, Move, Circle, Cable, 
    CheckCircle2, SkipBack, Play, RotateCcw, Pause, SkipForward, 
    Sun, Moon, Trash2, X, Undo2, Redo2, MousePointerClick
} from 'lucide-react';
import { NodeType } from '../types';

interface HeaderProps {
    onSave: () => void;
    onLoad: (file: File) => void;
    toolMode: 'select' | 'interact' | 'junction';
    setToolMode: (mode: 'select' | 'interact' | 'junction') => void;
    wireMode: 'manhattan' | 'bezier';
    setWireMode: (mode: 'manhattan' | 'bezier') => void;
    isSimulating: boolean;
    toggleSimulation: () => void;
    isPaused: boolean;
    setIsPaused: (paused: boolean) => void;
    stepBackward: () => void;
    stepForward: () => void;
    checkCompatibility: () => void;
    theme: 'dark' | 'light';
    toggleTheme: () => void;
    onClear: () => void;
    selectedId: string | null;
    deleteSelection: () => void;
    hasHistory: boolean;
    onUndo: () => void;
    onRedo: () => void;
    canUndo: boolean;
    canRedo: boolean;
}

export const Header: React.FC<HeaderProps> = ({
    onSave, onLoad,
    toolMode, setToolMode,
    wireMode, setWireMode,
    isSimulating, toggleSimulation,
    isPaused, setIsPaused,
    stepBackward, stepForward,
    checkCompatibility,
    theme, toggleTheme,
    onClear,
    selectedId, deleteSelection,
    hasHistory,
    onUndo, onRedo, canUndo, canRedo
}) => {
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files?.[0]) {
            onLoad(e.target.files[0]);
            e.target.value = ''; // Reset
        }
    };

    return (
        <div className="h-14 bg-white dark:bg-zinc-900 border-b border-zinc-200 dark:border-zinc-800 flex items-center px-4 justify-between z-30 shrink-0 shadow-sm transition-colors duration-300">
            {/* Logo Section */}
            <div className="flex items-center space-x-3 mr-4">
                <div className="w-8 h-8 bg-cyan-500 rounded-md flex items-center justify-center shadow-lg shadow-cyan-500/20">
                    <SquareActivity size={20} className="text-white" />
                </div>
                <span className="text-sm font-bold tracking-wider text-zinc-700 dark:text-zinc-200 uppercase hidden sm:block">LogicLab Ultra</span>
            </div>

            {/* Toolbar Controls */}
            <div className="flex items-center space-x-4 overflow-x-auto no-scrollbar mask-linear-fade flex-1">

                {/* File Ops */}
                <div className="flex items-center bg-zinc-100 dark:bg-zinc-800 rounded-md p-0.5 border border-zinc-200 dark:border-zinc-700 shrink-0">
                    <button onClick={onSave} className="p-1.5 rounded text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200 transition-colors" title="Save Circuit">
                        <Save size={16} />
                    </button>
                    <button onClick={() => fileInputRef.current?.click()} className="p-1.5 rounded text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200 transition-colors" title="Open Circuit">
                        <FolderOpen size={16} />
                    </button>
                    <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={handleFileChange} />
                </div>

                <div className="h-4 w-px bg-zinc-300 dark:bg-zinc-700 shrink-0"></div>

                {/* Undo / Redo */}
                <div className="flex items-center bg-zinc-100 dark:bg-zinc-800 rounded-md p-0.5 border border-zinc-200 dark:border-zinc-700 shrink-0">
                    <button 
                        onClick={onUndo} 
                        disabled={!canUndo}
                        className="p-1.5 rounded text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200 transition-colors disabled:opacity-30 disabled:hover:text-zinc-500" 
                        title="Undo (Ctrl+Z)"
                    >
                        <Undo2 size={16} />
                    </button>
                    <button 
                        onClick={onRedo} 
                        disabled={!canRedo}
                        className="p-1.5 rounded text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200 transition-colors disabled:opacity-30 disabled:hover:text-zinc-500" 
                        title="Redo (Ctrl+Y)"
                    >
                        <Redo2 size={16} />
                    </button>
                </div>

                <div className="h-4 w-px bg-zinc-300 dark:bg-zinc-700 shrink-0"></div>

                {/* Tools: Move / Interact / Junction */}
                <div className="flex items-center bg-zinc-100 dark:bg-zinc-800 rounded-md p-0.5 border border-zinc-200 dark:border-zinc-700 shrink-0">
                    <button 
                        onClick={() => setToolMode('select')}
                        className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-medium transition-colors ${toolMode === 'select' ? 'bg-white dark:bg-zinc-700 text-cyan-600 dark:text-cyan-400 shadow-sm ring-1 ring-zinc-200 dark:ring-zinc-600' : 'text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200'}`}
                        title="Move Mode (Drag components)"
                    >
                        <Move size={14} />
                        <span className="hidden sm:inline">Move</span>
                    </button>
                    <button 
                        onClick={() => setToolMode('interact')}
                        className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-medium transition-colors ${toolMode === 'interact' ? 'bg-white dark:bg-zinc-700 text-cyan-600 dark:text-cyan-400 shadow-sm ring-1 ring-zinc-200 dark:ring-zinc-600' : 'text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200'}`}
                        title="Interact Mode (Toggle switches)"
                    >
                        <MousePointerClick size={14} />
                        <span className="hidden sm:inline">Interact</span>
                    </button>
                    <div className="w-px h-4 bg-zinc-200 dark:bg-zinc-700 mx-1"></div>
                    <button 
                        onClick={() => setToolMode(toolMode === 'junction' ? 'select' : 'junction')}
                        className={`p-1.5 rounded transition-colors ${toolMode === 'junction' ? 'bg-white dark:bg-zinc-700 text-cyan-600 dark:text-cyan-400 shadow-sm ring-1 ring-zinc-200 dark:ring-zinc-600' : 'text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200'}`}
                        title="Junction Tool"
                    >
                        <Circle size={14} />
                    </button>
                </div>

                <div className="flex items-center bg-zinc-100 dark:bg-zinc-800 rounded-md p-0.5 border border-zinc-200 dark:border-zinc-700 shrink-0">
                     <button 
                        onClick={() => setWireMode(wireMode === 'manhattan' ? 'bezier' : 'manhattan')}
                        className={`p-1.5 rounded transition-colors text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200`}
                        title="Toggle Wire Style"
                    >
                        <Cable size={14} />
                    </button>
                </div>

                <div className="h-4 w-px bg-zinc-300 dark:bg-zinc-700 shrink-0"></div>

                {/* Simulation */}
                <div className="flex items-center space-x-2 bg-zinc-50 dark:bg-zinc-900/50 border border-zinc-200 dark:border-zinc-800 p-1 rounded-lg shrink-0">
                     <button onClick={checkCompatibility} className="p-1.5 rounded text-zinc-400 hover:text-green-500 dark:hover:text-green-400 hover:bg-green-100 dark:hover:bg-green-900/20 transition-colors" title="Check Compatibility">
                        <CheckCircle2 size={16} />
                    </button>
                    <div className="h-4 w-px bg-zinc-200 dark:bg-zinc-800"></div>
                    <button 
                        onClick={stepBackward} 
                        disabled={!isSimulating || !hasHistory} 
                        className="p-1.5 rounded text-zinc-400 hover:text-zinc-900 dark:hover:text-white hover:bg-zinc-100 dark:hover:bg-zinc-700 transition-colors disabled:opacity-30 disabled:hover:bg-transparent" 
                        title="Step Back (,)"
                    >
                        <SkipBack size={16} />
                    </button>
                    <button 
                        onClick={toggleSimulation}
                        className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-bold transition-all ${
                            isSimulating 
                                ? 'bg-red-50 text-red-500 hover:bg-red-100 border border-red-200 dark:bg-red-500/10 dark:hover:bg-red-500/20 dark:border-red-500/50' 
                                : 'bg-green-500 hover:bg-green-600 dark:bg-green-600 dark:hover:bg-green-500 text-white shadow-lg shadow-green-500/20 dark:shadow-green-900/20'
                        }`}
                    >
                        {isSimulating ? <RotateCcw size={14} /> : <Play size={14} />}
                        <span className="hidden sm:inline">{isSimulating ? 'Stop' : 'Run'}</span>
                    </button>
                    {isSimulating && (
                        <button onClick={() => setIsPaused(!isPaused)} className={`p-1.5 rounded transition-colors ${isPaused ? 'text-amber-500 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20' : 'text-zinc-400 hover:text-zinc-900 dark:hover:text-white hover:bg-zinc-100 dark:hover:bg-zinc-700'}`} title={isPaused ? "Resume" : "Pause"}>
                            {isPaused ? <Play size={14} /> : <Pause size={14} />}
                        </button>
                    )}
                    <button 
                        onClick={stepForward} 
                        className="p-1.5 rounded text-zinc-400 hover:text-zinc-900 dark:hover:text-white hover:bg-zinc-100 dark:hover:bg-zinc-700 transition-colors disabled:opacity-30 disabled:hover:bg-transparent" 
                        title="Step Forward (.)"
                    >
                        <SkipForward size={16} />
                    </button>
                </div>

            </div>

            {/* Right Actions */}
            <div className="flex items-center space-x-3 ml-4">
                 {selectedId && (
                    <button onClick={deleteSelection} className="flex items-center space-x-1 px-3 py-1.5 bg-red-50 text-red-500 dark:bg-red-500/10 dark:text-red-400 hover:bg-red-100 dark:hover:bg-red-500/20 border border-red-200 dark:border-red-500/30 rounded-md text-xs font-medium transition-colors" title="Delete Selected">
                        <X size={14} />
                        <span className="hidden sm:inline">Delete</span>
                    </button>
                )}
                <button onClick={toggleTheme} className="p-2 text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-white transition-colors" title="Toggle Theme">
                    {theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}
                </button>
                <button onClick={onClear} className="p-2 hover:bg-zinc-100 dark:hover:bg-zinc-800 text-zinc-500 hover:text-red-500 dark:hover:text-red-400 rounded-md transition-colors" title="Clear Canvas">
                    <Trash2 size={16} />
                </button>
            </div>
        </div>
    );
};

import React, { useRef, useState, useEffect } from 'react';
import { GRID_SIZE, NODE_DEFINITIONS } from '../constants';
import { CircuitState, NodeData, NodeType, Wire, Point, WiringState } from '../types';
import { GateShape } from './GateShapes';
import { getNodeDimensions, getInputPorts, getOutputPorts } from '../utils/componentUtils';
import { CheckCircle2, AlertTriangle } from 'lucide-react';
import { useTheme } from './ThemeContext';

interface CircuitCanvasProps {
    circuit: CircuitState;
    onUpdateCircuit: (nodes: NodeData[], wires: Wire[]) => void;
    onCommit: () => void;
    selectedId: string | null;
    setSelectedId: (id: string | null) => void;
    pendingComponent: NodeType | null;
    setPendingComponent: (type: NodeType | null) => void;
    toolMode: 'select' | 'interact' | 'junction';
    wireMode: 'manhattan' | 'bezier';
    isSimulating: boolean;
    validationResult: {
        valid: boolean;
        messages: string[];
        invalidNodeIds: string[];
        floatingInputs: { nodeId: string; index: number }[];
    } | null;
    setValidationResult: (res: any) => void;
}

export const CircuitCanvas: React.FC<CircuitCanvasProps> = ({ 
    circuit, onUpdateCircuit, onCommit,
    selectedId, setSelectedId,
    pendingComponent, setPendingComponent,
    toolMode, wireMode, isSimulating,
    validationResult, setValidationResult
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const { theme } = useTheme();

  // Local Interaction State
  const [draggingNodeId, setDraggingNodeId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<Point>({ x: 0, y: 0 });
  const [wiring, setWiring] = useState<WiringState | null>(null);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });

  // --- Keyboard Shortcuts (Local Interactions) ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
            if (pendingComponent) setPendingComponent(null);
            if (wiring) setWiring(null);
            if (selectedId) setSelectedId(null);
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [pendingComponent, wiring, selectedId, setPendingComponent, setSelectedId]);


  const addNode = (type: NodeType, x: number, y: number) => {
    onCommit(); // Snapshot before adding
    const def = NODE_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newNode: NodeData = {
      id: `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      position: { x: snapX, y: snapY },
      inputs: Array(def.inputs).fill(false),
      outputs: Array(def.outputs).fill(false),
      internalState: {},
      properties: {
          label: '',
          labelPosition: 'Top',
          inputCount: def.inputs,
          propagationDelay: 0,
          initialState: false,
          romValue: false,
          interval: type === 'CLOCK' ? 20 : 0
      }
    };

    onUpdateCircuit([...circuit.nodes, newNode], circuit.wires);
    setSelectedId(newNode.id);
  };

  // --- Interaction Handlers ---

  const handleNodeMouseDown = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();

    // Snappy Selection: Set selection immediately on mousedown
    setSelectedId(id);

    if (wiring || pendingComponent) return; 

    const node = circuit.nodes.find(n => n.id === id);
    if (!node) return;

    const isInteractive = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

    // 1. INTERACT MODE: Prioritize toggling over moving
    if (toolMode === 'interact' || isSimulating) {
        if (isInteractive) {
            // Interactive: Toggle/Action only. 
            // We still select it so the user can see attributes, but focus is interaction.
            if (!isSimulating) onCommit();

            let toggledNodes = circuit.nodes;

            // Special handling for Multi-bit inputs
            if (node.type.startsWith('INPUT_')) {
                const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
                const relY = e.clientY - rect.top; 
                const relX = e.clientX - rect.left;
                const { width, height } = getNodeDimensions(node);
                const bitCount = node.outputs.length;

                // Check Header Click (Direct Value Input)
                if (relY < 25) {
                    const inputVal = window.prompt(`Set Value for ${bitCount}-bit Input:`);
                    if (inputVal !== null) {
                        let val = parseInt(inputVal);
                        if (!isNaN(val)) {
                            const newOutputs = [];
                            for(let i=0; i<bitCount; i++) {
                                newOutputs.push(!!((val >> i) & 1));
                            }
                            toggledNodes = circuit.nodes.map(n => n.id === id ? { ...n, outputs: newOutputs } : n);
                            onUpdateCircuit(toggledNodes, circuit.wires);
                        }
                    }
                    return;
                }

                let bitIndexToCheck = -1;
                if (relY > height - 30) {
                    // Binary Footer Click Logic
                    const bitWidth = 10;
                    const bitSpacing = 2;
                    const nibbleGap = 6;
                    const totalWidth = bitCount * bitWidth + (bitCount - 1) * bitSpacing + Math.floor((bitCount - 1) / 4) * nibbleGap;
                    const startX = (width - totalWidth) / 2 + bitWidth / 2;
                    for (let i = 0; i < bitCount; i++) {
                        const nibblesBefore = Math.floor(i / 4);
                        const xPos = startX + i * (bitWidth + bitSpacing) + nibblesBefore * nibbleGap;
                        if (Math.abs(relX - xPos) < 8) {
                            bitIndexToCheck = bitCount - 1 - i;
                            break;
                        }
                    }
                } else {
                    const rowIdx = Math.floor((relY - 25) / 20);
                    if (rowIdx >= 0 && rowIdx < bitCount) bitIndexToCheck = rowIdx;
                }

                if (bitIndexToCheck >= 0 && bitIndexToCheck < bitCount) {
                    toggledNodes = circuit.nodes.map(n => {
                        if (n.id === id) {
                            const newOutputs = [...n.outputs];
                            newOutputs[bitIndexToCheck] = !newOutputs[bitIndexToCheck];
                            return { ...n, outputs: newOutputs };
                        }
                        return n;
                    });
                }
            } else {
                toggledNodes = circuit.nodes.map(n => {
                    if (n.id === id) {
                        const newState = !n.outputs[0];
                        return { ...n, outputs: [newState] };
                    }
                    return n;
                });
            }
            onUpdateCircuit(toggledNodes, circuit.wires);
            return; // Interaction consumes move
        }
    }

    // 2. MOVE MODE: Handle dragging
    if (toolMode === 'select' || toolMode === 'junction') {
        onCommit(); // Snapshot position before move
        setDraggingNodeId(id);
        const rect = containerRef.current!.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;
        setDragOffset({
            x: mouseX - node.position.x,
            y: mouseY - node.position.y
        });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    if (draggingNodeId) {
        const snapX = Math.round((x - dragOffset.x) / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round((y - dragOffset.y) / GRID_SIZE) * GRID_SIZE;

        const updatedNodes = circuit.nodes.map(n => {
            if (n.id === draggingNodeId) {
                return { ...n, position: { x: snapX, y: snapY }};
            }
            return n;
        });
        onUpdateCircuit(updatedNodes, circuit.wires);
    }
  };

  const handleMouseUp = () => {
    setDraggingNodeId(null);
    setWiring(null);
  };

  const startWiring = (e: React.MouseEvent, nodeId: string, outputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();
    if (toolMode === 'interact' && !isSimulating) return; 

    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setWiring({
        sourceNodeId: nodeId,
        sourceOutputIndex: outputIndex,
        startPoint: { x, y },
        active: true
    });
  };

  const completeWiring = (e: React.MouseEvent, targetNodeId: string, inputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();
    if (!wiring) return;
    if (wiring.sourceNodeId === targetNodeId) {
        setWiring(null);
        return;
    }

    onCommit();
    const exists = circuit.wires.some(w => w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex);
    let newWires = exists ? circuit.wires.filter(w => !(w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex)) : [...circuit.wires];

    newWires.push({
        id: `wire-${Date.now()}`,
        sourceNodeId: wiring.sourceNodeId,
        sourceOutputIndex: wiring.sourceOutputIndex,
        targetNodeId: targetNodeId,
        targetInputIndex: inputIndex,
        state: false
    });

    onUpdateCircuit(circuit.nodes, newWires);
    setWiring(null);
  };

  const handleWireClick = (e: React.MouseEvent, wire: Wire) => {
    e.stopPropagation();
    // Immediate Selection for Wires
    setSelectedId(wire.id);

    if (toolMode === 'junction') {
        const rect = containerRef.current!.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        onCommit();

        const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;
        const junctionId = `node-${Date.now()}-junction`;

        const newJunction: NodeData = {
            id: junctionId,
            type: 'JUNCTION',
            position: { x: snapX - 5, y: snapY - 5 },
            inputs: [false],
            outputs: [false],
            properties: { label: '' }
        };

        const wire1: Wire = {
            id: `wire-${Date.now()}-1`,
            sourceNodeId: wire.sourceNodeId,
            sourceOutputIndex: wire.sourceOutputIndex,
            targetNodeId: junctionId,
            targetInputIndex: 0,
            state: wire.state
        };
        const wire2: Wire = {
            id: `wire-${Date.now()}-2`,
            sourceNodeId: junctionId,
            sourceOutputIndex: 0,
            targetNodeId: wire.targetNodeId,
            targetInputIndex: wire.targetInputIndex,
            state: wire.state
        };

        const newWires = circuit.wires.filter(w => w.id !== wire.id).concat([wire1, wire2]);
        const newNodes = [...circuit.nodes, newJunction];
        onUpdateCircuit(newNodes, newWires);
        setSelectedId(junctionId);
    }
  };

  const handleCanvasClick = (e: React.MouseEvent) => {
      if (pendingComponent && containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        addNode(pendingComponent, x, y);
        setPendingComponent(null);
        return;
      }
      // Deselect when clicking empty background
      setSelectedId(null);
      if (validationResult?.valid) setValidationResult(null);
  };

  const getWirePath = (x1: number, y1: number, x2: number, y2: number) => {
    if (wireMode === 'bezier') {
        const dist = Math.abs(x2 - x1);
        const controlPointOffset = Math.max(dist * 0.5, 50);
        return `M ${x1} ${y1} C ${x1 + controlPointOffset} ${y1}, ${x2 - controlPointOffset} ${y2}, ${x2} ${y2}`;
    }
    const dx = x2 - x1;
    if (dx > 20) {
        const midX = (x1 + x2) / 2;
        return `M ${x1} ${y1} L ${midX} ${y1} L ${midX} ${y2} L ${x2} ${y2}`;
    }
    const stub = 20;
    const midY = (y1 + y2) / 2;
    return `M ${x1} ${y1} L ${x1 + stub} ${y1} L ${x1 + stub} ${midY} L ${x2 - stub} ${midY} L ${x2 - stub} ${y2} L ${x2} ${y2}`;
  };

  const getLabelStyle = (pos: string | undefined): React.CSSProperties => {
      switch (pos) {
          case 'Bottom': return { top: '100%', left: '50%', transform: 'translate(-50%, 8px)' };
          case 'Left': return { top: '50%', right: '100%', transform: 'translate(-8px, -50%)' };
          case 'Right': return { top: '50%', left: '100%', transform: 'translate(8px, -50%)' };
          case 'Top': default: return { bottom: '100%', left: '50%', transform: 'translate(-50%, -8px)' };
      }
  };

  const ghostSnapX = Math.round(mousePos.x / GRID_SIZE) * GRID_SIZE;
  const ghostSnapY = Math.round(mousePos.y / GRID_SIZE) * GRID_SIZE;
  const pendingDef = pendingComponent ? NODE_DEFINITIONS[pendingComponent] : null;

  return (
    <div 
        ref={containerRef}
        className={`flex-1 relative w-full h-full overflow-hidden bg-zinc-50 dark:bg-zinc-950
            ${isSimulating ? 'cursor-default' : pendingComponent ? 'cursor-cell' : 'cursor-crosshair'}`}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onClick={handleCanvasClick}
        onContextMenu={(e) => e.preventDefault()}
    >
        {/* Validation Messages Overlay */}
        {validationResult && (
            <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 pointer-events-none w-auto max-w-lg">
                <div className={`p-4 rounded-lg shadow-xl backdrop-blur-md border animate-in slide-in-from-top-4 duration-200
                    ${validationResult.valid ? 'bg-green-50/90 dark:bg-green-950/80 border-green-200 dark:border-green-800 text-green-800 dark:text-green-200' : 'bg-red-50/90 dark:bg-red-950/80 border-red-200 dark:border-red-800 text-red-800 dark:text-red-200'}`}
                >
                    <div className="flex items-start gap-3">
                        {validationResult.valid ? <CheckCircle2 size={20} className="mt-0.5 text-green-600 dark:text-green-400" /> : <AlertTriangle size={20} className="mt-0.5 text-red-600 dark:text-red-400" />}
                        <div>
                            <h4 className="font-bold text-sm mb-1">{validationResult.valid ? 'Circuit Valid' : 'Compatibility Issues Found'}</h4>
                            <ul className="text-xs space-y-1 list-disc list-inside opacity-90">
                                {validationResult.messages.map((m, i) => <li key={i}>{m}</li>)}
                            </ul>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* Grid Pattern */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full opacity-20 dark:opacity-20">
            <defs>
                <pattern id="grid" width={GRID_SIZE} height={GRID_SIZE} patternUnits="userSpaceOnUse">
                    <circle cx="1" cy="1" r="1" className="fill-zinc-400 dark:fill-zinc-500" />
                </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#grid)" />
        </svg>

        {/* Connections */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
            {circuit.wires.map(wire => {
                const sourceNode = circuit.nodes.find(n => n.id === wire.sourceNodeId);
                const targetNode = circuit.nodes.find(n => n.id === wire.targetNodeId);
                if (!sourceNode || !targetNode) return null;

                const sourcePorts = getOutputPorts(sourceNode);
                const targetPorts = getInputPorts(targetNode);

                const outputOffset = sourcePorts[wire.sourceOutputIndex] || { x: 0, y: 0 };
                const inputOffset = targetPorts[wire.targetInputIndex] || { x: 0, y: 0 };

                const startX = sourceNode.position.x + outputOffset.x;
                const startY = sourceNode.position.y + outputOffset.y;
                const endX = targetNode.position.x + inputOffset.x;
                const endY = targetNode.position.y + inputOffset.y;

                const isSelected = selectedId === wire.id;
                const pathData = getWirePath(startX, startY, endX, endY);

                const inactiveColor = wire.color || (theme === 'dark' ? "#52525b" : "#a1a1aa");
                const activeColor = "#22d3ee";
                const strokeColor = wire.state ? activeColor : (isSelected ? "#22d3ee" : inactiveColor);

                return (
                    <g 
                        key={wire.id} 
                        onClick={(e) => handleWireClick(e, wire)} 
                        className={`pointer-events-auto cursor-pointer group`}
                    >
                        {/* Hit area for wires */}
                        <path d={pathData} stroke="transparent" strokeWidth="12" fill="none" />
                        {wire.state && <path d={pathData} stroke={activeColor} strokeWidth="4" fill="none" opacity="0.3" filter="blur(2px)" />}
                        <path d={pathData} stroke={strokeColor} strokeWidth={isSelected ? "3" : "2"} fill="none" className="transition-all duration-150" strokeDasharray={isSelected ? "4" : "0"} strokeLinejoin="round" strokeLinecap="round" />
                    </g>
                );
            })}

            {wiring && (
                <path d={getWirePath(wiring.startPoint.x, wiring.startPoint.y, mousePos.x, mousePos.y)} stroke="#fbbf24" strokeWidth="2" fill="none" strokeDasharray="4" className="animate-pulse" strokeLinejoin="round" />
            )}
        </svg>

        {/* Nodes */}
        {circuit.nodes.map(node => {
            const { width, height } = getNodeDimensions(node);
            const isSelected = selectedId === node.id;
            const isInvalid = validationResult?.invalidNodeIds?.includes(node.id);
            const inputPorts = getInputPorts(node);
            const outputPorts = getOutputPorts(node);
            const def = NODE_DEFINITIONS[node.type];
            const canInteract = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

            let cursorClass = 'cursor-default';
            if (toolMode === 'interact' || isSimulating) {
                 cursorClass = canInteract ? 'cursor-pointer' : 'cursor-default';
            } else if (toolMode === 'select') {
                 cursorClass = 'cursor-grab active:cursor-grabbing';
            }

            return (
                <div
                    key={node.id}
                    className={`absolute group select-none transition-transform duration-75 ${isSelected ? 'scale-[1.02]' : ''}`}
                    style={{
                        left: node.position.x,
                        top: node.position.y,
                        width: width,
                        height: height,
                        pointerEvents: 'none',
                        zIndex: isSelected ? 50 : 10 
                    }}
                >
                    <div 
                        className={`absolute inset-0 pointer-events-auto transition-all duration-200 
                            ${isSelected ? 'drop-shadow-[0_0_12px_rgba(34,211,238,0.7)]' : ''} 
                            ${isInvalid ? 'drop-shadow-[0_0_8px_rgba(239,68,68,0.8)]' : ''}
                            ${cursorClass}
                        `}
                        onMouseDown={(e) => handleNodeMouseDown(e, node.id)}
                    >
                        <svg width={width} height={height} className="overflow-visible">
                            <GateShape node={node} />
                        </svg>
                    </div>

                    {isInvalid && (
                        <div className="absolute -top-3 -right-3 text-red-500 bg-white dark:bg-zinc-950 rounded-full p-0.5 shadow-md border border-red-200 dark:border-red-900 animate-bounce z-50">
                            <AlertTriangle size={14} fill="currentColor" className="text-red-100 dark:text-red-900" stroke="currentColor" />
                        </div>
                    )}

                    {inputPorts.map((offset, idx) => {
                        const isFloating = validationResult?.floatingInputs?.some(fi => fi.nodeId === node.id && fi.index === idx);
                        return (
                        <div
                            key={`input-${idx}`}
                            className="absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 cursor-crosshair"
                            style={{ left: offset.x, top: offset.y }}
                            onMouseUp={(e) => !isSimulating && completeWiring(e, node.id, idx)}
                            title={offset.label || "Input"}
                        >
                            <div className={`w-2 h-2 rounded-full bg-white dark:bg-zinc-900 border transition-all duration-300 ${
                                isFloating 
                                ? 'border-red-500 bg-red-500/50 ring-2 ring-red-500 ring-opacity-50 animate-pulse' 
                                : node.inputs[idx] ? 'border-cyan-400 bg-cyan-100 dark:bg-cyan-900' : 'border-zinc-400 dark:border-zinc-500'
                            }`} />
                        </div>
                        );
                    })}

                    {outputPorts.map((offset, idx) => (
                        <div
                            key={`output-${idx}`}
                            className="absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 cursor-crosshair"
                            style={{ left: offset.x, top: offset.y }}
                            onMouseDown={(e) => !isSimulating && startWiring(e, node.id, idx)}
                            title={offset.label || "Output"}
                        >
                            <div className={`w-2 h-2 rounded-full bg-white dark:bg-zinc-900 border ${node.outputs[idx] ? 'border-cyan-400 bg-cyan-500' : 'border-zinc-400 dark:border-zinc-500 group-hover:border-zinc-600 dark:group-hover:border-zinc-300'}`} />
                        </div>
                    ))}

                    {(isSelected || node.properties?.label) && node.type !== 'JUNCTION' && (
                        <div 
                            className={`absolute bg-white/90 dark:bg-zinc-900/90 text-zinc-800 dark:text-zinc-100 text-[10px] px-2 py-0.5 rounded border whitespace-nowrap shadow-md pointer-events-none backdrop-blur-sm z-[60] transition-colors
                            ${isSelected ? 'border-cyan-500 font-bold' : 'border-zinc-200 dark:border-zinc-700'}`}
                            style={getLabelStyle(node.properties?.labelPosition)}
                        >
                            {node.properties?.label || def.name}
                        </div>
                    )}
                </div>
            );
        })}

        {/* Ghost Component */}
        {pendingComponent && pendingDef && (
            <div 
                className="absolute pointer-events-none opacity-50 z-50"
                style={{ left: ghostSnapX, top: ghostSnapY, width: pendingDef.width, height: pendingDef.height }}
            >
                <svg width={pendingDef.width} height={pendingDef.height} className="overflow-visible">
                        <GateShape node={{ 
                        id: 'ghost', type: pendingComponent, position: {x: 0, y: 0}, inputs: Array(pendingDef.inputs).fill(false), outputs: Array(pendingDef.outputs).fill(false),
                        properties: { inputCount: pendingDef.inputs }
                    }} />
                </svg>
            </div>
        )}
    </div>
  );
};

import React from 'react';
import { NodeData, NodeType, Wire } from '../types';
import { Settings2, Hash, Type, Palette, Activity, Clock, AlignCenterVertical, MousePointerClick, Binary, Cable, Gauge } from 'lucide-react';
import { VARIABLE_INPUT_GATES } from '../utils/componentUtils';

interface PropertiesPanelProps {
  node: NodeData | null;
  wire: Wire | null;
  onUpdate: (id: string, updates: Partial<NodeData>) => void;
  onUpdateWire: (id: string, updates: Partial<Wire>) => void;
  width: number;
}

export const PropertiesPanel: React.FC<PropertiesPanelProps> = ({ node, wire, onUpdate, onUpdateWire, width }) => {
  if (!node && !wire) {
    return (
      <div 
        style={{ width }}
        className="bg-white dark:bg-zinc-900 border-l border-zinc-200 dark:border-zinc-800 p-6 flex flex-col items-center justify-center text-zinc-400 dark:text-zinc-500 h-full select-none transition-colors duration-300 flex-shrink-0"
      >
         <Settings2 size={32} className="mb-3 opacity-50" />
         <p className="text-sm font-medium">No Selection</p>
         <p className="text-xs text-zinc-500 dark:text-zinc-600 text-center mt-1">Select a component to edit its attributes.</p>
      </div>
    );
  }

  // --- Helpers ---
  const renderRow = (label: string, icon: React.ReactNode, control: React.ReactNode) => (
      <div className="flex flex-col py-2 border-b border-zinc-100 dark:border-zinc-800/50 last:border-0">
          <div className="flex items-center justify-between mb-1">
              <div className="flex items-center gap-2 text-zinc-600 dark:text-zinc-400">
                  {icon}
                  <span className="text-xs font-medium">{label}</span>
              </div>
              <div className="flex justify-end">
                  {control}
              </div>
          </div>
      </div>
  );

  const renderSimpleRow = (label: string, icon: React.ReactNode, control: React.ReactNode) => (
    <div className="flex items-center justify-between py-2 border-b border-zinc-100 dark:border-zinc-800/50 last:border-0">
        <div className="flex items-center gap-2 text-zinc-600 dark:text-zinc-400">
            {icon}
            <span className="text-xs font-medium">{label}</span>
        </div>
        <div className="w-1/2 flex justify-end">
            {control}
        </div>
    </div>
);

  // --- WIRE RENDERER ---
  if (wire) {
      return (
        <div 
            style={{ width }}
            className="bg-white dark:bg-zinc-900 border-l border-zinc-200 dark:border-zinc-800 flex flex-col h-full shadow-xl transition-colors duration-300 flex-shrink-0"
        >
           <div className="h-14 flex items-center px-4 border-b border-zinc-200 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50">
              <div className="flex items-center gap-2">
                 <Cable size={16} className="text-cyan-600 dark:text-cyan-400" />
                 <span className="font-semibold text-sm text-zinc-800 dark:text-zinc-200">Wire Attributes</span>
              </div>
           </div>

           <div className="flex-1 overflow-y-auto p-4">
              <div className="mb-6">
                  <h3 className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider mb-2">Appearance</h3>
                  <div className="bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-lg px-3 shadow-sm">
                      {renderSimpleRow(
                          "Color (Inactive)", 
                          <Palette size={14} />, 
                          <div className="flex items-center gap-2">
                            <input 
                                type="color" 
                                value={wire.color || '#52525b'} 
                                onChange={(e) => onUpdateWire(wire.id, { color: e.target.value })}
                                className="w-5 h-5 rounded cursor-pointer border-0 p-0 bg-transparent"
                            />
                            <span className="text-[10px] font-mono text-zinc-400">{wire.color || 'Default'}</span>
                          </div>
                      )}
                  </div>
              </div>

              <div className="mb-6">
                  <h3 className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider mb-2">Status</h3>
                  <div className="bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-lg px-3 shadow-sm">
                        {renderSimpleRow(
                            "Signal State",
                            <Activity size={14} />,
                            <span className={`text-xs font-bold ${wire.state ? 'text-cyan-500' : 'text-zinc-500'}`}>
                                {wire.state ? 'HIGH (1)' : 'LOW (0)'}
                            </span>
                        )}
                  </div>
              </div>

              <div className="text-xs text-zinc-400 dark:text-zinc-600 italic text-center mt-8">
                 ID: {wire.id.split('-')[1]}...
              </div>
           </div>
        </div>
      );
  }

  // --- COMPONENT RENDERER ---
  const isGate = VARIABLE_INPUT_GATES.includes(node!.type) || ['BUFFER', 'NOT'].includes(node!.type);
  const isStateful = ['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'D_LATCH', 'JK_MASTER_SLAVE', 'SHIFT_REGISTER_4BIT'].includes(node!.type);
  const isSwitch = ['SWITCH'].includes(node!.type);
  const isClock = node!.type === 'CLOCK';
  const isROM = node!.type === 'ROM_1BIT';
  const isEdgeTriggered = ['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'SHIFT_REGISTER_4BIT'].includes(node!.type);

  const isMultiBitInput = node!.type.startsWith('INPUT_') && node!.type.includes('BIT');
  const isMultiBitOutput = node!.type.startsWith('OUTPUT_') && node!.type.includes('BIT');
  const isMultiBit = isMultiBitInput || isMultiBitOutput;

  // --- Helpers for Node ---
  const getMultiBitValue = (bools: boolean[]) => {
      return bools.reduce((acc, b, i) => acc + (b ? Math.pow(2, i) : 0), 0);
  };

  const boolsToBinStr = (bools: boolean[]) => {
      return bools.map(b => b ? '1' : '0').reverse().join('');
  }

  const updateMultiBitValue = (val: number, bitCount: number) => {
      const newOutputs = [];
      for(let i=0; i<bitCount; i++) {
          newOutputs.push(!!((val >> i) & 1));
      }
      onUpdate(node!.id, { outputs: newOutputs });
  };

  const updateProp = (key: string, value: any) => {
      onUpdate(node!.id, { properties: { ...node!.properties, [key]: value } });
  };

  const handleBitWidthChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      const width = parseInt(e.target.value);
      let newType = node!.type;
      if (isMultiBitInput) newType = `INPUT_${width}BIT` as NodeType;
      else if (isMultiBitOutput) newType = `OUTPUT_${width}BIT` as NodeType;

      if (newType !== node!.type) {
          onUpdate(node!.id, { type: newType });
      }
  };

  const getBitWidth = (type: NodeType) => {
      if (type.includes('2BIT')) return 2;
      if (type.includes('4BIT')) return 4;
      if (type.includes('8BIT')) return 8;
      if (type.includes('16BIT')) return 16;
      return 0;
  };

  // Clock frequency calculation (assuming 50ms tick from App.tsx)
  const calculateFrequency = (interval: number) => {
      if (interval <= 0) return 0;
      // Full cycle is 2 * interval ticks.
      // Frequency f = 1 / (2 * interval * 0.05s)
      return (10 / interval).toFixed(2);
  };

  return (
    <div 
        style={{ width }}
        className="bg-white dark:bg-zinc-900 border-l border-zinc-200 dark:border-zinc-800 flex flex-col h-full shadow-xl transition-colors duration-300 flex-shrink-0"
    >
       <div className="h-14 flex items-center px-4 border-b border-zinc-200 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50">
          <div className="flex items-center gap-2">
             <Settings2 size={16} className="text-cyan-600 dark:text-cyan-400" />
             <span className="font-semibold text-sm text-zinc-800 dark:text-zinc-200">Attributes</span>
          </div>
          <div className="ml-auto text-[10px] font-mono text-zinc-400 bg-zinc-100 dark:bg-zinc-800 px-2 py-0.5 rounded">
              {node!.type}
          </div>
       </div>

       <div className="flex-1 overflow-y-auto p-4">

          {/* Group: Common */}
          <div className="mb-6">
              <h3 className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider mb-2">Common</h3>
              <div className="bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-lg px-3 shadow-sm">
                  {renderSimpleRow(
                      "Label", 
                      <Type size={14} />, 
                      <input 
                          type="text" 
                          value={node!.properties?.label || ''} 
                          onChange={(e) => updateProp('label', e.target.value)}
                          className="w-full bg-transparent text-right text-xs focus:outline-none text-zinc-800 dark:text-zinc-200 placeholder-zinc-400"
                          placeholder="Name"
                      />
                  )}
                  {renderSimpleRow(
                      "Label Position", 
                      <AlignCenterVertical size={14} />, 
                      <select 
                          value={node!.properties?.labelPosition || 'Top'}
                          onChange={(e) => updateProp('labelPosition', e.target.value)}
                          className="bg-transparent text-right text-xs focus:outline-none text-zinc-800 dark:text-zinc-200 cursor-pointer"
                      >
                          <option value="Top">Top</option>
                          <option value="Bottom">Bottom</option>
                          <option value="Left">Left</option>
                          <option value="Right">Right</option>
                      </select>
                  )}
                   {renderSimpleRow(
                      "Color", 
                      <Palette size={14} />, 
                      <div className="flex items-center gap-2">
                        <input 
                            type="color" 
                            value={node!.properties?.color || '#18181b'} 
                            onChange={(e) => updateProp('color', e.target.value)}
                            className="w-5 h-5 rounded cursor-pointer border-0 p-0 bg-transparent"
                        />
                        <span className="text-[10px] font-mono text-zinc-400">{node!.properties?.color || 'Default'}</span>
                      </div>
                  )}
              </div>
          </div>

          {/* Group: Value (For Multi-bit) */}
          {isMultiBitInput && (
              <div className="mb-6">
                  <h3 className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider mb-2">Value</h3>
                  <div className="bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-lg px-3 shadow-sm">
                        {renderSimpleRow(
                            "Decimal",
                            <Hash size={14} />,
                            <input
                                type="number"
                                min="0"
                                max={Math.pow(2, node!.outputs.length) - 1}
                                value={getMultiBitValue(node!.outputs)}
                                onChange={(e) => {
                                    const val = parseInt(e.target.value);
                                    if (!isNaN(val)) updateMultiBitValue(val, node!.outputs.length);
                                }}
                                className="w-full bg-transparent text-right text-xs focus:outline-none text-zinc-800 dark:text-zinc-200 font-mono"
                            />
                        )}
                         {renderSimpleRow(
                            "Binary",
                            <Binary size={14} />,
                            <span className="text-[10px] font-mono text-zinc-500">{boolsToBinStr(node!.outputs)}</span>
                        )}
                  </div>
              </div>
          )}

           {isMultiBitOutput && (
              <div className="mb-6">
                  <h3 className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider mb-2">State</h3>
                  <div className="bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-lg px-3 shadow-sm">
                        {renderSimpleRow(
                            "Decimal",
                            <Hash size={14} />,
                            <span className="text-xs font-mono text-zinc-800 dark:text-zinc-200">{getMultiBitValue(node!.inputs)}</span>
                        )}
                        {renderSimpleRow(
                            "Hex",
                            <Hash size={14} />,
                            <span className="text-xs font-mono text-cyan-600 dark:text-cyan-400">0x{getMultiBitValue(node!.inputs).toString(16).toUpperCase()}</span>
                        )}
                         {renderSimpleRow(
                            "Binary",
                            <Binary size={14} />,
                            <span className="text-[10px] font-mono text-zinc-500 truncate max-w-[100px] text-right block" title={boolsToBinStr(node!.inputs)}>{boolsToBinStr(node!.inputs)}</span>
                        )}
                  </div>
              </div>
          )}

          {/* Group: Simulation */}
          <div className="mb-6">
              <h3 className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider mb-2">Simulation</h3>
              <div className="bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-lg px-3 shadow-sm">

                  {VARIABLE_INPUT_GATES.includes(node!.type) && renderSimpleRow(
                      "Input Count", 
                      <Hash size={14} />, 
                      <select 
                          value={node!.properties?.inputCount || 2}
                          onChange={(e) => updateProp('inputCount', parseInt(e.target.value))}
                          className="bg-transparent text-right text-xs focus:outline-none text-zinc-800 dark:text-zinc-200"
                      >
                          {[2,3,4,5,6,8].map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                  )}

                  {isMultiBit && renderSimpleRow(
                      "Data Bits", 
                      <Hash size={14} />, 
                      <select 
                          value={getBitWidth(node!.type)}
                          onChange={handleBitWidthChange}
                          className="bg-transparent text-right text-xs focus:outline-none text-zinc-800 dark:text-zinc-200"
                      >
                          {[2,4,8,16].map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                  )}

                  {isGate && renderSimpleRow(
                      "Delay (ms)", 
                      <Activity size={14} />, 
                      <input 
                          type="number"
                          min="0"
                          value={node!.properties?.propagationDelay || 0}
                          onChange={(e) => updateProp('propagationDelay', parseInt(e.target.value) || 0)}
                          className="w-16 bg-transparent text-right text-xs focus:outline-none text-zinc-800 dark:text-zinc-200"
                      />
                  )}

                  {(isStateful || isSwitch) && renderSimpleRow(
                      "Initial State", 
                      <MousePointerClick size={14} />, 
                      <input 
                          type="checkbox"
                          checked={!!node!.properties?.initialState}
                          onChange={(e) => updateProp('initialState', e.target.checked)}
                          className="rounded border-zinc-300 text-cyan-500 focus:ring-0"
                      />
                  )}

                  {isEdgeTriggered && renderSimpleRow(
                      "Trigger", 
                      <Activity size={14} />, 
                      <select 
                          value={node!.properties?.trigger || 'Rising'}
                          onChange={(e) => updateProp('trigger', e.target.value)}
                          className="bg-transparent text-right text-xs focus:outline-none text-zinc-800 dark:text-zinc-200"
                      >
                          <option value="Rising">Rising Edge</option>
                          <option value="Falling">Falling Edge</option>
                      </select>
                  )}

                  {isROM && renderSimpleRow(
                      "ROM Value", 
                      <Hash size={14} />, 
                      <input 
                          type="checkbox"
                          checked={!!node!.properties?.romValue}
                          onChange={(e) => updateProp('romValue', e.target.checked)}
                          className="rounded border-zinc-300 text-cyan-500 focus:ring-0"
                      />
                  )}

                   {isClock && (
                     <>
                      {renderRow(
                          "Clock Interval", 
                          <Clock size={14} />, 
                          <span className="text-xs font-mono text-zinc-500">{node!.properties?.interval || 20} ticks</span>
                      )}
                      <div className="px-1 pb-4">
                        <input 
                            type="range"
                            min="1"
                            max="100"
                            step="1"
                            value={node!.properties?.interval || 20}
                            onChange={(e) => updateProp('interval', parseInt(e.target.value))}
                            className="w-full h-1.5 bg-zinc-200 dark:bg-zinc-800 rounded-lg appearance-none cursor-pointer accent-cyan-500"
                        />
                        <div className="flex justify-between mt-2 px-1">
                            <span className="text-[9px] text-zinc-500 uppercase font-bold">Fast</span>
                            <span className="text-[9px] text-zinc-500 uppercase font-bold">Slow</span>
                        </div>
                      </div>
                      {renderSimpleRow(
                          "Pulse Speed", 
                          <Gauge size={14} />, 
                          <span className="text-xs font-mono text-cyan-600 dark:text-cyan-400 font-bold">{calculateFrequency(node!.properties?.interval || 20)} Hz</span>
                      )}
                     </>
                   )}
              </div>
          </div>

          <div className="text-xs text-zinc-400 dark:text-zinc-600 italic text-center mt-8">
             ID: {node!.id.split('-')[1]}...
          </div>

       </div>
    </div>
  );
};

import React, { useRef, useState, useEffect } from 'react';
import { GRID_SIZE, NODE_DEFINITIONS } from '../constants';
import { CircuitState, NodeData, NodeType, Wire, Point, WiringState } from '../types';
import { GateShape } from './GateShapes';
import { getNodeDimensions, getInputPorts, getOutputPorts } from '../utils/componentUtils';
import { CheckCircle2, AlertTriangle } from 'lucide-react';
import { useTheme } from './ThemeContext';

interface CircuitCanvasProps {
    circuit: CircuitState;
    onUpdateCircuit: (nodes: NodeData[], wires: Wire[]) => void;
    onCommit: () => void;
    selectedId: string | null;
    setSelectedId: (id: string | null) => void;
    pendingComponent: NodeType | null;
    setPendingComponent: (type: NodeType | null) => void;
    toolMode: 'select' | 'interact' | 'junction';
    wireMode: 'manhattan' | 'bezier';
    isSimulating: boolean;
    validationResult: {
        valid: boolean;
        messages: string[];
        invalidNodeIds: string[];
        floatingInputs: { nodeId: string; index: number }[];
    } | null;
    setValidationResult: (res: any) => void;
}

export const CircuitCanvas: React.FC<CircuitCanvasProps> = ({ 
    circuit, onUpdateCircuit, onCommit,
    selectedId, setSelectedId,
    pendingComponent, setPendingComponent,
    toolMode, wireMode, isSimulating,
    validationResult, setValidationResult
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const { theme } = useTheme();

  // Local Interaction State
  const [draggingNodeId, setDraggingNodeId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<Point>({ x: 0, y: 0 });
  const [wiring, setWiring] = useState<WiringState | null>(null);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });

  // --- Keyboard Shortcuts ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
            if (pendingComponent) setPendingComponent(null);
            if (wiring) setWiring(null);
            if (selectedId) setSelectedId(null);
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [pendingComponent, wiring, selectedId, setPendingComponent, setSelectedId]);


  const addNode = (type: NodeType, x: number, y: number) => {
    onCommit();
    const def = NODE_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newNode: NodeData = {
      id: `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      position: { x: snapX, y: snapY },
      inputs: Array(def.inputs).fill(false),
      outputs: Array(def.outputs).fill(false),
      internalState: {},
      properties: {
          label: '',
          labelPosition: 'Top',
          inputCount: def.inputs,
          propagationDelay: 0,
          initialState: false,
          romValue: false,
          interval: type === 'CLOCK' ? 20 : 0
      }
    };

    onUpdateCircuit([...circuit.nodes, newNode], circuit.wires);
    setSelectedId(newNode.id);
  };

  // --- Interaction Handlers ---

  const handleNodeMouseDown = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();

    // Select immediately on mousedown
    setSelectedId(id);

    if (wiring || pendingComponent) return; 

    const node = circuit.nodes.find(n => n.id === id);
    if (!node) return;

    const isInteractive = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

    if (toolMode === 'interact' || isSimulating) {
        if (isInteractive) {
            if (!isSimulating) onCommit();
            let toggledNodes = circuit.nodes;

            if (node.type.startsWith('INPUT_')) {
                const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
                const relY = e.clientY - rect.top; 
                const relX = e.clientX - rect.left;
                const { width, height } = getNodeDimensions(node);
                const bitCount = node.outputs.length;

                if (relY < 25) {
                    const inputVal = window.prompt(`Set Value for ${bitCount}-bit Input:`);
                    if (inputVal !== null) {
                        let val = parseInt(inputVal);
                        if (!isNaN(val)) {
                            const newOutputs = [];
                            for(let i=0; i<bitCount; i++) {
                                newOutputs.push(!!((val >> i) & 1));
                            }
                            toggledNodes = circuit.nodes.map(n => n.id === id ? { ...n, outputs: newOutputs } : n);
                            onUpdateCircuit(toggledNodes, circuit.wires);
                        }
                    }
                    return;
                }

                let bitIndexToCheck = -1;
                if (relY > height - 30) {
                    const bitWidth = 10;
                    const bitSpacing = 2;
                    const nibbleGap = 6;
                    const totalWidth = bitCount * bitWidth + (bitCount - 1) * bitSpacing + Math.floor((bitCount - 1) / 4) * nibbleGap;
                    const startX = (width - totalWidth) / 2 + bitWidth / 2;
                    for (let i = 0; i < bitCount; i++) {
                        const nibblesBefore = Math.floor(i / 4);
                        const xPos = startX + i * (bitWidth + bitSpacing) + nibblesBefore * nibbleGap;
                        if (Math.abs(relX - xPos) < 8) {
                            bitIndexToCheck = bitCount - 1 - i;
                            break;
                        }
                    }
                } else {
                    const rowIdx = Math.floor((relY - 25) / 20);
                    if (rowIdx >= 0 && rowIdx < bitCount) bitIndexToCheck = rowIdx;
                }

                if (bitIndexToCheck >= 0 && bitIndexToCheck < bitCount) {
                    toggledNodes = circuit.nodes.map(n => {
                        if (n.id === id) {
                            const newOutputs = [...n.outputs];
                            newOutputs[bitIndexToCheck] = !newOutputs[bitIndexToCheck];
                            return { ...n, outputs: newOutputs };
                        }
                        return n;
                    });
                }
            } else {
                toggledNodes = circuit.nodes.map(n => {
                    if (n.id === id) {
                        const newState = !n.outputs[0];
                        return { ...n, outputs: [newState] };
                    }
                    return n;
                });
            }
            onUpdateCircuit(toggledNodes, circuit.wires);
            return;
        }
    }

    if (toolMode === 'select' || toolMode === 'junction') {
        onCommit();
        setDraggingNodeId(id);
        const rect = containerRef.current!.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;
        setDragOffset({
            x: mouseX - node.position.x,
            y: mouseY - node.position.y
        });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    if (draggingNodeId) {
        const snapX = Math.round((x - dragOffset.x) / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round((y - dragOffset.y) / GRID_SIZE) * GRID_SIZE;

        const updatedNodes = circuit.nodes.map(n => {
            if (n.id === draggingNodeId) {
                return { ...n, position: { x: snapX, y: snapY }};
            }
            return n;
        });
        onUpdateCircuit(updatedNodes, circuit.wires);
    }
  };

  const handleMouseUp = () => {
    setDraggingNodeId(null);
    setWiring(null);
  };

  const startWiring = (e: React.MouseEvent, nodeId: string, outputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();
    if (toolMode === 'interact' && !isSimulating) return; 

    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setWiring({
        sourceNodeId: nodeId,
        sourceOutputIndex: outputIndex,
        startPoint: { x, y },
        active: true
    });
  };

  const completeWiring = (e: React.MouseEvent, targetNodeId: string, inputIndex: number) => {
    e.stopPropagation();
    e.preventDefault();
    if (!wiring) return;
    if (wiring.sourceNodeId === targetNodeId) {
        setWiring(null);
        return;
    }

    onCommit();
    const exists = circuit.wires.some(w => w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex);
    let newWires = exists ? circuit.wires.filter(w => !(w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex)) : [...circuit.wires];

    newWires.push({
        id: `wire-${Date.now()}`,
        sourceNodeId: wiring.sourceNodeId,
        sourceOutputIndex: wiring.sourceOutputIndex,
        targetNodeId: targetNodeId,
        targetInputIndex: inputIndex,
        state: false
    });

    onUpdateCircuit(circuit.nodes, newWires);
    setWiring(null);
  };

  const handleWireClick = (e: React.MouseEvent, wire: Wire) => {
    e.stopPropagation();
    setSelectedId(wire.id);

    if (toolMode === 'junction') {
        const rect = containerRef.current!.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        onCommit();

        const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;
        const junctionId = `node-${Date.now()}-junction`;

        const newJunction: NodeData = {
            id: junctionId,
            type: 'JUNCTION',
            position: { x: snapX - 5, y: snapY - 5 },
            inputs: [false],
            outputs: [false],
            properties: { label: '' }
        };

        const wire1: Wire = {
            id: `wire-${Date.now()}-1`,
            sourceNodeId: wire.sourceNodeId,
            sourceOutputIndex: wire.sourceOutputIndex,
            targetNodeId: junctionId,
            targetInputIndex: 0,
            state: wire.state
        };
        const wire2: Wire = {
            id: `wire-${Date.now()}-2`,
            sourceNodeId: junctionId,
            sourceOutputIndex: 0,
            targetNodeId: wire.targetNodeId,
            targetInputIndex: wire.targetInputIndex,
            state: wire.state
        };

        const newWires = circuit.wires.filter(w => w.id !== wire.id).concat([wire1, wire2]);
        const newNodes = [...circuit.nodes, newJunction];
        onUpdateCircuit(newNodes, newWires);
        setSelectedId(junctionId);
    }
  };

  const handleCanvasClick = (e: React.MouseEvent) => {
      if (pendingComponent && containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        addNode(pendingComponent, x, y);
        setPendingComponent(null);
        return;
      }
      // Only deselect if we clicked the actual background
      setSelectedId(null);
      if (validationResult?.valid) setValidationResult(null);
  };

  const getWirePath = (x1: number, y1: number, x2: number, y2: number) => {
    if (wireMode === 'bezier') {
        const dist = Math.abs(x2 - x1);
        const controlPointOffset = Math.max(dist * 0.5, 50);
        return `M ${x1} ${y1} C ${x1 + controlPointOffset} ${y1}, ${x2 - controlPointOffset} ${y2}, ${x2} ${y2}`;
    }
    const dx = x2 - x1;
    if (dx > 20) {
        const midX = (x1 + x2) / 2;
        return `M ${x1} ${y1} L ${midX} ${y1} L ${midX} ${y2} L ${x2} ${y2}`;
    }
    const stub = 20;
    const midY = (y1 + y2) / 2;
    return `M ${x1} ${y1} L ${x1 + stub} ${y1} L ${x1 + stub} ${midY} L ${x2 - stub} ${midY} L ${x2 - stub} ${y2} L ${x2} ${y2}`;
  };

  const getLabelStyle = (pos: string | undefined): React.CSSProperties => {
      switch (pos) {
          case 'Bottom': return { top: '100%', left: '50%', transform: 'translate(-50%, 8px)' };
          case 'Left': return { top: '50%', right: '100%', transform: 'translate(-8px, -50%)' };
          case 'Right': return { top: '50%', left: '100%', transform: 'translate(8px, -50%)' };
          case 'Top': default: return { bottom: '100%', left: '50%', transform: 'translate(-50%, -8px)' };
      }
  };

  const ghostSnapX = Math.round(mousePos.x / GRID_SIZE) * GRID_SIZE;
  const ghostSnapY = Math.round(mousePos.y / GRID_SIZE) * GRID_SIZE;
  const pendingDef = pendingComponent ? NODE_DEFINITIONS[pendingComponent] : null;

  return (
    <div 
        ref={containerRef}
        className={`flex-1 relative w-full h-full overflow-hidden bg-zinc-50 dark:bg-zinc-950
            ${isSimulating ? 'cursor-default' : pendingComponent ? 'cursor-cell' : 'cursor-crosshair'}`}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onClick={handleCanvasClick}
        onContextMenu={(e) => e.preventDefault()}
    >
        {/* Grid Pattern */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full opacity-20 dark:opacity-20">
            <defs>
                <pattern id="grid" width={GRID_SIZE} height={GRID_SIZE} patternUnits="userSpaceOnUse">
                    <circle cx="1" cy="1" r="1" className="fill-zinc-400 dark:fill-zinc-500" />
                </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#grid)" />
        </svg>

        {/* Connections */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
            {circuit.wires.map(wire => {
                const sourceNode = circuit.nodes.find(n => n.id === wire.sourceNodeId);
                const targetNode = circuit.nodes.find(n => n.id === wire.targetNodeId);
                if (!sourceNode || !targetNode) return null;

                const sourcePorts = getOutputPorts(sourceNode);
                const targetPorts = getInputPorts(targetNode);

                const outputOffset = sourcePorts[wire.sourceOutputIndex] || { x: 0, y: 0 };
                const inputOffset = targetPorts[wire.targetInputIndex] || { x: 0, y: 0 };

                const startX = sourceNode.position.x + outputOffset.x;
                const startY = sourceNode.position.y + outputOffset.y;
                const endX = targetNode.position.x + inputOffset.x;
                const endY = targetNode.position.y + inputOffset.y;

                const isSelected = selectedId === wire.id;
                const pathData = getWirePath(startX, startY, endX, endY);

                const inactiveColor = wire.color || (theme === 'dark' ? "#52525b" : "#a1a1aa");
                const activeColor = "#22d3ee";
                const strokeColor = wire.state ? activeColor : (isSelected ? "#22d3ee" : inactiveColor);

                return (
                    <g 
                        key={wire.id} 
                        onClick={(e) => handleWireClick(e, wire)} 
                        className={`pointer-events-auto cursor-pointer group`}
                    >
                        <path d={pathData} stroke="transparent" strokeWidth="12" fill="none" />
                        {wire.state && <path d={pathData} stroke={activeColor} strokeWidth="4" fill="none" opacity="0.3" filter="blur(2px)" />}
                        <path d={pathData} stroke={strokeColor} strokeWidth={isSelected ? "3" : "2"} fill="none" className="transition-all duration-150" strokeDasharray={isSelected ? "4" : "0"} strokeLinejoin="round" strokeLinecap="round" />
                    </g>
                );
            })}

            {wiring && (
                <path d={getWirePath(wiring.startPoint.x, wiring.startPoint.y, mousePos.x, mousePos.y)} stroke="#fbbf24" strokeWidth="2" fill="none" strokeDasharray="4" className="animate-pulse" strokeLinejoin="round" />
            )}
        </svg>

        {/* Nodes */}
        {circuit.nodes.map(node => {
            const { width, height } = getNodeDimensions(node);
            const isSelected = selectedId === node.id;
            const isInvalid = validationResult?.invalidNodeIds?.includes(node.id);
            const inputPorts = getInputPorts(node);
            const outputPorts = getOutputPorts(node);
            const def = NODE_DEFINITIONS[node.type];
            const canInteract = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

            let cursorClass = 'cursor-default';
            if (toolMode === 'interact' || isSimulating) {
                 cursorClass = canInteract ? 'cursor-pointer' : 'cursor-default';
            } else if (toolMode === 'select') {
                 cursorClass = 'cursor-grab active:cursor-grabbing';
            }

            return (
                <div
                    key={node.id}
                    className={`absolute group select-none transition-transform duration-75 ${isSelected ? 'scale-[1.02]' : ''}`}
                    style={{
                        left: node.position.x,
                        top: node.position.y,
                        width: width,
                        height: height,
                        pointerEvents: 'none',
                        zIndex: isSelected ? 50 : 10 
                    }}
                    onClick={(e) => e.stopPropagation()} // Stop bubbling to canvas background
                >
                    <div 
                        className={`absolute inset-0 pointer-events-auto transition-all duration-200 
                            ${isSelected ? 'drop-shadow-[0_0_12px_rgba(34,211,238,0.7)]' : ''} 
                            ${isInvalid ? 'drop-shadow-[0_0_8px_rgba(239,68,68,0.8)]' : ''}
                            ${cursorClass}
                        `}
                        onMouseDown={(e) => handleNodeMouseDown(e, node.id)}
                    >
                        <svg width={width} height={height} className="overflow-visible">
                            <GateShape node={node} />
                        </svg>
                    </div>

                    {isInvalid && (
                        <div className="absolute -top-3 -right-3 text-red-500 bg-white dark:bg-zinc-950 rounded-full p-0.5 shadow-md border border-red-200 dark:border-red-900 animate-bounce z-50">
                            <AlertTriangle size={14} fill="currentColor" className="text-red-100 dark:text-red-900" stroke="currentColor" />
                        </div>
                    )}

                    {inputPorts.map((offset, idx) => {
                        const isFloating = validationResult?.floatingInputs?.some(fi => fi.nodeId === node.id && fi.index === idx);
                        return (
                        <div
                            key={`input-${idx}`}
                            className="absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 cursor-crosshair"
                            style={{ left: offset.x, top: offset.y }}
                            onMouseUp={(e) => !isSimulating && completeWiring(e, node.id, idx)}
                            title={offset.label || "Input"}
                        >
                            <div className={`w-2 h-2 rounded-full bg-white dark:bg-zinc-900 border transition-all duration-300 ${
                                isFloating 
                                ? 'border-red-500 bg-red-500/50 ring-2 ring-red-500 ring-opacity-50 animate-pulse' 
                                : node.inputs[idx] ? 'border-cyan-400 bg-cyan-100 dark:bg-cyan-900' : 'border-zinc-400 dark:border-zinc-500'
                            }`} />
                        </div>
                        );
                    })}

                    {outputPorts.map((offset, idx) => (
                        <div
                            key={`output-${idx}`}
                            className="absolute w-4 h-4 -ml-2 -mt-2 rounded-full pointer-events-auto flex items-center justify-center hover:scale-150 transition-transform z-10 cursor-crosshair"
                            style={{ left: offset.x, top: offset.y }}
                            onMouseDown={(e) => !isSimulating && startWiring(e, node.id, idx)}
                            title={offset.label || "Output"}
                        >
                            <div className={`w-2 h-2 rounded-full bg-white dark:bg-zinc-900 border ${node.outputs[idx] ? 'border-cyan-400 bg-cyan-500' : 'border-zinc-400 dark:border-zinc-500 group-hover:border-zinc-600 dark:group-hover:border-zinc-300'}`} />
                        </div>
                    ))}

                    {(isSelected || node.properties?.label) && node.type !== 'JUNCTION' && (
                        <div 
                            className={`absolute bg-white/90 dark:bg-zinc-900/90 text-zinc-800 dark:text-zinc-100 text-[10px] px-2 py-0.5 rounded border whitespace-nowrap shadow-md pointer-events-none backdrop-blur-sm z-[60] transition-colors
                            ${isSelected ? 'border-cyan-500 font-bold' : 'border-zinc-200 dark:border-zinc-700'}`}
                            style={getLabelStyle(node.properties?.labelPosition)}
                        >
                            {node.properties?.label || def.name}
                        </div>
                    )}
                </div>
            );
        })}

        {/* Ghost Component */}
        {pendingComponent && pendingDef && (
            <div 
                className="absolute pointer-events-none opacity-50 z-50"
                style={{ left: ghostSnapX, top: ghostSnapY, width: pendingDef.width, height: pendingDef.height }}
            >
                <svg width={pendingDef.width} height={pendingDef.height} className="overflow-visible">
                        <GateShape node={{ 
                        id: 'ghost', type: pendingComponent, position: {x: 0, y: 0}, inputs: Array(pendingDef.inputs).fill(false), outputs: Array(pendingDef.outputs).fill(false),
                        properties: { inputCount: pendingDef.inputs }
                    }} />
                </svg>
            </div>
        )}
    </div>
  );
};

import { NodeType } from './types';

export const GRID_SIZE = 20;

// Helper to generate port offsets for multi-bit components
// startY aligns with the center of the first bit's row (Header height + half-row)
const generatePorts = (count: number, x: number, startY: number = 40) => {
    return Array.from({ length: count }, (_, i) => ({
        x,
        y: startY + (i * 20),
        label: `${i}`
    }));
};

// Calculated heights: Header (30) + Rows (count * 20) + Footer (40)
const getMbHeight = (count: number) => 30 + (count * 20) + 40;

// Helper to generate RAM definitions
const ADDRESS_BITS = 4;
const getRamDefinition = (dataBits: number, name: string) => {
    const inputs = ADDRESS_BITS + dataBits + 2; // + WE, + CS
    const outputs = dataBits;

    // Layout: 
    // Header (30)
    // Address Pins (4 * 20)
    // Spacer (10)
    // Data Pins (dataBits * 20)
    // Spacer (10)
    // Control Pins (2 * 20)
    // Footer (20)

    const height = 30 + (ADDRESS_BITS * 20) + 10 + (dataBits * 20) + 10 + (2 * 20) + 20;
    const width = 140;

    const inputOffsets = [];
    let currentY = 40; // Start inside first row (30 + 10)

    // Address pins
    for(let i=0; i<ADDRESS_BITS; i++) {
        inputOffsets.push({ x: 0, y: currentY, label: `A${i}` });
        currentY += 20;
    }

    currentY += 10; // Spacer

    // Data In pins
    for(let i=0; i<dataBits; i++) {
        inputOffsets.push({ x: 0, y: currentY, label: `D${i}` });
        currentY += 20;
    }

    currentY += 10; // Spacer

    // Controls
    inputOffsets.push({ x: 0, y: currentY, label: 'WE' });
    currentY += 20;
    inputOffsets.push({ x: 0, y: currentY, label: 'CS' });

    const outputOffsets = [];
    let outStartY = 30 + (ADDRESS_BITS * 20) + 10 + 10; 
    for(let i=0; i<dataBits; i++) {
        outputOffsets.push({ x: width, y: outStartY + (i*20), label: `Q${i}` });
    }

    return { width, height, inputs, outputs, inputOffsets, outputOffsets, name };
};

