            <g>
                <rect x="0" y="0" width="100" height="120" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={50} y={15}>SHIFT REG 4b</GateText>
                <GateText x={10} y={30}>D</GateText> 
                <path d="M 0 85 L 10 90 L 0 95" fill="none" stroke="#71717a" />
                <rect x="30" y="40" width="15" height="40" fill={regReg[0] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />
                <rect x="45" y="40" width="15" height="40" fill={regReg[1] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />
                <rect x="60" y="40" width="15" height="40" fill={regReg[2] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />
                <rect x="75" y="40" width="15" height="40" fill={regReg[3] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />
                <GateText x={90} y={20}>Q0</GateText> <GateText x={90} y={50}>Q1</GateText>
                <GateText x={90} y={80}>Q2</GateText> <GateText x={90} y={110}>Q3</GateText>
            </g>
        );

    case 'RAM_4BIT':
    case 'RAM_8BIT':
    case 'RAM_16BIT':
        const dBits = type === 'RAM_4BIT' ? 4 : (type === 'RAM_8BIT' ? 8 : 16);
        const aBits = 4;
        let addrAddr = 0;
        for(let i=0; i<aBits; i++) {
            if (node.inputs[i]) addrAddr += Math.pow(2, i);
        }
        const WE_WE = node.inputs[aBits + dBits];
        const CS_CS = node.inputs[aBits + dBits + 1];
        const mem_mem = node.internalState?.memory || [];
        const sVal = mem_mem[addrAddr] || 0;
        let sStat = "IDLE";
        if (CS_CS) {
            sStat = WE_WE ? "WRITE" : "READ";
        } else {
            sStat = "OFF";
        }
        return (
            <g>
                <rect x="0" y="0" width={width} height={height} rx="4" fill="#09090b" stroke="#52525b" strokeWidth="2" />
                <GateText x={width/2} y={15} fill="#e4e4e7" fontSize="12">{type.replace('_', ' ')}</GateText>
                <rect x="40" y="35" width={width - 80} height="40" rx="2" fill="#000" stroke="#3f3f46" />
                <GateText x={width/2} y={47} fill="#71717a" fontSize="9">ADDR</GateText>
                <GateText x={width/2} y={63} fill="#22d3ee" fontSize="12" >{`0x${addrAddr.toString(16).toUpperCase()}`}</GateText>
                <rect x="40" y="80" width={width - 80} height="40" rx="2" fill="#000" stroke="#3f3f46" />
                <GateText x={width/2} y={92} fill="#71717a" fontSize="9">DATA</GateText>
                <GateText x={width/2} y={108} fill="#ef4444" fontSize="12">{`0x${sVal.toString(16).toUpperCase().padStart(dBits > 8 ? 4 : 2, '0')}`}</GateText>
                <rect x="40" y="125" width={width - 80} height="16" rx="2" fill={CS_CS ? (WE_WE ? "#7f1d1d" : "#064e3b") : "#27272a"} />
                <GateText x={width/2} y={133} fill={CS_CS ? "#fff" : "#52525b"} fontSize="9">{sStat}</GateText>
            </g>
        );

    case 'MUX_2_1':
        return (
          <g>
              <path d="M 0 0 L 60 20 L 60 60 L 0 80 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
              <GateText x={30} y={40}>MUX</GateText>
              <GateText x={10} y={20}>0</GateText> <GateText x={10} y={60}>1</GateText> <GateText x={30} y={70}>S</GateText>
              <GateText x={50} y={40}>Y</GateText>
          </g>
        );
    case 'MUX_4_1':
        return (
            <g>
                <path d="M 0 0 L 60 20 L 60 100 L 0 120 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <GateText x={30} y={60}>MUX 4</GateText>
                <GateText x={10} y={20}>0</GateText> <GateText x={10} y={40}>1</GateText>
                <GateText x={10} y={60}>2</GateText> <GateText x={10} y={80}>3</GateText>
                <GateText x={50} y={60}>Y</GateText>
            </g>
        );
    case 'DEMUX_1_2':
        return (
          <g>
              <path d="M 0 20 L 60 0 L 60 80 L 0 60 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
              <GateText x={30} y={40}>DEMUX</GateText>
              <GateText x={10} y={40}>D</GateText> 
              <GateText x={50} y={20}>0</GateText> <GateText x={50} y={60}>1</GateText>
          </g>
        );
    case 'DEMUX_1_4':
        return (
            <g>
                <path d="M 0 20 L 60 0 L 60 120 L 0 100 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <GateText x={30} y={60}>DEMUX 4</GateText>
                <GateText x={10} y={60}>D</GateText> 
                <GateText x={50} y={20}>0</GateText> <GateText x={50} y={40}>1</GateText>
                <GateText x={50} y={60}>2</GateText> <GateText x={50} y={80}>3</GateText>
            </g>
        );
    case 'DECODER_2_4':
        return (
            <g>
                <rect x="0" y="0" width="60" height="100" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={30} y={50}>DEC 2:4</GateText>
                <GateText x={10} y={80}>0</GateText> <GateText x={10} y={90}>1</GateText>
                <GateText x={50} y={20}>0</GateText> <GateText x={50} y={40}>1</GateText>
                <GateText x={50} y={60}>2</GateText> <GateText x={50} y={80}>3</GateText>
            </g>
        );
    case 'PRIORITY_ENCODER_4_2':
        return (
            <g>
                <rect x="0" y="0" width="70" height="100" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={35} y={10}>PRIO ENC</GateText>
                <GateText x={10} y={20}>0</GateText> <GateText x={10} y={40}>1</GateText>
                <GateText x={10} y={60}>2</GateText> <GateText x={10} y={80}>3</GateText>
                <GateText x={60} y={30}>A0</GateText> <GateText x={60} y={50}>A1</GateText> <GateText x={60} y={80}>V</GateText>
            </g>
        );

    default:
      return <rect width="40" height="40" fill="red" />;
  }
};

import React, { useRef } from 'react';
import { 
    SquareActivity, Save, FolderOpen, Move, Circle, Cable, 
    CheckCircle2, SkipBack, Play, RotateCcw, Pause, SkipForward, 
    Sun, Moon, Trash2, X, Undo2, Redo2, MousePointerClick
} from 'lucide-react';
import { NodeType } from '../types';

interface HeaderProps {
    onSave: () => void;
    onLoad: (file: File) => void;
    toolMode: 'select' | 'interact' | 'junction';
    setToolMode: (mode: 'select' | 'interact' | 'junction') => void;
    wireMode: 'manhattan' | 'bezier';
    setWireMode: (mode: 'manhattan' | 'bezier') => void;
    isSimulating: boolean;
    toggleSimulation: () => void;
    isPaused: boolean;
    setIsPaused: (paused: boolean) => void;
    stepBackward: () => void;
    stepForward: () => void;
    checkCompatibility: () => void;
    theme: 'dark' | 'light';
    toggleTheme: () => void;
    onClear: () => void;
    selectedId: string | null;
    deleteSelection: () => void;
    hasHistory: boolean;
    onUndo: () => void;
    onRedo: () => void;
    canUndo: boolean;
    canRedo: boolean;
}

export const Header: React.FC<HeaderProps> = ({
    onSave, onLoad,
    toolMode, setToolMode,
    wireMode, setWireMode,
    isSimulating, toggleSimulation,
    isPaused, setIsPaused,
    stepBackward, stepForward,
    checkCompatibility,
    theme, toggleTheme,
    onClear,
    selectedId, deleteSelection,
    hasHistory,
    onUndo, onRedo, canUndo, canRedo
}) => {
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files?.[0]) {
            onLoad(e.target.files[0]);
            e.target.value = ''; // Reset
        }
    };

    return (
        <div className="h-14 bg-white dark:bg-zinc-900 border-b border-zinc-200 dark:border-zinc-800 flex items-center px-4 justify-between z-30 shrink-0 shadow-sm transition-colors duration-300">
            {/* Logo Section */}
            <div className="flex items-center space-x-3 mr-4">
                <div className="w-8 h-8 bg-cyan-500 rounded-md flex items-center justify-center shadow-lg shadow-cyan-500/20">
                    <SquareActivity size={20} className="text-white" />
                </div>
                <span className="text-sm font-bold tracking-wider text-zinc-700 dark:text-zinc-200 uppercase hidden sm:block">LogicLab Ultra</span>
            </div>

            {/* Toolbar Controls */}
            <div className="flex items-center space-x-4 overflow-x-auto no-scrollbar mask-linear-fade flex-1">

                {/* File Ops */}
                <div className="flex items-center bg-zinc-100 dark:bg-zinc-800 rounded-md p-0.5 border border-zinc-200 dark:border-zinc-700 shrink-0">
                    <button onClick={onSave} className="p-1.5 rounded text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200 transition-colors" title="Save Circuit">
                        <Save size={16} />
                    </button>
                    <button onClick={() => fileInputRef.current?.click()} className="p-1.5 rounded text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200 transition-colors" title="Open Circuit">
                        <FolderOpen size={16} />
                    </button>
                    <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={handleFileChange} />
                </div>

                <div className="h-4 w-px bg-zinc-300 dark:bg-zinc-700 shrink-0"></div>

                {/* Undo / Redo */}
                <div className="flex items-center bg-zinc-100 dark:bg-zinc-800 rounded-md p-0.5 border border-zinc-200 dark:border-zinc-700 shrink-0">
                    <button 
                        onClick={onUndo} 
                        disabled={!canUndo}
                        className="p-1.5 rounded text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200 transition-colors disabled:opacity-30 disabled:hover:text-zinc-500" 
                        title="Undo (Ctrl+Z)"
                    >
                        <Undo2 size={16} />
                    </button>
                    <button 
                        onClick={onRedo} 
                        disabled={!canRedo}
                        className="p-1.5 rounded text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200 transition-colors disabled:opacity-30 disabled:hover:text-zinc-500" 
                        title="Redo (Ctrl+Y)"
                    >
                        <Redo2 size={16} />
                    </button>
                </div>

                <div className="h-4 w-px bg-zinc-300 dark:bg-zinc-700 shrink-0"></div>

                {/* Tools: Move / Interact / Junction */}
                <div className="flex items-center bg-zinc-100 dark:bg-zinc-800 rounded-md p-0.5 border border-zinc-200 dark:border-zinc-700 shrink-0">
                    <button 
                        onClick={() => setToolMode('select')}
                        className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-medium transition-colors ${toolMode === 'select' ? 'bg-white dark:bg-zinc-700 text-cyan-600 dark:text-cyan-400 shadow-sm ring-1 ring-zinc-200 dark:ring-zinc-600' : 'text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200'}`}
                        title="Move Mode (Drag components)"
                    >
                        <Move size={14} />
                        <span className="hidden sm:inline">Move</span>
                    </button>
                    <button 
                        onClick={() => setToolMode('interact')}
                        className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-medium transition-colors ${toolMode === 'interact' ? 'bg-white dark:bg-zinc-700 text-cyan-600 dark:text-cyan-400 shadow-sm ring-1 ring-zinc-200 dark:ring-zinc-600' : 'text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200'}`}
                        title="Interact Mode (Toggle switches)"
                    >
                        <MousePointerClick size={14} />
                        <span className="hidden sm:inline">Interact</span>
                    </button>
                    <div className="w-px h-4 bg-zinc-200 dark:bg-zinc-700 mx-1"></div>
                    <button 
                        onClick={() => setToolMode(toolMode === 'junction' ? 'select' : 'junction')}
                        className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-medium transition-colors ${toolMode === 'junction' ? 'bg-white dark:bg-zinc-700 text-cyan-600 dark:text-cyan-400 shadow-sm ring-1 ring-zinc-200 dark:ring-zinc-600' : 'text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200'}`}
                        title="Junction Tool"
                    >
                        <Circle size={14} />
                        <span className="hidden sm:inline">Junction</span>
                    </button>
                </div>

                <div className="flex items-center bg-zinc-100 dark:bg-zinc-800 rounded-md p-0.5 border border-zinc-200 dark:border-zinc-700 shrink-0">
                     <button 
                        onClick={() => setWireMode(wireMode === 'manhattan' ? 'bezier' : 'manhattan')}
                        className={`p-1.5 rounded transition-colors text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-200`}
                        title="Toggle Wire Style"
                    >
                        <Cable size={14} />
                    </button>
                </div>

                <div className="h-4 w-px bg-zinc-300 dark:bg-zinc-700 shrink-0"></div>

                {/* Simulation */}
                <div className="flex items-center space-x-2 bg-zinc-50 dark:bg-zinc-900/50 border border-zinc-200 dark:border-zinc-800 p-1 rounded-lg shrink-0">
                     <button onClick={checkCompatibility} className="p-1.5 rounded text-zinc-400 hover:text-green-500 dark:hover:text-green-400 hover:bg-green-100 dark:hover:bg-green-900/20 transition-colors" title="Check Compatibility">
                        <CheckCircle2 size={16} />
                    </button>
                    <div className="h-4 w-px bg-zinc-200 dark:bg-zinc-800"></div>
                    <button 
                        onClick={stepBackward} 
                        disabled={!isSimulating || !hasHistory} 
                        className="p-1.5 rounded text-zinc-400 hover:text-zinc-900 dark:hover:text-white hover:bg-zinc-100 dark:hover:bg-zinc-700 transition-colors disabled:opacity-30 disabled:hover:bg-transparent" 
                        title="Step Back (,)"
                    >
                        <SkipBack size={16} />
                    </button>
                    <button 
                        onClick={toggleSimulation}
                        className={`flex items-center space-x-2 px-3 py-1.5 rounded text-xs font-bold transition-all ${
                            isSimulating 
                                ? 'bg-red-50 text-red-500 hover:bg-red-100 border border-red-200 dark:bg-red-500/10 dark:hover:bg-red-500/20 dark:border-red-500/50' 
                                : 'bg-green-500 hover:bg-green-600 dark:bg-green-600 dark:hover:bg-green-500 text-white shadow-lg shadow-green-500/20 dark:shadow-green-900/20'
                        }`}
                    >
                        {isSimulating ? <RotateCcw size={14} /> : <Play size={14} />}
                        <span className="hidden sm:inline">{isSimulating ? 'Stop' : 'Run'}</span>
                    </button>
                    {isSimulating && (
                        <button onClick={() => setIsPaused(!isPaused)} className={`p-1.5 rounded transition-colors ${isPaused ? 'text-amber-500 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20' : 'text-zinc-400 hover:text-zinc-900 dark:hover:text-white hover:bg-zinc-100 dark:hover:bg-zinc-700'}`} title={isPaused ? "Resume" : "Pause"}>
                            {isPaused ? <Play size={14} /> : <Pause size={14} />}
                        </button>
                    )}
                    <button 
                        onClick={stepForward} 
                        className="p-1.5 rounded text-zinc-400 hover:text-zinc-900 dark:hover:text-white hover:bg-zinc-100 dark:hover:bg-zinc-700 transition-colors disabled:opacity-30 disabled:hover:bg-transparent" 
                        title="Step Forward (.)"
                    >
                        <SkipForward size={16} />
                    </button>
                </div>

            </div>

            {/* Right Actions */}
            <div className="flex items-center space-x-3 ml-4">
                 {selectedId && (
                    <button onClick={deleteSelection} className="flex items-center space-x-1 px-3 py-1.5 bg-red-50 text-red-500 dark:bg-red-500/10 dark:text-red-400 hover:bg-red-100 dark:hover:bg-red-500/20 border border-red-200 dark:border-red-500/30 rounded-md text-xs font-medium transition-colors" title="Delete Selected">
                        <X size={14} />
                        <span className="hidden sm:inline">Delete</span>
                    </button>
                )}
                <button onClick={toggleTheme} className="p-2 text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-white transition-colors" title="Toggle Theme">
                    {theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}
                </button>
                <button onClick={onClear} className="p-2 hover:bg-zinc-100 dark:hover:bg-zinc-800 text-zinc-500 hover:text-red-500 dark:hover:text-red-400 rounded-md transition-colors" title="Clear Canvas">
                    <Trash2 size={16} />
                </button>
            </div>
        </div>
    );
};

export type NodeType = 
  | 'AND' | 'OR' | 'NOT' | 'XOR' | 'NAND' | 'NOR' | 'XNOR' | 'BUFFER'
  | 'SWITCH' | 'BULB' | 'CLOCK' | 'BUTTON' | 'CONSTANT_1' | 'CONSTANT_0'
  | 'INPUT_2BIT' | 'INPUT_4BIT' | 'INPUT_8BIT' | 'INPUT_16BIT'
  | 'OUTPUT_2BIT' | 'OUTPUT_4BIT' | 'OUTPUT_8BIT' | 'OUTPUT_16BIT'
  | 'HALF_ADDER' | 'FULL_ADDER' | 'SUBTRACTOR' | 'COMPARATOR_1BIT'
  | 'D_LATCH' | 'D_FF' | 'JK_FF' | 'T_FF' | 'SR_FF'
  | 'GATED_SR_LATCH' | 'JK_MASTER_SLAVE' | 'RAM_1BIT' | 'ROM_1BIT' | 'SHIFT_REGISTER_4BIT'
  | 'RAM_4BIT' | 'RAM_8BIT' | 'RAM_16BIT'
  | 'MUX_2_1' | 'MUX_4_1' | 'DEMUX_1_2' | 'DEMUX_1_4'
  | 'DECODER_2_4' | 'PRIORITY_ENCODER_4_2'
  | 'HEX_DISPLAY' | 'SEVEN_SEGMENT'
  | 'JUNCTION';

export interface Point {
  x: number;
  y: number;
}

export interface Port {
  id: string;
  type: 'input' | 'output';
  offset: Point;
  label?: string;
}

export interface NodeData {
  id: string;
  type: NodeType;
  position: Point;
  inputs: boolean[];
  outputs: boolean[];
  internalState?: {
    lastClock?: boolean;
    storedValue?: boolean;
    masterValue?: boolean; // For Master-Slave
    register?: boolean[]; // For Shift Register
    memory?: number[]; // For RAM arrays
    [key: string]: any;
  };
  properties?: {
    label?: string;
    inputCount?: number;
    propagationDelay?: number;
    initialState?: boolean;
    romValue?: boolean; // For ROM
    [key: string]: any;
  };
}

export interface Wire {
  id: string;
  sourceNodeId: string;
  sourceOutputIndex: number;
  targetNodeId: string;
  targetInputIndex: number;
  state: boolean;
  color?: string; // Inactive color
  activeColor?: string; // Color when High
  thickness?: number; // Width of the wire
}

export interface CircuitState {
  nodes: NodeData[];
  wires: Wire[];
}

export interface WiringState {
  sourceNodeId: string;
  sourceOutputIndex: number;
  startPoint: Point;
  active: boolean;
}

