                )}
                <div className="flex items-center space-x-2">
                    <div className="w-8 h-8 bg-cyan-500 rounded-md flex items-center justify-center shadow-lg">
                        <SquareActivity size={18} className="text-white" />
                    </div>
                    {!isMobile && <span className="text-xs font-bold tracking-wider text-zinc-700 dark:text-zinc-200 uppercase">LogicLab</span>}
                </div>
            </div>

            {/* Middle Section: Tools & Sim */}
            <div className="flex items-center space-x-2 lg:space-x-4 overflow-x-auto no-scrollbar mask-linear-fade flex-1 px-2">
