                        <SkipForward size={16} />
                    </button>
                </div>

                {!isMobile && <div className="h-4 w-px bg-zinc-300 dark:bg-zinc-700" />}

                {/* Tool Selection Group */}
                <div className="flex items-center space-x-1 bg-zinc-100 dark:bg-zinc-800 rounded-lg p-0.5 border border-zinc-200 dark:border-zinc-700 shrink-0">
                    <button onClick={() => setToolMode('select')} className={`p-2 rounded-md ${toolMode === 'select' ? 'bg-white dark:bg-zinc-700 text-cyan-600 shadow-sm' : 'text-zinc-500'}`}>
                        <Move size={16} />
