                    <button onClick={() => setToolMode('interact')} className={`p-2 rounded-md ${toolMode === 'interact' ? 'bg-white dark:bg-zinc-700 text-cyan-600 shadow-sm' : 'text-zinc-500'}`}>
                        <MousePointerClick size={16} />
                    </button>
                    <button onClick={() => setToolMode('junction')} className={`p-2 rounded-md ${toolMode === 'junction' ? 'bg-white dark:bg-zinc-700 text-cyan-600 shadow-sm' : 'text-zinc-500'}`}>
                        <Circle size={14} />
                    </button>
                </div>
            </div>

            {/* Right Section: Actions */}
            <div className="flex items-center space-x-1 lg:space-x-3">
                 {selectedId && (
                    <button onClick={deleteSelection} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-md">
                        <Trash2 size={18} />
                    </button>
                )}
                <button onClick={toggleTheme} className="p-2 text-zinc-500 dark:text-zinc-400">
                    {theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}
                </button>
                {isMobile && (
                    <button onClick={togglePanel} className="p-2 text-zinc-500 dark:text-zinc-400 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-md">
                        <Info size={20} />
                    </button>
                )}
