import React, { useState, useCallback, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { CircuitCanvas } from './components/CircuitCanvas';
import { Header } from './components/Header';
import { PropertiesPanel } from './components/PropertiesPanel';
import { ThemeProvider, useTheme } from './components/ThemeContext';
import { CircuitState, NodeData, NodeType, Wire } from './types';
import { evaluateCircuit } from './utils/circuitLogic';
import { NODE_DEFINITIONS } from './constants';

const MAX_HISTORY = 50;

const AppContent: React.FC = () => {
  const { theme, toggleTheme } = useTheme();

  // -- Global Application State --
  const [circuit, setCircuit] = useState<CircuitState>({ nodes: [], wires: [] });
  const [past, setPast] = useState<CircuitState[]>([]);
  const [future, setFuture] = useState<CircuitState[]>([]);
  const [simHistory, setSimHistory] = useState<CircuitState[]>([]);

  const [pendingComponent, setPendingComponent] = useState<NodeType | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  // -- Interaction Modes --
  const [toolMode, setToolMode] = useState<'select' | 'interact' | 'junction'>('select');
  const [wireMode, setWireMode] = useState<'manhattan' | 'bezier'>('manhattan');

  // -- Simulation State --
  const [isSimulating, setIsSimulating] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  // -- UI Layout State (Responsive) --
  const [sidebarWidth, setSidebarWidth] = useState(260);
  const [panelWidth, setPanelWidth] = useState(280);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);
  const [isResizingPanel, setIsResizingPanel] = useState(false);

  // Panel Visibility States
  const [isSidebarOpen, setIsSidebarOpen] = useState(false); // Default closed on mobile
  const [isPanelOpen, setIsPanelOpen] = useState(false); // Default closed
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);

  // -- Validation State --
  const [validationResult, setValidationResult] = useState<{
      valid: boolean; 
      messages: string[]; 
      invalidNodeIds: string[];
      floatingInputs: { nodeId: string; index: number }[];
  } | null>(null);

  // Handle Window Resize
  useEffect(() => {
    const handleResize = () => {
        const mobile = window.innerWidth < 1024;
        setIsMobile(mobile);
        if (!mobile) setIsSidebarOpen(true);
    };
    handleResize(); // Initial check
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const snapshot = useCallback(() => {
    setPast(prev => {
        const last = prev[prev.length - 1];
        if (last && JSON.stringify(last) === JSON.stringify(circuit)) return prev;
        const newPast = [...prev, circuit];
        return newPast.length > MAX_HISTORY ? newPast.slice(newPast.length - MAX_HISTORY) : newPast;
    });
    setFuture([]);
  }, [circuit]);

  const undo = useCallback(() => {
      if (past.length === 0) return;
      const previous = past[past.length - 1];
      setFuture(prev => [circuit, ...prev]);
      setPast(past.slice(0, -1));
      setCircuit(previous);
      if (isSimulating) { setIsSimulating(false); setSimHistory([]); }
      setValidationResult(null);
  }, [past, circuit, isSimulating]);

  const redo = useCallback(() => {
      if (future.length === 0) return;
      const next = future[0];
      setPast(prev => [...prev, circuit]);
      setFuture(future.slice(1));
      setCircuit(next);
      if (isSimulating) { setIsSimulating(false); setSimHistory([]); }
      setValidationResult(null);
  }, [future, circuit, isSimulating]);

  const tick = useCallback(() => {
    setCircuit(prev => {
        setSimHistory(h => {
            const newHistory = [...h, prev];
            return newHistory.length > MAX_HISTORY ? newHistory.slice(1) : newHistory;
        });
        const hasClock = prev.nodes.some(n => n.type === 'CLOCK');
        let nextNodes = [...prev.nodes];
        if (hasClock) {
            nextNodes = nextNodes.map(n => {
                if (n.type === 'CLOCK') {
                    const speed = n.properties?.interval || 20; 
                    const currentCount = (n.internalState?.tickCount || 0) + 1;
                    if (currentCount >= speed) {
                         return { ...n, outputs: [!n.outputs[0]], internalState: { ...n.internalState, tickCount: 0 } };
                    } else {
                        return { ...n, internalState: { ...n.internalState, tickCount: currentCount } };
                    }
                }
                return n;
            });
        }
        return evaluateCircuit(nextNodes, prev.wires);
    });
  }, []);

  useEffect(() => {
    let interval: number;
    if (isSimulating && !isPaused) { interval = window.setInterval(tick, 50); }
    return () => clearInterval(interval);
  }, [isSimulating, isPaused, tick]);

  const validateCircuit = useCallback(() => {
      const messages: string[] = [];
      const invalidNodeIds: string[] = [];
      const floatingInputs: { nodeId: string; index: number }[] = [];
      let valid = true;
      if (circuit.nodes.length === 0) return { valid: false, messages: ["Circuit is empty."], invalidNodeIds: [], floatingInputs: [] };

      circuit.nodes.forEach(node => {
          // Exclude I/O sources and junctions from input validation
          if (['SWITCH', 'CLOCK', 'BUTTON', 'CONSTANT_1', 'CONSTANT_0', 'JUNCTION', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type)) return;

          const inputCount = node.inputs.length;
          let nodeHasFloatingInput = false;
          for(let i=0; i<inputCount; i++) {
              const isConnected = circuit.wires.some(w => w.targetNodeId === node.id && w.targetInputIndex === i);
              if (!isConnected) { 
                  valid = false; 
                  nodeHasFloatingInput = true; 
                  floatingInputs.push({ nodeId: node.id, index: i }); 
              }
          }
          if (nodeHasFloatingInput) {
              const label = node.properties?.label || NODE_DEFINITIONS[node.type]?.name || node.type;
              messages.push(`${label}: Missing input connections.`);
              invalidNodeIds.push(node.id);
          }
      });
      return { valid, messages: valid ? ["All components are correctly connected."] : messages, invalidNodeIds, floatingInputs };
  }, [circuit]);

  const checkCompatibility = useCallback(() => {
    const result = validateCircuit();
    setValidationResult(result);
  }, [validateCircuit]);

  const toggleSimulation = () => {
    if (isSimulating) {
        setIsSimulating(false); setIsPaused(false); setSimHistory([]); setToolMode('select'); setValidationResult(null);
    } else {
        const result = validateCircuit();
        setValidationResult(result);
        if (!result.valid) return;
        setIsSimulating(true); setToolMode('interact'); setSimHistory([circuit]);
    }
  };

  const stepForward = useCallback(() => {
    if (!isSimulating) {
        const result = validateCircuit();
        setValidationResult(result);
        if (!result.valid) return;
        setIsSimulating(true); setToolMode('interact');
    }
    setIsPaused(true); tick();
  }, [isSimulating, validateCircuit, tick]);

  const stepBackward = useCallback(() => {
    if (!isSimulating || simHistory.length === 0) return;
    setIsPaused(true);
    const prev = simHistory[simHistory.length - 1];
    setCircuit(prev);
    setSimHistory(h => h.slice(0, -1));
  }, [isSimulating, simHistory]);

  const handleUpdateCircuit = (nodes: NodeData[], wires: Wire[]) => {
      const evaluated = evaluateCircuit(nodes, wires);
      setCircuit(evaluated);
  };

  const handleDeleteSelection = () => {
    if (!selectedId) return;
    snapshot();
    const isWire = circuit.wires.find(w => w.id === selectedId);
    if (isWire) {
        handleUpdateCircuit(circuit.nodes, circuit.wires.filter(w => w.id !== selectedId));
        setSelectedId(null);
        return;
    }
    const newWires = circuit.wires.filter(w => w.sourceNodeId !== selectedId && w.targetNodeId !== selectedId);
    const newNodes = circuit.nodes.filter(n => n.id !== selectedId);
    handleUpdateCircuit(newNodes, newWires);
    setSelectedId(null);
  };

  const handleNodeUpdate = (id: string, updates: Partial<NodeData>) => {
    snapshot();
    const prev = circuit;
    const newNodes = prev.nodes.map(n => {
        if (n.id === id) {
            let updatedNode = { ...n, ...updates };
            if (updates.type && updates.type !== n.type) {
                 const def = NODE_DEFINITIONS[updates.type];
                 if (def) {
                     updatedNode.inputs = def.inputs > n.inputs.length ? [...n.inputs, ...Array(def.inputs - n.inputs.length).fill(false)] : n.inputs.slice(0, def.inputs);
                     updatedNode.outputs = def.outputs > n.outputs.length ? [...n.outputs, ...Array(def.outputs - n.outputs.length).fill(false)] : n.outputs.slice(0, def.outputs);
                 }
            }
            if (updates.properties?.inputCount) {
                const count = updates.properties.inputCount;
                updatedNode.inputs = count > updatedNode.inputs.length ? [...updatedNode.inputs, ...Array(count - updatedNode.inputs.length).fill(false)] : updatedNode.inputs.slice(0, count);
            }
            if (updates.properties?.initialState !== undefined) {
                if (['SWITCH', 'CONSTANT_1', 'CONSTANT_0'].includes(updatedNode.type)) updatedNode.outputs = [!!updates.properties.initialState];
                if (['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'D_LATCH'].includes(updatedNode.type)) {
                    updatedNode.internalState = { ...updatedNode.internalState, storedValue: !!updates.properties.initialState };
                    updatedNode.outputs = [!!updates.properties.initialState, !updates.properties.initialState];
                }
            }
            return updatedNode;
        }
        return n;
    });
    const validWires = prev.wires.filter(w => {
        const source = newNodes.find(n => n.id === w.sourceNodeId);
        const target = newNodes.find(n => n.id === w.targetNodeId);
        return source && target && w.sourceOutputIndex < source.outputs.length && w.targetInputIndex < target.inputs.length;
    });
    handleUpdateCircuit(newNodes, validWires);
  };

  const handleWireUpdate = (id: string, updates: Partial<Wire>) => {
        snapshot();
        setCircuit(prev => ({ ...prev, wires: prev.wires.map(w => w.id === id ? { ...w, ...updates } : w) }));
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (isResizingSidebar) setSidebarWidth(Math.max(180, Math.min(450, e.clientX)));
      if (isResizingPanel) setPanelWidth(Math.max(200, Math.min(500, window.innerWidth - e.clientX)));
    };
    const handleMouseUp = () => { setIsResizingSidebar(false); setIsResizingPanel(false); };
    if (isResizingSidebar || isResizingPanel) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
    } else { document.body.style.cursor = ''; }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingSidebar, isResizingPanel]);

  const selectedNode = circuit.nodes.find(n => n.id === selectedId) || null;
  const selectedWire = circuit.wires.find(w => w.id === selectedId) || null;

  return (
    <div className={`${theme} h-screen w-screen overflow-hidden flex flex-col`}>
      <Header 
        onSave={() => {}}
        onLoad={() => {}}
        toolMode={toolMode}
        setToolMode={setToolMode}
        wireMode={wireMode}
        setWireMode={setWireMode}
        isSimulating={isSimulating}
        toggleSimulation={toggleSimulation}
        isPaused={isPaused}
        setIsPaused={setIsPaused}
        stepBackward={stepBackward}
        stepForward={stepForward}
        checkCompatibility={checkCompatibility}
        theme={theme}
        toggleTheme={toggleTheme}
        onClear={() => { snapshot(); setCircuit({nodes:[], wires:[]}); setIsSimulating(false); }}
        selectedId={selectedId}
        deleteSelection={handleDeleteSelection}
        hasHistory={simHistory.length > 0}
        onUndo={undo}
        onRedo={redo}
        canUndo={past.length > 0}
        canRedo={future.length > 0}
        isMobile={isMobile}
        toggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
        togglePanel={() => setIsPanelOpen(!isPanelOpen)}
        isPanelOpen={isPanelOpen}
        hasErrors={validationResult !== null && !validationResult.valid}
      />

      <div className="flex flex-1 w-full bg-zinc-50 dark:bg-black font-sans transition-colors duration-300 overflow-hidden relative">
        {/* Sidebar */}
        <div 
          className={`h-full z-40 transition-all duration-300 ease-in-out absolute lg:relative flex flex-shrink-0
            ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
            ${isMobile ? 'w-full max-w-[320px] shadow-2xl' : ''}`}
          style={{ width: isMobile ? '100%' : (isSidebarOpen ? sidebarWidth : 0) }}
        >
          <Sidebar 
            onSelectComponent={(type) => { setPendingComponent(type); if(isMobile) setIsSidebarOpen(false); }} 
            selectedComponent={pendingComponent} 
            width={isMobile ? '100%' : sidebarWidth} 
            onClose={() => setIsSidebarOpen(false)}
            isMobile={isMobile}
          />
        </div>

        {!isMobile && isSidebarOpen && <div className="w-1 cursor-col-resize hover:bg-cyan-500 transition-colors z-20 bg-zinc-200 dark:bg-zinc-800 flex-shrink-0" onMouseDown={() => setIsResizingSidebar(true)} />}

        <CircuitCanvas 
          circuit={circuit} onUpdateCircuit={handleUpdateCircuit} onCommit={snapshot}
          selectedId={selectedId} setSelectedId={setSelectedId}
          pendingComponent={pendingComponent} setPendingComponent={setPendingComponent}
          toolMode={toolMode} wireMode={wireMode} isSimulating={isSimulating}
          validationResult={validationResult} setValidationResult={setValidationResult}
          onOpenProperties={() => setIsPanelOpen(true)}
        />

        {!isMobile && isPanelOpen && <div className="w-1 cursor-col-resize hover:bg-cyan-500 transition-colors z-20 bg-zinc-200 dark:bg-zinc-800 flex-shrink-0" onMouseDown={() => setIsResizingPanel(true)} />}

        {/* Properties Panel */}
        <div 
          className={`h-full z-40 transition-all duration-300 ease-in-out absolute right-0 lg:relative flex flex-shrink-0
            ${isPanelOpen ? 'translate-x-0' : 'translate-x-full'}
            ${isMobile ? 'w-full max-w-[320px] shadow-2xl' : ''}`}
          style={{ width: isMobile ? '100%' : (isPanelOpen ? panelWidth : 0) }}
        >
          <PropertiesPanel 
            node={selectedNode} 
            wire={selectedWire} 
            onUpdate={handleNodeUpdate} 
            onUpdateWire={handleWireUpdate} 
            width={isMobile ? '100%' : panelWidth} 
            onClose={() => setIsPanelOpen(false)}
            isMobile={isMobile}
          />
        </div>

        {/* Mobile Overlays */}
        {isMobile && (isSidebarOpen || isPanelOpen) && (
          <div 
            className="absolute inset-0 bg-black/40 backdrop-blur-sm z-30 transition-opacity" 
            onClick={() => { setIsSidebarOpen(false); setIsPanelOpen(false); }}
          />
        )}
      </div>
    </div>
  );
};

const App: React.FC = () => <ThemeProvider><AppContent /></ThemeProvider>;
export default App;

import React, { useRef, useState, useEffect } from 'react';
import { GRID_SIZE, NODE_DEFINITIONS } from '../constants';
import { CircuitState, NodeData, NodeType, Wire, Point, WiringState } from '../types';
import { GateShape } from './GateShapes';
import { getNodeDimensions, getInputPorts, getOutputPorts } from '../utils/componentUtils';
import { AlertTriangle, Info, X } from 'lucide-react';
import { useTheme } from './ThemeContext';

interface CircuitCanvasProps {
    circuit: CircuitState;
    onUpdateCircuit: (nodes: NodeData[], wires: Wire[]) => void;
    onCommit: () => void;
    selectedId: string | null;
    setSelectedId: (id: string | null) => void;
    pendingComponent: NodeType | null;
    setPendingComponent: (type: NodeType | null) => void;
    toolMode: 'select' | 'interact' | 'junction';
    wireMode: 'manhattan' | 'bezier';
    isSimulating: boolean;
    validationResult: {
        valid: boolean;
        messages: string[];
        invalidNodeIds: string[];
        floatingInputs: { nodeId: string; index: number }[];
    } | null;
    setValidationResult: (res: any) => void;
    onOpenProperties?: () => void;
}

export const CircuitCanvas: React.FC<CircuitCanvasProps> = ({ 
    circuit, onUpdateCircuit, onCommit,
    selectedId, setSelectedId,
    pendingComponent, setPendingComponent,
    toolMode, wireMode, isSimulating,
    validationResult, setValidationResult,
    onOpenProperties
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const { theme } = useTheme();

  const [draggingNodeId, setDraggingNodeId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<Point>({ x: 0, y: 0 });
  const [wiring, setWiring] = useState<WiringState | null>(null);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
            if (pendingComponent) setPendingComponent(null);
            if (wiring) setWiring(null);
            if (selectedId) setSelectedId(null);
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [pendingComponent, wiring, selectedId, setPendingComponent, setSelectedId]);

  const addNode = (type: NodeType, x: number, y: number) => {
    onCommit();
    const def = NODE_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newNode: NodeData = {
      id: `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      position: { x: snapX, y: snapY },
      inputs: Array(def.inputs).fill(false),
      outputs: Array(def.outputs).fill(false),
      internalState: {},
      properties: { label: '', labelPosition: 'Top', inputCount: def.inputs, propagationDelay: 0, initialState: false, romValue: false, interval: type === 'CLOCK' ? 20 : 0 }
    };

    onUpdateCircuit([...circuit.nodes, newNode], circuit.wires);
    setSelectedId(newNode.id);
  };

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
    if (e.button !== 0) return; // Only left click for selection/drag
    e.stopPropagation();
    setSelectedId(id);
    if (wiring || pendingComponent) return; 

    const node = circuit.nodes.find(n => n.id === id);
    if (!node) return;

    const isInteractive = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

    if (toolMode === 'interact' || isSimulating) {
        if (isInteractive) {
            if (!isSimulating) onCommit();
            let toggledNodes = circuit.nodes;

            if (node.type.startsWith('INPUT_')) {
                const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
                const relY = e.clientY - rect.top; 
                const relX = e.clientX - rect.left;
                const { width, height } = getNodeDimensions(node);
                const bitCount = node.outputs.length;

                if (relY < 25) {
                    const inputVal = window.prompt(`Set Value for ${bitCount}-bit Input:`);
                    if (inputVal !== null) {
                        let val = parseInt(inputVal);
                        if (!isNaN(val)) {
                            const newOutputs = [];
                            for(let i=0; i<bitCount; i++) { newOutputs.push(!!((val >> i) & 1)); }
                            toggledNodes = circuit.nodes.map(n => n.id === id ? { ...n, outputs: newOutputs } : n);
                            onUpdateCircuit(toggledNodes, circuit.wires);
                        }
                    }
                    return;
                }

                let bitIndexToCheck = -1;
                if (relY > height - 30) {
                    const bitWidth = 10;
                    const bitSpacing = 2;
                    const nibbleGap = 6;
                    const totalWidth = bitCount * bitWidth + (bitCount - 1) * bitSpacing + Math.floor((bitCount - 1) / 4) * nibbleGap;
                    const startX = (width - totalWidth) / 2 + bitWidth / 2;
                    for (let i = 0; i < bitCount; i++) {
                        const nibblesBefore = Math.floor(i / 4);
                        const xPos = startX + i * (bitWidth + bitSpacing) + nibblesBefore * nibbleGap;
                        if (Math.abs(relX - xPos) < 10) { bitIndexToCheck = bitCount - 1 - i; break; }
                    }
                } else {
                    const rowIdx = Math.floor((relY - 25) / 20);
                    if (rowIdx >= 0 && rowIdx < bitCount) bitIndexToCheck = rowIdx;
                }

                if (bitIndexToCheck >= 0 && bitIndexToCheck < bitCount) {
                    toggledNodes = circuit.nodes.map(n => {
                        if (n.id === id) {
                            const newOutputs = [...n.outputs];
                            newOutputs[bitIndexToCheck] = !newOutputs[bitIndexToCheck];
                            return { ...n, outputs: newOutputs };
                        }
                        return n;
                    });
                }
            } else {
                toggledNodes = circuit.nodes.map(n => n.id === id ? { ...n, outputs: [!n.outputs[0]] } : n);
            }
            onUpdateCircuit(toggledNodes, circuit.wires);
            return;
        }
    }

    if (toolMode === 'select' || toolMode === 'junction') {
        onCommit();
        setDraggingNodeId(id);
        const rect = containerRef.current!.getBoundingClientRect();
        setDragOffset({ x: e.clientX - rect.left - node.position.x, y: e.clientY - rect.top - node.position.y });
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    if (draggingNodeId) {
        const snapX = Math.round((x - dragOffset.x) / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round((y - dragOffset.y) / GRID_SIZE) * GRID_SIZE;
        const updatedNodes = circuit.nodes.map(n => n.id === draggingNodeId ? { ...n, position: { x: snapX, y: snapY } } : n);
        onUpdateCircuit(updatedNodes, circuit.wires);
    }
  };

  const handlePointerUp = () => {
    setDraggingNodeId(null);
    setWiring(null);
  };

  const handleContextMenu = (e: React.MouseEvent, id: string) => {
      e.preventDefault();
      e.stopPropagation();
      setSelectedId(id);
      if (onOpenProperties) onOpenProperties();
  };

  const startWiring = (e: React.PointerEvent, nodeId: string, outputIndex: number) => {
    e.stopPropagation();
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    setWiring({ sourceNodeId: nodeId, sourceOutputIndex: outputIndex, startPoint: { x: e.clientX - rect.left, y: e.clientY - rect.top }, active: true });
  };

  const completeWiring = (e: React.PointerEvent, targetNodeId: string, inputIndex: number) => {
    e.stopPropagation();
    if (!wiring || wiring.sourceNodeId === targetNodeId) { setWiring(null); return; }
    onCommit();
    const exists = circuit.wires.some(w => w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex);
    let newWires = exists ? circuit.wires.filter(w => !(w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex)) : [...circuit.wires];
    newWires.push({ id: `wire-${Date.now()}`, sourceNodeId: wiring.sourceNodeId, sourceOutputIndex: wiring.sourceOutputIndex, targetNodeId: targetNodeId, targetInputIndex: inputIndex, state: false });
    onUpdateCircuit(circuit.nodes, newWires);
    setWiring(null);
  };

  const handleWireClick = (e: React.PointerEvent, wire: Wire) => {
    e.stopPropagation();
    setSelectedId(wire.id);
    if (toolMode === 'junction') {
        const rect = containerRef.current!.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        onCommit();
        const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;
        const junctionId = `node-${Date.now()}-junction`;
        const newJunction: NodeData = { id: junctionId, type: 'JUNCTION', position: { x: snapX - 5, y: snapY - 5 }, inputs: [false], outputs: [false], properties: { label: '' } };
        const wire1: Wire = { id: `wire-${Date.now()}-1`, sourceNodeId: wire.sourceNodeId, sourceOutputIndex: wire.sourceOutputIndex, targetNodeId: junctionId, targetInputIndex: 0, state: wire.state };
        const wire2: Wire = { id: `wire-${Date.now()}-2`, sourceNodeId: junctionId, sourceOutputIndex: 0, targetNodeId: wire.targetNodeId, targetInputIndex: wire.targetInputIndex, state: wire.state };
        const newWires = circuit.wires.filter(w => w.id !== wire.id).concat([wire1, wire2]);
        onUpdateCircuit([...circuit.nodes, newJunction], newWires);
        setSelectedId(junctionId);
    }
  };

  const handleCanvasClick = (e: React.PointerEvent) => {
      if (e.button !== 0) return; // Ignore right clicks on background
      if (pendingComponent && containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        addNode(pendingComponent, e.clientX - rect.left, e.clientY - rect.top);
        setPendingComponent(null);
        return;
      }
      setSelectedId(null);
      if (validationResult?.valid) setValidationResult(null);
  };

  const getWirePath = (x1: number, y1: number, x2: number, y2: number) => {
    if (wireMode === 'bezier') {
        const dist = Math.abs(x2 - x1);
        const controlPointOffset = Math.max(dist * 0.5, 50);
        return `M ${x1} ${y1} C ${x1 + controlPointOffset} ${y1}, ${x2 - controlPointOffset} ${y2}, ${x2} ${y2}`;
    }
    const dx = x2 - x1;
    if (dx > 20) {
        const midX = (x1 + x2) / 2;
        return `M ${x1} ${y1} L ${midX} ${y1} L ${midX} ${y2} L ${x2} ${y2}`;
    }
    const stub = 20;
    const midY = (y1 + y2) / 2;
    return `M ${x1} ${y1} L ${x1 + stub} ${y1} L ${x1 + stub} ${midY} L ${x2 - stub} ${midY} L ${x2 - stub} ${y2} L ${x2} ${y2}`;
  };

  const getLabelStyle = (pos: string | undefined): React.CSSProperties => {
      switch (pos) {
          case 'Bottom': return { top: '100%', left: '50%', transform: 'translate(-50%, 8px)' };
          case 'Left': return { top: '50%', right: '100%', transform: 'translate(-8px, -50%)' };
          case 'Right': return { top: '50%', left: '100%', transform: 'translate(8px, -50%)' };
          case 'Top': default: return { bottom: '100%', left: '50%', transform: 'translate(-50%, -8px)' };
      }
  };

  const ghostSnapX = Math.round(mousePos.x / GRID_SIZE) * GRID_SIZE;
  const ghostSnapY = Math.round(mousePos.y / GRID_SIZE) * GRID_SIZE;
  const pendingDef = pendingComponent ? NODE_DEFINITIONS[pendingComponent] : null;

  return (
    <div 
        ref={containerRef}
        className={`flex-1 relative w-full h-full overflow-hidden bg-zinc-50 dark:bg-zinc-950 touch-none
            ${isSimulating ? 'cursor-default' : pendingComponent ? 'cursor-cell' : 'cursor-crosshair'}`}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerDown={handleCanvasClick}
        onContextMenu={(e) => e.preventDefault()}
    >
        {/* Grid Pattern */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full opacity-20 dark:opacity-20">
            <defs>
                <pattern id="grid" width={GRID_SIZE} height={GRID_SIZE} patternUnits="userSpaceOnUse">
                    <circle cx="1" cy="1" r="1" className="fill-zinc-400 dark:fill-zinc-500" />
                </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#grid)" />
        </svg>

        {/* Connections */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
            {circuit.wires.map(wire => {
                const sourceNode = circuit.nodes.find(n => n.id === wire.sourceNodeId);
                const targetNode = circuit.nodes.find(n => n.id === wire.targetNodeId);
                if (!sourceNode || !targetNode) return null;
                const sourcePorts = getOutputPorts(sourceNode);
                const targetPorts = getInputPorts(targetNode);
                const outputOffset = sourcePorts[wire.sourceOutputIndex] || { x: 0, y: 0 };
                const inputOffset = targetPorts[wire.targetInputIndex] || { x: 0, y: 0 };
                const startX = sourceNode.position.x + outputOffset.x;
                const startY = sourceNode.position.y + outputOffset.y;
                const endX = targetNode.position.x + inputOffset.x;
                const endY = targetNode.position.y + inputOffset.y;
                const isSelected = selectedId === wire.id;
                const pathData = getWirePath(startX, startY, endX, endY);
                const inactiveColor = wire.color || (theme === 'dark' ? "#52525b" : "#a1a1aa");
                const activeColor = wire.activeColor || "#22d3ee";
                const thickness = wire.thickness || 2;
                const strokeColor = wire.state ? activeColor : (isSelected ? activeColor : inactiveColor);

                return (
                    <g 
                      key={wire.id} 
                      onPointerDown={(e) => handleWireClick(e, wire)} 
                      onContextMenu={(e) => handleContextMenu(e, wire.id)}
                      className={`pointer-events-auto cursor-pointer group`}
                    >
                        <path d={pathData} stroke="transparent" strokeWidth={Math.max(16, thickness + 8)} fill="none" />
                        {wire.state && <path d={pathData} stroke={activeColor} strokeWidth={thickness + 2} fill="none" opacity="0.3" filter="blur(2px)" />}
                        <path d={pathData} stroke={strokeColor} strokeWidth={isSelected ? thickness + 1 : thickness} fill="none" className="transition-all duration-150" strokeDasharray={isSelected ? "4" : "0"} strokeLinejoin="round" strokeLinecap="round" />
                    </g>
                );
            })}
            {wiring && <path d={getWirePath(wiring.startPoint.x, wiring.startPoint.y, mousePos.x, mousePos.y)} stroke="#fbbf24" strokeWidth="2" fill="none" strokeDasharray="4" className="animate-pulse" strokeLinejoin="round" />}
        </svg>

        {/* Nodes */}
        {circuit.nodes.map(node => {
            const { width, height } = getNodeDimensions(node);
            const isSelected = selectedId === node.id;
            const isInvalid = validationResult?.invalidNodeIds?.includes(node.id);
            const inputPorts = getInputPorts(node);
            const outputPorts = getOutputPorts(node);
            const def = NODE_DEFINITIONS[node.type];
            const canInteract = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);
            const cursorClass = (toolMode === 'interact' || isSimulating) ? (canInteract ? 'cursor-pointer' : 'cursor-default') : (toolMode === 'select' ? 'cursor-grab active:cursor-grabbing' : 'cursor-default');

            return (
                <div key={node.id} className={`absolute group select-none transition-transform duration-75 ${isSelected ? 'scale-[1.02]' : ''}`}
                    style={{ left: node.position.x, top: node.position.y, width: width, height: height, pointerEvents: 'none', zIndex: isSelected ? 50 : 10 }}
                    onPointerDown={(e) => e.stopPropagation()}
                >
                    <div className={`absolute inset-0 pointer-events-auto transition-all duration-200 
                            ${isSelected ? 'drop-shadow-[0_0_12px_rgba(34,211,238,0.7)]' : ''} 
                            ${isInvalid ? 'drop-shadow-[0_0_8px_rgba(239,68,68,0.8)]' : ''} ${cursorClass}`}
                        onPointerDown={(e) => handlePointerDown(e, node.id)}
                        onContextMenu={(e) => handleContextMenu(e, node.id)}
                    >
                        <svg width={width} height={height} className="overflow-visible">
                            <GateShape node={node} />
                        </svg>
                    </div>

                    {isInvalid && (
                        <div className="absolute -top-3 -right-3 text-red-500 bg-white dark:bg-zinc-950 rounded-full p-1 shadow-md border border-red-200 dark:border-red-900 animate-bounce z-50">
                            <AlertTriangle size={16} />
                        </div>
                    )}

                    {inputPorts.map((offset, idx) => {
                        const isFloating = validationResult?.floatingInputs?.some(fi => fi.nodeId === node.id && fi.index === idx);
                        return (
                        <div key={`input-${idx}`}
                            className="absolute w-8 h-8 -ml-4 -mt-4 rounded-full pointer-events-auto flex items-center justify-center hover:scale-125 transition-transform z-10 cursor-crosshair"
                            style={{ left: offset.x, top: offset.y }}
                            onPointerUp={(e) => !isSimulating && completeWiring(e, node.id, idx)}
                            title={offset.label || `Input ${idx}`}
                        >
                            <div className={`w-3.5 h-3.5 rounded-full bg-white dark:bg-zinc-900 border-2 transition-all duration-300 ${
                                isFloating ? 'border-red-500 bg-red-500/30 ring-4 ring-red-500/20 animate-pulse' : 
                                node.inputs[idx] ? 'border-cyan-400 bg-cyan-100 dark:bg-cyan-900' : 'border-zinc-400 dark:border-zinc-500'
                            }`} />
                        </div>
                        );
                    })}

                    {outputPorts.map((offset, idx) => (
                        <div key={`output-${idx}`}
                            className="absolute w-8 h-8 -ml-4 -mt-4 rounded-full pointer-events-auto flex items-center justify-center hover:scale-125 transition-transform z-10 cursor-crosshair"
                            style={{ left: offset.x, top: offset.y }}
                            onPointerDown={(e) => !isSimulating && startWiring(e, node.id, idx)}
                            title={offset.label || `Output ${idx}`}
                        >
                            <div className={`w-3.5 h-3.5 rounded-full bg-white dark:bg-zinc-900 border-2 ${node.outputs[idx] ? 'border-cyan-400 bg-cyan-500' : 'border-zinc-400 dark:border-zinc-500 group-hover:border-zinc-600 dark:group-hover:border-zinc-300'}`} />
                        </div>
                    ))}

                    {(isSelected || node.properties?.label) && node.type !== 'JUNCTION' && (
                        <div className={`absolute bg-white/95 dark:bg-zinc-900/95 text-zinc-800 dark:text-zinc-100 text-[10px] px-2 py-0.5 rounded border whitespace-nowrap shadow-md pointer-events-none backdrop-blur-sm z-[60] transition-colors
                            ${isSelected ? 'border-cyan-500 font-bold' : 'border-zinc-200 dark:border-zinc-700'}`}
                            style={getLabelStyle(node.properties?.labelPosition)}
                        >
                            {node.properties?.label || def.name}
                        </div>
                    )}
                </div>
            );
        })}

        {/* Ghost Component */}
        {pendingComponent && pendingDef && (
            <div className="absolute pointer-events-none opacity-50 z-50"
                style={{ left: ghostSnapX, top: ghostSnapY, width: pendingDef.width, height: pendingDef.height }}>
                <svg width={pendingDef.width} height={pendingDef.height} className="overflow-visible">
                        <GateShape node={{ id: 'ghost', type: pendingComponent, position: {x: 0, y: 0}, inputs: Array(pendingDef.inputs).fill(false), outputs: Array(pendingDef.outputs).fill(false), properties: { inputCount: pendingDef.inputs } }} />
                </svg>
            </div>
        )}

        {/* Validation HUD */}
        {validationResult && (
            <div className={`absolute bottom-4 left-4 p-4 rounded-xl shadow-2xl backdrop-blur-md border z-[70] max-w-xs transition-all duration-300 animate-in fade-in slide-in-from-bottom-2 ${validationResult.valid ? 'bg-green-50/90 dark:bg-green-950/40 border-green-200 dark:border-green-800' : 'bg-red-50/90 dark:bg-red-950/40 border-red-200 dark:border-red-800'}`}>
                <div className="flex justify-between items-start mb-2">
                    <div className="flex items-center gap-2">
                        {validationResult.valid ? <ShieldCheck size={18} className="text-green-600" /> : <ShieldAlert size={18} className="text-red-600" />}
                        <span className={`text-xs font-bold uppercase tracking-wider ${validationResult.valid ? 'text-green-700' : 'text-red-700'}`}>
                            {validationResult.valid ? 'Circuit Valid' : 'Circuit Issues'}
                        </span>
                    </div>
                    <button onClick={() => setValidationResult(null)} className="text-zinc-400 hover:text-zinc-600 transition-colors">
                        <X size={14} />
                    </button>
                </div>
                <div className="space-y-1">
                    {validationResult.messages.map((msg, i) => (
                        <div key={i} className="flex gap-2 text-[11px] leading-relaxed text-zinc-600 dark:text-zinc-300">
                            <div className={`w-1 h-1 rounded-full mt-1.5 shrink-0 ${validationResult.valid ? 'bg-green-500' : 'bg-red-500'}`} />
                            {msg}
                        </div>
                    ))}
                </div>
                {!validationResult.valid && (
                    <div className="mt-3 text-[10px] text-zinc-500 flex items-center gap-1 bg-white/50 dark:bg-black/20 p-2 rounded">
                        <Info size={12} /> Floating inputs are highlighted in red.
                    </div>
                )}
            </div>
        )}
    </div>
  );
};

const ShieldCheck = ({ size, className }: { size: number, className: string }) => <Info size={size} className={className} />;
const ShieldAlert = ({ size, className }: { size: number, className: string }) => <AlertTriangle size={size} className={className} />;

