                <rect x="0" y="0" width="90" height="100" rx="4" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <GateText x={45} y={25}>JK M-S</GateText>
                <GateText x={10} y={20}>J</GateText> <GateText x={10} y={80}>K</GateText>
                <path d="M 0 45 L 10 50 L 0 55" fill="none" stroke="#71717a" />
                <GateText x={80} y={20}>Q</GateText> <GateText x={80} y={80}>!Q</GateText>
            </g>
        );
    case 'RAM_1BIT':
        return (
            <g>
                <rect x="0" y="0" width="70" height="80" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={35} y={20}>RAM 1b</GateText>
                <GateText x={10} y={20}>D</GateText> <GateText x={10} y={40}>W</GateText> <GateText x={10} y={60}>S</GateText>
                <GateText x={60} y={40}>Q</GateText>
            </g>
        );
    case 'ROM_1BIT':
        return (
            <g>
                <rect x="0" y="0" width="60" height="60" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={30} y={15}>ROM 1b</GateText>
                <GateText x={30} y={45}>{node.properties?.romValue ? '1' : '0'}</GateText>
                <GateText x={10} y={30}>S</GateText>
                <GateText x={50} y={30}>Q</GateText>
            </g>
        );
    case 'SHIFT_REGISTER_4BIT':
        const regReg = node.internalState?.register || [false, false, false, false];
        return (
            <g>
                <rect x="0" y="0" width="100" height="120" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={50} y={15}>SHIFT REG 4b</GateText>
                <GateText x={10} y={30}>D</GateText> 
                <path d="M 0 85 L 10 90 L 0 95" fill="none" stroke="#71717a" />
                <rect x="30" y="40" width="15" height="40" fill={regReg[0] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />
                <rect x="45" y="40" width="15" height="40" fill={regReg[1] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />
                <rect x="60" y="40" width="15" height="40" fill={regReg[2] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />
                <rect x="75" y="40" width="15" height="40" fill={regReg[3] ? "#22d3ee" : "#27272a"} stroke="#3f3f46" />
                <GateText x={90} y={20}>Q0</GateText> <GateText x={90} y={50}>Q1</GateText>
                <GateText x={90} y={80}>Q2</GateText> <GateText x={90} y={110}>Q3</GateText>
            </g>
        );

    case 'RAM_4BIT':
    case 'RAM_8BIT':
    case 'RAM_16BIT':
        const dBits = type === 'RAM_4BIT' ? 4 : (type === 'RAM_8BIT' ? 8 : 16);
        const aBits = 4;
        let addrAddr = 0;
        for(let i=0; i<aBits; i++) {
            if (node.inputs[i]) addrAddr += Math.pow(2, i);
        }
        const WE_WE = node.inputs[aBits + dBits];
        const CS_CS = node.inputs[aBits + dBits + 1];
        const mem_mem = node.internalState?.memory || [];
        const sVal = mem_mem[addrAddr] || 0;
        let sStat = "IDLE";
        if (CS_CS) {
            sStat = WE_WE ? "WRITE" : "READ";
        } else {
            sStat = "OFF";
        }
        return (
            <g>
                <rect x="0" y="0" width={width} height={height} rx="4" fill="#09090b" stroke="#52525b" strokeWidth="2" />
                <GateText x={width/2} y={15} fill="#e4e4e7" fontSize="12">{type.replace('_', ' ')}</GateText>
                <rect x="40" y="35" width={width - 80} height="40" rx="2" fill="#000" stroke="#3f3f46" />
                <GateText x={width/2} y={47} fill="#71717a" fontSize="9">ADDR</GateText>
                <GateText x={width/2} y={63} fill="#22d3ee" fontSize="12" >{`0x${addrAddr.toString(16).toUpperCase()}`}</GateText>
                <rect x="40" y="80" width={width - 80} height="40" rx="2" fill="#000" stroke="#3f3f46" />
                <GateText x={width/2} y={92} fill="#71717a" fontSize="9">DATA</GateText>
                <GateText x={width/2} y={108} fill="#ef4444" fontSize="12">{`0x${sVal.toString(16).toUpperCase().padStart(dBits > 8 ? 4 : 2, '0')}`}</GateText>
                <rect x="40" y="125" width={width - 80} height="16" rx="2" fill={CS_CS ? (WE_WE ? "#7f1d1d" : "#064e3b") : "#27272a"} />
                <GateText x={width/2} y={133} fill={CS_CS ? "#fff" : "#52525b"} fontSize="9">{sStat}</GateText>
            </g>
        );

    case 'MUX_2_1':
        return (
          <g>
              <path d="M 0 0 L 60 20 L 60 60 L 0 80 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
              <GateText x={30} y={40}>MUX</GateText>
              <GateText x={10} y={20}>0</GateText> <GateText x={10} y={60}>1</GateText> <GateText x={30} y={70}>S</GateText>
              <GateText x={50} y={40}>Y</GateText>
          </g>
        );
    case 'MUX_4_1':
        return (
            <g>
                <path d="M 0 0 L 60 20 L 60 100 L 0 120 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <GateText x={30} y={60}>MUX 4</GateText>
                <GateText x={10} y={20}>0</GateText> <GateText x={10} y={40}>1</GateText>
                <GateText x={10} y={60}>2</GateText> <GateText x={10} y={80}>3</GateText>
                <GateText x={50} y={60}>Y</GateText>
            </g>
        );
    case 'DEMUX_1_2':
        return (
          <g>
              <path d="M 0 20 L 60 0 L 60 80 L 0 60 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
              <GateText x={30} y={40}>DEMUX</GateText>
              <GateText x={10} y={40}>D</GateText> 
              <GateText x={50} y={20}>0</GateText> <GateText x={50} y={60}>1</GateText>
          </g>
        );
    case 'DEMUX_1_4':
        return (
            <g>
                <path d="M 0 20 L 60 0 L 60 120 L 0 100 Z" fill={fillColor} stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <GateText x={30} y={60}>DEMUX 4</GateText>
                <GateText x={10} y={60}>D</GateText> 
                <GateText x={50} y={20}>0</GateText> <GateText x={50} y={40}>1</GateText>
                <GateText x={50} y={60}>2</GateText> <GateText x={50} y={80}>3</GateText>
            </g>
        );
    case 'DECODER_2_4':
        return (
            <g>
                <rect x="0" y="0" width="60" height="100" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={30} y={50}>DEC 2:4</GateText>
                <GateText x={10} y={80}>0</GateText> <GateText x={10} y={90}>1</GateText>
                <GateText x={50} y={20}>0</GateText> <GateText x={50} y={40}>1</GateText>
                <GateText x={50} y={60}>2</GateText> <GateText x={50} y={80}>3</GateText>
            </g>
        );
    case 'PRIORITY_ENCODER_4_2':
        return (
            <g>
                <rect x="0" y="0" width="70" height="100" rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={35} y={10}>PRIO ENC</GateText>
                <GateText x={10} y={20}>0</GateText> <GateText x={10} y={40}>1</GateText>
                <GateText x={10} y={60}>2</GateText> <GateText x={10} y={80}>3</GateText>
                <GateText x={60} y={30}>A0</GateText> <GateText x={60} y={50}>A1</GateText> <GateText x={60} y={80}>V</GateText>
            </g>
        );

    default:
      return <rect width="40" height="40" fill="red" />;
  }
};

import React from 'react';
import { NodeData, Wire } from '../types';
import { Settings2, Type, Palette, Clock, X, Droplets, Zap, Power, Activity } from 'lucide-react';

interface PropertiesPanelProps {
  node: NodeData | null;
  wire: Wire | null;
  onUpdate: (id: string, updates: Partial<NodeData>) => void;
  onUpdateWire: (id: string, updates: Partial<Wire>) => void;
  width: number | string;
  onClose?: () => void;
  isMobile?: boolean;
}

const PRESET_COLORS = [
  { name: 'Default', off: '#52525b', on: '#22d3ee' },
  { name: 'Power', off: '#7f1d1d', on: '#ef4444' },
  { name: 'Logic', off: '#064e3b', on: '#22c55e' },
  { name: 'Clock', off: '#78350f', on: '#f59e0b' },
  { name: 'Bus', off: '#1e3a8a', on: '#3b82f6' },
  { name: 'Neutral', off: '#3f3f46', on: '#a1a1aa' },
];

export const PropertiesPanel: React.FC<PropertiesPanelProps> = ({ node, wire, onUpdate, onUpdateWire, width, onClose, isMobile }) => {
  const renderSimpleRow = (label: string, icon: React.ReactNode, control: React.ReactNode) => (
    <div className="flex items-center justify-between py-3 border-b border-zinc-100 dark:border-zinc-800/50 last:border-0">
        <div className="flex items-center gap-2 text-zinc-600 dark:text-zinc-400">
            {icon}<span className="text-xs font-medium">{label}</span>
        </div>
        <div className="w-1/2 flex justify-end">{control}</div>
    </div>
  );

  const renderHeader = (title: string, Icon: any) => (
    <div className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest mt-6 mb-3 flex items-center gap-1.5">
      <Icon size={12} className="text-zinc-500" /> {title}
    </div>
  );

  if (!node && !wire) {
    return (
      <div style={{ width }} className="bg-white dark:bg-zinc-900 border-l border-zinc-200 dark:border-zinc-800 p-6 flex flex-col items-center justify-center text-zinc-400 h-full">
         <Settings2 size={32} className="mb-3 opacity-30" />
         <p className="text-sm font-medium">No Selection</p>
         <p className="text-[10px] mt-2 text-center opacity-50 px-4 italic">Right-click a component or wire to see its properties.</p>
         {isMobile && <button onClick={onClose} className="mt-4 px-4 py-2 bg-zinc-100 dark:bg-zinc-800 rounded-md text-xs">Close</button>}
      </div>
    );
  }

  // Determine if component supports propagation delay (Gates and FFs)
  const supportsDelay = node && [
    'AND', 'OR', 'NOT', 'XOR', 'NAND', 'NOR', 'XNOR', 'BUFFER',
    'D_LATCH', 'D_FF', 'JK_FF', 'T_FF', 'SR_FF', 'GATED_SR_LATCH', 'HALF_ADDER', 'FULL_ADDER'
  ].includes(node.type);

  // Determine if component supports initial state
  const supportsInitialState = node && [
    'SWITCH', 'D_LATCH', 'D_FF', 'JK_FF', 'T_FF', 'SR_FF', 'GATED_SR_LATCH', 'JK_MASTER_SLAVE'
  ].includes(node.type);

  return (
    <div style={{ width }} className="bg-white dark:bg-zinc-900 border-l border-zinc-200 dark:border-zinc-800 flex flex-col h-full shadow-xl transition-colors duration-300">
       <div className="h-14 flex items-center px-4 border-b border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900 shrink-0">
          <div className="flex items-center gap-2">
             <Settings2 size={16} className="text-cyan-600" />
             <span className="font-bold text-sm text-zinc-800 dark:text-zinc-200">Properties</span>
          </div>
          {isMobile && <button onClick={onClose} className="ml-auto p-2 text-zinc-500"><X size={20}/></button>}
       </div>

       <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
          {wire ? (
              <div className="space-y-6">
                  <div>
                    {renderHeader("Visual Style", Palette)}

                    {renderSimpleRow("Off State", <Droplets size={14} />, 
                      <input type="color" value={wire.color || '#52525b'} onChange={(e) => onUpdateWire(wire.id, { color: e.target.value })} className="w-8 h-8 rounded-full cursor-pointer border-2 border-zinc-200 dark:border-zinc-700 p-0 bg-transparent overflow-hidden"/>
                    )}

                    {renderSimpleRow("On State", <Droplets size={14} className="text-cyan-500" />, 
                      <input type="color" value={wire.activeColor || '#22d3ee'} onChange={(e) => onUpdateWire(wire.id, { activeColor: e.target.value })} className="w-8 h-8 rounded-full cursor-pointer border-2 border-zinc-200 dark:border-zinc-700 p-0 bg-transparent overflow-hidden"/>
                    )}

                    <div className="mt-4">
                      <div className="text-[10px] text-zinc-500 mb-2 font-medium">Quick Presets</div>
                      <div className="grid grid-cols-6 gap-2">
                        {PRESET_COLORS.map((p) => (
                          <button 
                            key={p.name}
                            onClick={() => onUpdateWire(wire.id, { color: p.off, activeColor: p.on })}
                            title={p.name}
                            className="group relative flex flex-col items-center gap-1"
                          >
                            <div className="w-full aspect-square rounded-md border border-zinc-200 dark:border-zinc-700 overflow-hidden flex flex-col">
                              <div className="flex-1" style={{ backgroundColor: p.on }} />
                              <div className="flex-1" style={{ backgroundColor: p.off }} />
                            </div>
                          </button>
                        ))}
                      </div>
                    </div>
                  </div>

                  <div className="pt-4 border-t border-zinc-100 dark:border-zinc-800/50">
                      <div className="flex justify-between mb-2">
                        <span className="text-xs font-medium text-zinc-500">Thickness</span>
                        <span className="text-xs font-mono text-cyan-600 dark:text-cyan-400">{wire.thickness || 2}px</span>
                      </div>
                      <input type="range" min="1" max="8" value={wire.thickness || 2} onChange={(e) => onUpdateWire(wire.id, { thickness: parseInt(e.target.value) })} className="w-full h-2 bg-zinc-100 dark:bg-zinc-800 rounded-lg appearance-none cursor-pointer accent-cyan-500"/>
                  </div>
              </div>
          ) : (
              <div className="space-y-2">
                  <div className="first:mt-0">
                    {renderHeader("Identity", Type)}
                    {renderSimpleRow("Label", <Type size={14} />, 
                      <input type="text" value={node!.properties?.label || ''} onChange={(e) => onUpdate(node!.id, { properties: { ...node!.properties, label: e.target.value } })} className="w-full bg-zinc-50 dark:bg-zinc-800/50 text-right text-xs focus:ring-1 focus:ring-cyan-500 rounded px-2 py-1 border border-transparent dark:border-zinc-700" placeholder="Name"/>
                    )}
                    {renderSimpleRow("Gate Color", <Palette size={14} />, 
                      <input type="color" value={node!.properties?.color || '#18181b'} onChange={(e) => onUpdate(node!.id, { properties: { ...node!.properties, color: e.target.value } })} className="w-8 h-8 rounded-md cursor-pointer border-2 border-zinc-200 dark:border-zinc-700 p-0 bg-transparent overflow-hidden"/>
                    )}
                  </div>

                  {supportsInitialState && (
                    <div>
                      {renderHeader("Logic Behavior", Power)}
                      {renderSimpleRow("Initial State", <Power size={14} className={node!.properties?.initialState ? "text-cyan-500" : "text-zinc-500"} />, 
                        <button 
                          onClick={() => onUpdate(node!.id, { properties: { ...node!.properties, initialState: !node!.properties?.initialState } })}
                          className={`w-10 h-5 rounded-full transition-colors relative flex items-center px-1 ${node!.properties?.initialState ? 'bg-cyan-500' : 'bg-zinc-300 dark:bg-zinc-700'}`}
                        >
                          <div className={`w-3.5 h-3.5 bg-white rounded-full shadow-sm transition-transform ${node!.properties?.initialState ? 'translate-x-5' : 'translate-x-0'}`} />
                        </button>
                      )}
                    </div>
                  )}

                  {node!.type === 'CLOCK' && (
                      <div className="pt-2">
                          {renderHeader("Pulse Configuration", Activity)}
                          <div className="flex justify-between mb-2">
                            <span className="text-xs font-medium text-zinc-500">Clock Interval</span>
                            <span className="text-xs font-mono text-amber-500">{node!.properties?.interval || 20} ticks</span>
                          </div>
                          <input type="range" min="1" max="100" value={node!.properties?.interval || 20} onChange={(e) => onUpdate(node!.id, { properties: { ...node!.properties, interval: parseInt(e.target.value) } })} className="w-full h-2 bg-zinc-100 dark:bg-zinc-800 rounded-lg accent-amber-500 appearance-none cursor-pointer"/>
                          <div className="text-[9px] text-zinc-400 mt-2 text-center italic">Lower interval values increase frequency.</div>
                      </div>
                  )}

                  {supportsDelay && (
                    <div className="pt-2">
                       {renderHeader("Timing & Performance", Zap)}
                       <div className="flex justify-between mb-2">
                        <span className="text-xs font-medium text-zinc-500">Propagation Delay</span>
                        <span className="text-xs font-mono text-cyan-500">{node!.properties?.propagationDelay || 0}ns</span>
                      </div>
                      <input 
                        type="range" min="0" max="100" step="5"
                        value={node!.properties?.propagationDelay || 0} 
                        onChange={(e) => onUpdate(node!.id, { properties: { ...node!.properties, propagationDelay: parseInt(e.target.value) } })} 
                        className="w-full h-2 bg-zinc-100 dark:bg-zinc-800 rounded-lg accent-cyan-500 appearance-none cursor-pointer"
                      />
                      <div className="text-[9px] text-zinc-400 mt-2 text-center italic">Simulates signal latency across the logic gate.</div>
                    </div>
                  )}
              </div>
          )}
          <div className="text-[10px] text-zinc-300 dark:text-zinc-700 font-mono text-center mt-12 bg-zinc-50 dark:bg-zinc-950 py-2 rounded border border-zinc-100 dark:border-zinc-900">
            UUID: {(wire || node)!.id.split('-').slice(-1)[0]}
          </div>
       </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { CircuitCanvas } from './components/CircuitCanvas';
import { Header } from './components/Header';
import { PropertiesPanel } from './components/PropertiesPanel';
import { ThemeProvider, useTheme } from './components/ThemeContext';
import { CircuitState, NodeData, NodeType, Wire } from './types';
import { evaluateCircuit } from './utils/circuitLogic';
import { NODE_DEFINITIONS } from './constants';

const MAX_HISTORY = 50;

const AppContent: React.FC = () => {
  const { theme, toggleTheme } = useTheme();

  // -- Global Application State --
  const [circuit, setCircuit] = useState<CircuitState>({ nodes: [], wires: [] });
  const [past, setPast] = useState<CircuitState[]>([]);
  const [future, setFuture] = useState<CircuitState[]>([]);
  const [simHistory, setSimHistory] = useState<CircuitState[]>([]);

  const [pendingComponent, setPendingComponent] = useState<NodeType | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  // -- Interaction Modes --
  const [toolMode, setToolMode] = useState<'select' | 'interact' | 'junction'>('select');
  const [wireMode, setWireMode] = useState<'manhattan' | 'bezier'>('manhattan');

  // -- Simulation State --
  const [isSimulating, setIsSimulating] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  // -- UI Layout State (Responsive) --
  const [sidebarWidth, setSidebarWidth] = useState(260);
  const [panelWidth, setPanelWidth] = useState(280);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);
  const [isResizingPanel, setIsResizingPanel] = useState(false);

  // Panel Visibility States
  const [isSidebarOpen, setIsSidebarOpen] = useState(false); // Default closed on mobile
  const [isPanelOpen, setIsPanelOpen] = useState(false); // Default closed
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);

  // -- Validation State --
  const [validationResult, setValidationResult] = useState<{
      valid: boolean; 
      messages: string[]; 
      invalidNodeIds: string[];
      floatingInputs: { nodeId: string; index: number }[];
  } | null>(null);

  // Handle Window Resize
  useEffect(() => {
    const handleResize = () => {
        const mobile = window.innerWidth < 1024;
        setIsMobile(mobile);
        if (!mobile) setIsSidebarOpen(true);
    };
    handleResize(); // Initial check
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const snapshot = useCallback(() => {
    setPast(prev => {
        const last = prev[prev.length - 1];
        if (last && JSON.stringify(last) === JSON.stringify(circuit)) return prev;
        const newPast = [...prev, circuit];
        return newPast.length > MAX_HISTORY ? newPast.slice(newPast.length - MAX_HISTORY) : newPast;
    });
    setFuture([]);
  }, [circuit]);

  const undo = useCallback(() => {
      if (past.length === 0) return;
      const previous = past[past.length - 1];
      setFuture(prev => [circuit, ...prev]);
      setPast(past.slice(0, -1));
      setCircuit(previous);
      if (isSimulating) { setIsSimulating(false); setSimHistory([]); }
      setValidationResult(null);
  }, [past, circuit, isSimulating]);

  const redo = useCallback(() => {
      if (future.length === 0) return;
      const next = future[0];
      setPast(prev => [...prev, circuit]);
      setFuture(future.slice(1));
      setCircuit(next);
      if (isSimulating) { setIsSimulating(false); setSimHistory([]); }
      setValidationResult(null);
  }, [future, circuit, isSimulating]);

  const tick = useCallback(() => {
    setCircuit(prev => {
        setSimHistory(h => {
            const newHistory = [...h, prev];
            return newHistory.length > MAX_HISTORY ? newHistory.slice(1) : newHistory;
        });
        const hasClock = prev.nodes.some(n => n.type === 'CLOCK');
        let nextNodes = [...prev.nodes];
        if (hasClock) {
            nextNodes = nextNodes.map(n => {
                if (n.type === 'CLOCK') {
                    const speed = n.properties?.interval || 20; 
                    const currentCount = (n.internalState?.tickCount || 0) + 1;
                    if (currentCount >= speed) {
                         return { ...n, outputs: [!n.outputs[0]], internalState: { ...n.internalState, tickCount: 0 } };
                    } else {
                        return { ...n, internalState: { ...n.internalState, tickCount: currentCount } };
                    }
                }
                return n;
            });
        }
        return evaluateCircuit(nextNodes, prev.wires);
    });
  }, []);

  useEffect(() => {
    let interval: number;
    if (isSimulating && !isPaused) { interval = window.setInterval(tick, 50); }
    return () => clearInterval(interval);
  }, [isSimulating, isPaused, tick]);

  const validateCircuit = useCallback(() => {
      const messages: string[] = [];
      const invalidNodeIds: string[] = [];
      const floatingInputs: { nodeId: string; index: number }[] = [];
      let valid = true;
      if (circuit.nodes.length === 0) return { valid: false, messages: ["Circuit is empty."], invalidNodeIds: [], floatingInputs: [] };

      circuit.nodes.forEach(node => {
          if (['SWITCH', 'CLOCK', 'BUTTON', 'CONSTANT_1', 'CONSTANT_0', 'JUNCTION', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type)) return;

          const inputCount = node.inputs.length;
          let nodeHasFloatingInput = false;
          for(let i=0; i<inputCount; i++) {
              const isConnected = circuit.wires.some(w => w.targetNodeId === node.id && w.targetInputIndex === i);
              if (!isConnected) { 
                  valid = false; 
                  nodeHasFloatingInput = true; 
                  floatingInputs.push({ nodeId: node.id, index: i }); 
              }
          }
          if (nodeHasFloatingInput) {
              const label = node.properties?.label || NODE_DEFINITIONS[node.type]?.name || node.type;
              messages.push(`${label}: Missing input connections.`);
              invalidNodeIds.push(node.id);
          }
      });
      return { valid, messages: valid ? ["All components are correctly connected."] : messages, invalidNodeIds, floatingInputs };
  }, [circuit]);

  const checkCompatibility = useCallback(() => {
    const result = validateCircuit();
    setValidationResult(result);
  }, [validateCircuit]);

  const toggleSimulation = () => {
    if (isSimulating) {
        setIsSimulating(false); setIsPaused(false); setSimHistory([]); setToolMode('select'); setValidationResult(null);
    } else {
        const result = validateCircuit();
        setValidationResult(result);
        if (!result.valid) return;
        setIsSimulating(true); setToolMode('interact'); setSimHistory([circuit]);
    }
  };

  const stepForward = useCallback(() => {
    if (!isSimulating) {
        const result = validateCircuit();
        setValidationResult(result);
        if (!result.valid) return;
        setIsSimulating(true); setToolMode('interact');
    }
    setIsPaused(true); tick();
  }, [isSimulating, validateCircuit, tick]);

  const stepBackward = useCallback(() => {
    if (!isSimulating || simHistory.length === 0) return;
    setIsPaused(true);
    const prev = simHistory[simHistory.length - 1];
    setCircuit(prev);
    setSimHistory(h => h.slice(0, -1));
  }, [isSimulating, simHistory]);

  const handleUpdateCircuit = (nodes: NodeData[], wires: Wire[]) => {
      const evaluated = evaluateCircuit(nodes, wires);
      setCircuit(evaluated);
  };

  const handleDeleteSelection = () => {
    if (!selectedId) return;
    snapshot();
    const isWire = circuit.wires.find(w => w.id === selectedId);
    if (isWire) {
        handleUpdateCircuit(circuit.nodes, circuit.wires.filter(w => w.id !== selectedId));
        setSelectedId(null);
        return;
    }
    const newWires = circuit.wires.filter(w => w.sourceNodeId !== selectedId && w.targetNodeId !== selectedId);
    const newNodes = circuit.nodes.filter(n => n.id !== selectedId);
    handleUpdateCircuit(newNodes, newWires);
    setSelectedId(null);
  };

  const handleNodeUpdate = (id: string, updates: Partial<NodeData>) => {
    snapshot();
    const prev = circuit;
    const newNodes = prev.nodes.map(n => {
        if (n.id === id) {
            let updatedNode = { ...n, ...updates };
            if (updates.type && updates.type !== n.type) {
                 const def = NODE_DEFINITIONS[updates.type];
                 if (def) {
                     updatedNode.inputs = def.inputs > n.inputs.length ? [...n.inputs, ...Array(def.inputs - n.inputs.length).fill(false)] : n.inputs.slice(0, def.inputs);
                     updatedNode.outputs = def.outputs > n.outputs.length ? [...n.outputs, ...Array(def.outputs - n.outputs.length).fill(false)] : n.outputs.slice(0, def.outputs);
                 }
            }
            if (updates.properties?.inputCount) {
                const count = updates.properties.inputCount;
                updatedNode.inputs = count > updatedNode.inputs.length ? [...updatedNode.inputs, ...Array(count - updatedNode.inputs.length).fill(false)] : updatedNode.inputs.slice(0, count);
            }
            if (updates.properties?.initialState !== undefined) {
                if (['SWITCH', 'CONSTANT_1', 'CONSTANT_0'].includes(updatedNode.type)) updatedNode.outputs = [!!updates.properties.initialState];
                if (['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'D_LATCH'].includes(updatedNode.type)) {
                    updatedNode.internalState = { ...updatedNode.internalState, storedValue: !!updates.properties.initialState };
                    updatedNode.outputs = [!!updates.properties.initialState, !updates.properties.initialState];
                }
            }
            return updatedNode;
        }
        return n;
    });
    const validWires = prev.wires.filter(w => {
        const source = newNodes.find(n => n.id === w.sourceNodeId);
        const target = newNodes.find(n => n.id === w.targetNodeId);
        return source && target && w.sourceOutputIndex < source.outputs.length && w.targetInputIndex < target.inputs.length;
    });
    handleUpdateCircuit(newNodes, validWires);
  };

  const handleWireUpdate = (id: string, updates: Partial<Wire>) => {
        snapshot();
        setCircuit(prev => ({ ...prev, wires: prev.wires.map(w => w.id === id ? { ...w, ...updates } : w) }));
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (isResizingSidebar) setSidebarWidth(Math.max(180, Math.min(450, e.clientX)));
      if (isResizingPanel) setPanelWidth(Math.max(200, Math.min(500, window.innerWidth - e.clientX)));
    };
    const handleMouseUp = () => { setIsResizingSidebar(false); setIsResizingPanel(false); };
    if (isResizingSidebar || isResizingPanel) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
    } else { document.body.style.cursor = ''; }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingSidebar, isResizingPanel]);

  const selectedNode = circuit.nodes.find(n => n.id === selectedId) || null;
  const selectedWire = circuit.wires.find(w => w.id === selectedId) || null;

  const anyMobilePanelOpen = isMobile && (isSidebarOpen || isPanelOpen);

  return (
    <div className={`${theme} h-screen w-screen overflow-hidden flex flex-col`}>
      <Header 
        onSave={() => {}}
        onLoad={() => {}}
        toolMode={toolMode}
        setToolMode={setToolMode}
        wireMode={wireMode}
        setWireMode={setWireMode}
        isSimulating={isSimulating}
        toggleSimulation={toggleSimulation}
        isPaused={isPaused}
        setIsPaused={setIsPaused}
        stepBackward={stepBackward}
        stepForward={stepForward}
        checkCompatibility={checkCompatibility}
        theme={theme}
        toggleTheme={toggleTheme}
        onClear={() => { snapshot(); setCircuit({nodes:[], wires:[]}); setIsSimulating(false); }}
        selectedId={selectedId}
        deleteSelection={handleDeleteSelection}
        hasHistory={simHistory.length > 0}
        onUndo={undo}
        onRedo={redo}
        canUndo={past.length > 0}
        canRedo={future.length > 0}
        isMobile={isMobile}
        toggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
        togglePanel={() => setIsPanelOpen(!isPanelOpen)}
        isPanelOpen={isPanelOpen}
        hasErrors={validationResult !== null && !validationResult.valid}
      />

      <div className="flex flex-1 w-full bg-zinc-50 dark:bg-black font-sans transition-colors duration-300 overflow-hidden relative">

        {/* DESKTOP SIDEBAR (Left) */}
        {!isMobile && (
          <>
            <div 
              className={`h-full z-40 transition-all duration-300 ease-in-out relative flex flex-shrink-0
                ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}
              style={{ width: isSidebarOpen ? sidebarWidth : 0 }}
            >
              <Sidebar 
                onSelectComponent={(type) => { setPendingComponent(type); }} 
                selectedComponent={pendingComponent} 
                width={sidebarWidth} 
                onClose={() => setIsSidebarOpen(false)}
                isMobile={false}
              />
            </div>
            {isSidebarOpen && <div className="w-1 cursor-col-resize hover:bg-cyan-500 transition-colors z-20 bg-zinc-200 dark:bg-zinc-800 flex-shrink-0" onMouseDown={() => setIsResizingSidebar(true)} />}
          </>
        )}

        {/* CANVAS */}
        <CircuitCanvas 
          circuit={circuit} onUpdateCircuit={handleUpdateCircuit} onCommit={snapshot}
          selectedId={selectedId} setSelectedId={setSelectedId}
          pendingComponent={pendingComponent} setPendingComponent={setPendingComponent}
          toolMode={toolMode} wireMode={wireMode} isSimulating={isSimulating}
          validationResult={validationResult} setValidationResult={setValidationResult}
          onOpenProperties={() => setIsPanelOpen(true)}
        />

        {/* DESKTOP PROPERTIES PANEL (Right) */}
        {!isMobile && (
          <>
            {isPanelOpen && <div className="w-1 cursor-col-resize hover:bg-cyan-500 transition-colors z-20 bg-zinc-200 dark:bg-zinc-800 flex-shrink-0" onMouseDown={() => setIsResizingPanel(true)} />}
            <div 
              className={`h-full z-40 transition-all duration-300 ease-in-out relative flex flex-shrink-0
                ${isPanelOpen ? 'translate-x-0' : 'translate-x-full'}`}
              style={{ width: isPanelOpen ? panelWidth : 0 }}
            >
              <PropertiesPanel 
                node={selectedNode} 
                wire={selectedWire} 
                onUpdate={handleNodeUpdate} 
                onUpdateWire={handleWireUpdate} 
                width={panelWidth} 
                onClose={() => setIsPanelOpen(false)}
                isMobile={false}
              />
            </div>
          </>
        )}

        {/* MOBILE UNIFIED SIDEBAR (Right Stacked) */}
        {isMobile && (
           <div 
           className={`h-full z-40 transition-all duration-300 ease-in-out absolute right-0 flex flex-col shadow-2xl bg-white dark:bg-zinc-900 overflow-hidden
             ${anyMobilePanelOpen ? 'translate-x-0' : 'translate-x-full'}`}
           style={{ width: '85%', maxWidth: '340px' }}
         >
           {/* Top Section: Properties (If Open) */}
           {isPanelOpen && (
             <div className={`${isSidebarOpen ? 'h-1/2' : 'h-full'} border-b border-zinc-200 dark:border-zinc-800 overflow-hidden flex flex-col`}>
               <PropertiesPanel 
                 node={selectedNode} 
                 wire={selectedWire} 
                 onUpdate={handleNodeUpdate} 
                 onUpdateWire={handleWireUpdate} 
                 width="100%" 
                 onClose={() => setIsPanelOpen(false)}
                 isMobile={true}
               />
             </div>
           )}

           {/* Bottom Section: Components (If Open) */}
           {isSidebarOpen && (
             <div className={`${isPanelOpen ? 'h-1/2' : 'h-full'} overflow-hidden flex flex-col`}>
               <Sidebar 
                 onSelectComponent={(type) => { setPendingComponent(type); setIsSidebarOpen(false); }} 
                 selectedComponent={pendingComponent} 
                 width="100%" 
                 onClose={() => setIsSidebarOpen(false)}
                 isMobile={true}
               />
             </div>
           )}
         </div>
        )}

        {/* Mobile Overlays */}
        {isMobile && anyMobilePanelOpen && (
          <div 
            className="absolute inset-0 bg-black/40 backdrop-blur-sm z-30 transition-opacity" 
            onClick={() => { setIsSidebarOpen(false); setIsPanelOpen(false); }}
          />
        )}
      </div>
    </div>
  );
};

const App: React.FC = () => <ThemeProvider><AppContent /></ThemeProvider>;
export default App;

import React, { useState, useCallback, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { CircuitCanvas } from './components/CircuitCanvas';
import { Header } from './components/Header';
import { PropertiesPanel } from './components/PropertiesPanel';
import { ThemeProvider, useTheme } from './components/ThemeContext';
import { CircuitState, NodeData, NodeType, Wire } from './types';
import { evaluateCircuit } from './utils/circuitLogic';
import { NODE_DEFINITIONS } from './constants';

const MAX_HISTORY = 50;

const AppContent: React.FC = () => {
  const { theme, toggleTheme } = useTheme();

  // -- Global Application State --
  const [circuit, setCircuit] = useState<CircuitState>({ nodes: [], wires: [] });
  const [past, setPast] = useState<CircuitState[]>([]);
  const [future, setFuture] = useState<CircuitState[]>([]);
  const [simHistory, setSimHistory] = useState<CircuitState[]>([]);

  const [pendingComponent, setPendingComponent] = useState<NodeType | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  // -- Interaction Modes --
  const [toolMode, setToolMode] = useState<'select' | 'interact' | 'junction'>('select');
  const [wireMode, setWireMode] = useState<'manhattan' | 'bezier'>('manhattan');

  // -- Simulation State --
  const [isSimulating, setIsSimulating] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  // -- UI Layout State (Responsive) --
  const [sidebarWidth, setSidebarWidth] = useState(260);
  const [panelWidth, setPanelWidth] = useState(280);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);
  const [isResizingPanel, setIsResizingPanel] = useState(false);

  // Panel Visibility States
  const [isSidebarOpen, setIsSidebarOpen] = useState(true); 
  const [isPanelOpen, setIsPanelOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);

  // -- Validation State --
  const [validationResult, setValidationResult] = useState<{
      valid: boolean; 
      messages: string[]; 
      invalidNodeIds: string[];
      floatingInputs: { nodeId: string; index: number }[];
  } | null>(null);

  // Handle Window Resize
  useEffect(() => {
    const handleResize = () => {
        const mobile = window.innerWidth < 1024;
        setIsMobile(mobile);
        if (!mobile && !isPanelOpen) setIsSidebarOpen(true);
    };
    handleResize(); // Initial check
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [isPanelOpen]);

  const snapshot = useCallback(() => {
    setPast(prev => {
        const last = prev[prev.length - 1];
        if (last && JSON.stringify(last) === JSON.stringify(circuit)) return prev;
        const newPast = [...prev, circuit];
        return newPast.length > MAX_HISTORY ? newPast.slice(newPast.length - MAX_HISTORY) : newPast;
    });
    setFuture([]);
  }, [circuit]);

  const undo = useCallback(() => {
      if (past.length === 0) return;
      const previous = past[past.length - 1];
      setFuture(prev => [circuit, ...prev]);
      setPast(past.slice(0, -1));
      setCircuit(previous);
      if (isSimulating) { setIsSimulating(false); setSimHistory([]); }
      setValidationResult(null);
  }, [past, circuit, isSimulating]);

  const redo = useCallback(() => {
      if (future.length === 0) return;
      const next = future[0];
      setPast(prev => [...prev, circuit]);
      setFuture(future.slice(1));
      setCircuit(next);
      if (isSimulating) { setIsSimulating(false); setSimHistory([]); }
      setValidationResult(null);
  }, [future, circuit, isSimulating]);

  const tick = useCallback(() => {
    setCircuit(prev => {
        setSimHistory(h => {
            const newHistory = [...h, prev];
            return newHistory.length > MAX_HISTORY ? newHistory.slice(1) : newHistory;
        });
        const hasClock = prev.nodes.some(n => n.type === 'CLOCK');
        let nextNodes = [...prev.nodes];
        if (hasClock) {
            nextNodes = nextNodes.map(n => {
                if (n.type === 'CLOCK') {
                    const speed = n.properties?.interval || 20; 
                    const currentCount = (n.internalState?.tickCount || 0) + 1;
                    if (currentCount >= speed) {
                         return { ...n, outputs: [!n.outputs[0]], internalState: { ...n.internalState, tickCount: 0 } };
                    } else {
                        return { ...n, internalState: { ...n.internalState, tickCount: currentCount } };
                    }
                }
                return n;
            });
        }
        return evaluateCircuit(nextNodes, prev.wires);
    });
  }, []);

  useEffect(() => {
    let interval: number;
    if (isSimulating && !isPaused) { interval = window.setInterval(tick, 50); }
    return () => clearInterval(interval);
  }, [isSimulating, isPaused, tick]);

  const validateCircuit = useCallback(() => {
      const messages: string[] = [];
      const invalidNodeIds: string[] = [];
      const floatingInputs: { nodeId: string; index: number }[] = [];
      let valid = true;
      if (circuit.nodes.length === 0) return { valid: false, messages: ["Circuit is empty."], invalidNodeIds: [], floatingInputs: [] };

      circuit.nodes.forEach(node => {
          if (['SWITCH', 'CLOCK', 'BUTTON', 'CONSTANT_1', 'CONSTANT_0', 'JUNCTION', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type)) return;

          const inputCount = node.inputs.length;
          let nodeHasFloatingInput = false;
          for(let i=0; i<inputCount; i++) {
              const isConnected = circuit.wires.some(w => w.targetNodeId === node.id && w.targetInputIndex === i);
              if (!isConnected) { 
                  valid = false; 
                  nodeHasFloatingInput = true; 
                  floatingInputs.push({ nodeId: node.id, index: i }); 
              }
          }
          if (nodeHasFloatingInput) {
              const label = node.properties?.label || NODE_DEFINITIONS[node.type]?.name || node.type;
              messages.push(`${label}: Missing input connections.`);
              invalidNodeIds.push(node.id);
          }
      });
      return { valid, messages: valid ? ["All components are correctly connected."] : messages, invalidNodeIds, floatingInputs };
  }, [circuit]);

  const checkCompatibility = useCallback(() => {
    const result = validateCircuit();
    setValidationResult(result);
  }, [validateCircuit]);

  const toggleSimulation = () => {
    if (isSimulating) {
        setIsSimulating(false); setIsPaused(false); setSimHistory([]); setToolMode('select'); setValidationResult(null);
    } else {
        const result = validateCircuit();
        setValidationResult(result);
        if (!result.valid) return;
        setIsSimulating(true); setToolMode('interact'); setSimHistory([circuit]);
    }
  };

  const stepForward = useCallback(() => {
    if (!isSimulating) {
        const result = validateCircuit();
        setValidationResult(result);
        if (!result.valid) return;
        setIsSimulating(true); setToolMode('interact');
    }
    setIsPaused(true); tick();
  }, [isSimulating, validateCircuit, tick]);

  const stepBackward = useCallback(() => {
    if (!isSimulating || simHistory.length === 0) return;
    setIsPaused(true);
    const prev = simHistory[simHistory.length - 1];
    setCircuit(prev);
    setSimHistory(h => h.slice(0, -1));
  }, [isSimulating, simHistory]);

  const handleUpdateCircuit = (nodes: NodeData[], wires: Wire[]) => {
      const evaluated = evaluateCircuit(nodes, wires);
      setCircuit(evaluated);
  };

  const handleDeleteSelection = () => {
    if (!selectedId) return;
    snapshot();
    const isWire = circuit.wires.find(w => w.id === selectedId);
    if (isWire) {
        handleUpdateCircuit(circuit.nodes, circuit.wires.filter(w => w.id !== selectedId));
        setSelectedId(null);
        return;
    }
    const newWires = circuit.wires.filter(w => w.sourceNodeId !== selectedId && w.targetNodeId !== selectedId);
    const newNodes = circuit.nodes.filter(n => n.id !== selectedId);
    handleUpdateCircuit(newNodes, newWires);
    setSelectedId(null);
  };

  const handleNodeUpdate = (id: string, updates: Partial<NodeData>) => {
    snapshot();
    const prev = circuit;
    const newNodes = prev.nodes.map(n => {
        if (n.id === id) {
            let updatedNode = { ...n, ...updates };
            if (updates.type && updates.type !== n.type) {
                 const def = NODE_DEFINITIONS[updates.type];
                 if (def) {
                     updatedNode.inputs = def.inputs > n.inputs.length ? [...n.inputs, ...Array(def.inputs - n.inputs.length).fill(false)] : n.inputs.slice(0, def.inputs);
                     updatedNode.outputs = def.outputs > n.outputs.length ? [...n.outputs, ...Array(def.outputs - n.outputs.length).fill(false)] : n.outputs.slice(0, def.outputs);
                 }
            }
            if (updates.properties?.inputCount) {
                const count = updates.properties.inputCount;
                updatedNode.inputs = count > updatedNode.inputs.length ? [...updatedNode.inputs, ...Array(count - updatedNode.inputs.length).fill(false)] : updatedNode.inputs.slice(0, count);
            }
            if (updates.properties?.initialState !== undefined) {
                if (['SWITCH', 'CONSTANT_1', 'CONSTANT_0'].includes(updatedNode.type)) updatedNode.outputs = [!!updates.properties.initialState];
                if (['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'D_LATCH'].includes(updatedNode.type)) {
                    updatedNode.internalState = { ...updatedNode.internalState, storedValue: !!updates.properties.initialState };
                    updatedNode.outputs = [!!updates.properties.initialState, !updates.properties.initialState];
                }
            }
            return updatedNode;
        }
        return n;
    });
    const validWires = prev.wires.filter(w => {
        const source = newNodes.find(n => n.id === w.sourceNodeId);
        const target = newNodes.find(n => n.id === w.targetNodeId);
        return source && target && w.sourceOutputIndex < source.outputs.length && w.targetInputIndex < target.inputs.length;
    });
    handleUpdateCircuit(newNodes, validWires);
  };

  const handleWireUpdate = (id: string, updates: Partial<Wire>) => {
        snapshot();
        setCircuit(prev => ({ ...prev, wires: prev.wires.map(w => w.id === id ? { ...w, ...updates } : w) }));
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (isResizingSidebar) setSidebarWidth(Math.max(180, Math.min(450, e.clientX)));
      if (isResizingPanel) setPanelWidth(Math.max(200, Math.min(500, window.innerWidth - e.clientX)));
    };
    const handleMouseUp = () => { setIsResizingSidebar(false); setIsResizingPanel(false); };
    if (isResizingSidebar || isResizingPanel) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
    } else { document.body.style.cursor = ''; }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingSidebar, isResizingPanel]);

  const selectedNode = circuit.nodes.find(n => n.id === selectedId) || null;
  const selectedWire = circuit.wires.find(w => w.id === selectedId) || null;

  const togglePanel = () => {
    const newState = !isPanelOpen;
    setIsPanelOpen(newState);
    if (newState) {
      setIsSidebarOpen(false); // Hide components when properties open
    } else if (!isMobile) {
      setIsSidebarOpen(true); // Restore components on desktop when properties close
    }
  };

  return (
    <div className={`${theme} h-screen w-screen overflow-hidden flex flex-col`}>
      <Header 
        onSave={() => {}}
        onLoad={() => {}}
        toolMode={toolMode}
        setToolMode={setToolMode}
        wireMode={wireMode}
        setWireMode={setWireMode}
        isSimulating={isSimulating}
        toggleSimulation={toggleSimulation}
        isPaused={isPaused}
        setIsPaused={setIsPaused}
        stepBackward={stepBackward}
        stepForward={stepForward}
        checkCompatibility={checkCompatibility}
        theme={theme}
        toggleTheme={toggleTheme}
        onClear={() => { snapshot(); setCircuit({nodes:[], wires:[]}); setIsSimulating(false); }}
        selectedId={selectedId}
        deleteSelection={handleDeleteSelection}
        hasHistory={simHistory.length > 0}
        onUndo={undo}
        onRedo={redo}
        canUndo={past.length > 0}
        canRedo={future.length > 0}
        isMobile={isMobile}
        toggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
        togglePanel={togglePanel}
        isPanelOpen={isPanelOpen}
        hasErrors={validationResult !== null && !validationResult.valid}
      />

      <div className="flex flex-1 w-full bg-zinc-50 dark:bg-black font-sans transition-colors duration-300 overflow-hidden relative">

        {/* Focused Properties View - Overlays both Sidebar and Canvas when open */}
        {isPanelOpen ? (
          <div className="flex-1 bg-white dark:bg-zinc-950 flex justify-center animate-in fade-in duration-300">
            <PropertiesPanel 
              node={selectedNode} 
              wire={selectedWire} 
              onUpdate={handleNodeUpdate} 
              onUpdateWire={handleWireUpdate} 
              width="100%" 
              onClose={() => setIsPanelOpen(false)}
              isMobile={isMobile}
            />
          </div>
        ) : (
          <>
            {/* Component Sidebar (Left) - Only shown if Panel is Closed */}
            {!isMobile && isSidebarOpen && (
              <>
                <div className="h-full flex flex-shrink-0 relative" style={{ width: sidebarWidth }}>
                  <Sidebar 
                    onSelectComponent={(type) => { setPendingComponent(type); }} 
                    selectedComponent={pendingComponent} 
                    width={sidebarWidth} 
                    onClose={() => setIsSidebarOpen(false)}
                    isMobile={false}
                  />
                </div>
                <div className="w-1 cursor-col-resize hover:bg-cyan-500 transition-colors z-20 bg-zinc-200 dark:bg-zinc-800 flex-shrink-0" onMouseDown={() => setIsResizingSidebar(true)} />
              </>
            )}

            {/* Mobile Sidebar Overlay */}
            {isMobile && isSidebarOpen && (
              <div className="absolute inset-0 z-50 flex">
                <div className="w-3/4 max-w-sm h-full shadow-2xl">
                  <Sidebar 
                    onSelectComponent={(type) => { setPendingComponent(type); setIsSidebarOpen(false); }} 
                    selectedComponent={pendingComponent} 
                    width="100%" 
                    onClose={() => setIsSidebarOpen(false)}
                    isMobile={true}
                  />
                </div>
                <div className="flex-1 bg-black/40 backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />
              </div>
            )}

            {/* Circuit Canvas (Main View) - Only shown if Panel is Closed */}
            <CircuitCanvas 
              circuit={circuit} onUpdateCircuit={handleUpdateCircuit} onCommit={snapshot}
              selectedId={selectedId} setSelectedId={setSelectedId}
              pendingComponent={pendingComponent} setPendingComponent={setPendingComponent}
              toolMode={toolMode} wireMode={wireMode} isSimulating={isSimulating}
              validationResult={validationResult} setValidationResult={setValidationResult}
              onOpenProperties={() => setIsPanelOpen(true)}
            />
          </>
        )}
      </div>
    </div>
  );
};

const App: React.FC = () => <ThemeProvider><AppContent /></ThemeProvider>;
export default App;

import React from 'react';
import { NodeData, Wire } from '../types';
import { Settings2, Type, Palette, Clock, X, Droplets, Zap, Power, Activity, ArrowLeft } from 'lucide-react';

interface PropertiesPanelProps {
  node: NodeData | null;
  wire: Wire | null;
  onUpdate: (id: string, updates: Partial<NodeData>) => void;
  onUpdateWire: (id: string, updates: Partial<Wire>) => void;
  width: number | string;
  onClose?: () => void;
  isMobile?: boolean;
}

const PRESET_COLORS = [
  { name: 'Default', off: '#52525b', on: '#22d3ee' },
  { name: 'Power', off: '#7f1d1d', on: '#ef4444' },
  { name: 'Logic', off: '#064e3b', on: '#22c55e' },
  { name: 'Clock', off: '#78350f', on: '#f59e0b' },
  { name: 'Bus', off: '#1e3a8a', on: '#3b82f6' },
  { name: 'Neutral', off: '#3f3f46', on: '#a1a1aa' },
];

export const PropertiesPanel: React.FC<PropertiesPanelProps> = ({ node, wire, onUpdate, onUpdateWire, width, onClose, isMobile }) => {
  const renderSimpleRow = (label: string, icon: React.ReactNode, control: React.ReactNode) => (
    <div className="flex items-center justify-between py-4 border-b border-zinc-100 dark:border-zinc-800/50 last:border-0">
        <div className="flex items-center gap-3 text-zinc-600 dark:text-zinc-400">
            {icon}<span className="text-sm font-medium">{label}</span>
        </div>
        <div className="w-1/2 flex justify-end">{control}</div>
    </div>
  );

  const renderHeader = (title: string, Icon: any) => (
    <div className="text-[10px] font-bold text-zinc-400 dark:text-zinc-500 uppercase tracking-widest mt-8 mb-4 flex items-center gap-1.5">
      <Icon size={14} className="text-zinc-400 dark:text-zinc-600" /> {title}
    </div>
  );

  if (!node && !wire) {
    return (
      <div style={{ width }} className="bg-white dark:bg-zinc-950 p-6 flex flex-col items-center justify-center text-zinc-400 h-full max-w-2xl mx-auto">
         <Settings2 size={48} className="mb-4 opacity-20" />
         <p className="text-lg font-medium text-zinc-500">No Selection</p>
         <p className="text-xs mt-2 text-center opacity-50 px-8 italic">Please select a component or wire in the circuit to edit its properties.</p>
         <button 
           onClick={onClose} 
           className="mt-8 flex items-center gap-2 px-6 py-2.5 bg-cyan-600 hover:bg-cyan-500 text-white rounded-lg text-sm font-bold shadow-lg transition-all active:scale-95"
         >
           <ArrowLeft size={16} /> Back to Circuit
         </button>
      </div>
    );
  }

  // Determine if component supports propagation delay (Gates and FFs)
  const supportsDelay = node && [
    'AND', 'OR', 'NOT', 'XOR', 'NAND', 'NOR', 'XNOR', 'BUFFER',
    'D_LATCH', 'D_FF', 'JK_FF', 'T_FF', 'SR_FF', 'GATED_SR_LATCH', 'HALF_ADDER', 'FULL_ADDER'
  ].includes(node.type);

  // Determine if component supports initial state
  const supportsInitialState = node && [
    'SWITCH', 'D_LATCH', 'D_FF', 'JK_FF', 'T_FF', 'SR_FF', 'GATED_SR_LATCH', 'JK_MASTER_SLAVE'
  ].includes(node.type);

  return (
    <div style={{ width }} className="bg-white dark:bg-zinc-950 flex flex-col h-full overflow-hidden">
       {/* Focused Header */}
       <div className="h-16 flex items-center px-4 border-b border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 shrink-0">
          <div className="flex items-center gap-4 max-w-4xl mx-auto w-full">
             <button 
               onClick={onClose} 
               className="p-2 hover:bg-zinc-100 dark:hover:bg-zinc-800 rounded-full transition-colors text-zinc-500"
               title="Return to Workspace"
             >
               <ArrowLeft size={20} />
             </button>
             <div className="flex items-center gap-2">
                <Settings2 size={20} className="text-cyan-600" />
                <span className="font-bold text-base text-zinc-800 dark:text-zinc-200">Component Settings</span>
             </div>
             <div className="ml-auto flex items-center gap-2 px-3 py-1 rounded-full bg-zinc-100 dark:bg-zinc-800 text-[10px] font-mono text-zinc-500">
               ID: {(wire || node)!.id.split('-').slice(-1)[0]}
             </div>
          </div>
       </div>

       <div className="flex-1 overflow-y-auto custom-scrollbar">
          <div className="max-w-xl mx-auto px-6 py-8">
            {wire ? (
                <div className="space-y-8 animate-in fade-in slide-in-from-bottom-2">
                    <div>
                      {renderHeader("Visual Appearance", Palette)}

                      {renderSimpleRow("Default Color", <Droplets size={18} />, 
                        <input type="color" value={wire.color || '#52525b'} onChange={(e) => onUpdateWire(wire.id, { color: e.target.value })} className="w-10 h-10 rounded-lg cursor-pointer border-2 border-zinc-200 dark:border-zinc-700 p-0 bg-transparent overflow-hidden"/>
                      )}

                      {renderSimpleRow("Active Color (High)", <Droplets size={18} className="text-cyan-500" />, 
                        <input type="color" value={wire.activeColor || '#22d3ee'} onChange={(e) => onUpdateWire(wire.id, { activeColor: e.target.value })} className="w-10 h-10 rounded-lg cursor-pointer border-2 border-zinc-200 dark:border-zinc-700 p-0 bg-transparent overflow-hidden"/>
                      )}

                      <div className="mt-6">
                        <div className="text-[10px] text-zinc-500 mb-3 font-bold uppercase tracking-widest">Theme Presets</div>
                        <div className="grid grid-cols-3 sm:grid-cols-6 gap-3">
                          {PRESET_COLORS.map((p) => (
                            <button 
                              key={p.name}
                              onClick={() => onUpdateWire(wire.id, { color: p.off, activeColor: p.on })}
                              title={p.name}
                              className="group relative flex flex-col items-center gap-1.5 transition-transform active:scale-90"
                            >
                              <div className="w-full aspect-square rounded-xl border-2 border-zinc-200 dark:border-zinc-700 overflow-hidden flex flex-col shadow-sm group-hover:border-cyan-500">
                                <div className="flex-1" style={{ backgroundColor: p.on }} />
                                <div className="flex-1" style={{ backgroundColor: p.off }} />
                              </div>
                              <span className="text-[9px] font-medium text-zinc-500">{p.name}</span>
                            </button>
                          ))}
                        </div>
                      </div>
                    </div>

                    <div className="pt-6 border-t border-zinc-100 dark:border-zinc-800/50">
                        {renderHeader("Line Geometry", Zap)}
                        <div className="flex justify-between mb-3">
                          <span className="text-sm font-medium text-zinc-600 dark:text-zinc-400">Path Thickness</span>
                          <span className="text-sm font-mono text-cyan-600 dark:text-cyan-400">{wire.thickness || 2}px</span>
                        </div>
                        <input type="range" min="1" max="12" step="1" value={wire.thickness || 2} onChange={(e) => onUpdateWire(wire.id, { thickness: parseInt(e.target.value) })} className="w-full h-2.5 bg-zinc-100 dark:bg-zinc-800 rounded-lg appearance-none cursor-pointer accent-cyan-500"/>
                        <div className="flex justify-between mt-2 text-[10px] text-zinc-400 px-1">
                          <span>1px</span>
                          <span>6px (Default)</span>
                          <span>12px</span>
                        </div>
                    </div>
                </div>
            ) : (
                <div className="space-y-8 animate-in fade-in slide-in-from-bottom-2">
                    <div className="first:mt-0">
                      {renderHeader("Component Identity", Type)}
                      {renderSimpleRow("Friendly Name", <Type size={18} />, 
                        <input 
                          type="text" 
                          value={node!.properties?.label || ''} 
                          onChange={(e) => onUpdate(node!.id, { properties: { ...node!.properties, label: e.target.value } })} 
                          className="w-full max-w-[200px] bg-zinc-50 dark:bg-zinc-900 text-right text-sm focus:ring-2 focus:ring-cyan-500 rounded-lg px-3 py-2 border border-zinc-200 dark:border-zinc-700 outline-none transition-all" 
                          placeholder="e.g. Master Clock"
                        />
                      )}
                      {renderSimpleRow("Shell Color", <Palette size={18} />, 
                        <input type="color" value={node!.properties?.color || '#18181b'} onChange={(e) => onUpdate(node!.id, { properties: { ...node!.properties, color: e.target.value } })} className="w-10 h-10 rounded-lg cursor-pointer border-2 border-zinc-200 dark:border-zinc-700 p-0 bg-transparent overflow-hidden"/>
                      )}
                    </div>

                    {supportsInitialState && (
                      <div className="pt-6 border-t border-zinc-100 dark:border-zinc-800/50">
                        {renderHeader("Logic Behavior", Power)}
                        {renderSimpleRow("Power-On State", <Power size={18} className={node!.properties?.initialState ? "text-cyan-500" : "text-zinc-500"} />, 
                          <button 
                            onClick={() => onUpdate(node!.id, { properties: { ...node!.properties, initialState: !node!.properties?.initialState } })}
                            className={`w-14 h-7 rounded-full transition-all relative flex items-center px-1.5 shadow-inner ${node!.properties?.initialState ? 'bg-cyan-500' : 'bg-zinc-300 dark:bg-zinc-700'}`}
                          >
                            <div className={`w-4.5 h-4.5 bg-white rounded-full shadow-md transition-transform ${node!.properties?.initialState ? 'translate-x-7' : 'translate-x-0'}`} />
                          </button>
                        )}
                        <p className="text-[11px] text-zinc-400 mt-3 leading-relaxed">
                          Determines the logical state when the circuit is first initialized or reset.
                        </p>
                      </div>
                    )}

                    {node!.type === 'CLOCK' && (
                        <div className="pt-6 border-t border-zinc-100 dark:border-zinc-800/50">
                            {renderHeader("Signal Configuration", Activity)}
                            <div className="flex justify-between mb-3">
                              <span className="text-sm font-medium text-zinc-600 dark:text-zinc-400">Pulse Interval (Frequency)</span>
                              <span className="text-sm font-mono text-amber-500">{node!.properties?.interval || 20} ticks</span>
                            </div>
                            <input type="range" min="2" max="200" step="2" value={node!.properties?.interval || 20} onChange={(e) => onUpdate(node!.id, { properties: { ...node!.properties, interval: parseInt(e.target.value) } })} className="w-full h-2.5 bg-zinc-100 dark:bg-zinc-800 rounded-lg accent-amber-500 appearance-none cursor-pointer"/>
                            <div className="text-[11px] text-zinc-400 mt-4 bg-zinc-50 dark:bg-zinc-900/50 p-3 rounded-lg border border-zinc-100 dark:border-zinc-800 italic">
                              A lower interval results in a faster clock frequency. 20 ticks is approximately 1 second at 50Hz simulation speed.
                            </div>
                        </div>
                    )}

                    {supportsDelay && (
                      <div className="pt-6 border-t border-zinc-100 dark:border-zinc-800/50">
                         {renderHeader("Timing & Performance", Zap)}
                         <div className="flex justify-between mb-3">
                          <span className="text-sm font-medium text-zinc-600 dark:text-zinc-400">Propagation Delay</span>
                          <span className="text-sm font-mono text-cyan-500">{node!.properties?.propagationDelay || 0}ns</span>
                        </div>
                        <input 
                          type="range" min="0" max="250" step="5"
                          value={node!.properties?.propagationDelay || 0} 
                          onChange={(e) => onUpdate(node!.id, { properties: { ...node!.properties, propagationDelay: parseInt(e.target.value) } })} 
                          className="w-full h-2.5 bg-zinc-100 dark:bg-zinc-800 rounded-lg accent-cyan-500 appearance-none cursor-pointer"
                        />
                        <div className="text-[11px] text-zinc-400 mt-4 leading-relaxed">
                          Simulates signal latency across the logic gate. In large circuits, high delays can cause race conditions or synchronization issues.
                        </div>
                      </div>
                    )}

                    <div className="pt-12 flex justify-center">
                       <button 
                         onClick={onClose}
                         className="px-8 py-3 bg-zinc-800 dark:bg-zinc-100 text-white dark:text-black rounded-xl font-bold text-sm shadow-xl transition-all hover:scale-105 active:scale-95 flex items-center gap-2"
                       >
                         Apply & Return <ArrowLeft size={16} className="rotate-180" />
                       </button>
                    </div>
                </div>
            )}
          </div>
       </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { NodeType } from '../types';
import { 
  Combine, GitBranch, ArrowRightFromLine, AlertCircle, 
  BoxSelect, Cpu, Calculator, Watch, Power, Disc, Grid3X3, Binary, Activity, ToggleLeft, Lightbulb, X, Search
} from 'lucide-react';

interface SidebarProps {
  onSelectComponent: (type: NodeType | null) => void;
  selectedComponent: NodeType | null;
  width: number | string;
  onClose?: () => void;
  isMobile?: boolean;
}

const SidebarItem: React.FC<{ type: NodeType, icon: any, label: string, isActive: boolean, onClick: () => void }> = ({ type, icon: Icon, label, isActive, onClick }) => (
    <div 
        onClick={onClick} 
        className={`flex flex-col items-center justify-center p-3 border rounded-xl cursor-pointer transition-all shadow-sm min-h-[90px] w-full active:scale-95 touch-manipulation ${isActive ? 'bg-cyan-50 dark:bg-cyan-900/30 border-cyan-500 ring-2 ring-cyan-500 ring-opacity-20' : 'bg-white dark:bg-zinc-800/50 border-zinc-200 dark:border-zinc-700/50 hover:border-zinc-300 dark:hover:border-zinc-600'}`}
        role="button"
        aria-pressed={isActive}
    >
      <div className={`mb-2 shrink-0 transition-transform ${isActive ? 'text-cyan-600 dark:text-cyan-400 scale-110' : 'text-zinc-500 dark:text-zinc-400'}`}><Icon size={28} /></div>
      <span className={`text-[11px] font-bold text-center leading-tight break-words px-1 tracking-tight ${isActive ? 'text-cyan-700 dark:text-cyan-200' : 'text-zinc-600 dark:text-zinc-300'}`}>{label}</span>
    </div>
);

export const Sidebar: React.FC<SidebarProps> = ({ onSelectComponent, selectedComponent, width, onClose, isMobile }) => {
  const [searchQuery, setSearchQuery] = useState('');

  const libraryData = useMemo(() => [
    {
      title: "I/O Controls",
      items: [
        {type: "SWITCH", icon: ToggleLeft, label: "Switch"}, 
        {type: "BUTTON", icon: Disc, label: "Button"},
        {type: "CLOCK", icon: Watch, label: "Clock"}, 
        {type: "LOGIC_PROBE", icon: Activity, label: "Probe"},
        {type: "BULB", icon: Lightbulb, label: "LED"}, 
        {type: "HEX_DISPLAY", icon: BoxSelect, label: "Hex Disp"},
        {type: "CONSTANT_1", icon: Power, label: "High"}, 
        {type: "CONSTANT_0", icon: Power, label: "Low"}
      ]
    },
    {
      title: "Data Monitoring",
      items: [
        {type: "BINARY_MONITOR_4BIT", icon: Binary, label: "Bin 4b"}, 
        {type: "BINARY_MONITOR_8BIT", icon: Binary, label: "Bin 8b"},
        {type: "OUTPUT_4BIT", icon: Lightbulb, label: "Bus 4b"}, 
        {type: "OUTPUT_8BIT", icon: Lightbulb, label: "Bus 8b"}
      ]
    },
    {
      title: "Combinational",
      items: [
        {type: "AND", icon: Combine, label: "AND Gate"}, 
        {type: "OR", icon: GitBranch, label: "OR Gate"},
        {type: "NOT", icon: ArrowRightFromLine, label: "Inverter"}, 
        {type: "NAND", icon: Combine, label: "NAND Gate"},
        {type: "NOR", icon: GitBranch, label: "NOR Gate"}, 
        {type: "XOR", icon: AlertCircle, label: "XOR Gate"}
      ]
    },
    {
      title: "Sequential",
      items: [
        {type: "D_FF", icon: Cpu, label: "D-FF"}, 
        {type: "T_FF", icon: Cpu, label: "T-FF"},
        {type: "JK_FF", icon: Cpu, label: "JK-FF"}, 
        {type: "RAM_1BIT", icon: Cpu, label: "RAM 1b"},
        {type: "RAM_4BIT", icon: Grid3X3, label: "RAM 16x4"}, 
        {type: "SHIFT_REGISTER_4BIT", icon: Cpu, label: "Shift Reg"}
      ]
    }
  ], []);

  const filteredData = useMemo(() => {
    if (!searchQuery.trim()) return libraryData;
    const query = searchQuery.toLowerCase();
    return libraryData.map(section => ({
      ...section,
      items: section.items.filter(item => 
        item.label.toLowerCase().includes(query) || 
        item.type.toLowerCase().includes(query)
      )
    })).filter(section => section.items.length > 0);
  }, [libraryData, searchQuery]);

  const handleItemClick = (type: NodeType) => selectedComponent === type ? onSelectComponent(null) : onSelectComponent(type);

  const renderSection = (title: string, items: {type: NodeType, icon: any, label: string}[]) => (
    <div className="mb-8" key={title}>
        <div className="flex items-center gap-2 mb-4">
            <div className="h-px bg-zinc-200 dark:bg-zinc-800 flex-1" />
            <div className="text-[10px] font-black text-zinc-400 dark:text-zinc-500 uppercase tracking-[0.2em]">{title}</div>
            <div className="h-px bg-zinc-200 dark:bg-zinc-800 flex-1" />
        </div>
        <div className="grid grid-cols-2 gap-3">
            {items.map(item => <SidebarItem key={item.type} type={item.type as NodeType} icon={item.icon} label={item.label} isActive={selectedComponent === item.type} onClick={() => handleItemClick(item.type as NodeType)} />)}
        </div>
    </div>
  );

  return (
    <div style={{ width }} className="bg-white dark:bg-zinc-900 border-r border-zinc-200 dark:border-zinc-800 flex flex-col h-full select-none z-50 shadow-xl transition-colors duration-300 overflow-hidden">
      <div className="flex flex-col border-b border-zinc-200 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 backdrop-blur-md shrink-0 p-4 space-y-4">
          <div className="flex items-center">
            <span className="font-bold text-sm text-zinc-800 dark:text-zinc-200 tracking-tight">Component Library</span>
            {isMobile && (
              <button 
                  onClick={onClose} 
                  className="ml-auto p-2 text-zinc-500 hover:text-zinc-800 dark:hover:text-zinc-200 transition-colors"
                  aria-label="Close Library"
              >
                  <X size={22}/>
              </button>
            )}
          </div>

          <div className="relative group">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-zinc-400 group-focus-within:text-cyan-500 transition-colors">
              <Search size={16} />
            </div>
            <input 
              type="text"
              placeholder="Search components..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-10 py-2 bg-white dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 rounded-lg text-xs font-medium focus:outline-none focus:ring-2 focus:ring-cyan-500/50 focus:border-cyan-500 transition-all text-zinc-700 dark:text-zinc-200 placeholder-zinc-400 dark:placeholder-zinc-500 shadow-inner"
            />
            {searchQuery && (
              <button 
                onClick={() => setSearchQuery('')}
                className="absolute inset-y-0 right-0 pr-3 flex items-center text-zinc-400 hover:text-zinc-600 dark:hover:text-zinc-200 transition-colors"
                title="Clear search"
              >
                <X size={14} />
              </button>
            )}
          </div>
      </div>

      {/* Scrollable Container with overscroll control for better mobile feel */}
      <div className="flex-1 overflow-y-auto p-4 custom-scrollbar overscroll-contain pb-20 lg:pb-4">
        {filteredData.length > 0 ? (
          filteredData.map(section => renderSection(section.title, section.items))
        ) : (
          <div className="flex flex-col items-center justify-center py-20 text-center space-y-3 opacity-60">
            <div className="p-4 rounded-full bg-zinc-100 dark:bg-zinc-800 text-zinc-400">
              <Search size={32} />
            </div>
            <div>
              <p className="text-sm font-bold text-zinc-600 dark:text-zinc-300">No components found</p>
              <p className="text-[11px] text-zinc-500 mt-1">Try searching for a different term or browse categories.</p>
            </div>
            <button 
              onClick={() => setSearchQuery('')}
              className="mt-2 text-xs font-bold text-cyan-600 dark:text-cyan-400 hover:underline"
            >
              Clear Search
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { CircuitCanvas } from './components/CircuitCanvas';
import { Header } from './components/Header';
import { PropertiesPanel } from './components/PropertiesPanel';
import { ThemeProvider, useTheme } from './components/ThemeContext';
import { CircuitState, NodeData, NodeType, Wire } from './types';
import { evaluateCircuit } from './utils/circuitLogic';
import { NODE_DEFINITIONS } from './constants';

const MAX_HISTORY = 50;

const AppContent: React.FC = () => {
  const { theme, toggleTheme } = useTheme();

  // -- Global Application State --
  const [circuit, setCircuit] = useState<CircuitState>({ nodes: [], wires: [] });
  const [past, setPast] = useState<CircuitState[]>([]);
  const [future, setFuture] = useState<CircuitState[]>([]);
  const [simHistory, setSimHistory] = useState<CircuitState[]>([]);

  const [pendingComponent, setPendingComponent] = useState<NodeType | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  // -- Interaction Modes --
  const [toolMode, setToolMode] = useState<'select' | 'interact' | 'junction'>('select');
  const [wireMode, setWireMode] = useState<'manhattan' | 'bezier'>('manhattan');
  const [intersectionLogicEnabled, setIntersectionLogicEnabled] = useState(false);

  // -- Simulation State --
  const [isSimulating, setIsSimulating] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  // -- UI Layout State (Responsive) --
  const [sidebarWidth, setSidebarWidth] = useState(260);
  const [panelWidth, setPanelWidth] = useState(280);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);
  const [isResizingPanel, setIsResizingPanel] = useState(false);

  // Panel Visibility States
  const [isSidebarOpen, setIsSidebarOpen] = useState(true); 
  const [isPanelOpen, setIsPanelOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);

  // -- Validation State --
  const [validationResult, setValidationResult] = useState<{
      valid: boolean; 
      messages: string[]; 
      invalidNodeIds: string[];
      floatingInputs: { nodeId: string; index: number }[];
  } | null>(null);

  // Handle Window Resize
  useEffect(() => {
    const handleResize = () => {
        const mobile = window.innerWidth < 1024;
        setIsMobile(mobile);
        if (!mobile && !isPanelOpen) setIsSidebarOpen(true);
    };
    handleResize(); // Initial check
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [isPanelOpen]);

  const snapshot = useCallback(() => {
    setPast(prev => {
        const last = prev[prev.length - 1];
        if (last && JSON.stringify(last) === JSON.stringify(circuit)) return prev;
        const newPast = [...prev, circuit];
        return newPast.length > MAX_HISTORY ? newPast.slice(newPast.length - MAX_HISTORY) : newPast;
    });
    setFuture([]);
  }, [circuit]);

  const undo = useCallback(() => {
      if (past.length === 0) return;
      const previous = past[past.length - 1];
      setFuture(prev => [circuit, ...prev]);
      setPast(past.slice(0, -1));
      setCircuit(previous);
      if (isSimulating) { setIsSimulating(false); setSimHistory([]); }
      setValidationResult(null);
  }, [past, circuit, isSimulating]);

  const redo = useCallback(() => {
      if (future.length === 0) return;
      const next = future[0];
      setPast(prev => [...prev, circuit]);
      setFuture(future.slice(1));
      setCircuit(next);
      if (isSimulating) { setIsSimulating(false); setSimHistory([]); }
      setValidationResult(null);
  }, [future, circuit, isSimulating]);

  const tick = useCallback(() => {
    setCircuit(prev => {
        setSimHistory(h => {
            const newHistory = [...h, prev];
            return newHistory.length > MAX_HISTORY ? newHistory.slice(1) : newHistory;
        });
        const hasClock = prev.nodes.some(n => n.type === 'CLOCK');
        let nextNodes = [...prev.nodes];
        if (hasClock) {
            nextNodes = nextNodes.map(n => {
                if (n.type === 'CLOCK') {
                    const speed = n.properties?.interval || 20; 
                    const currentCount = (n.internalState?.tickCount || 0) + 1;
                    if (currentCount >= speed) {
                         return { ...n, outputs: [!n.outputs[0]], internalState: { ...n.internalState, tickCount: 0 } };
                    } else {
                        return { ...n, internalState: { ...n.internalState, tickCount: currentCount } };
                    }
                }
                return n;
            });
        }
        return evaluateCircuit(nextNodes, prev.wires);
    });
  }, []);

  useEffect(() => {
    let interval: number;
    if (isSimulating && !isPaused) { interval = window.setInterval(tick, 50); }
    return () => clearInterval(interval);
  }, [isSimulating, isPaused, tick]);

  const validateCircuit = useCallback(() => {
      const messages: string[] = [];
      const invalidNodeIds: string[] = [];
      const floatingInputs: { nodeId: string; index: number }[] = [];
      let valid = true;
      if (circuit.nodes.length === 0) return { valid: false, messages: ["Circuit is empty."], invalidNodeIds: [], floatingInputs: [] };

      circuit.nodes.forEach(node => {
          if (['SWITCH', 'CLOCK', 'BUTTON', 'CONSTANT_1', 'CONSTANT_0', 'JUNCTION', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type)) return;

          const inputCount = node.inputs.length;
          let nodeHasFloatingInput = false;
          for(let i=0; i<inputCount; i++) {
              const isConnected = circuit.wires.some(w => w.targetNodeId === node.id && w.targetInputIndex === i);
              if (!isConnected) { 
                  valid = false; 
                  nodeHasFloatingInput = true; 
                  floatingInputs.push({ nodeId: node.id, index: i }); 
              }
          }
          if (nodeHasFloatingInput) {
              const label = node.properties?.label || NODE_DEFINITIONS[node.type]?.name || node.type;
              messages.push(`${label}: Missing input connections.`);
              invalidNodeIds.push(node.id);
          }
      });
      return { valid, messages: valid ? ["All components are correctly connected."] : messages, invalidNodeIds, floatingInputs };
  }, [circuit]);

  const checkCompatibility = useCallback(() => {
    const result = validateCircuit();
    setValidationResult(result);
  }, [validateCircuit]);

  const toggleSimulation = () => {
    if (isSimulating) {
        setIsSimulating(false); setIsPaused(false); setSimHistory([]); setToolMode('select'); setValidationResult(null);
    } else {
        const result = validateCircuit();
        setValidationResult(result);
        if (!result.valid) return;
        setIsSimulating(true); setToolMode('interact'); setSimHistory([circuit]);
    }
  };

  const stepForward = useCallback(() => {
    if (!isSimulating) {
        const result = validateCircuit();
        setValidationResult(result);
        if (!result.valid) return;
        setIsSimulating(true); setToolMode('interact');
    }
    setIsPaused(true); tick();
  }, [isSimulating, validateCircuit, tick]);

  const stepBackward = useCallback(() => {
    if (!isSimulating || simHistory.length === 0) return;
    setIsPaused(true);
    const prev = simHistory[simHistory.length - 1];
    setCircuit(prev);
    setSimHistory(h => h.slice(0, -1));
  }, [isSimulating, simHistory]);

  const handleUpdateCircuit = (nodes: NodeData[], wires: Wire[]) => {
      const evaluated = evaluateCircuit(nodes, wires);
      setCircuit(evaluated);
  };

  const handleDeleteSelection = () => {
    if (!selectedId) return;
    snapshot();
    const isWire = circuit.wires.find(w => w.id === selectedId);
    if (isWire) {
        handleUpdateCircuit(circuit.nodes, circuit.wires.filter(w => w.id !== selectedId));
        setSelectedId(null);
        return;
    }
    const newWires = circuit.wires.filter(w => w.sourceNodeId !== selectedId && w.targetNodeId !== selectedId);
    const newNodes = circuit.nodes.filter(n => n.id !== selectedId);
    handleUpdateCircuit(newNodes, newWires);
    setSelectedId(null);
  };

  const handleNodeUpdate = (id: string, updates: Partial<NodeData>) => {
    snapshot();
    const prev = circuit;
    const newNodes = prev.nodes.map(n => {
        if (n.id === id) {
            let updatedNode = { ...n, ...updates };
            if (updates.type && updates.type !== n.type) {
                 const def = NODE_DEFINITIONS[updates.type];
                 if (def) {
                     updatedNode.inputs = def.inputs > n.inputs.length ? [...n.inputs, ...Array(def.inputs - n.inputs.length).fill(false)] : n.inputs.slice(0, def.inputs);
                     updatedNode.outputs = def.outputs > n.outputs.length ? [...n.outputs, ...Array(def.outputs - n.outputs.length).fill(false)] : n.outputs.slice(0, def.outputs);
                 }
            }
            if (updates.properties?.inputCount) {
                const count = updates.properties.inputCount;
                updatedNode.inputs = count > updatedNode.inputs.length ? [...updatedNode.inputs, ...Array(count - updatedNode.inputs.length).fill(false)] : updatedNode.inputs.slice(0, count);
            }
            if (updates.properties?.initialState !== undefined) {
                if (['SWITCH', 'CONSTANT_1', 'CONSTANT_0'].includes(updatedNode.type)) updatedNode.outputs = [!!updates.properties.initialState];
                if (['D_FF', 'T_FF', 'JK_FF', 'SR_FF', 'D_LATCH'].includes(updatedNode.type)) {
                    updatedNode.internalState = { ...updatedNode.internalState, storedValue: !!updates.properties.initialState };
                    updatedNode.outputs = [!!updates.properties.initialState, !updates.properties.initialState];
                }
            }
            return updatedNode;
        }
        return n;
    });
    const validWires = prev.wires.filter(w => {
        const source = newNodes.find(n => n.id === w.sourceNodeId);
        const target = newNodes.find(n => n.id === w.targetNodeId);
        return source && target && w.sourceOutputIndex < source.outputs.length && w.targetInputIndex < target.inputs.length;
    });
    handleUpdateCircuit(newNodes, validWires);
  };

  const handleWireUpdate = (id: string, updates: Partial<Wire>) => {
        snapshot();
        setCircuit(prev => ({ ...prev, wires: prev.wires.map(w => w.id === id ? { ...w, ...updates } : w) }));
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (isResizingSidebar) setSidebarWidth(Math.max(180, Math.min(450, e.clientX)));
      if (isResizingPanel) setPanelWidth(Math.max(200, Math.min(500, window.innerWidth - e.clientX)));
    };
    const handleMouseUp = () => { setIsResizingSidebar(false); setIsResizingPanel(false); };
    if (isResizingSidebar || isResizingPanel) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
    } else { document.body.style.cursor = ''; }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingSidebar, isResizingPanel]);

  const selectedNode = circuit.nodes.find(n => n.id === selectedId) || null;
  const selectedWire = circuit.wires.find(w => w.id === selectedId) || null;

  const togglePanel = () => {
    const newState = !isPanelOpen;
    setIsPanelOpen(newState);
    if (newState) {
      setIsSidebarOpen(false); // Hide components when properties open
    } else if (!isMobile) {
      setIsSidebarOpen(true); // Restore components on desktop when properties close
    }
  };

  return (
    <div className={`${theme} h-screen w-screen overflow-hidden flex flex-col`}>
      <Header 
        onSave={() => {}}
        onLoad={() => {}}
        toolMode={toolMode}
        setToolMode={setToolMode}
        wireMode={wireMode}
        setWireMode={setWireMode}
        isSimulating={isSimulating}
        toggleSimulation={toggleSimulation}
        isPaused={isPaused}
        setIsPaused={setIsPaused}
        stepBackward={stepBackward}
        stepForward={stepForward}
        checkCompatibility={checkCompatibility}
        theme={theme}
        toggleTheme={toggleTheme}
        onClear={() => { snapshot(); setCircuit({nodes:[], wires:[]}); setIsSimulating(false); }}
        selectedId={selectedId}
        deleteSelection={handleDeleteSelection}
        hasHistory={simHistory.length > 0}
        onUndo={undo}
        onRedo={redo}
        canUndo={past.length > 0}
        canRedo={future.length > 0}
        isMobile={isMobile}
        toggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
        togglePanel={togglePanel}
        isPanelOpen={isPanelOpen}
        hasErrors={validationResult !== null && !validationResult.valid}
        intersectionLogicEnabled={intersectionLogicEnabled}
        setIntersectionLogicEnabled={setIntersectionLogicEnabled}
      />

      <div className="flex flex-1 w-full bg-zinc-50 dark:bg-black font-sans transition-colors duration-300 overflow-hidden relative">

        {/* Focused Properties View - Overlays both Sidebar and Canvas when open */}
        {isPanelOpen ? (
          <div className="flex-1 bg-white dark:bg-zinc-950 flex justify-center animate-in fade-in duration-300">
            <PropertiesPanel 
              node={selectedNode} 
              wire={selectedWire} 
              onUpdate={handleNodeUpdate} 
              onUpdateWire={handleWireUpdate} 
              width="100%" 
              onClose={() => setIsPanelOpen(false)}
              isMobile={isMobile}
            />
          </div>
        ) : (
          <>
            {/* Component Sidebar (Left) - Only shown if Panel is Closed */}
            {!isMobile && isSidebarOpen && (
              <>
                <div className="h-full flex flex-shrink-0 relative" style={{ width: sidebarWidth }}>
                  <Sidebar 
                    onSelectComponent={(type) => { setPendingComponent(type); }} 
                    selectedComponent={pendingComponent} 
                    width={sidebarWidth} 
                    onClose={() => setIsSidebarOpen(false)}
                    isMobile={false}
                  />
                </div>
                <div className="w-1 cursor-col-resize hover:bg-cyan-500 transition-colors z-20 bg-zinc-200 dark:bg-zinc-800 flex-shrink-0" onMouseDown={() => setIsResizingSidebar(true)} />
              </>
            )}

            {/* Mobile Sidebar Overlay */}
            {isMobile && isSidebarOpen && (
              <div className="absolute inset-0 z-50 flex">
                <div className="w-3/4 max-w-sm h-full shadow-2xl">
                  <Sidebar 
                    onSelectComponent={(type) => { setPendingComponent(type); setIsSidebarOpen(false); }} 
                    selectedComponent={pendingComponent} 
                    width="100%" 
                    onClose={() => setIsSidebarOpen(false)}
                    isMobile={true}
                  />
                </div>
                <div className="flex-1 bg-black/40 backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />
              </div>
            )}

            {/* Circuit Canvas (Main View) - Only shown if Panel is Closed */}
            <CircuitCanvas 
              circuit={circuit} onUpdateCircuit={handleUpdateCircuit} onCommit={snapshot}
              selectedId={selectedId} setSelectedId={setSelectedId}
              pendingComponent={pendingComponent} setPendingComponent={setPendingComponent}
              toolMode={toolMode} wireMode={wireMode} isSimulating={isSimulating}
              validationResult={validationResult} setValidationResult={setValidationResult}
              onOpenProperties={() => setIsPanelOpen(true)}
              intersectionLogicEnabled={intersectionLogicEnabled}
            />
          </>
        )}
      </div>
    </div>
  );
};

