import React, { useRef, useState, useEffect, useMemo } from 'react';
import { GRID_SIZE, NODE_DEFINITIONS, MB_SPACING, MB_START_Y } from '../constants';
import { CircuitState, NodeData, NodeType, Wire, Point, WiringState } from '../types';
import { GateShape } from './GateShapes';
import { getNodeDimensions, getInputPorts, getOutputPorts } from '../utils/componentUtils';
import { AlertTriangle, Info, X, Settings2 } from 'lucide-react';
import { useTheme } from './ThemeContext';

interface CircuitCanvasProps {
    circuit: CircuitState;
    onUpdateCircuit: (nodes: NodeData[], wires: Wire[]) => void;
    onCommit: () => void;
    selectedId: string | null;
    setSelectedId: (id: string | null) => void;
    pendingComponent: NodeType | null;
    setPendingComponent: (type: NodeType | null) => void;
    toolMode: 'move' | 'interact' | 'junction';
    wireMode: 'manhattan' | 'bezier';
    isSimulating: boolean;
    validationResult: {
        valid: boolean;
        messages: string[];
        invalidNodeIds: string[];
        floatingInputs: { nodeId: string; index: number }[];
    } | null;
    setValidationResult: (res: any) => void;
    onOpenProperties?: () => void;
    intersectionLogicEnabled: boolean;
    defaultWireThickness: number;
}

const getIntersection = (p1: Point, p2: Point, p3: Point, p4: Point): Point | null => {
    const denom = (p4.y - p3.y) * (p2.x - p1.x) - (p4.x - p3.x) * (p2.y - p1.y);
    if (denom === 0) return null; 
    const ua = ((p4.x - p3.x) * (p1.y - p3.y) - (p4.y - p3.y) * (p1.x - p3.x)) / denom;
    const ub = ((p2.x - p1.x) * (p1.y - p3.y) - (p2.y - p1.y) * (p1.x - p3.x)) / denom;
    if (ua > 0.01 && ua < 0.99 && ub > 0.01 && ub < 0.99) {
        return {
            x: p1.x + ua * (p2.x - p1.x),
            y: p1.y + ua * (p2.y - p1.y)
        };
    }
    return null;
};

export const CircuitCanvas: React.FC<CircuitCanvasProps> = ({ 
    circuit, onUpdateCircuit, onCommit,
    selectedId, setSelectedId,
    pendingComponent, setPendingComponent,
    toolMode, wireMode, isSimulating,
    validationResult, setValidationResult,
    onOpenProperties,
    intersectionLogicEnabled,
    defaultWireThickness
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const { theme } = useTheme();

  const [draggingNodeId, setDraggingNodeId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<Point>({ x: 0, y: 0 });
  const [wiring, setWiring] = useState<WiringState | null>(null);
  const [hoveredPort, setHoveredPort] = useState<{ nodeId: string, index: number, isInput: boolean } | null>(null);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });

  const getManhattanPoints = (x1: number, y1: number, x2: number, y2: number): Point[] => {
    const dx = x2 - x1;
    if (dx > 20) {
        const midX = (x1 + x2) / 2;
        return [{x: x1, y: y1}, {x: midX, y: y1}, {x: midX, y: y2}, {x: x2, y: y2}];
    }
    const stub = 20;
    const midY = (y1 + y2) / 2;
    return [{x: x1, y: y1}, {x: x1 + stub, y: y1}, {x: x1 + stub, y: midY}, {x: x2 - stub, y: midY}, {x: x2 - stub, y: y2}, {x: x2, y: y2}];
  };

  const wireIntersections = useMemo(() => {
    if (!intersectionLogicEnabled || wireMode !== 'manhattan') return [];

    const results: { point: Point, wire1: Wire, wire2: Wire }[] = [];
    const wires = circuit.wires;

    for (let i = 0; i < wires.length; i++) {
        for (let j = i + 1; j < wires.length; j++) {
            const w1 = wires[i];
            const w2 = wires[j];
            const s1 = circuit.nodes.find(n => n.id === w1.sourceNodeId);
            const t1 = circuit.nodes.find(n => n.id === w1.targetNodeId);
            const s2 = circuit.nodes.find(n => n.id === w2.sourceNodeId);
            const t2 = circuit.nodes.find(n => n.id === w2.targetNodeId);
            if (!s1 || !t1 || !s2 || !t2) continue;

            const p1 = s1.position.x + getOutputPorts(s1)[w1.sourceOutputIndex].x;
            const q1 = s1.position.y + getOutputPorts(s1)[w1.sourceOutputIndex].y;
            const p2 = t1.position.x + getInputPorts(t1)[w1.targetInputIndex].x;
            const q2 = t1.position.y + getInputPorts(t1)[w1.targetInputIndex].y;

            const p3 = s2.position.x + getOutputPorts(s2)[w2.sourceOutputIndex].x;
            const q3 = s2.position.y + getOutputPorts(s2)[w2.sourceOutputIndex].y;
            const p4 = t2.position.x + getInputPorts(t2)[w2.targetInputIndex].x;
            const q4 = t2.position.y + getInputPorts(t2)[w2.targetInputIndex].y;

            const pts1 = getManhattanPoints(p1, q1, p2, q2);
            const pts2 = getManhattanPoints(p3, q3, p4, q4);

            for (let a = 0; a < pts1.length - 1; a++) {
                for (let b = 0; b < pts2.length - 1; b++) {
                    const intersect = getIntersection(pts1[a], pts1[a+1], pts2[b], pts2[b+1]);
                    if (intersect) {
                        const alreadyJunctioned = circuit.nodes.some(n => 
                            n.type === 'JUNCTION' && 
                            Math.abs(n.position.x + 5 - intersect.x) < 2 && 
                            Math.abs(n.position.y + 5 - intersect.y) < 2
                        );
                        if (!alreadyJunctioned) {
                            results.push({ point: intersect, wire1: w1, wire2: w2 });
                        }
                    }
                }
            }
        }
    }
    return results;
  }, [circuit, intersectionLogicEnabled, wireMode]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
            if (pendingComponent) setPendingComponent(null);
            if (wiring) setWiring(null);
            if (selectedId) setSelectedId(null);
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [pendingComponent, wiring, selectedId, setPendingComponent, setSelectedId]);

  const addNode = (type: NodeType, x: number, y: number) => {
    onCommit();
    const def = NODE_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newNode: NodeData = {
      id: `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      position: { x: snapX, y: snapY },
      inputs: Array(def.inputs).fill(false),
      outputs: Array(def.outputs).fill(false),
      internalState: {},
      properties: { label: '', labelPosition: 'Top', inputCount: def.inputs, propagationDelay: 0, initialState: false, romValue: false, interval: type === 'CLOCK' ? 20 : 0 }
    };

    onUpdateCircuit([...circuit.nodes, newNode], circuit.wires);
    setSelectedId(newNode.id);
  };

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
    if (e.button !== 0) return; 
    e.stopPropagation();
    setSelectedId(id);

    if (wiring || pendingComponent) return; 

    const node = circuit.nodes.find(n => n.id === id);
    if (!node) return;

    const isInteractive = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

    if (toolMode === 'interact' || isSimulating) {
        if (isInteractive) {
            if (!isSimulating) onCommit();
            let toggledNodes = circuit.nodes;

            if (node.type.startsWith('INPUT_')) {
                const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
                const relY = e.clientY - rect.top; 
                const relX = e.clientX - rect.left;
                const { width, height } = getNodeDimensions(node);
                const bitCount = node.outputs.length;

                // Check for clicking on the "Header" to set direct value
                if (relY < 25) {
                    const inputVal = window.prompt(`Set Value for ${bitCount}-bit Input:`);
                    if (inputVal !== null) {
                        let val = parseInt(inputVal);
                        if (!isNaN(val)) {
                            const newOutputs = [];
                            for(let i=0; i<bitCount; i++) { newOutputs.push(!!((val >> i) & 1)); }
                            toggledNodes = circuit.nodes.map(n => n.id === id ? { ...n, outputs: newOutputs } : n);
                            onUpdateCircuit(toggledNodes, circuit.wires);
                        }
                    }
                    return;
                }

                // Check for individual bit clicks in the body or footer
                let bitIndexToCheck = -1;
                if (relY > height - 30) {
                    const bitWidth = 8;
                    const bitSpacing = 1;
                    const nibbleGap = 4;
                    const totalWidth = bitCount * bitWidth + (bitCount - 1) * bitSpacing + Math.floor((bitCount - 1) / 4) * nibbleGap;
                    const startX = (width - totalWidth) / 2 + bitWidth / 2;
                    for (let i = 0; i < bitCount; i++) {
                        const nibblesBefore = Math.floor(i / 4);
                        const xPos = startX + i * (bitWidth + bitSpacing) + nibblesBefore * nibbleGap;
                        if (Math.abs(relX - xPos) < 10) { bitIndexToCheck = bitCount - 1 - i; break; }
                    }
                } else {
                    const rowIdx = Math.floor((relY - MB_START_Y) / MB_SPACING); 
                    if (rowIdx >= 0 && rowIdx < bitCount) bitIndexToCheck = rowIdx;
                }

                if (bitIndexToCheck >= 0 && bitIndexToCheck < bitCount) {
                    toggledNodes = circuit.nodes.map(n => {
                        if (n.id === id) {
                            const newOutputs = [...n.outputs];
                            newOutputs[bitIndexToCheck] = !newOutputs[bitIndexToCheck];
                            return { ...n, outputs: newOutputs };
                        }
                        return n;
                    });
                }
            } else {
                toggledNodes = circuit.nodes.map(n => n.id === id ? { ...n, outputs: [!n.outputs[0]] } : n);
            }
            onUpdateCircuit(toggledNodes, circuit.wires);
            return;
        }

        if (toolMode === 'interact') return;
    }

    if (toolMode === 'move' || toolMode === 'junction') {
        onCommit();
        setDraggingNodeId(id);
        const rect = containerRef.current!.getBoundingClientRect();
        setDragOffset({ x: e.clientX - rect.left - node.position.x, y: e.clientY - rect.top - node.position.y });
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    // Automatic port snapping logic
    if (wiring) {
        let bestPort = null;
        let minDist = 25; // Snap threshold radius

        circuit.nodes.forEach(node => {
            const ports = getInputPorts(node);
            ports.forEach((offset, idx) => {
                const px = node.position.x + offset.x;
                const py = node.position.y + offset.y;
                const dist = Math.sqrt(Math.pow(x - px, 2) + Math.pow(y - py, 2));
                if (dist < minDist) {
                    minDist = dist;
                    bestPort = { nodeId: node.id, index: idx, isInput: true };
                }
            });
        });

        if (bestPort !== hoveredPort) {
            setHoveredPort(bestPort);
        }
    }

    if (draggingNodeId) {
        const snapX = Math.round((x - dragOffset.x) / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round((y - dragOffset.y) / GRID_SIZE) * GRID_SIZE;
        const updatedNodes = circuit.nodes.map(n => n.id === draggingNodeId ? { ...n, position: { x: snapX, y: snapY } } : n);
        onUpdateCircuit(updatedNodes, circuit.wires);
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (wiring && hoveredPort && hoveredPort.isInput) {
        completeWiring(e, hoveredPort.nodeId, hoveredPort.index);
    }
    setDraggingNodeId(null);
    setWiring(null);
    setHoveredPort(null);
  };

  const handleContextMenu = (e: React.MouseEvent, id: string) => {
      e.preventDefault();
      e.stopPropagation();
      setSelectedId(id);
      if (onOpenProperties) onOpenProperties();
  };

  const startWiring = (e: React.PointerEvent, nodeId: string, outputIndex: number) => {
    e.stopPropagation();
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    setWiring({ sourceNodeId: nodeId, sourceOutputIndex: outputIndex, startPoint: { x: e.clientX - rect.left, y: e.clientY - rect.top }, active: true });
  };

  const completeWiring = (e: React.PointerEvent, targetNodeId: string, inputIndex: number) => {
    if (!wiring || wiring.sourceNodeId === targetNodeId) { 
        setWiring(null);
        return; 
    }
    onCommit();
    const exists = circuit.wires.some(w => w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex);
    let newWires = exists ? circuit.wires.filter(w => !(w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex)) : [...circuit.wires];

    newWires.push({ 
        id: `wire-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`, 
        sourceNodeId: wiring.sourceNodeId, 
        sourceOutputIndex: wiring.sourceOutputIndex, 
        targetNodeId: targetNodeId, 
        targetInputIndex: inputIndex, 
        state: false,
        thickness: defaultWireThickness
    });

    onUpdateCircuit(circuit.nodes, newWires);
    setWiring(null);
    setHoveredPort(null);
  };

  const handleWireClick = (e: React.PointerEvent, wire: Wire) => {
    e.stopPropagation();
    setSelectedId(wire.id);
    if (toolMode === 'junction') {
        const rect = containerRef.current!.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        onCommit();
        createJunctionAtPoint({ x, y }, wire);
    }
  };

  const createJunctionAtPoint = (point: Point, wire1: Wire, wire2?: Wire) => {
    const snapX = Math.round(point.x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(point.y / GRID_SIZE) * GRID_SIZE;
    const junctionId = `node-${Date.now()}-junction`;
    const newJunction: NodeData = { id: junctionId, type: 'JUNCTION', position: { x: snapX - 5, y: snapY - 5 }, inputs: [false], outputs: [false], properties: { label: '' } };

    const wire1_1: Wire = { id: `wire-${Date.now()}-1a`, sourceNodeId: wire1.sourceNodeId, sourceOutputIndex: wire1.sourceOutputIndex, targetNodeId: junctionId, targetInputIndex: 0, state: wire1.state, thickness: wire1.thickness };
    const wire1_2: Wire = { id: `wire-${Date.now()}-1b`, sourceNodeId: junctionId, sourceOutputIndex: 0, targetNodeId: wire1.targetNodeId, targetInputIndex: wire1.targetInputIndex, state: wire1.state, thickness: wire1.thickness };

    let newWires = circuit.wires.filter(w => w.id !== wire1.id).concat([wire1_1, wire1_2]);

    if (wire2) {
        const wire2_1: Wire = { id: `wire-${Date.now()}-2a`, sourceNodeId: wire2.sourceNodeId, sourceOutputIndex: wire2.sourceOutputIndex, targetNodeId: junctionId, targetInputIndex: 0, state: wire2.state, thickness: wire2.thickness };
        const wire2_2: Wire = { id: `wire-${Date.now()}-2b`, sourceNodeId: junctionId, sourceOutputIndex: 0, targetNodeId: wire2.targetNodeId, targetInputIndex: wire2.targetInputIndex, state: wire2.state, thickness: wire2.thickness };
        newWires = newWires.filter(w => w.id !== wire2.id).concat([wire2_1, wire2_2]);
    }

    onUpdateCircuit([...circuit.nodes, newJunction], newWires);
    setSelectedId(junctionId);
  };

  const handleCanvasClick = (e: React.PointerEvent) => {
      if (e.button !== 0) return; 
      if (pendingComponent && containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        addNode(pendingComponent, e.clientX - rect.left, e.clientY - rect.top);
        setPendingComponent(null);
        return;
      }
      setSelectedId(null);
      if (validationResult?.valid) setValidationResult(null);
  };

  const getWirePath = (x1: number, y1: number, x2: number, y2: number) => {
    if (wireMode === 'bezier') {
        const dx = Math.abs(x2 - x1);
        const dy = Math.abs(y2 - y1);
        const controlPointOffset = Math.min(Math.max(dx * 0.45, 30), 120);
        // Add vertical bias for tight corners
        const vBias = dx < 40 ? dy * 0.2 : 0;
        return `M ${x1} ${y1} C ${x1 + controlPointOffset} ${y1 - vBias}, ${x2 - controlPointOffset} ${y2 + vBias}, ${x2} ${y2}`;
    }
    const dx = x2 - x1;
    if (dx > 20) {
        const midX = (x1 + x2) / 2;
        return `M ${x1} ${y1} L ${midX} ${y1} L ${midX} ${y2} L ${x2} ${y2}`;
    }
    const stub = 20;
    const midY = (y1 + y2) / 2;
    return `M ${x1} ${y1} L ${x1 + stub} ${y1} L ${x1 + stub} ${midY} L ${x2 - stub} ${midY} L ${x2 - stub} ${y2} L ${x2} ${y2}`;
  };

  const getLabelStyle = (pos: string | undefined): React.CSSProperties => {
      switch (pos) {
          case 'Bottom': return { top: '100%', left: '50%', transform: 'translate(-50%, 8px)' };
          case 'Left': return { top: '50%', right: '100%', transform: 'translate(-8px, -50%)' };
          case 'Right': return { top: '50%', left: '100%', transform: 'translate(8px, -50%)' };
          case 'Top': default: return { bottom: '100%', left: '50%', transform: 'translate(-50%, -8px)' };
      }
  };

  const ghostSnapX = Math.round(mousePos.x / GRID_SIZE) * GRID_SIZE;
  const ghostSnapY = Math.round(mousePos.y / GRID_SIZE) * GRID_SIZE;
  const pendingDef = pendingComponent ? NODE_DEFINITIONS[pendingComponent] : null;

  return (
    <div 
        ref={containerRef}
        className={`flex-1 relative w-full h-full overflow-hidden bg-zinc-50 dark:bg-zinc-950 touch-none
            ${isSimulating || toolMode === 'interact' ? 'cursor-default' : pendingComponent ? 'cursor-cell' : 'cursor-crosshair'}`}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerDown={handleCanvasClick}
        onContextMenu={(e) => e.preventDefault()}
    >
        {/* Grid Background */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full opacity-20 dark:opacity-20">
            <defs>
                <pattern id="grid" width={GRID_SIZE} height={GRID_SIZE} patternUnits="userSpaceOnUse">
                    <circle cx="1" cy="1" r="1" className="fill-zinc-400 dark:fill-zinc-500" />
                </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#grid)" />
        </svg>

        {/* Wires Layer */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
            {circuit.wires.map(wire => {
                const sourceNode = circuit.nodes.find(n => n.id === wire.sourceNodeId);
                const targetNode = circuit.nodes.find(n => n.id === wire.targetNodeId);
                if (!sourceNode || !targetNode) return null;
                const sourcePorts = getOutputPorts(sourceNode);
                const targetPorts = getInputPorts(targetNode);
                const outputOffset = sourcePorts[wire.sourceOutputIndex] || { x: 0, y: 0 };
                const inputOffset = targetPorts[wire.targetInputIndex] || { x: 0, y: 0 };
                const startX = sourceNode.position.x + outputOffset.x;
                const startY = sourceNode.position.y + outputOffset.y;
                const endX = targetNode.position.x + inputOffset.x;
                const endY = targetNode.position.y + inputOffset.y;
                const isSelected = selectedId === wire.id;
                const pathData = getWirePath(startX, startY, endX, endY);
                const inactiveColor = wire.color || (theme === 'dark' ? "#52525b" : "#a1a1aa");
                const activeColor = wire.activeColor || "#22d3ee";
                const thickness = wire.thickness || defaultWireThickness;
                const strokeColor = wire.state ? activeColor : (isSelected ? activeColor : inactiveColor);

                return (
                    <g 
                      key={wire.id} 
                      onPointerDown={(e) => handleWireClick(e, wire)} 
                      onContextMenu={(e) => handleContextMenu(e, wire.id)}
                      className={`pointer-events-auto cursor-pointer group`}
                    >
                        <path d={pathData} stroke="transparent" strokeWidth={Math.max(16, thickness + 12)} fill="none" />
                        {wire.state && (
                            <path 
                                d={pathData} 
                                stroke={activeColor} 
                                strokeWidth={thickness + 3} 
                                fill="none" 
                                opacity="0.4" 
                                filter="blur(3px)" 
                                strokeDasharray={`4, ${thickness * 4}`}
                                className="animate-signal-flow"
                            />
                        )}
                        <path 
                            d={pathData} 
                            stroke={strokeColor} 
                            strokeWidth={isSelected ? thickness + 1 : thickness} 
                            fill="none" 
                            className="transition-all duration-150" 
                            strokeDasharray={isSelected ? "4" : "0"} 
                            strokeLinejoin="round" 
                            strokeLinecap="round" 
                        />
                    </g>
                );
            })}

            {wireIntersections.map((intersect, idx) => (
                <g 
                    key={`intersect-${idx}`}
                    className="pointer-events-auto cursor-pointer transition-all hover:scale-125"
                    onPointerDown={(e) => {
                        e.stopPropagation();
                        onCommit();
                        createJunctionAtPoint(intersect.point, intersect.wire1, intersect.wire2);
                    }}
                >
                    <circle cx={intersect.point.x} cy={intersect.point.y} r="12" fill="transparent" />
                    <circle 
                        cx={intersect.point.x} cy={intersect.point.y} r="4" 
                        fill="none" stroke="#22d3ee" strokeWidth="1.5" strokeDasharray="2"
                        className="animate-spin-slow"
                    />
                </g>
            ))}

            {wiring && (
                <path 
                    d={getWirePath(wiring.startPoint.x, wiring.startPoint.y, hoveredPort ? circuit.nodes.find(n => n.id === hoveredPort!.nodeId)!.position.x + (hoveredPort!.isInput ? getInputPorts(circuit.nodes.find(n => n.id === hoveredPort!.nodeId)!)[hoveredPort!.index].x : getOutputPorts(circuit.nodes.find(n => n.id === hoveredPort!.nodeId)!)[hoveredPort!.index].x) : mousePos.x, hoveredPort ? circuit.nodes.find(n => n.id === hoveredPort!.nodeId)!.position.y + (hoveredPort!.isInput ? getInputPorts(circuit.nodes.find(n => n.id === hoveredPort!.nodeId)!)[hoveredPort!.index].y : getOutputPorts(circuit.nodes.find(n => n.id === hoveredPort!.nodeId)!)[hoveredPort!.index].y) : mousePos.y)} 
                    stroke={hoveredPort?.isInput ? "#22d3ee" : "#fbbf24"} 
                    strokeWidth={defaultWireThickness} fill="none" strokeDasharray="4" className="animate-pulse" strokeLinejoin="round" 
                />
            )}
        </svg>

        {/* Nodes and Ports Layer */}
        {circuit.nodes.map(node => {
            const { width, height } = getNodeDimensions(node);
            const isSelected = selectedId === node.id;
            const isInvalid = validationResult?.invalidNodeIds?.includes(node.id);
            const inputPorts = getInputPorts(node);
            const outputPorts = getOutputPorts(node);
            const def = NODE_DEFINITIONS[node.type];
            const canInteract = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

            const cursorClass = (toolMode === 'interact' || isSimulating) 
                ? (canInteract ? 'cursor-pointer' : 'cursor-default') 
                : (toolMode === 'move' ? 'cursor-grab active:cursor-grabbing' : 'cursor-default');

            return (
                <div key={node.id} className={`absolute group select-none transition-transform duration-75 ${isSelected ? 'scale-[1.02]' : ''}`}
                    style={{ left: node.position.x, top: node.position.y, width: width, height: height, pointerEvents: 'none', zIndex: isSelected ? 50 : 10 }}
                    onPointerDown={(e) => e.stopPropagation()}
                >
                    <div className={`absolute inset-0 pointer-events-auto transition-all duration-200 
                            ${isSelected ? 'drop-shadow-[0_0_12px_rgba(34,211,238,0.7)]' : ''} 
                            ${isInvalid ? 'drop-shadow-[0_0_8px_rgba(239,68,68,0.8)]' : ''} ${cursorClass}`}
                        onPointerDown={(e) => handlePointerDown(e, node.id)}
                        onContextMenu={(e) => handleContextMenu(e, node.id)}
                    >
                        <svg width={width} height={height} className="overflow-visible">
                            <GateShape node={node} />
                        </svg>
                    </div>

                    {isSelected && (
                      <div className="absolute -top-10 left-1/2 -translate-x-1/2 flex items-center gap-1 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-lg p-1 shadow-xl pointer-events-auto z-[70] animate-in zoom-in-95">
                        <button onClick={(e) => { e.stopPropagation(); onOpenProperties?.(); }} className="p-1.5 hover:bg-zinc-100 dark:hover:bg-zinc-800 text-cyan-600 rounded-md transition-colors" title="Open Properties"><Settings2 size={16} /></button>
                        <button onClick={(e) => { e.stopPropagation(); (window as any).deleteSelection?.(); }} className="p-1.5 hover:bg-red-50 dark:hover:bg-red-950 text-red-500 rounded-md transition-colors" title="Delete Node"><X size={16} /></button>
                      </div>
                    )}

                    {inputPorts.map((offset, idx) => {
                        const isFloating = validationResult?.floatingInputs?.some(fi => fi.nodeId === node.id && fi.index === idx);
                        const isHovered = hoveredPort?.nodeId === node.id && hoveredPort?.index === idx && hoveredPort.isInput;
                        return (
                        <div key={`input-${idx}`}
                            className="absolute w-8 h-8 -ml-4 -mt-4 rounded-full pointer-events-auto flex items-center justify-center transition-all z-20 cursor-crosshair"
                            style={{ left: offset.x, top: offset.y }}
                            onPointerUp={(e) => wiring && completeWiring(e, node.id, idx)}
                        >
                            <div className={`w-3.5 h-3.5 rounded-full bg-white dark:bg-zinc-900 border-2 transition-all duration-200 ${
                                isHovered ? 'border-cyan-400 bg-cyan-400 scale-150 ring-4 ring-cyan-500/30' :
                                isFloating ? 'border-red-500 bg-red-500/30 ring-4 ring-red-500/20 animate-pulse' : 
                                node.inputs[idx] ? 'border-cyan-400 bg-cyan-100 dark:bg-cyan-900' : 'border-zinc-400 dark:border-zinc-500'
                            }`} />
                        </div>
                        );
                    })}

                    {outputPorts.map((offset, idx) => (
                        <div key={`output-${idx}`}
                            className="absolute w-8 h-8 -ml-4 -mt-4 rounded-full pointer-events-auto flex items-center justify-center transition-transform z-20 cursor-crosshair"
                            style={{ left: offset.x, top: offset.y }}
                            onPointerDown={(e) => !isSimulating && startWiring(e, node.id, idx)}
                        >
                            <div className={`w-3.5 h-3.5 rounded-full bg-white dark:bg-zinc-900 border-2 ${node.outputs[idx] ? 'border-cyan-400 bg-cyan-500' : 'border-zinc-400 dark:border-zinc-500'}`} />
                        </div>
                    ))}

                    {(isSelected || node.properties?.label) && node.type !== 'JUNCTION' && (
                        <div className={`absolute bg-white/95 dark:bg-zinc-900/95 text-zinc-800 dark:text-zinc-100 text-[10px] px-2 py-0.5 rounded border whitespace-nowrap shadow-md pointer-events-none backdrop-blur-sm z-[60] transition-colors
                            ${isSelected ? 'border-cyan-500 font-bold' : 'border-zinc-200 dark:border-zinc-700'}`}
                            style={getLabelStyle(node.properties?.labelPosition)}
                        >
                            {node.properties?.label || def.name}
                        </div>
                    )}
                </div>
            );
        })}

        {/* Pending Component Ghost */}
        {pendingComponent && pendingDef && (
            <div className="absolute pointer-events-none opacity-50 z-50"
                style={{ left: ghostSnapX, top: ghostSnapY, width: pendingDef.width, height: pendingDef.height }}>
                <svg width={pendingDef.width} height={pendingDef.height} className="overflow-visible">
                        <GateShape node={{ id: 'ghost', type: pendingComponent, position: {x: 0, y: 0}, inputs: Array(pendingDef.inputs).fill(false), outputs: Array(pendingDef.outputs).fill(false), properties: { inputCount: pendingDef.inputs } }} />
                </svg>
            </div>
        )}

        <style>{`
            @keyframes spin-slow {
                from { transform: rotate(0deg); }
                to { transform: rotate(360deg); }
            }
            @keyframes signal-flow {
                from { stroke-dashoffset: 20; }
                to { stroke-dashoffset: 0; }
            }
            .animate-spin-slow {
                animation: spin-slow 8s linear infinite;
                transform-origin: center;
            }
            .animate-signal-flow {
                animation: signal-flow 0.8s linear infinite;
            }
        `}</style>
    </div>
  );
};

import React, { useRef, useState, useEffect, useMemo } from 'react';
import { GRID_SIZE, NODE_DEFINITIONS, MB_SPACING, MB_START_Y } from '../constants';
import { CircuitState, NodeData, NodeType, Wire, Point, WiringState } from '../types';
import { GateShape } from './GateShapes';
import { getNodeDimensions, getInputPorts, getOutputPorts } from '../utils/componentUtils';
import { AlertTriangle, Info, X, Settings2 } from 'lucide-react';
import { useTheme } from './ThemeContext';

interface CircuitCanvasProps {
    circuit: CircuitState;
    onUpdateCircuit: (nodes: NodeData[], wires: Wire[]) => void;
    onCommit: () => void;
    selectedId: string | null;
    setSelectedId: (id: string | null) => void;
    pendingComponent: NodeType | null;
    setPendingComponent: (type: NodeType | null) => void;
    toolMode: 'move' | 'interact' | 'junction';
    wireMode: 'manhattan' | 'bezier';
    isSimulating: boolean;
    validationResult: {
        valid: boolean;
        messages: string[];
        invalidNodeIds: string[];
        floatingInputs: { nodeId: string; index: number }[];
    } | null;
    setValidationResult: (res: any) => void;
    onOpenProperties?: () => void;
    intersectionLogicEnabled: boolean;
    defaultWireThickness: number;
}

const getIntersection = (p1: Point, p2: Point, p3: Point, p4: Point): Point | null => {
    const denom = (p4.y - p3.y) * (p2.x - p1.x) - (p4.x - p3.x) * (p2.y - p1.y);
    if (denom === 0) return null; 
    const ua = ((p4.x - p3.x) * (p1.y - p3.y) - (p4.y - p3.y) * (p1.x - p3.x)) / denom;
    const ub = ((p2.x - p1.x) * (p1.y - p3.y) - (p2.y - p1.y) * (p1.x - p3.x)) / denom;
    if (ua > 0.01 && ua < 0.99 && ub > 0.01 && ub < 0.99) {
        return {
            x: p1.x + ua * (p2.x - p1.x),
            y: p1.y + ua * (p2.y - p1.y)
        };
    }
    return null;
};

export const CircuitCanvas: React.FC<CircuitCanvasProps> = ({ 
    circuit, onUpdateCircuit, onCommit,
    selectedId, setSelectedId,
    pendingComponent, setPendingComponent,
    toolMode, wireMode, isSimulating,
    validationResult, setValidationResult,
    onOpenProperties,
    intersectionLogicEnabled,
    defaultWireThickness
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const { theme } = useTheme();

  const [draggingNodeId, setDraggingNodeId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<Point>({ x: 0, y: 0 });
  const [wiring, setWiring] = useState<WiringState | null>(null);
  const [hoveredPort, setHoveredPort] = useState<{ nodeId: string, index: number, isInput: boolean } | null>(null);
  const [mousePos, setMousePos] = useState<Point>({ x: 0, y: 0 });

  const getManhattanPoints = (x1: number, y1: number, x2: number, y2: number): Point[] => {
    const dx = x2 - x1;
    if (dx > 20) {
        const midX = (x1 + x2) / 2;
        return [{x: x1, y: y1}, {x: midX, y: y1}, {x: midX, y: y2}, {x: x2, y: y2}];
    }
    const stub = 20;
    const midY = (y1 + y2) / 2;
    return [{x: x1, y: y1}, {x: x1 + stub, y: y1}, {x: x1 + stub, y: midY}, {x: x2 - stub, y: midY}, {x: x2 - stub, y: y2}, {x: x2, y: y2}];
  };

  const wireIntersections = useMemo(() => {
    if (!intersectionLogicEnabled || wireMode !== 'manhattan') return [];

    const results: { point: Point, wire1: Wire, wire2: Wire }[] = [];
    const wires = circuit.wires;

    for (let i = 0; i < wires.length; i++) {
        for (let j = i + 1; j < wires.length; j++) {
            const w1 = wires[i];
            const w2 = wires[j];
            const s1 = circuit.nodes.find(n => n.id === w1.sourceNodeId);
            const t1 = circuit.nodes.find(n => n.id === w1.targetNodeId);
            const s2 = circuit.nodes.find(n => n.id === w2.sourceNodeId);
            const t2 = circuit.nodes.find(n => n.id === w2.targetNodeId);
            if (!s1 || !t1 || !s2 || !t2) continue;

            const p1 = s1.position.x + getOutputPorts(s1)[w1.sourceOutputIndex].x;
            const q1 = s1.position.y + getOutputPorts(s1)[w1.sourceOutputIndex].y;
            const p2 = t1.position.x + getInputPorts(t1)[w1.targetInputIndex].x;
            const q2 = t1.position.y + getInputPorts(t1)[w1.targetInputIndex].y;

            const p3 = s2.position.x + getOutputPorts(s2)[w2.sourceOutputIndex].x;
            const q3 = s2.position.y + getOutputPorts(s2)[w2.sourceOutputIndex].y;
            const p4 = t2.position.x + getInputPorts(t2)[w2.targetInputIndex].x;
            const q4 = t2.position.y + getInputPorts(t2)[w2.targetInputIndex].y;

            const pts1 = getManhattanPoints(p1, q1, p2, q2);
            const pts2 = getManhattanPoints(p3, q3, p4, q4);

            for (let a = 0; a < pts1.length - 1; a++) {
                for (let b = 0; b < pts2.length - 1; b++) {
                    const intersect = getIntersection(pts1[a], pts1[a+1], pts2[b], pts2[b+1]);
                    if (intersect) {
                        const alreadyJunctioned = circuit.nodes.some(n => 
                            n.type === 'JUNCTION' && 
                            Math.abs(n.position.x + 5 - intersect.x) < 2 && 
                            Math.abs(n.position.y + 5 - intersect.y) < 2
                        );
                        if (!alreadyJunctioned) {
                            results.push({ point: intersect, wire1: w1, wire2: w2 });
                        }
                    }
                }
            }
        }
    }
    return results;
  }, [circuit, intersectionLogicEnabled, wireMode]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
            if (pendingComponent) setPendingComponent(null);
            if (wiring) setWiring(null);
            if (selectedId) setSelectedId(null);
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [pendingComponent, wiring, selectedId, setPendingComponent, setSelectedId]);

  const addNode = (type: NodeType, x: number, y: number) => {
    onCommit();
    const def = NODE_DEFINITIONS[type];
    const snapX = Math.round(x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(y / GRID_SIZE) * GRID_SIZE;

    const newNode: NodeData = {
      id: `node-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      position: { x: snapX, y: snapY },
      inputs: Array(def.inputs).fill(false),
      outputs: Array(def.outputs).fill(false),
      internalState: {},
      properties: { label: '', labelPosition: 'Top', inputCount: def.inputs, propagationDelay: 0, initialState: false, romValue: false, interval: type === 'CLOCK' ? 20 : 0 }
    };

    onUpdateCircuit([...circuit.nodes, newNode], circuit.wires);
    setSelectedId(newNode.id);
  };

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
    if (e.button !== 0) return; 
    e.stopPropagation();
    setSelectedId(id);

    if (wiring || pendingComponent) return; 

    const node = circuit.nodes.find(n => n.id === id);
    if (!node) return;

    const isInteractive = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

    if (toolMode === 'interact' || isSimulating) {
        if (isInteractive) {
            if (!isSimulating) onCommit();
            let toggledNodes = circuit.nodes;

            if (node.type.startsWith('INPUT_')) {
                const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
                const relY = e.clientY - rect.top; 
                const relX = e.clientX - rect.left;
                const { width, height } = getNodeDimensions(node);
                const bitCount = node.outputs.length;

                // Check for clicking on the "Header" to set direct value
                if (relY < 25) {
                    const inputVal = window.prompt(`Set Value for ${bitCount}-bit Input:`);
                    if (inputVal !== null) {
                        let val = parseInt(inputVal);
                        if (!isNaN(val)) {
                            const newOutputs = [];
                            for(let i=0; i<bitCount; i++) { newOutputs.push(!!((val >> i) & 1)); }
                            toggledNodes = circuit.nodes.map(n => n.id === id ? { ...n, outputs: newOutputs } : n);
                            onUpdateCircuit(toggledNodes, circuit.wires);
                        }
                    }
                    return;
                }

                // Check for individual bit clicks in the body or footer
                let bitIndexToCheck = -1;
                if (relY > height - 30) {
                    const bitWidth = 8;
                    const bitSpacing = 1;
                    const nibbleGap = 4;
                    const totalWidth = bitCount * bitWidth + (bitCount - 1) * bitSpacing + Math.floor((bitCount - 1) / 4) * nibbleGap;
                    const startX = (width - totalWidth) / 2 + bitWidth / 2;
                    for (let i = 0; i < bitCount; i++) {
                        const nibblesBefore = Math.floor(i / 4);
                        const xPos = startX + i * (bitWidth + bitSpacing) + nibblesBefore * nibbleGap;
                        if (Math.abs(relX - xPos) < 10) { bitIndexToCheck = bitCount - 1 - i; break; }
                    }
                } else {
                    const rowIdx = Math.floor((relY - MB_START_Y) / MB_SPACING); 
                    if (rowIdx >= 0 && rowIdx < bitCount) bitIndexToCheck = rowIdx;
                }

                if (bitIndexToCheck >= 0 && bitIndexToCheck < bitCount) {
                    toggledNodes = circuit.nodes.map(n => {
                        if (n.id === id) {
                            const newOutputs = [...n.outputs];
                            newOutputs[bitIndexToCheck] = !newOutputs[bitIndexToCheck];
                            return { ...n, outputs: newOutputs };
                        }
                        return n;
                    });
                }
            } else {
                toggledNodes = circuit.nodes.map(n => n.id === id ? { ...n, outputs: [!n.outputs[0]] } : n);
            }
            onUpdateCircuit(toggledNodes, circuit.wires);
            return;
        }

        if (toolMode === 'interact') return;
    }

    if (toolMode === 'move' || toolMode === 'junction') {
        onCommit();
        setDraggingNodeId(id);
        const rect = containerRef.current!.getBoundingClientRect();
        setDragOffset({ x: e.clientX - rect.left - node.position.x, y: e.clientY - rect.top - node.position.y });
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });

    // Automatic port snapping logic
    if (wiring) {
        let bestPort = null;
        let minDist = 25; // Snap threshold radius

        circuit.nodes.forEach(node => {
            const ports = getInputPorts(node);
            ports.forEach((offset, idx) => {
                const px = node.position.x + offset.x;
                const py = node.position.y + offset.y;
                const dist = Math.sqrt(Math.pow(x - px, 2) + Math.pow(y - py, 2));
                if (dist < minDist) {
                    minDist = dist;
                    bestPort = { nodeId: node.id, index: idx, isInput: true };
                }
            });
        });

        if (bestPort !== hoveredPort) {
            setHoveredPort(bestPort);
        }
    }

    if (draggingNodeId) {
        const snapX = Math.round((x - dragOffset.x) / GRID_SIZE) * GRID_SIZE;
        const snapY = Math.round((y - dragOffset.y) / GRID_SIZE) * GRID_SIZE;
        const updatedNodes = circuit.nodes.map(n => n.id === draggingNodeId ? { ...n, position: { x: snapX, y: snapY } } : n);
        onUpdateCircuit(updatedNodes, circuit.wires);
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (wiring && hoveredPort && hoveredPort.isInput) {
        completeWiring(e, hoveredPort.nodeId, hoveredPort.index);
    }
    setDraggingNodeId(null);
    setWiring(null);
    setHoveredPort(null);
  };

  const handleContextMenu = (e: React.MouseEvent, id: string) => {
      e.preventDefault();
      e.stopPropagation();
      setSelectedId(id);
      if (onOpenProperties) onOpenProperties();
  };

  const startWiring = (e: React.PointerEvent, nodeId: string, outputIndex: number) => {
    e.stopPropagation();
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    setWiring({ sourceNodeId: nodeId, sourceOutputIndex: outputIndex, startPoint: { x: e.clientX - rect.left, y: e.clientY - rect.top }, active: true });
  };

  const completeWiring = (e: React.PointerEvent, targetNodeId: string, inputIndex: number) => {
    if (!wiring || wiring.sourceNodeId === targetNodeId) { 
        setWiring(null);
        return; 
    }
    onCommit();
    const exists = circuit.wires.some(w => w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex);
    let newWires = exists ? circuit.wires.filter(w => !(w.targetNodeId === targetNodeId && w.targetInputIndex === inputIndex)) : [...circuit.wires];

    newWires.push({ 
        id: `wire-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`, 
        sourceNodeId: wiring.sourceNodeId, 
        sourceOutputIndex: wiring.sourceOutputIndex, 
        targetNodeId: targetNodeId, 
        targetInputIndex: inputIndex, 
        state: false,
        thickness: defaultWireThickness
    });

    onUpdateCircuit(circuit.nodes, newWires);
    setWiring(null);
    setHoveredPort(null);
  };

  const handleWireClick = (e: React.PointerEvent, wire: Wire) => {
    e.stopPropagation();
    setSelectedId(wire.id);
    if (toolMode === 'junction') {
        const rect = containerRef.current!.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        onCommit();
        createJunctionAtPoint({ x, y }, wire);
    }
  };

  const createJunctionAtPoint = (point: Point, wire1: Wire, wire2?: Wire) => {
    const snapX = Math.round(point.x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(point.y / GRID_SIZE) * GRID_SIZE;
    const junctionId = `node-${Date.now()}-junction`;
    const newJunction: NodeData = { id: junctionId, type: 'JUNCTION', position: { x: snapX - 5, y: snapY - 5 }, inputs: [false], outputs: [false], properties: { label: '' } };

    const wire1_1: Wire = { id: `wire-${Date.now()}-1a`, sourceNodeId: wire1.sourceNodeId, sourceOutputIndex: wire1.sourceOutputIndex, targetNodeId: junctionId, targetInputIndex: 0, state: wire1.state, thickness: wire1.thickness };
    const wire1_2: Wire = { id: `wire-${Date.now()}-1b`, sourceNodeId: junctionId, sourceOutputIndex: 0, targetNodeId: wire1.targetNodeId, targetInputIndex: wire1.targetInputIndex, state: wire1.state, thickness: wire1.thickness };

    let newWires = circuit.wires.filter(w => w.id !== wire1.id).concat([wire1_1, wire1_2]);

    if (wire2) {
        const wire2_1: Wire = { id: `wire-${Date.now()}-2a`, sourceNodeId: wire2.sourceNodeId, sourceOutputIndex: wire2.sourceOutputIndex, targetNodeId: junctionId, targetInputIndex: 0, state: wire2.state, thickness: wire2.thickness };
        const wire2_2: Wire = { id: `wire-${Date.now()}-2b`, sourceNodeId: junctionId, sourceOutputIndex: 0, targetNodeId: wire2.targetNodeId, targetInputIndex: wire2.targetInputIndex, state: wire2.state, thickness: wire2.thickness };
        newWires = newWires.filter(w => w.id !== wire2.id).concat([wire2_1, wire2_2]);
    }

    onUpdateCircuit([...circuit.nodes, newJunction], newWires);
    setSelectedId(junctionId);
  };

  const handleCanvasClick = (e: React.PointerEvent) => {
      if (e.button !== 0) return; 
      if (pendingComponent && containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        addNode(pendingComponent, e.clientX - rect.left, e.clientY - rect.top);
        setPendingComponent(null);
        return;
      }
      setSelectedId(null);
      if (validationResult?.valid) setValidationResult(null);
  };

  const getWirePath = (x1: number, y1: number, x2: number, y2: number) => {
    if (wireMode === 'bezier') {
        const dx = Math.abs(x2 - x1);
        const dy = Math.abs(y2 - y1);
        const controlPointOffset = Math.min(Math.max(dx * 0.45, 30), 120);
        // Add vertical bias for tight corners
        const vBias = dx < 40 ? dy * 0.2 : 0;
        return `M ${x1} ${y1} C ${x1 + controlPointOffset} ${y1 - vBias}, ${x2 - controlPointOffset} ${y2 + vBias}, ${x2} ${y2}`;
    }
    const dx = x2 - x1;
    if (dx > 20) {
        const midX = (x1 + x2) / 2;
        return `M ${x1} ${y1} L ${midX} ${y1} L ${midX} ${y2} L ${x2} ${y2}`;
    }
    const stub = 20;
    const midY = (y1 + y2) / 2;
    return `M ${x1} ${y1} L ${x1 + stub} ${y1} L ${x1 + stub} ${midY} L ${x2 - stub} ${midY} L ${x2 - stub} ${y2} L ${x2} ${y2}`;
  };

  const getLabelStyle = (pos: string | undefined): React.CSSProperties => {
      switch (pos) {
          case 'Bottom': return { top: '100%', left: '50%', transform: 'translate(-50%, 12px)' };
          case 'Left': return { top: '50%', right: '100%', transform: 'translate(-12px, -50%)' };
          case 'Right': return { top: '50%', left: '100%', transform: 'translate(12px, -50%)' };
          case 'Top': default: return { bottom: '100%', left: '50%', transform: 'translate(-50%, -12px)' };
      }
  };

  const ghostSnapX = Math.round(mousePos.x / GRID_SIZE) * GRID_SIZE;
  const ghostSnapY = Math.round(mousePos.y / GRID_SIZE) * GRID_SIZE;
  const pendingDef = pendingComponent ? NODE_DEFINITIONS[pendingComponent] : null;

  return (
    <div 
        ref={containerRef}
        className={`flex-1 relative w-full h-full overflow-hidden bg-zinc-50 dark:bg-zinc-950 touch-none
            ${isSimulating || toolMode === 'interact' ? 'cursor-default' : pendingComponent ? 'cursor-cell' : 'cursor-crosshair'}`}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerDown={handleCanvasClick}
        onContextMenu={(e) => e.preventDefault()}
    >
        {/* Grid Background */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full opacity-20 dark:opacity-20">
            <defs>
                <pattern id="grid" width={GRID_SIZE} height={GRID_SIZE} patternUnits="userSpaceOnUse">
                    <circle cx="1" cy="1" r="1" className="fill-zinc-400 dark:fill-zinc-500" />
                </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#grid)" />
        </svg>

        {/* Wires Layer */}
        <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible">
            {circuit.wires.map(wire => {
                const sourceNode = circuit.nodes.find(n => n.id === wire.sourceNodeId);
                const targetNode = circuit.nodes.find(n => n.id === wire.targetNodeId);
                if (!sourceNode || !targetNode) return null;
                const sourcePorts = getOutputPorts(sourceNode);
                const targetPorts = getInputPorts(targetNode);
                const outputOffset = sourcePorts[wire.sourceOutputIndex] || { x: 0, y: 0 };
                const inputOffset = targetPorts[wire.targetInputIndex] || { x: 0, y: 0 };
                const startX = sourceNode.position.x + outputOffset.x;
                const startY = sourceNode.position.y + outputOffset.y;
                const endX = targetNode.position.x + inputOffset.x;
                const endY = targetNode.position.y + inputOffset.y;
                const isSelected = selectedId === wire.id;
                const pathData = getWirePath(startX, startY, endX, endY);
                const inactiveColor = wire.color || (theme === 'dark' ? "#52525b" : "#a1a1aa");
                const activeColor = wire.activeColor || "#22d3ee";
                const thickness = wire.thickness || defaultWireThickness;
                const strokeColor = wire.state ? activeColor : (isSelected ? activeColor : inactiveColor);

                return (
                    <g 
                      key={wire.id} 
                      onPointerDown={(e) => handleWireClick(e, wire)} 
                      onContextMenu={(e) => handleContextMenu(e, wire.id)}
                      className={`pointer-events-auto cursor-pointer group`}
                    >
                        <path d={pathData} stroke="transparent" strokeWidth={Math.max(16, thickness + 12)} fill="none" />
                        {wire.state && (
                            <path 
                                d={pathData} 
                                stroke={activeColor} 
                                strokeWidth={thickness + 3} 
                                fill="none" 
                                opacity="0.4" 
                                filter="blur(3px)" 
                                strokeDasharray={`4, ${thickness * 4}`}
                                className="animate-signal-flow"
                            />
                        )}
                        <path 
                            d={pathData} 
                            stroke={strokeColor} 
                            strokeWidth={isSelected ? thickness + 1 : thickness} 
                            fill="none" 
                            className="transition-all duration-150" 
                            strokeDasharray={isSelected ? "4" : "0"} 
                            strokeLinejoin="round" 
                            strokeLinecap="round" 
                        />
                    </g>
                );
            })}

            {wireIntersections.map((intersect, idx) => (
                <g 
                    key={`intersect-${idx}`}
                    className="pointer-events-auto cursor-pointer transition-all hover:scale-125"
                    onPointerDown={(e) => {
                        e.stopPropagation();
                        onCommit();
                        createJunctionAtPoint(intersect.point, intersect.wire1, intersect.wire2);
                    }}
                >
                    <circle cx={intersect.point.x} cy={intersect.point.y} r="12" fill="transparent" />
                    <circle 
                        cx={intersect.point.x} cy={intersect.point.y} r="4" 
                        fill="none" stroke="#22d3ee" strokeWidth="1.5" strokeDasharray="2"
                        className="animate-spin-slow"
                    />
                </g>
            ))}

            {wiring && (
                <path 
                    d={getWirePath(wiring.startPoint.x, wiring.startPoint.y, hoveredPort ? circuit.nodes.find(n => n.id === hoveredPort!.nodeId)!.position.x + (hoveredPort!.isInput ? getInputPorts(circuit.nodes.find(n => n.id === hoveredPort!.nodeId)!)[hoveredPort!.index].x : getOutputPorts(circuit.nodes.find(n => n.id === hoveredPort!.nodeId)!)[hoveredPort!.index].x) : mousePos.x, hoveredPort ? circuit.nodes.find(n => n.id === hoveredPort!.nodeId)!.position.y + (hoveredPort!.isInput ? getInputPorts(circuit.nodes.find(n => n.id === hoveredPort!.nodeId)!)[hoveredPort!.index].y : getOutputPorts(circuit.nodes.find(n => n.id === hoveredPort!.nodeId)!)[hoveredPort!.index].y) : mousePos.y)} 
                    stroke={hoveredPort?.isInput ? "#22d3ee" : "#fbbf24"} 
                    strokeWidth={defaultWireThickness} fill="none" strokeDasharray="4" className="animate-pulse" strokeLinejoin="round" 
                />
            )}
        </svg>

        {/* Nodes and Ports Layer */}
        {circuit.nodes.map(node => {
            const { width, height } = getNodeDimensions(node);
            const isSelected = selectedId === node.id;
            const isInvalid = validationResult?.invalidNodeIds?.includes(node.id);
            const inputPorts = getInputPorts(node);
            const outputPorts = getOutputPorts(node);
            const def = NODE_DEFINITIONS[node.type];
            const canInteract = ['SWITCH', 'BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type);

            const cursorClass = (toolMode === 'interact' || isSimulating) 
                ? (canInteract ? 'cursor-pointer' : 'cursor-default') 
                : (toolMode === 'move' ? 'cursor-grab active:cursor-grabbing' : 'cursor-default');

            return (
                <div key={node.id} className={`absolute group select-none transition-transform duration-75 ${isSelected ? 'scale-[1.02]' : ''}`}
                    style={{ left: node.position.x, top: node.position.y, width: width, height: height, pointerEvents: 'none', zIndex: isSelected ? 50 : 10 }}
                    onPointerDown={(e) => e.stopPropagation()}
                >
                    <div className={`absolute inset-0 pointer-events-auto transition-all duration-200 
                            ${isSelected ? 'drop-shadow-[0_0_12px_rgba(34,211,238,0.7)]' : ''} 
                            ${isInvalid ? 'drop-shadow-[0_0_8px_rgba(239,68,68,0.8)]' : ''} ${cursorClass}`}
                        onPointerDown={(e) => handlePointerDown(e, node.id)}
                        onContextMenu={(e) => handleContextMenu(e, node.id)}
                    >
                        <svg width={width} height={height} className="overflow-visible">
                            <GateShape node={node} />
                        </svg>
                    </div>

                    {isSelected && (
                      <div className="absolute -top-10 left/2 -translate-x-1/2 flex items-center gap-1 bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-lg p-1 shadow-xl pointer-events-auto z-[70] animate-in zoom-in-95">
                        <button onClick={(e) => { e.stopPropagation(); onOpenProperties?.(); }} className="p-1.5 hover:bg-zinc-100 dark:hover:bg-zinc-800 text-cyan-600 rounded-md transition-colors" title="Open Properties"><Settings2 size={16} /></button>
                        <button onClick={(e) => { e.stopPropagation(); (window as any).deleteSelection?.(); }} className="p-1.5 hover:bg-red-50 dark:hover:bg-red-950 text-red-500 rounded-md transition-colors" title="Delete Node"><X size={16} /></button>
                      </div>
                    )}

                    {inputPorts.map((offset, idx) => {
                        const isFloating = validationResult?.floatingInputs?.some(fi => fi.nodeId === node.id && fi.index === idx);
                        const isHovered = hoveredPort?.nodeId === node.id && hoveredPort?.index === idx && hoveredPort.isInput;
                        return (
                        <div key={`input-${idx}`}
                            className="absolute w-8 h-8 -ml-4 -mt-4 rounded-full pointer-events-auto flex items-center justify-center transition-all z-20 cursor-crosshair"
                            style={{ left: offset.x, top: offset.y }}
                            onPointerUp={(e) => wiring && completeWiring(e, node.id, idx)}
                        >
                            <div className={`w-3.5 h-3.5 rounded-full bg-white dark:bg-zinc-900 border-2 transition-all duration-200 ${
                                isHovered ? 'border-cyan-400 bg-cyan-400 scale-150 ring-4 ring-cyan-500/30' :
                                isFloating ? 'border-red-500 bg-red-500/30 ring-4 ring-red-500/20 animate-pulse' : 
                                node.inputs[idx] ? 'border-cyan-400 bg-cyan-100 dark:bg-cyan-900' : 'border-zinc-400 dark:border-zinc-500'
                            }`} />
                        </div>
                        );
                    })}

                    {outputPorts.map((offset, idx) => (
                        <div key={`output-${idx}`}
                            className="absolute w-8 h-8 -ml-4 -mt-4 rounded-full pointer-events-auto flex items-center justify-center transition-transform z-20 cursor-crosshair"
                            style={{ left: offset.x, top: offset.y }}
                            onPointerDown={(e) => !isSimulating && startWiring(e, node.id, idx)}
                        >
                            <div className={`w-3.5 h-3.5 rounded-full bg-white dark:bg-zinc-900 border-2 ${node.outputs[idx] ? 'border-cyan-400 bg-cyan-500' : 'border-zinc-400 dark:border-zinc-500'}`} />
                        </div>
                    ))}
                </div>
            );
        })}

        {/* Global Label Overlay Layer (Renders on top of everything) */}
        <div className="absolute inset-0 pointer-events-none z-[100]">
            {circuit.nodes.map(node => {
                const isSelected = selectedId === node.id;
                const def = NODE_DEFINITIONS[node.type];
                if (node.type === 'JUNCTION') return null;
                if (!isSelected && !node.properties?.label) return null;

                const { width, height } = getNodeDimensions(node);
                const labelStyle = getLabelStyle(node.properties?.labelPosition);

                return (
                    <div 
                        key={`label-overlay-${node.id}`}
                        className={`absolute flex items-center justify-center transition-all duration-200 
                            ${isSelected ? 'z-[110]' : 'z-[100]'}`}
                        style={{ 
                            left: node.position.x, 
                            top: node.position.y, 
                            width: width, 
                            height: height 
                        }}
                    >
                        <div 
                            className={`absolute bg-white/95 dark:bg-zinc-900/95 text-zinc-800 dark:text-zinc-100 text-[11px] px-2.5 py-1 rounded-md border whitespace-nowrap shadow-xl backdrop-blur-md transition-all
                                ${isSelected ? 'border-cyan-500 ring-2 ring-cyan-500/20 font-bold scale-105' : 'border-zinc-200 dark:border-zinc-800 font-medium opacity-90'}`}
                            style={labelStyle}
                        >
                            {node.properties?.label || def.name}
                        </div>
                    </div>
                );
            })}
        </div>

        {/* Pending Component Ghost */}
        {pendingComponent && pendingDef && (
            <div className="absolute pointer-events-none opacity-50 z-50"
                style={{ left: ghostSnapX, top: ghostSnapY, width: pendingDef.width, height: pendingDef.height }}>
                <svg width={pendingDef.width} height={pendingDef.height} className="overflow-visible">
                        <GateShape node={{ id: 'ghost', type: pendingComponent, position: {x: 0, y: 0}, inputs: Array(pendingDef.inputs).fill(false), outputs: Array(pendingDef.outputs).fill(false), properties: { inputCount: pendingDef.inputs } }} />
                </svg>
            </div>
        )}

        <style>{`
            @keyframes spin-slow {
                from { transform: rotate(0deg); }
                to { transform: rotate(360deg); }
            }
            @keyframes signal-flow {
                from { stroke-dashoffset: 20; }
                to { stroke-dashoffset: 0; }
            }
            .animate-spin-slow {
                animation: spin-slow 8s linear infinite;
                transform-origin: center;
            }
            .animate-signal-flow {
                animation: signal-flow 0.8s linear infinite;
            }
        `}</style>
    </div>
  );
};

import React, { useState, useCallback, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { CircuitCanvas } from './components/CircuitCanvas';
import { Header } from './components/Header';
import { PropertiesPanel } from './components/PropertiesPanel';
import { SettingsModal } from './components/SettingsModal';
import { OnboardingTutorial } from './components/OnboardingTutorial';
import { ThemeProvider, useTheme } from './components/ThemeContext';
import { CircuitState, NodeData, NodeType, Wire } from './types';
import { evaluateCircuit } from './utils/circuitLogic';
import { NODE_DEFINITIONS } from './constants';

const MAX_HISTORY = 50;
const AUTOSAVE_KEY = 'logiclab-ultra-autosave';
const PROJECTS_KEY = 'logiclab-ultra-projects-library';
const NAME_STORAGE_KEY = 'logiclab-ultra-name';
const TUTORIAL_STORAGE_KEY = 'logiclab-ultra-tutorial-completed';

const AppContent: React.FC = () => {
  const { theme, toggleTheme } = useTheme();

  const [circuit, setCircuit] = useState<CircuitState>({ nodes: [], wires: [] });
  const [circuitName, setCircuitName] = useState('Untitled Circuit');
  const [past, setPast] = useState<CircuitState[]>([]);
  const [future, setFuture] = useState<CircuitState[]>([]);
  const [simHistory, setSimHistory] = useState<CircuitState[]>([]);

  const [pendingComponent, setPendingComponent] = useState<NodeType | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const [toolMode, setToolMode] = useState<'move' | 'interact' | 'junction'>('move');
  const [wireMode, setWireMode] = useState<'manhattan' | 'bezier'>('manhattan');
  const [defaultWireThickness, setDefaultWireThickness] = useState(2);
  const [intersectionLogicEnabled, setIntersectionLogicEnabled] = useState(false);

  const [isSimulating, setIsSimulating] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  const [sidebarWidth, setSidebarWidth] = useState(260);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);

  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [isSidebarOpen, setIsSidebarOpen] = useState(!isMobile); 
  const [isPanelOpen, setIsPanelOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [showTutorial, setShowTutorial] = useState(false);

  const [validationResult, setValidationResult] = useState<{
      valid: boolean; 
      messages: string[]; 
      invalidNodeIds: string[];
      floatingInputs: { nodeId: string; index: number }[];
  } | null>(null);

  const [localProjects, setLocalProjects] = useState<Record<string, CircuitState>>({});

  // -- Persistence Logic --

  useEffect(() => {
    const savedAutosave = localStorage.getItem(AUTOSAVE_KEY);
    const savedName = localStorage.getItem(NAME_STORAGE_KEY);
    const savedLibrary = localStorage.getItem(PROJECTS_KEY);
    const tutorialCompleted = localStorage.getItem(TUTORIAL_STORAGE_KEY);

    if (savedAutosave) {
      try {
        const parsed = JSON.parse(savedAutosave) as CircuitState;
        if (parsed.nodes && parsed.wires) {
          setCircuit(parsed);
        }
      } catch (e) {
        console.error("Failed to load autosave", e);
      }
    }

    if (savedName) setCircuitName(savedName);

    if (savedLibrary) {
      try {
        setLocalProjects(JSON.parse(savedLibrary));
      } catch (e) {
        console.error("Failed to load project library", e);
      }
    }

    if (!tutorialCompleted) {
      setShowTutorial(true);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(AUTOSAVE_KEY, JSON.stringify(circuit));
    localStorage.setItem(NAME_STORAGE_KEY, circuitName);
  }, [circuit, circuitName]);

  const saveLocalProject = useCallback((name?: string) => {
    const projName = name || window.prompt("Enter a name for this project:", circuitName);
    if (!projName) return;

    const trimmedName = projName.trim();
    const updatedLibrary = { ...localProjects, [trimmedName]: circuit };
    setLocalProjects(updatedLibrary);
    localStorage.setItem(PROJECTS_KEY, JSON.stringify(updatedLibrary));
    setCircuitName(trimmedName);
  }, [circuit, localProjects, circuitName]);

  const loadLocalProject = useCallback((name: string) => {
    const targetProject = localProjects[name];
    if (targetProject) {
      snapshot();
      setCircuit(targetProject);
      setCircuitName(name);
      setSelectedId(null);
      setValidationResult(null);
    }
  }, [localProjects, circuit]);

  const deleteLocalProject = useCallback((name: string) => {
    if (!window.confirm(`Delete project "${name}" from browser storage?`)) return;
    const { [name]: removed, ...remaining } = localProjects;
    setLocalProjects(remaining);
    localStorage.setItem(PROJECTS_KEY, JSON.stringify(remaining));
  }, [localProjects]);

  const handleExport = useCallback(() => {
    const finalName = circuitName || 'Untitled Circuit';
    try {
        const dataStr = JSON.stringify(circuit, null, 2);
        const blob = new Blob([dataStr], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const sanitizedName = finalName.replace(/[^a-z0-9]/gi, '-').toLowerCase() || 'logiclab-circuit';
        const filename = `${sanitizedName}.json`;
        const link = document.createElement('a');
        link.href = url;
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    } catch (err) {
        console.error("Export failed:", err);
        alert("Failed to export circuit.");
    }
  }, [circuit, circuitName]);

  const handleImport = useCallback((file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parsed = JSON.parse(content) as CircuitState;
        if (parsed.nodes && parsed.wires) {
          snapshot();
          setCircuit(parsed);
          const fileName = file.name.replace(/\.[^/.]+$/, "").replace(/-/g, ' ');
          setCircuitName(fileName.charAt(0).toUpperCase() + fileName.slice(1));
          setSelectedId(null);
          setValidationResult(null);
        } else {
          alert("Invalid circuit file format.");
        }
      } catch (err) {
        alert("Failed to parse circuit file.");
      }
    };
    reader.readAsText(file);
  }, [circuit]);

  useEffect(() => {
    const handleResize = () => {
        const mobile = window.innerWidth < 1024;
        setIsMobile(mobile);
        if (!mobile && !isPanelOpen) setIsSidebarOpen(true);
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [isPanelOpen]);

  const snapshot = useCallback(() => {
    setPast(prev => {
        const last = prev[prev.length - 1];
        if (last && JSON.stringify(last) === JSON.stringify(circuit)) return prev;
        return [...prev, circuit].slice(-MAX_HISTORY);
    });
    setFuture([]);
  }, [circuit]);

  const undo = useCallback(() => {
      if (past.length === 0) return;
      const previous = past[past.length - 1];
      setFuture(prev => [circuit, ...prev]);
      setPast(past.slice(0, -1));
      setCircuit(previous);
      if (isSimulating) { setIsSimulating(false); setSimHistory([]); }
      setValidationResult(null);
  }, [past, circuit, isSimulating]);

  const redo = useCallback(() => {
      if (future.length === 0) return;
      const next = future[0];
      setPast(prev => [...prev, circuit]);
      setFuture(future.slice(1));
      setCircuit(next);
      if (isSimulating) { setIsSimulating(false); setSimHistory([]); }
      setValidationResult(null);
  }, [future, circuit, isSimulating]);

  const tick = useCallback(() => {
    setCircuit(prev => {
        setSimHistory(h => [...h, prev].slice(-MAX_HISTORY));
        const nextNodes = prev.nodes.map(n => {
            if (n.type === 'CLOCK') {
                const speed = n.properties?.interval || 20; 
                const currentCount = (n.internalState?.tickCount || 0) + 1;
                if (currentCount >= speed) {
                     return { ...n, outputs: [!n.outputs[0]], internalState: { ...n.internalState, tickCount: 0 } };
                } else {
                    return { ...n, internalState: { ...n.internalState, tickCount: currentCount } };
                }
            }
            return n;
        });
        return evaluateCircuit(nextNodes, prev.wires);
    });
  }, []);

  useEffect(() => {
    let interval: number;
    if (isSimulating && !isPaused) { interval = window.setInterval(tick, 50); }
    return () => clearInterval(interval);
  }, [isSimulating, isPaused, tick]);

  const validateCircuit = useCallback(() => {
      const messages: string[] = [];
      const invalidNodeIds: string[] = [];
      const floatingInputs: { nodeId: string; index: number }[] = [];
      let valid = true;
      if (circuit.nodes.length === 0) return { valid: false, messages: ["Circuit is empty."], invalidNodeIds: [], floatingInputs: [] };

      circuit.nodes.forEach(node => {
          if (['SWITCH', 'CLOCK', 'BUTTON', 'CONSTANT_1', 'CONSTANT_0', 'JUNCTION', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type)) return;
          const inputCount = node.inputs.length;
          let nodeHasFloatingInput = false;
          for(let i=0; i<inputCount; i++) {
              const isConnected = circuit.wires.some(w => w.targetNodeId === node.id && w.targetInputIndex === i);
              if (!isConnected) { 
                  valid = false; nodeHasFloatingInput = true; 
                  floatingInputs.push({ nodeId: node.id, index: i }); 
              }
          }
          if (nodeHasFloatingInput) {
              const label = node.properties?.label || NODE_DEFINITIONS[node.type]?.name || node.type;
              messages.push(`${label}: Missing input connections.`);
              invalidNodeIds.push(node.id);
          }
      });
      return { valid, messages: valid ? ["All components are correctly connected."] : messages, invalidNodeIds, floatingInputs };
  }, [circuit]);

  const toggleSimulation = () => {
    if (isSimulating) {
        setIsSimulating(false); setIsPaused(false); setSimHistory([]); setValidationResult(null);
    } else {
        const result = validateCircuit();
        setValidationResult(result);
        if (!result.valid) return;
        setIsSimulating(true); setToolMode('interact'); setSimHistory([circuit]);
    }
  };

  const handleUpdateCircuit = (nodes: NodeData[], wires: Wire[]) => {
      const evaluated = evaluateCircuit(nodes, wires);
      setCircuit(evaluated);
  };

  const handleDeleteSelection = useCallback(() => {
    if (!selectedId) return;
    snapshot();
    const isWire = circuit.wires.find(w => w.id === selectedId);
    if (isWire) {
        handleUpdateCircuit(circuit.nodes, circuit.wires.filter(w => w.id !== selectedId));
        setSelectedId(null);
        return;
    }
    const newWires = circuit.wires.filter(w => w.sourceNodeId !== selectedId && w.targetNodeId !== selectedId);
    const newNodes = circuit.nodes.filter(n => n.id !== selectedId);
    handleUpdateCircuit(newNodes, newWires);
    setSelectedId(null);
  }, [selectedId, circuit, snapshot]);

  useEffect(() => {
    (window as any).deleteSelection = handleDeleteSelection;
  }, [handleDeleteSelection]);

  const handleNodeUpdate = (id: string, updates: Partial<NodeData>) => {
    snapshot();
    const newNodes = circuit.nodes.map(n => {
        if (n.id === id) {
            let updatedNode = { ...n, ...updates };
            if (updates.type && updates.type !== n.type) {
                 const def = NODE_DEFINITIONS[updates.type];
                 if (def) {
                     updatedNode.inputs = Array(def.inputs).fill(false);
                     updatedNode.outputs = Array(def.outputs).fill(false);
                 }
            }
            return updatedNode;
        }
        return n;
    });
    handleUpdateCircuit(newNodes, circuit.wires);
  };

  const handleWireUpdate = (id: string, updates: Partial<Wire>) => {
        snapshot();
        setCircuit(prev => ({ ...prev, wires: prev.wires.map(w => w.id === id ? { ...w, ...updates } : w) }));
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (isResizingSidebar) setSidebarWidth(Math.max(180, Math.min(450, e.clientX)));
    };
    const handleMouseUp = () => setIsResizingSidebar(false);
    if (isResizingSidebar) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
    } else { document.body.style.cursor = ''; }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingSidebar]);

  const closeTutorial = () => {
    setShowTutorial(false);
    localStorage.setItem(TUTORIAL_STORAGE_KEY, 'true');
  };

  const selectedNode = circuit.nodes.find(n => n.id === selectedId) || null;
  const selectedWire = circuit.wires.find(w => w.id === selectedId) || null;

  return (
    <div className={`${theme} h-screen w-screen overflow-hidden flex flex-col`}>
      <Header 
        toolMode={toolMode} setToolMode={setToolMode}
        isSimulating={isSimulating} toggleSimulation={toggleSimulation}
        isPaused={isPaused} setIsPaused={setIsPaused}
        stepForward={() => tick()}
        checkCompatibility={() => setValidationResult(validateCircuit())}
        selectedId={selectedId} deleteSelection={handleDeleteSelection}
        onUndo={undo} onRedo={redo}
        canUndo={past.length > 0} canRedo={future.length > 0}
        isMobile={isMobile} toggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
        togglePanel={() => setIsPanelOpen(!isPanelOpen)} isPanelOpen={isPanelOpen}
        hasErrors={validationResult !== null && !validationResult.valid}
        openSettings={() => setIsSettingsOpen(true)}
      />

      <div className="flex-1 w-full bg-zinc-50 dark:bg-black font-sans transition-colors duration-300 overflow-hidden relative">
        {isPanelOpen ? (
          <div className="flex-1 bg-white dark:bg-zinc-950 flex justify-center animate-in fade-in duration-300 z-50">
            <PropertiesPanel 
              node={selectedNode} wire={selectedWire} 
              onUpdate={handleNodeUpdate} onUpdateWire={handleWireUpdate} 
              width="100%" onClose={() => setIsPanelOpen(false)} isMobile={isMobile}
            />
          </div>
        ) : (
          <>
            {!isMobile && isSidebarOpen && (
              <>
                <div className="h-full flex flex-shrink-0 relative" style={{ width: sidebarWidth }}>
                  <Sidebar 
                    onSelectComponent={(type) => setPendingComponent(type)} 
                    selectedComponent={pendingComponent} 
                    width={sidebarWidth} onClose={() => setIsSidebarOpen(false)} isMobile={false}
                  />
                </div>
                <div className="w-1 cursor-col-resize hover:bg-cyan-500 transition-colors z-20 bg-zinc-200 dark:bg-zinc-800 flex-shrink-0" onMouseDown={() => setIsResizingSidebar(true)} />
              </>
            )}

            {isMobile && isSidebarOpen && (
              <div className="absolute inset-0 z-[60] flex">
                <div className="w-3/4 max-w-sm h-full shadow-2xl animate-in slide-in-from-left duration-200">
                  <Sidebar 
                    onSelectComponent={(type) => { setPendingComponent(type); setIsSidebarOpen(false); }} 
                    selectedComponent={pendingComponent} 
                    width="100%" onClose={() => setIsSidebarOpen(false)} isMobile={true}
                  />
                </div>
                <div className="flex-1 bg-black/40 backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />
              </div>
            )}

            <CircuitCanvas 
              circuit={circuit} onUpdateCircuit={handleUpdateCircuit} onCommit={snapshot}
              selectedId={selectedId} setSelectedId={setSelectedId}
              pendingComponent={pendingComponent} setPendingComponent={setPendingComponent}
              toolMode={toolMode} wireMode={wireMode} isSimulating={isSimulating}
              validationResult={validationResult} setValidationResult={setValidationResult}
              onOpenProperties={() => setIsPanelOpen(true)}
              intersectionLogicEnabled={intersectionLogicEnabled}
              defaultWireThickness={defaultWireThickness}
            />
          </>
        )}
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        theme={theme}
        toggleTheme={toggleTheme}
        wireMode={wireMode}
        setWireMode={setWireMode}
        defaultWireThickness={defaultWireThickness}
        setDefaultWireThickness={setDefaultWireThickness}
        intersectionLogicEnabled={intersectionLogicEnabled}
        setIntersectionLogicEnabled={setIntersectionLogicEnabled}
        onShowTutorial={() => { setIsSettingsOpen(false); setShowTutorial(true); }}
        onSave={handleExport}
        onLoad={handleImport}
        onClear={() => { snapshot(); setCircuit({nodes:[], wires:[]}); }}
        localProjects={localProjects}
        onSaveLocal={saveLocalProject}
        onLoadLocal={loadLocalProject}
        onDeleteLocal={deleteLocalProject}
      />

      <OnboardingTutorial 
        isOpen={showTutorial}
        onClose={closeTutorial}
      />
    </div>
  );
};

const App: React.FC = () => <ThemeProvider><AppContent /></ThemeProvider>;
export default App;

import React, { useRef } from 'react';
import { X, Sun, Moon, Network, HelpCircle, Layers, Palette, Save, FolderOpen, Trash2, Maximize2, FileJson, PlayCircle } from 'lucide-react';
import { CircuitState } from '../types';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  theme: 'dark' | 'light';
  toggleTheme: () => void;
  wireMode: 'manhattan' | 'bezier';
  setWireMode: (mode: 'manhattan' | 'bezier') => void;
  defaultWireThickness: number;
  setDefaultWireThickness: (thickness: number) => void;
  intersectionLogicEnabled: boolean;
  setIntersectionLogicEnabled: (enabled: boolean) => void;
  onShowTutorial: () => void;
  onSave: () => void;
  onLoad: (file: File) => void;
  onClear: () => void;
  localProjects?: Record<string, CircuitState>;
  onSaveLocal?: (name?: string) => void;
  onLoadLocal?: (name: string) => void;
  onDeleteLocal?: (name: string) => void;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({
  isOpen, onClose, theme, toggleTheme, wireMode, setWireMode, 
  defaultWireThickness, setDefaultWireThickness,
  intersectionLogicEnabled, setIntersectionLogicEnabled, onShowTutorial,
  onSave, onLoad, onClear,
  localProjects = {}, onSaveLocal, onLoadLocal, onDeleteLocal
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) return null;

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      onLoad(file);
      onClose();
    }
  };

  const projectNames = Object.keys(localProjects);

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />
      <div className="relative w-full max-w-lg bg-white dark:bg-zinc-900 rounded-2xl shadow-2xl border border-zinc-200 dark:border-zinc-800 overflow-hidden animate-in zoom-in-95 duration-200">
        <div className="flex items-center justify-between p-4 border-b border-zinc-100 dark:border-zinc-800">
          <h2 className="text-lg font-bold text-zinc-800 dark:text-zinc-100 flex items-center gap-2">
            <Palette className="text-cyan-500" size={20} />
            Preferences & Library
          </h2>
          <button onClick={onClose} className="p-2 text-zinc-400 hover:text-zinc-600 dark:hover:text-zinc-200 transition-colors">
            <X size={20} />
          </button>
        </div>

        <div className="p-6 space-y-6 max-h-[80vh] overflow-y-auto custom-scrollbar">

          {/* Project Library Section */}
          <div className="space-y-4">
            <div className="text-[10px] font-bold text-zinc-400 dark:text-zinc-500 uppercase tracking-widest flex justify-between items-center">
              <span>Local Project Library (Browser Storage)</span>
              <button 
                onClick={() => onSaveLocal?.()}
                className="text-cyan-600 hover:text-cyan-500 font-black normal-case text-[11px] bg-cyan-500/10 px-2 py-0.5 rounded transition-colors"
              >
                + New Save
              </button>
            </div>

            <div className="space-y-2">
              {projectNames.length > 0 ? (
                projectNames.map(name => (
                  <div key={name} className="flex items-center justify-between p-3 bg-zinc-50 dark:bg-zinc-800/50 border border-zinc-200 dark:border-zinc-800 rounded-xl group hover:border-cyan-500/50 transition-colors">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded-lg bg-cyan-500/10 flex items-center justify-center text-cyan-600">
                        <FileJson size={16} />
                      </div>
                      <span className="text-sm font-bold text-zinc-700 dark:text-zinc-200 truncate max-w-[180px]">{name}</span>
                    </div>
                    <div className="flex items-center gap-1 opacity-40 group-hover:opacity-100 transition-opacity">
                      <button 
                        onClick={() => { onLoadLocal?.(name); onClose(); }}
                        className="p-2 text-zinc-500 hover:text-cyan-600 hover:bg-cyan-50 dark:hover:bg-cyan-900/20 rounded-lg transition-all"
                        title="Load Project"
                      >
                        <PlayCircle size={18} />
                      </button>
                      <button 
                        onClick={() => onDeleteLocal?.(name)}
                        className="p-2 text-zinc-500 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-all"
                        title="Delete Save"
                      >
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </div>
                ))
              ) : (
                <div className="py-8 text-center border-2 border-dashed border-zinc-200 dark:border-zinc-800 rounded-2xl">
                   <p className="text-xs text-zinc-400 font-medium">No named projects saved yet.</p>
                </div>
              )}
            </div>
          </div>

          <div className="h-px bg-zinc-100 dark:bg-zinc-800" />

          {/* Import/Export Section */}
          <div className="space-y-4">
            <div className="text-[10px] font-bold text-zinc-400 dark:text-zinc-500 uppercase tracking-widest">Hard Copy Management</div>
            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={() => { onSave(); onClose(); }}
                className="flex items-center justify-center gap-2 px-4 py-3 bg-zinc-100 dark:bg-zinc-800 text-zinc-700 dark:text-zinc-200 rounded-xl text-sm font-bold hover:bg-zinc-200 dark:hover:bg-zinc-700 transition-all active:scale-95"
              >
                <Save size={18} className="text-cyan-500" />
                Export JSON
              </button>
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="flex items-center justify-center gap-2 px-4 py-3 bg-zinc-100 dark:bg-zinc-800 text-zinc-700 dark:text-zinc-200 rounded-xl text-sm font-bold hover:bg-zinc-200 dark:hover:bg-zinc-700 transition-all active:scale-95"
              >
                <FolderOpen size={18} className="text-cyan-500" />
                Import File
              </button>
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                accept=".json" 
                className="hidden" 
              />
            </div>
            <button 
                onClick={() => { if(window.confirm("Clear entire workspace?")) { onClear(); onClose(); } }}
                className="w-full flex items-center justify-center gap-2 px-4 py-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-xl text-xs font-bold transition-all"
            >
                <Trash2 size={16} />
                Nuke Workspace
            </button>
          </div>

          <div className="h-px bg-zinc-100 dark:bg-zinc-800" />

          {/* Visuals Section */}
          <div className="space-y-6">
            <div className="text-[10px] font-bold text-zinc-400 dark:text-zinc-500 uppercase tracking-widest">Visual Appearance</div>

            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <div className="text-sm font-bold text-zinc-700 dark:text-zinc-200 flex items-center gap-2">
                  <Sun size={16} /> Color Theme
                </div>
                <div className="text-xs text-zinc-500">Workspace color palette.</div>
              </div>
              <button 
                onClick={toggleTheme}
                className="px-4 py-2 bg-zinc-100 dark:bg-zinc-800 text-zinc-700 dark:text-zinc-200 rounded-lg text-sm font-bold hover:bg-zinc-200 dark:hover:bg-zinc-700 transition-colors flex items-center gap-2"
              >
                {theme === 'dark' ? <Moon size={16} /> : <Sun size={16} />}
                {theme === 'dark' ? 'Dark' : 'Light'}
              </button>
            </div>

            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <div className="text-sm font-bold text-zinc-700 dark:text-zinc-200 flex items-center gap-2">
                  <Layers size={16} /> Wire Style
                </div>
                <div className="text-xs text-zinc-500">Routing geometry.</div>
              </div>
              <div className="flex bg-zinc-100 dark:bg-zinc-800 p-1 rounded-lg">
                <button 
                  onClick={() => setWireMode('manhattan')}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${wireMode === 'manhattan' ? 'bg-white dark:bg-zinc-700 text-cyan-600 shadow-sm' : 'text-zinc-500'}`}
                >
                  Manhattan
                </button>
                <button 
                  onClick={() => setWireMode('bezier')}
                  className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all ${wireMode === 'bezier' ? 'bg-white dark:bg-zinc-700 text-cyan-600 shadow-sm' : 'text-zinc-500'}`}
                >
                  Bezier
                </button>
              </div>
            </div>

            <div className="space-y-3">
              <div className="flex justify-between items-center">
                <div className="space-y-0.5">
                  <div className="text-sm font-bold text-zinc-700 dark:text-zinc-200 flex items-center gap-2">
                    <Maximize2 size={16} /> Global Thickness
                  </div>
                  <div className="text-xs text-zinc-500">Base width for connections.</div>
                </div>
                <span className="text-xs font-mono font-bold text-cyan-500">{defaultWireThickness}px</span>
              </div>
              <input 
                type="range" 
                min="1" 
                max="8" 
                step="1" 
                value={defaultWireThickness} 
                onChange={(e) => setDefaultWireThickness(parseInt(e.target.value))}
                className="w-full h-2 bg-zinc-100 dark:bg-zinc-800 rounded-lg appearance-none cursor-pointer accent-cyan-500"
              />
            </div>

            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <div className="text-sm font-bold text-zinc-700 dark:text-zinc-200 flex items-center gap-2">
                  <Network size={16} /> Intersection Logic
                </div>
                <div className="text-xs text-zinc-500">Dynamic node splitting.</div>
              </div>
              <button 
                onClick={() => setIntersectionLogicEnabled(!intersectionLogicEnabled)}
                className={`w-12 h-6 rounded-full transition-all relative flex items-center px-1 shadow-inner ${intersectionLogicEnabled ? 'bg-cyan-500' : 'bg-zinc-300 dark:bg-zinc-700'}`}
              >
                <div className={`w-4 h-4 bg-white rounded-full shadow-md transition-transform ${intersectionLogicEnabled ? 'translate-x-6' : 'translate-x-0'}`} />
              </button>
            </div>
          </div>

          <div className="pt-4 border-t border-zinc-100 dark:border-zinc-800">
            <button 
              onClick={onShowTutorial}
              className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-cyan-600/10 dark:bg-cyan-500/10 text-cyan-600 dark:text-cyan-400 rounded-xl text-sm font-bold hover:bg-cyan-600/20 dark:hover:bg-cyan-500/20 transition-colors"
            >
              <HelpCircle size={18} />
              Re-show Guided Tutorial
            </button>
          </div>
        </div>

        <div className="p-4 bg-zinc-50 dark:bg-zinc-800/50 text-center">
          <p className="text-[10px] text-zinc-400 font-medium uppercase tracking-widest">LogicLab Ultra v2.2</p>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { CircuitCanvas } from './components/CircuitCanvas';
import { Header } from './components/Header';
import { PropertiesPanel } from './components/PropertiesPanel';
import { SettingsModal } from './components/SettingsModal';
import { OnboardingTutorial } from './components/OnboardingTutorial';
import { ThemeProvider, useTheme } from './components/ThemeContext';
import { CircuitState, NodeData, NodeType, Wire, Point } from './types';
import { evaluateCircuit } from './utils/circuitLogic';
import { NODE_DEFINITIONS } from './constants';
import { getNodeDimensions, getOutputPorts, getInputPorts } from './utils/componentUtils';

const MAX_HISTORY = 50;
const AUTOSAVE_KEY = 'logiclab-ultra-autosave';
const PROJECTS_KEY = 'logiclab-ultra-projects-library';
const NAME_STORAGE_KEY = 'logiclab-ultra-name';
const TUTORIAL_STORAGE_KEY = 'logiclab-ultra-tutorial-completed';

const AppContent: React.FC = () => {
  const { theme, toggleTheme } = useTheme();

  const [circuit, setCircuit] = useState<CircuitState>({ nodes: [], wires: [] });
  const [circuitName, setCircuitName] = useState('Untitled Circuit');
  const [past, setPast] = useState<CircuitState[]>([]);
  const [future, setFuture] = useState<CircuitState[]>([]);
  const [simHistory, setSimHistory] = useState<CircuitState[]>([]);

  const [pendingComponent, setPendingComponent] = useState<NodeType | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const [toolMode, setToolMode] = useState<'move' | 'interact' | 'junction'>('move');
  const [wireMode, setWireMode] = useState<'manhattan' | 'bezier'>('manhattan');
  const [defaultWireThickness, setDefaultWireThickness] = useState(2);
  const [intersectionLogicEnabled, setIntersectionLogicEnabled] = useState(false);

  const [isSimulating, setIsSimulating] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  const [sidebarWidth, setSidebarWidth] = useState(260);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);

  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [isSidebarOpen, setIsSidebarOpen] = useState(!isMobile); 
  const [isPanelOpen, setIsPanelOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [showTutorial, setShowTutorial] = useState(false);

  const [validationResult, setValidationResult] = useState<{
      valid: boolean; 
      messages: string[]; 
      invalidNodeIds: string[];
      floatingInputs: { nodeId: string; index: number }[];
  } | null>(null);

  const [localProjects, setLocalProjects] = useState<Record<string, CircuitState>>({});

  // -- Persistence Logic --

  useEffect(() => {
    const savedAutosave = localStorage.getItem(AUTOSAVE_KEY);
    const savedName = localStorage.getItem(NAME_STORAGE_KEY);
    const savedLibrary = localStorage.getItem(PROJECTS_KEY);
    const tutorialCompleted = localStorage.getItem(TUTORIAL_STORAGE_KEY);

    if (savedAutosave) {
      try {
        const parsed = JSON.parse(savedAutosave) as CircuitState;
        if (parsed.nodes && parsed.wires) {
          setCircuit(parsed);
        }
      } catch (e) {
        console.error("Failed to load autosave", e);
      }
    }

    if (savedName) setCircuitName(savedName);

    if (savedLibrary) {
      try {
        setLocalProjects(JSON.parse(savedLibrary));
      } catch (e) {
        console.error("Failed to load project library", e);
      }
    }

    if (!tutorialCompleted) {
      setShowTutorial(true);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(AUTOSAVE_KEY, JSON.stringify(circuit));
    localStorage.setItem(NAME_STORAGE_KEY, circuitName);
  }, [circuit, circuitName]);

  const saveLocalProject = useCallback((name?: string) => {
    const projName = name || window.prompt("Enter a name for this project:", circuitName);
    if (!projName) return;

    const trimmedName = projName.trim();
    const updatedLibrary = { ...localProjects, [trimmedName]: circuit };
    setLocalProjects(updatedLibrary);
    localStorage.setItem(PROJECTS_KEY, JSON.stringify(updatedLibrary));
    setCircuitName(trimmedName);
  }, [circuit, localProjects, circuitName]);

  const loadLocalProject = useCallback((name: string) => {
    const targetProject = localProjects[name];
    if (targetProject) {
      snapshot();
      setCircuit(targetProject);
      setCircuitName(name);
      setSelectedId(null);
      setValidationResult(null);
    }
  }, [localProjects, circuit]);

  const deleteLocalProject = useCallback((name: string) => {
    if (!window.confirm(`Delete project "${name}" from browser storage?`)) return;
    const { [name]: removed, ...remaining } = localProjects;
    setLocalProjects(remaining);
    localStorage.setItem(PROJECTS_KEY, JSON.stringify(remaining));
  }, [localProjects]);

  const handleExport = useCallback(() => {
    const finalName = circuitName || 'Untitled Circuit';
    try {
        const dataStr = JSON.stringify(circuit, null, 2);
        const blob = new Blob([dataStr], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const sanitizedName = finalName.replace(/[^a-z0-9]/gi, '-').toLowerCase() || 'logiclab-circuit';
        const filename = `${sanitizedName}.json`;
        const link = document.createElement('a');
        link.href = url;
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    } catch (err) {
        console.error("Export failed:", err);
        alert("Failed to export circuit.");
    }
  }, [circuit, circuitName]);

  const handleExportSchematic = useCallback(() => {
    if (circuit.nodes.length === 0) {
      alert("Canvas is empty. Add some components first!");
      return;
    }

    // 1. Calculate Bounding Box
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    circuit.nodes.forEach(node => {
      const { width, height } = getNodeDimensions(node);
      minX = Math.min(minX, node.position.x);
      minY = Math.min(minY, node.position.y);
      maxX = Math.max(maxX, node.position.x + width);
      maxY = Math.max(maxY, node.position.y + height);
    });

    const padding = 50;
    const viewWidth = (maxX - minX) + padding * 2;
    const viewHeight = (maxY - minY) + padding * 2;
    const offsetX = minX - padding;
    const offsetY = minY - padding;

    // 2. Build SVG Content
    const isDark = theme === 'dark';
    const bgColor = isDark ? '#09090b' : '#fafafa';
    const textColor = isDark ? '#e4e4e7' : '#27272a';
    const wireBaseColor = isDark ? '#52525b' : '#a1a1aa';
    const activeColor = '#22d3ee';

    let svgStr = `<svg xmlns="http://www.w3.org/2000/svg" width="${viewWidth}" height="${viewHeight}" viewBox="${offsetX} ${offsetY} ${viewWidth} ${viewHeight}">`;

    // Background
    svgStr += `<rect x="${offsetX}" y="${offsetY}" width="${viewWidth}" height="${viewHeight}" fill="${bgColor}" />`;

    // Grid (optional but looks nice)
    svgStr += `<defs><pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="${isDark ? '#27272a' : '#e5e5e5'}" /></pattern></defs>`;
    svgStr += `<rect x="${offsetX}" y="${offsetY}" width="${viewWidth}" height="${viewHeight}" fill="url(#grid)" />`;

    // Wires
    circuit.wires.forEach(wire => {
      const s = circuit.nodes.find(n => n.id === wire.sourceNodeId);
      const t = circuit.nodes.find(n => n.id === wire.targetNodeId);
      if (!s || !t) return;
      const sP = getOutputPorts(s)[wire.sourceOutputIndex];
      const tP = getInputPorts(t)[wire.targetInputIndex];
      const x1 = s.position.x + sP.x;
      const y1 = s.position.y + sP.y;
      const x2 = t.position.x + tP.x;
      const y2 = t.position.y + tP.y;

      let path = '';
      if (wireMode === 'bezier') {
        const dx = Math.abs(x2 - x1);
        const cpO = Math.min(Math.max(dx * 0.45, 30), 120);
        path = `M ${x1} ${y1} C ${x1 + cpO} ${y1}, ${x2 - cpO} ${y2}, ${x2} ${y2}`;
      } else {
        const dx = x2 - x1;
        if (dx > 20) {
          const midX = (x1 + x2) / 2;
          path = `M ${x1} ${y1} L ${midX} ${y1} L ${midX} ${y2} L ${x2} ${y2}`;
        } else {
          const stub = 20; const midY = (y1 + y2) / 2;
          path = `M ${x1} ${y1} L ${x1 + stub} ${y1} L ${x1 + stub} ${midY} L ${x2 - stub} ${midY} L ${x2 - stub} ${y2} L ${x2} ${y2}`;
        }
      }

      const stroke = wire.state ? activeColor : wireBaseColor;
      const thick = wire.thickness || 2;
      svgStr += `<path d="${path}" fill="none" stroke="${stroke}" stroke-width="${thick}" stroke-linecap="round" />`;
    });

    // Nodes (simplified rects for the export to avoid full SVG serialization complexity)
    circuit.nodes.forEach(node => {
      if (node.type === 'JUNCTION') {
        svgStr += `<circle cx="${node.position.x + 5}" cy="${node.position.y + 5}" r="4" fill="${node.outputs[0] ? activeColor : wireBaseColor}" />`;
        return;
      }

      const { width, height } = getNodeDimensions(node);
      const nodeDef = NODE_DEFINITIONS[node.type];
      const fill = isDark ? '#18181b' : '#ffffff';
      const stroke = isDark ? '#3f3f46' : '#d4d4d8';

      svgStr += `<rect x="${node.position.x}" y="${node.position.y}" width="${width}" height="${height}" rx="4" fill="${fill}" stroke="${stroke}" stroke-width="2" />`;

      // Label
      const labelText = node.properties?.label || nodeDef.name;
      svgStr += `<text x="${node.position.x + width/2}" y="${node.position.y - 12}" fill="${textColor}" font-family="sans-serif" font-size="11" font-weight="bold" text-anchor="middle">${labelText}</text>`;

      // Type identifier inside node
      svgStr += `<text x="${node.position.x + width/2}" y="${node.position.y + height/2}" fill="${isDark ? '#71717a' : '#a1a1aa'}" font-family="sans-serif" font-size="9" font-weight="bold" text-anchor="middle">${node.type}</text>`;
    });

    svgStr += `</svg>`;

    const blob = new Blob([svgStr], { type: 'image/svg+xml' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${circuitName.toLowerCase().replace(/\s+/g, '-')}-schematic.svg`;
    link.click();
    URL.revokeObjectURL(url);
  }, [circuit, circuitName, theme, wireMode]);

  const handleImport = useCallback((file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parsed = JSON.parse(content) as CircuitState;
        if (parsed.nodes && parsed.wires) {
          snapshot();
          setCircuit(parsed);
          const fileName = file.name.replace(/\.[^/.]+$/, "").replace(/-/g, ' ');
          setCircuitName(fileName.charAt(0).toUpperCase() + fileName.slice(1));
          setSelectedId(null);
          setValidationResult(null);
        } else {
          alert("Invalid circuit file format.");
        }
      } catch (err) {
        alert("Failed to parse circuit file.");
      }
    };
    reader.readAsText(file);
  }, [circuit]);

  useEffect(() => {
    const handleResize = () => {
        const mobile = window.innerWidth < 1024;
        setIsMobile(mobile);
        if (!mobile && !isPanelOpen) setIsSidebarOpen(true);
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [isPanelOpen]);

  const snapshot = useCallback(() => {
    setPast(prev => {
        const last = prev[prev.length - 1];
        if (last && JSON.stringify(last) === JSON.stringify(circuit)) return prev;
        return [...prev, circuit].slice(-MAX_HISTORY);
    });
    setFuture([]);
  }, [circuit]);

  const undo = useCallback(() => {
      if (past.length === 0) return;
      const previous = past[past.length - 1];
      setFuture(prev => [circuit, ...prev]);
      setPast(past.slice(0, -1));
      setCircuit(previous);
      if (isSimulating) { setIsSimulating(false); setSimHistory([]); }
      setValidationResult(null);
  }, [past, circuit, isSimulating]);

  const redo = useCallback(() => {
      if (future.length === 0) return;
      const next = future[0];
      setPast(prev => [...prev, circuit]);
      setFuture(future.slice(1));
      setCircuit(next);
      if (isSimulating) { setIsSimulating(false); setSimHistory([]); }
      setValidationResult(null);
  }, [future, circuit, isSimulating]);

  const tick = useCallback(() => {
    setCircuit(prev => {
        setSimHistory(h => [...h, prev].slice(-MAX_HISTORY));
        const nextNodes = prev.nodes.map(n => {
            if (n.type === 'CLOCK') {
                const speed = n.properties?.interval || 20; 
                const currentCount = (n.internalState?.tickCount || 0) + 1;
                if (currentCount >= speed) {
                     return { ...n, outputs: [!n.outputs[0]], internalState: { ...n.internalState, tickCount: 0 } };
                } else {
                    return { ...n, internalState: { ...n.internalState, tickCount: currentCount } };
                }
            }
            return n;
        });
        return evaluateCircuit(nextNodes, prev.wires);
    });
  }, []);

  useEffect(() => {
    let interval: number;
    if (isSimulating && !isPaused) { interval = window.setInterval(tick, 50); }
    return () => clearInterval(interval);
  }, [isSimulating, isPaused, tick]);

  const validateCircuit = useCallback(() => {
      const messages: string[] = [];
      const invalidNodeIds: string[] = [];
      const floatingInputs: { nodeId: string; index: number }[] = [];
      let valid = true;
      if (circuit.nodes.length === 0) return { valid: false, messages: ["Circuit is empty."], invalidNodeIds: [], floatingInputs: [] };

      circuit.nodes.forEach(node => {
          if (['SWITCH', 'CLOCK', 'BUTTON', 'CONSTANT_1', 'CONSTANT_0', 'JUNCTION', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT'].includes(node.type)) return;
          const inputCount = node.inputs.length;
          let nodeHasFloatingInput = false;
          for(let i=0; i<inputCount; i++) {
              const isConnected = circuit.wires.some(w => w.targetNodeId === node.id && w.targetInputIndex === i);
              if (!isConnected) { 
                  valid = false; nodeHasFloatingInput = true; 
                  floatingInputs.push({ nodeId: node.id, index: i }); 
              }
          }
          if (nodeHasFloatingInput) {
              const label = node.properties?.label || NODE_DEFINITIONS[node.type]?.name || node.type;
              messages.push(`${label}: Missing input connections.`);
              invalidNodeIds.push(node.id);
          }
      });
      return { valid, messages: valid ? ["All components are correctly connected."] : messages, invalidNodeIds, floatingInputs };
  }, [circuit]);

  const toggleSimulation = () => {
    if (isSimulating) {
        setIsSimulating(false); setIsPaused(false); setSimHistory([]); setValidationResult(null);
    } else {
        const result = validateCircuit();
        setValidationResult(result);
        if (!result.valid) return;
        setIsSimulating(true); setToolMode('interact'); setSimHistory([circuit]);
    }
  };

  const handleUpdateCircuit = (nodes: NodeData[], wires: Wire[]) => {
      const evaluated = evaluateCircuit(nodes, wires);
      setCircuit(evaluated);
  };

  const handleDeleteSelection = useCallback(() => {
    if (!selectedId) return;
    snapshot();
    const isWire = circuit.wires.find(w => w.id === selectedId);
    if (isWire) {
        handleUpdateCircuit(circuit.nodes, circuit.wires.filter(w => w.id !== selectedId));
        setSelectedId(null);
        return;
    }
    const newWires = circuit.wires.filter(w => w.sourceNodeId !== selectedId && w.targetNodeId !== selectedId);
    const newNodes = circuit.nodes.filter(n => n.id !== selectedId);
    handleUpdateCircuit(newNodes, newWires);
    setSelectedId(null);
  }, [selectedId, circuit, snapshot]);

  useEffect(() => {
    (window as any).deleteSelection = handleDeleteSelection;
  }, [handleDeleteSelection]);

  const handleNodeUpdate = (id: string, updates: Partial<NodeData>) => {
    snapshot();
    const newNodes = circuit.nodes.map(n => {
        if (n.id === id) {
            let updatedNode = { ...n, ...updates };
            if (updates.type && updates.type !== n.type) {
                 const def = NODE_DEFINITIONS[updates.type];
                 if (def) {
                     updatedNode.inputs = Array(def.inputs).fill(false);
                     updatedNode.outputs = Array(def.outputs).fill(false);
                 }
            }
            return updatedNode;
        }
        return n;
    });
    handleUpdateCircuit(newNodes, circuit.wires);
  };

  const handleWireUpdate = (id: string, updates: Partial<Wire>) => {
        snapshot();
        setCircuit(prev => ({ ...prev, wires: prev.wires.map(w => w.id === id ? { ...w, ...updates } : w) }));
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (isResizingSidebar) setSidebarWidth(Math.max(180, Math.min(450, e.clientX)));
    };
    const handleMouseUp = () => setIsResizingSidebar(false);
    if (isResizingSidebar) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
    } else { document.body.style.cursor = ''; }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingSidebar]);

  const closeTutorial = () => {
    setShowTutorial(false);
    localStorage.setItem(TUTORIAL_STORAGE_KEY, 'true');
  };

  const selectedNode = circuit.nodes.find(n => n.id === selectedId) || null;
  const selectedWire = circuit.wires.find(w => w.id === selectedId) || null;

  return (
    <div className={`${theme} h-screen w-screen overflow-hidden flex flex-col`}>
      <Header 
        toolMode={toolMode} setToolMode={setToolMode}
        isSimulating={isSimulating} toggleSimulation={toggleSimulation}
        isPaused={isPaused} setIsPaused={setIsPaused}
        stepForward={() => tick()}
        checkCompatibility={() => setValidationResult(validateCircuit())}
        selectedId={selectedId} deleteSelection={handleDeleteSelection}
        onUndo={undo} onRedo={redo}
        canUndo={past.length > 0} canRedo={future.length > 0}
        isMobile={isMobile} toggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
        togglePanel={() => setIsPanelOpen(!isPanelOpen)} isPanelOpen={isPanelOpen}
        hasErrors={validationResult !== null && !validationResult.valid}
        openSettings={() => setIsSettingsOpen(true)}
      />

      <div className="flex-1 w-full bg-zinc-50 dark:bg-black font-sans transition-colors duration-300 overflow-hidden relative">
        {isPanelOpen ? (
          <div className="flex-1 bg-white dark:bg-zinc-950 flex justify-center animate-in fade-in duration-300 z-50">
            <PropertiesPanel 
              node={selectedNode} wire={selectedWire} 
              onUpdate={handleNodeUpdate} onUpdateWire={handleWireUpdate} 
              width="100%" onClose={() => setIsPanelOpen(false)} isMobile={isMobile}
            />
          </div>
        ) : (
          <>
            {!isMobile && isSidebarOpen && (
              <>
                <div className="h-full flex flex-shrink-0 relative" style={{ width: sidebarWidth }}>
                  <Sidebar 
                    onSelectComponent={(type) => setPendingComponent(type)} 
                    selectedComponent={pendingComponent} 
                    width={sidebarWidth} onClose={() => setIsSidebarOpen(false)} isMobile={false}
                  />
                </div>
                <div className="w-1 cursor-col-resize hover:bg-cyan-500 transition-colors z-20 bg-zinc-200 dark:bg-zinc-800 flex-shrink-0" onMouseDown={() => setIsResizingSidebar(true)} />
              </>
            )}

            {isMobile && isSidebarOpen && (
              <div className="absolute inset-0 z-[60] flex">
                <div className="w-3/4 max-w-sm h-full shadow-2xl animate-in slide-in-from-left duration-200">
                  <Sidebar 
                    onSelectComponent={(type) => { setPendingComponent(type); setIsSidebarOpen(false); }} 
                    selectedComponent={pendingComponent} 
                    width="100%" onClose={() => setIsSidebarOpen(false)} isMobile={true}
                  />
                </div>
                <div className="flex-1 bg-black/40 backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />
              </div>
            )}

            <CircuitCanvas 
              circuit={circuit} onUpdateCircuit={handleUpdateCircuit} onCommit={snapshot}
              selectedId={selectedId} setSelectedId={setSelectedId}
              pendingComponent={pendingComponent} setPendingComponent={setPendingComponent}
              toolMode={toolMode} wireMode={wireMode} isSimulating={isSimulating}
              validationResult={validationResult} setValidationResult={setValidationResult}
              onOpenProperties={() => setIsPanelOpen(true)}
              intersectionLogicEnabled={intersectionLogicEnabled}
              defaultWireThickness={defaultWireThickness}
            />
          </>
        )}
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        theme={theme}
        toggleTheme={toggleTheme}
        wireMode={wireMode}
        setWireMode={setWireMode}
        defaultWireThickness={defaultWireThickness}
        setDefaultWireThickness={setDefaultWireThickness}
        intersectionLogicEnabled={intersectionLogicEnabled}
        setIntersectionLogicEnabled={setIntersectionLogicEnabled}
        onShowTutorial={() => { setIsSettingsOpen(false); setShowTutorial(true); }}
        onSave={handleExport}
        onLoad={handleImport}
        onClear={() => { snapshot(); setCircuit({nodes:[], wires:[]}); }}
        localProjects={localProjects}
        onSaveLocal={saveLocalProject}
        onLoadLocal={loadLocalProject}
        onDeleteLocal={deleteLocalProject}
        onExportSchematic={handleExportSchematic}
      />

      <OnboardingTutorial 
        isOpen={showTutorial}
        onClose={closeTutorial}
      />
    </div>
  );
};

const App: React.FC = () => <ThemeProvider><AppContent /></ThemeProvider>;
export default App;

export type NodeType = 
  | 'AND' | 'OR' | 'NOT' | 'XOR' | 'NAND' | 'NOR' | 'XNOR' | 'BUFFER'
  | 'SWITCH' | 'BULB' | 'CLOCK' | 'BUTTON' | 'CONSTANT_1' | 'CONSTANT_0'
  | 'INPUT_2BIT' | 'INPUT_4BIT' | 'INPUT_8BIT' | 'INPUT_16BIT'
  | 'OUTPUT_2BIT' | 'OUTPUT_4BIT' | 'OUTPUT_8BIT' | 'OUTPUT_16BIT'
  | 'HALF_ADDER' | 'FULL_ADDER' | 'SUBTRACTOR' | 'COMPARATOR_1BIT'
  | 'D_LATCH' | 'D_FF' | 'JK_FF' | 'T_FF' | 'SR_FF'
  | 'GATED_SR_LATCH' | 'JK_MASTER_SLAVE' | 'RAM_1BIT' | 'ROM_1BIT' | 'SHIFT_REGISTER_4BIT'
  | 'RAM_4BIT' | 'RAM_8BIT' | 'RAM_16BIT'
  | 'MUX_2_1' | 'MUX_4_1' | 'MUX_8_1' | 'DEMUX_1_2' | 'DEMUX_1_4' | 'DEMUX_1_8' | 'DEMUX_1_16'
  | 'DECODER_2_4' | 'PRIORITY_ENCODER_4_2'
  | 'HEX_DISPLAY' | 'SEVEN_SEGMENT'
  | 'JUNCTION'
  | 'LOGIC_PROBE'
  | 'BINARY_MONITOR_4BIT'
  | 'BINARY_MONITOR_8BIT';

export interface Point {
  x: number;
  y: number;
}

export interface Port {
  id: string;
  type: 'input' | 'output';
  offset: Point;
  label?: string;
}

export interface NodeData {
  id: string;
  type: NodeType;
  position: Point;
  inputs: boolean[];
  outputs: boolean[];
  internalState?: {
    lastClock?: boolean;
    storedValue?: boolean;
    masterValue?: boolean; // For Master-Slave
    register?: boolean[]; // For Shift Register
    memory?: number[]; // For RAM arrays
    [key: string]: any;
  };
  properties?: {
    label?: string;
    inputCount?: number;
    propagationDelay?: number;
    initialState?: boolean;
    romValue?: boolean; // For ROM
    [key: string]: any;
  };
}

export interface Wire {
  id: string;
  sourceNodeId: string;
  sourceOutputIndex: number;
  targetNodeId: string;
  targetInputIndex: number;
  state: boolean;
  color?: string; // Inactive color
  activeColor?: string; // Color when High
  thickness?: number; // Width of the wire
}

export interface CircuitState {
  nodes: NodeData[];
  wires: Wire[];
}

export interface WiringState {
  sourceNodeId: string;
  sourceOutputIndex: number;
  startPoint: Point;
  active: boolean;
}

