import { NodeType } from './types';

export const GRID_SIZE = 20;
export const MB_SPACING = 24;
export const MB_START_Y = 35;
export const MB_ROW_HEIGHT = 20;

// Helper to generate port offsets for multi-bit components
const generatePorts = (count: number, x: number, startY: number = MB_START_Y, spacing: number = MB_SPACING) => {
    return Array.from({ length: count }, (_, i) => ({
        x,
        // Aligned to the center of the 24px row
        y: startY + (i * spacing) + (spacing / 2),
        label: `${i}`
    }));
};

const getMbHeight = (count: number) => MB_START_Y + (count * MB_SPACING) + 40;

const getRamDefinition = (addrBits: number, dataBits: number, name: string) => {
    const inputs = addrBits + dataBits + 2; // Address + Data + WE + CS
    const outputs = dataBits;

    // Calculate a height that accommodates all ports nicely
    const maxPortCount = Math.max(addrBits + dataBits + 2, dataBits);
    const height = Math.max(160, maxPortCount * 18 + 60);
    const width = 160;

    const inputOffsets = [];
    let currentY = 40;

    // Address Ports
    for(let i=0; i<addrBits; i++) {
        inputOffsets.push({ x: 0, y: currentY, label: `A${i}` });
        currentY += 18;
    }
    currentY += 10;

    // Data In Ports
    for(let i=0; i<dataBits; i++) {
        inputOffsets.push({ x: 0, y: currentY, label: `D${i}` });
        currentY += 18;
    }
    currentY += 10;

    // Control Ports
    inputOffsets.push({ x: 0, y: currentY, label: 'WE' });
    currentY += 18;
    inputOffsets.push({ x: 0, y: currentY, label: 'CS' });

    const outputOffsets = [];
    // Align output ports to the right, centered vertically or matching data inputs
    let outStartY = 40 + (addrBits * 18) + 10; 
    for(let i=0; i<dataBits; i++) {
        outputOffsets.push({ x: width, y: outStartY + (i*18), label: `Q${i}` });
    }

    return { width, height, inputs, outputs, inputOffsets, outputOffsets, name };
};

const getRomDefinition = (addrBits: number, dataBits: number, name: string) => {
    const inputs = addrBits + 1; // Address + CS
    const outputs = dataBits;
    const height = Math.max(120, Math.max(addrBits + 1, dataBits) * 20 + 40);
    const width = 140;

    const inputOffsets = [];
    for(let i=0; i<addrBits; i++) {
        inputOffsets.push({ x: 0, y: 40 + i * 20, label: `A${i}` });
    }
    inputOffsets.push({ x: 0, y: 40 + addrBits * 20 + 10, label: 'CS' });

    const outputOffsets = [];
    for(let i=0; i<dataBits; i++) {
        outputOffsets.push({ x: width, y: 40 + i * 20, label: `Q${i}` });
    }

    return { width, height, inputs, outputs, inputOffsets, outputOffsets, name };
};

