        {type: "DEMUX_1_2", icon: Split, label: "Demux 1:2"}, 
        {type: "DEMUX_1_4", icon: Split, label: "Demux 1:4"},
        {type: "DEMUX_1_8", icon: Split, label: "Demux 1:8"}, 
