        {type: "INPUT_4BIT", icon: Binary, label: "Input 4-Bit"},
        {type: "INPUT_8BIT", icon: Binary, label: "Input 8-Bit"}, 
        {type: "INPUT_16BIT", icon: Binary, label: "Input 16-Bit"},
        {type: "OUTPUT_2BIT", icon: Activity, label: "Out 2-Bit"}, 
        {type: "OUTPUT_4BIT", icon: Activity, label: "Out 4-Bit"},
