          <div className="flex items-center">
            <span className="font-extrabold text-sm text-zinc-800 dark:text-zinc-200 tracking-tight">Component Library</span>
            {isMobile && (
              <button 
                  onClick={onClose} 
                  className="ml-auto p-2 text-zinc-500 hover:text-zinc-800 dark:hover:text-zinc-200 transition-colors"
                  aria-label="Close sidebar"
              >
                  <X size={22}/>
