import { NodeData, Wire, NodeType } from '../types';

export const evaluateCircuit = (nodes: NodeData[], wires: Wire[]): { nodes: NodeData[], wires: Wire[] } => {
  let nextNodes = nodes.map(n => ({ 
    ...n, 
    inputs: [...n.inputs], 
    outputs: [...n.outputs],
    internalState: { ...n.internalState },
    properties: { ...n.properties }
  }));
  let nextWires = wires.map(w => ({ ...w }));

  let stable = false;
  let iterations = 0;
  const MAX_ITERATIONS = 50; 

  while (!stable && iterations < MAX_ITERATIONS) {
    stable = true;
    iterations++;

    nextWires.forEach(wire => {
      const sourceNode = nextNodes.find(n => n.id === wire.sourceNodeId);
      if (sourceNode) {
        const val = sourceNode.outputs[wire.sourceOutputIndex] || false;
        if (wire.state !== val) {
          wire.state = val;
          stable = false;
        }
      }
    });

    nextWires.forEach(wire => {
      const targetNode = nextNodes.find(n => n.id === wire.targetNodeId);
      if (targetNode) {
        if (targetNode.inputs[wire.targetInputIndex] !== wire.state) {
          targetNode.inputs[wire.targetInputIndex] = wire.state;
          stable = false;
        }
      }
    });

    nextNodes.forEach(node => {
      if (['TOGGLE_SWITCH', 'CLOCK', 'PUSH_BUTTON', 'INPUT_2BIT', 'INPUT_4BIT', 'INPUT_8BIT', 'INPUT_16BIT', 'VCC', 'GND'].includes(node.type)) return;

      const oldOutputs = [...node.outputs];
      let newOutputs = [...oldOutputs];

      switch (node.type) {
        case 'AND': newOutputs = [node.inputs.every(v => v === true)]; break;
        case 'OR': newOutputs = [node.inputs.some(v => v === true)]; break;
        case 'NOT': newOutputs = [!node.inputs[0]]; break;
        case 'NAND': newOutputs = [!node.inputs.every(v => v === true)]; break;
        case 'NOR': newOutputs = [!node.inputs.some(v => v === true)]; break;
        case 'XOR': newOutputs = [node.inputs.filter(v => v).length % 2 === 1]; break;
        case 'XNOR': newOutputs = [node.inputs.filter(v => v).length % 2 === 0]; break;
        case 'BUFFER': newOutputs = [node.inputs[0]]; break;
        case 'TRI_STATE_BUFFER': newOutputs = [node.inputs[1] ? node.inputs[0] : false]; break;
        case 'JUNCTION': newOutputs = [node.inputs[0]]; break;
        case 'HALF_ADDER': {
           const a = node.inputs[0]; const b = node.inputs[1];
           newOutputs = [a !== b, a && b]; 
           break;
        }
        case 'FULL_ADDER': {
            const a = node.inputs[0]; const b = node.inputs[1]; const cin = node.inputs[2];
            const sum = (a ? 1:0) + (b ? 1:0) + (cin ? 1:0);
            newOutputs = [sum % 2 === 1, sum >= 2];
            break;
        }
        case 'SUBTRACTOR': {
            const a = node.inputs[0]; const b = node.inputs[1];
            newOutputs = [a !== b, (!a && b)];
            break;
        }
        case 'COMPARATOR_1BIT': {
            const a = node.inputs[0]; const b = node.inputs[1];
            newOutputs = [a && !b, a === b, !a && b];
            break;
        }
        case 'MUX_2_1': newOutputs = [node.inputs[2] ? node.inputs[1] : node.inputs[0]]; break;
        case 'MUX_4_1': {
            const s0 = node.inputs[4]; const s1 = node.inputs[5];
            const idx = (s0?1:0) + (s1?2:0);
            newOutputs = [node.inputs[idx]];
            break;
        }
        case 'MUX_8_1': {
            const s0 = node.inputs[8]; const s1 = node.inputs[9]; const s2 = node.inputs[10];
            const idx = (s0?1:0) + (s1?2:0) + (s2?4:0);
            newOutputs = [node.inputs[idx]];
            break;
        }
        case 'DEMUX_1_2': {
            const d = node.inputs[0]; const s = node.inputs[1];
            newOutputs = [!s ? d : false, s ? d : false];
            break;
        }
        case 'DEMUX_1_4': {
            const d = node.inputs[0]; const s0 = node.inputs[1]; const s1 = node.inputs[2];
            const idx = (s0?1:0) + (s1?2:0);
            newOutputs = [false, false, false, false];
            newOutputs[idx] = d;
            break;
        }
        case 'DEMUX_1_8': {
            const d = node.inputs[0]; const s0 = node.inputs[1]; const s1 = node.inputs[2]; const s2 = node.inputs[3];
            const idx = (s0?1:0) + (s1?2:0) + (s2?4:0);
            newOutputs = new Array(8).fill(false);
            newOutputs[idx] = d;
            break;
        }
        case 'DEMUX_1_16': {
            const d = node.inputs[0]; 
            const s0 = node.inputs[1]; const s1 = node.inputs[2]; 
            const s2 = node.inputs[3]; const s3 = node.inputs[4];
            const idx = (s0?1:0) + (s1?2:0) + (s2?4:0) + (s3?8:0);
            newOutputs = new Array(16).fill(false);
            newOutputs[idx] = d;
            break;
        }
        case 'DECODER_2_4': {
            const s0 = node.inputs[0]; const s1 = node.inputs[1];
            const idx = (s0?1:0) + (s1?2:0);
            newOutputs = [false, false, false, false];
            newOutputs[idx] = true;
            break;
        }
        case 'DECODER_3_8': {
            const s0 = node.inputs[0]; const s1 = node.inputs[1]; const s2 = node.inputs[2];
            const idx = (s0?1:0) + (s1?2:0) + (s2?4:0);
            newOutputs = new Array(8).fill(false);
            newOutputs[idx] = true;
            break;
        }
        case 'PRIORITY_ENCODER_4_2': {
            const i0 = node.inputs[0]; const i1 = node.inputs[1];
            const i2 = node.inputs[2]; const i3 = node.inputs[3];
            let a0 = false, a1 = false, v = false;
            if (i3) { a1=true; a0=true; v=true; }
            else if (i2) { a1=true; a0=false; v=true; }
            else if (i1) { a1=false; a0=true; v=true; }
            else if (i0) { a1=false; a0=false; v=true; }
            newOutputs = [a0, a1, v];
            break;
        }
        case 'D_LATCH': {
           const D = node.inputs[0]; const E = node.inputs[1];
           const Q = E ? D : oldOutputs[0];
           newOutputs = [Q, !Q];
           break;
        }
        case 'D_FF': {
           const D = node.inputs[0]; const Clk = node.inputs[1];
           const lastClk = node.internalState?.lastClock || false;
           let Q = oldOutputs[0];
           if (!lastClk && Clk) { Q = D; }
           newOutputs = [Q, !Q];
           node.internalState = { ...node.internalState, lastClock: Clk };
           break;
        }
        case 'T_FF': {
           const T = node.inputs[0]; const Clk = node.inputs[1];
           const lastClk = node.internalState?.lastClock || false;
           let Q = oldOutputs[0];
           if (!lastClk && Clk) { if (T) Q = !Q; }
           newOutputs = [Q, !Q];
           node.internalState = { ...node.internalState, lastClock: Clk };
           break;
        }
        case 'JK_FF': {
           const J = node.inputs[0]; const Clk = node.inputs[1]; const K = node.inputs[2];
           const lastClk = node.internalState?.lastClock || false;
           let Q = oldOutputs[0];
           if (!lastClk && Clk) {
               if (J && !K) Q = true;
               else if (!J && K) Q = false;
               else if (J && K) Q = !Q;
           }
           newOutputs = [Q, !Q];
           node.internalState = { ...node.internalState, lastClock: Clk };
           break;
        }
        case 'SR_FF': {
            const S = node.inputs[0]; const Clk = node.inputs[1]; const R = node.inputs[2];
            const lastClk = node.internalState?.lastClock || false;
            let Q = oldOutputs[0];
            if (!lastClk && Clk) { if (S && !R) Q = true; else if (!S && R) Q = false; }
            newOutputs = [Q, !Q];
            node.internalState = { ...node.internalState, lastClock: Clk };
            break;
        }
        case 'GATED_SR_LATCH': {
            const S = node.inputs[0]; const En = node.inputs[1]; const R = node.inputs[2];
            let Q = oldOutputs[0];
            if (En) { if (S && !R) Q = true; else if (!S && R) Q = false; }
            newOutputs = [Q, !Q];
            break;
        }
        case 'JK_MASTER_SLAVE': {
            const J = node.inputs[0]; const Clk = node.inputs[1]; const K = node.inputs[2];
            const lastClk = node.internalState?.lastClock || false;
            let Q = oldOutputs[0];
            if (lastClk && !Clk) { if (J && !K) Q = true; else if (!J && K) Q = false; else if (J && K) Q = !Q; }
            newOutputs = [Q, !Q];
            node.internalState = { ...node.internalState, lastClock: Clk };
            break;
        }
        case 'MEMORY_CELL': {
            const Data = node.inputs[0]; const Write = node.inputs[1]; const Sel = node.inputs[2];
            let stored = node.internalState?.storedValue || false;
            if (Sel && Write) { stored = Data; }
            newOutputs = [Sel ? stored : false];
            node.internalState = { ...node.internalState, storedValue: stored };
            break;
        }
        case 'ROM_1BIT': {
             const Sel = node.inputs[0];
             const val = node.properties?.romValue || false;
             newOutputs = [Sel ? val : false];
             break;
        }
        case 'SHIFT_REGISTER_4BIT': {
             const Data = node.inputs[0]; const Clk = node.inputs[1];
             const lastClk = node.internalState?.lastClock || false;
             let reg = node.internalState?.register || [false, false, false, false];
             if (!lastClk && Clk) { reg = [Data, reg[0], reg[1], reg[2]]; }
             newOutputs = [...reg];
             node.internalState = { ...node.internalState, lastClock: Clk, register: reg };
             break;
        }
        case 'ALU_4BIT': {
            let a = 0; for(let i=0; i<4; i++) { if(node.inputs[i]) a += Math.pow(2, i); }
            let b = 0; for(let i=4; i<8; i++) { if(node.inputs[i]) b += Math.pow(2, i-4); }
            const op = (node.inputs[8]?1:0) + (node.inputs[9]?2:0);
            let result = 0; let carry = false;
            switch(op) {
              case 0: result = a + b; carry = result > 15; break;
              case 1: result = a - b; carry = a < b; if(result < 0) result += 16; break;
              case 2: result = a & b; break;
              case 3: result = a | b; break;
            }
            newOutputs = [];
            for(let i=0; i<4; i++) { newOutputs.push(!!((result >> i) & 1)); }
            newOutputs.push(carry);
            newOutputs.push((result % 16) === 0);
            break;
        }
        case 'COUNTER_4BIT': {
          const clk = node.inputs[0]; const rst = node.inputs[1];
          const lastClk = node.internalState?.lastClock || false;
          let val = node.internalState?.counterValue || 0;
          if (rst) { val = 0; }
          else if (!lastClk && clk) { val = (val + 1) % 16; }
          newOutputs = [];
          for(let i=0; i<4; i++) { newOutputs.push(!!((val >> i) & 1)); }
          node.internalState = { ...node.internalState, lastClock: clk, counterValue: val };
          break;
        }
        case 'REG_4BIT': {
          const clk = node.inputs[4];
          const lastClk = node.internalState?.lastClock || false;
          let reg = node.internalState?.register || [false, false, false, false];
          if (!lastClk && clk) { reg = [node.inputs[0], node.inputs[1], node.inputs[2], node.inputs[3]]; }
          newOutputs = [...reg];
          node.internalState = { ...node.internalState, lastClock: clk, register: reg };
          break;
        }
        case 'RAM_4BIT':
        case 'RAM_8BIT':
        case 'RAM_16BIT':
        case 'RAM_64_8':
        case 'RAM_256_8':
        case 'RAM_64BIT':
        case 'RAM_128BIT':
        case 'RAM_256BIT': {
            let addrWidth = 4;
            let dataWidth = 4;

            if (node.type === 'RAM_4BIT') { addrWidth = 4; dataWidth = 4; }
            else if (node.type === 'RAM_8BIT') { addrWidth = 4; dataWidth = 8; }
            else if (node.type === 'RAM_16BIT') { addrWidth = 4; dataWidth = 16; }
            else if (node.type === 'RAM_64_8') { addrWidth = 6; dataWidth = 8; }
            else if (node.type === 'RAM_256_8') { addrWidth = 8; dataWidth = 8; }
            else if (node.type === 'RAM_64BIT') { addrWidth = 3; dataWidth = 8; }
            else if (node.type === 'RAM_128BIT') { addrWidth = 4; dataWidth = 8; }
            else if (node.type === 'RAM_256BIT') { addrWidth = 5; dataWidth = 8; }

            const totalWords = Math.pow(2, addrWidth);
            let address = 0;
            for(let i=0; i<addrWidth; i++) { if(node.inputs[i]) address += Math.pow(2, i); }

            let dataIn = 0;
            for(let i=0; i<dataWidth; i++) { if(node.inputs[addrWidth + i]) dataIn += Math.pow(2, i); }

            const WE = node.inputs[addrWidth + dataWidth];
            const CS = node.inputs[addrWidth + dataWidth + 1];

            let memory = node.internalState?.memory;
            if (!memory || !Array.isArray(memory)) { memory = new Array(totalWords).fill(0); }

            let val = 0;
            const nextMemory = [...memory];
            if (CS) { 
                if (WE) { nextMemory[address] = dataIn; } 
                val = nextMemory[address]; 
            }

            newOutputs = [];
            for(let i=0; i<dataWidth; i++) { newOutputs.push(CS ? !!((val >> i) & 1) : false); }
            node.internalState = { ...node.internalState, memory: nextMemory };
            break;
        }
        case 'ROM_4BIT':
        case 'ROM_8BIT': {
            const addrWidth = 4;
            const dataWidth = node.type === 'ROM_4BIT' ? 4 : 8;
            const totalWords = Math.pow(2, addrWidth);
            let address = 0;
            for(let i=0; i<addrWidth; i++) { if(node.inputs[i]) address += Math.pow(2, i); }
            const CS = node.inputs[addrWidth];
            let romData = node.properties?.romData;
            if (!romData || !Array.isArray(romData)) { romData = new Array(totalWords).fill(0); }
            const val = CS ? romData[address] : 0;
            newOutputs = [];
            for(let i=0; i<dataWidth; i++) { newOutputs.push(!!((val >> i) & 1)); }
            break;
        }
      }

      if (JSON.stringify(newOutputs) !== JSON.stringify(oldOutputs)) {
          node.outputs = newOutputs;
          stable = false;
      }
    });
  }

  return { nodes: nextNodes, wires: nextWires };
};

import React from 'react';
import { NodeData } from '../types';
import { getNodeDimensions } from '../utils/componentUtils';
import { MB_START_Y, MB_SPACING } from '../constants';

interface GateShapeProps {
  node: NodeData;
}

interface TextProps {
  x: number;
  y: number;
  children?: React.ReactNode;
  fill?: string;
  fontSize?: string;
  fontFamily?: string;
}

const GateText = ({ x, y, children, fill="#71717a", fontSize="10", fontFamily }: TextProps) => (
  <text 
    x={x} y={y} 
    textAnchor="middle" dominantBaseline="middle" 
    fill={fill} fontSize={fontSize} fontFamily={fontFamily}
    fontWeight="bold" className="pointer-events-none select-none"
  >
    {children}
  </text>
);

const boolsToVal = (bools: boolean[]) => bools.reduce((acc, b, i) => acc + (b ? Math.pow(2, i) : 0), 0);
const boolsToHex = (bools: boolean[]) => `0x${boolsToVal(bools).toString(16).toUpperCase().padStart(Math.ceil(bools.length / 4), '0')}`;

export const GateShape: React.FC<GateShapeProps> = ({ node }) => {
  const type = node.type;
  const active = node.outputs[0]; 
  const strokeColor = active ? "#22d3ee" : "#71717a"; 
  const fillColor = node.properties?.color || "#18181b"; 
  const activeFill = active ? "#0ea5e9" : fillColor; 
  const { width, height } = getNodeDimensions(node);

  const getGatePath = (gateType: 'AND' | 'OR' | 'NAND' | 'NOR' | 'XOR' | 'XNOR') => {
     switch (gateType) {
         case 'AND': case 'NAND': return `M 0 0 L ${width/2} 0 A ${height/2} ${height/2} 0 0 1 ${width/2} ${height} L 0 ${height} Z`;
         case 'OR': case 'NOR': return `M 0 0 Q ${width*0.25} ${height/2} 0 ${height} Q ${width*0.8} ${height} ${width} ${height/2} Q ${width*0.8} 0 0 0 Z`;
         case 'XOR': case 'XNOR': return `M 10 0 Q ${width*0.35} ${height/2} 10 ${height} Q ${width*0.9} ${height} ${width} ${height/2} Q ${width*0.9} 0 10 0 Z`;
     }
  };

  const renderBinaryFooter = (bitCount: number, values: boolean[]) => {
      const bitWidth = 8; const bitSpacing = 1; const nibbleGap = 4;
      const totalWidth = bitCount * bitWidth + (bitCount - 1) * bitSpacing + Math.floor((bitCount - 1) / 4) * nibbleGap;
      const startX = (width - totalWidth) / 2 + bitWidth / 2;
      return (
        <g transform={`translate(0, ${height - 35})`}>
            <rect x="5" y="0" width={width - 10} height="24" rx="4" fill="#000" stroke="#3f3f46" />
            {Array.from({length: bitCount}).map((_, i) => {
                const bitIndex = bitCount - 1 - i; const bitVal = values[bitIndex]; const nibblesBefore = Math.floor(i / 4);
                const xPos = startX + i * (bitWidth + bitSpacing) + nibblesBefore * nibbleGap;
                return (
                    <text key={bitIndex} x={xPos} y="12" textAnchor="middle" dominantBaseline="middle" fill={bitVal ? "#22d3ee" : "#27272a"} fontSize="10" fontFamily="monospace" fontWeight="bold">
                        {bitVal ? "1" : "0"}
                    </text>
                );
            })}
        </g>
      );
  };

  switch (true) {
    case type === 'AND': return <path d={getGatePath('AND')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />;
    case type === 'NAND': return (
        <g>
          <path d={getGatePath('NAND')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <circle cx={width} cy={height/2} r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case type === 'OR': return <path d={getGatePath('OR')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />;
    case type === 'NOR': return (
        <g>
          <path d={getGatePath('OR')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <circle cx={width} cy={height/2} r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case type === 'XOR': return (
        <g>
          <path d={getGatePath('XOR')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <path d={`M -5 0 Q ${width*0.20} ${height/2} -5 ${height}`} fill="none" stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case type === 'XNOR': return (
        <g>
          <path d={getGatePath('XOR')} fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <circle cx={width} cy={height/2} r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <path d={`M -5 0 Q ${width*0.20} ${height/2} -5 ${height}`} fill="none" stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case type === 'NOT': return (
        <g>
          <path d="M 0 0 L 35 20 L 0 40 Z" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <circle cx="40" cy="20" r="5" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
        </g>
      );
    case type === 'BUFFER': return <path d="M 0 0 L 30 20 L 0 40 Z" fill={fillColor} stroke={strokeColor} strokeWidth="2" />;
    case type === 'TRI_STATE_BUFFER': return (
        <g>
            <path d="M 0 0 L 30 20 L 0 40 Z" fill={fillColor} stroke={strokeColor} strokeWidth="2" transform="translate(0, 20)"/>
            <line x1="25" y1="0" x2="25" y2="28" stroke={node.inputs[1] ? "#22d3ee" : "#71717a"} strokeWidth="2" />
        </g>
    );
    case type === 'VCC': return (
            <g>
                <rect x="0" y="0" width="30" height="30" rx="2" fill={fillColor} stroke="#22d3ee" strokeWidth="2" />
                <GateText x={15} y={15} fill="#22d3ee" fontSize="11">VCC</GateText>
            </g>
        );
    case type === 'GND': return (
            <g>
                <rect x="0" y="0" width="30" height="30" rx="2" fill={fillColor} stroke="#52525b" strokeWidth="2" />
                <GateText x={15} y={15} fill="#71717a" fontSize="11">GND</GateText>
            </g>
        );
    case type === 'JUNCTION': return <circle cx="5" cy="5" r="5" fill={active ? "#22d3ee" : "#71717a"} />;
    case type === 'TOGGLE_SWITCH': return (
        <g>
          <rect x="0" y="0" width="40" height="40" rx="4" fill={activeFill} stroke={strokeColor} strokeWidth="2" />
          <text x="20" y="25" textAnchor="middle" fill={active ? "#fff" : "#a1a1aa"} fontSize="12" fontWeight="bold">{active ? "1" : "0"}</text>
        </g>
      );
    case type === 'PUSH_BUTTON': return (
          <g>
            <circle cx="20" cy="20" r="15" fill={active ? "#22c55e" : "#3f3f46"} stroke={strokeColor} strokeWidth="2" />
            <circle cx="20" cy="20" r="10" fill={active ? "#16a34a" : "#18181b"} />
          </g>
        );
    case type === 'CLOCK': return (
            <g>
                <rect x="0" y="0" width="40" height="40" rx="4" fill="#18181b" stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
                <path d="M 10 20 L 15 20 L 15 10 L 25 10 L 25 30 L 35 30" fill="none" stroke={active ? "#22d3ee" : "#52525b"} strokeWidth="2" />
            </g>
        );
    case type === 'LED': return (
        <g>
          <circle cx="20" cy="20" r="15" fill={node.inputs[0] ? "#ef4444" : "#27272a"} stroke={node.inputs[0] ? "#f87171" : "#52525b"} strokeWidth="2" style={{ filter: node.inputs[0] ? 'drop-shadow(0 0 8px #ef4444)' : 'none'}} />
          {node.inputs[0] && <circle cx="20" cy="20" r="5" fill="white" opacity="0.4" />}
        </g>
      );
    case type === 'HEX_DIGIT':
        const hVal = (node.inputs[0]?1:0) + (node.inputs[1]?2:0) + (node.inputs[2]?4:0) + (node.inputs[3]?8:0);
        return (
            <g>
                <rect x="0" y="0" width="60" height="80" fill="#000" stroke="#3f3f46" strokeWidth="4" />
                <text x="30" y="45" textAnchor="middle" dominantBaseline="middle" fill="#ef4444" fontSize="40" fontFamily="monospace" style={{ filter: 'drop-shadow(0 0 4px #ef4444)'}}>
                    {hVal.toString(16).toUpperCase()}
                </text>
            </g>
        );
    case type.startsWith('INPUT_'):
        const bitCount = node.outputs.length;
        return (
            <g>
                <rect x="0" y="0" width={width} height={height} rx="4" fill="#18181b" stroke="#52525b" strokeWidth="2" />
                <GateText x={width/2} y={15}>{`IN ${bitCount}b (${boolsToHex(node.outputs)})`}</GateText>
                {node.outputs.map((state, i) => (
                   <g key={i} transform={`translate(10, ${MB_START_Y + (i * MB_SPACING)})`}>
                       <rect x="0" y="2" width={width - 20} height="20" rx="2" fill="#27272a" stroke="none" />
                       <g transform="translate(5, 4)">
                           <rect x="0" y="0" width="24" height="12" rx="2" fill={state ? "#0ea5e9" : "#3f3f46"} stroke={state ? "#22d3ee" : "#52525b"} />
                           <circle cx={state ? 18 : 6} cy={6} r="4" fill="white" />
                       </g>
                       <text x={width - 35} y="12" textAnchor="end" dominantBaseline="middle" fill="#71717a" fontSize="11" fontFamily="monospace">{i.toString()}</text>
                   </g>
                ))}
                {renderBinaryFooter(bitCount, node.outputs)}
            </g>
        );
    case type.startsWith('OUTPUT_'):
        const outBits = node.inputs.length;
        return (
            <g>
                <rect x="0" y="0" width={width} height={height} rx="4" fill="#09090b" stroke="#52525b" strokeWidth="2" />
                <GateText x={width/2} y={15}>{`OUT ${outBits}b (${boolsToHex(node.inputs)})`}</GateText>
                {node.inputs.map((state, i) => (
                    <g key={i} transform={`translate(10, ${MB_START_Y + (i * MB_SPACING)})`}>
                         <rect x="0" y="2" width={width - 20} height="20" rx="2" fill="#18181b" stroke="none" />
                         <circle cx="12" cy="12" r="5" fill={state ? "#ef4444" : "#27272a"} stroke={state ? "#f87171" : "#3f3f46"} />
                         <text x="30" y="12" dominantBaseline="middle" fill="#71717a" fontSize="11" fontFamily="monospace">{i.toString()}</text>
                    </g>
                ))}
                 {renderBinaryFooter(outBits, node.inputs)}
            </g>
        );
    case type === 'ALU_4BIT':
      return (
        <g>
          <path d="M 0 0 L 120 20 L 120 140 L 0 160 L 0 100 L 40 80 L 0 60 Z" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <GateText x={75} y={80} fill="#e4e4e7">ALU</GateText>
        </g>
      );
    case type === 'COUNTER_4BIT':
      const cVal = node.internalState?.counterValue || 0;
      return (
        <g>
          <rect x="0" y="0" width={width} height={height} rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
          <rect x="20" y="20" width="40" height="60" rx="4" fill="#000" />
          <GateText x={40} y={50} fill="#22d3ee" fontSize="24" fontFamily="monospace">{cVal}</GateText>
        </g>
      );
    case type.startsWith('RAM_') && type !== 'RAM_1BIT':
    case type.startsWith('MEMORY_CELL'): {
        // Find bit counts based on type suffix
        let aBits = 4; let dBits = 4;
        if (type === 'RAM_8BIT') { dBits = 8; }
        else if (type === 'RAM_16BIT') { dBits = 16; }
        else if (type === 'RAM_64_8') { aBits = 6; dBits = 8; }
        else if (type === 'RAM_256_8') { aBits = 8; dBits = 8; }
        else if (type === 'RAM_64BIT') { aBits = 3; dBits = 8; }
        else if (type === 'RAM_128BIT') { aBits = 4; dBits = 8; }
        else if (type === 'RAM_256BIT') { aBits = 5; dBits = 8; }

        let addrVal = 0;
        for(let i=0; i<aBits; i++) { if(node.inputs[i]) addrVal += Math.pow(2, i); }
        const CS = node.inputs[aBits + dBits + 1];
        const mem = node.internalState?.memory || [];
        const currentData = CS ? (mem[addrVal] || 0) : 0;

        return (
            <g>
                <rect x="0" y="0" width={width} height={height} rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={width/2} y={15} fill="#e4e4e7" fontSize="10">{node.type.replace(/_/g, ' ')}</GateText>

                {/* Visual Address/Data Monitor */}
                <rect x="15" y="30" width={width - 30} height="40" rx="4" fill="#000" stroke="#3f3f46" strokeWidth="1" />
                <GateText x={width/2} y={42} fontSize="8" fill="#52525b">ADDR: 0x{addrVal.toString(16).toUpperCase()}</GateText>
                <GateText x={width/2} y={58} fontSize="14" fill={CS ? "#22d3ee" : "#27272a"} fontFamily="monospace">
                    {currentData.toString(16).toUpperCase().padStart(dBits > 8 ? 4 : 2, '0')}
                </GateText>

                <GateText x={width/2} y={height - 20} fontSize="8" fill="#52525b">
                    {Math.pow(2, aBits)} WORDS x {dBits} BITS
                </GateText>
            </g>
        );
    }
    default:
        return (
            <g>
                <rect x="0" y="0" width={width} height={height} rx="4" fill={fillColor} stroke={strokeColor} strokeWidth="2" />
                <GateText x={width/2} y={height/2}>{type.replace(/_/g, ' ')}</GateText>
            </g>
        );
  }
};

